/// Gives raw GPUI action surfaces a stable accessible name even when their
/// visible text is rendered as an inaccessible `SharedString` child. Callers
/// can still provide a richer `.aria_label(...)` afterwards for content whose
/// title is more useful than its stable element id.
trait MacroActionAccessibility: StatefulInteractiveElement + Element + Sized {
    fn aria_label_from_id(self) -> Self {
        let label = <Self as Element>::id(&self)
            .map(|id| humanize_action_id(&id.to_string()))
            .unwrap_or_else(|| "Macro action".to_owned());
        self.aria_label(label)
    }
}

impl<T> MacroActionAccessibility for T where T: StatefulInteractiveElement + Element + Sized {}

fn humanize_action_id(id: &str) -> String {
    let words = id
        .split(['-', '_'])
        .filter(|word| !word.is_empty())
        .collect::<Vec<_>>();
    if words.is_empty() {
        "Macro action".to_owned()
    } else {
        words.join(" ")
    }
}

fn mutation_field_placeholder(label: &str) -> String {
    let label = label
        .split(" (")
        .next()
        .unwrap_or(label)
        .trim_end_matches(':');
    match label {
        "Task name" => "What needs to be done?".into(),
        "Details" | "Message" | "Markdown" => "Start writing…".into(),
        "Due date" => "Add a date".into(),
        "Assignees" | "Assignee user IDs" => "Choose people".into(),
        "Parent task" | "Parent task ID" => "Link a parent task".into(),
        "Dependencies" | "Depends on task IDs" => "Link dependencies".into(),
        "Related documents" | "Relevant document IDs" => "Link documents".into(),
        "Project" | "Project ID" => "Choose a project".into(),
        "Team" | "Team ID" => "Choose a team".into(),
        "Search people, documents, customers, and tags" => {
            "Search people, documents, customers, and tags…".into()
        }
        _ => format!("Enter {}", label.to_ascii_lowercase()),
    }
}

fn macro_button(id: impl Into<ElementId>, label: impl Into<SharedString>) -> Button {
    Button::new(id, label).tab_index(0isize)
}

