#[derive(Clone)]
struct ApiPermissionTokenProvider {
    api: macro_api::MacroApi,
}

impl PermissionTokenProvider for ApiPermissionTokenProvider {
    fn permission_token<'a>(&'a self, scope_id: &'a str) -> TokenFuture<'a> {
        Box::pin(async move {
            self.api
                .get_document_permissions_token(scope_id)
                .await
                .map(|response| response.token)
        })
    }
}

