#[derive(Debug, Clone, Copy, PartialEq)]
enum CanvasKeyboardCommand {
    SelectAll,
    Copy,
    Cut,
    Paste,
    Undo,
    Redo,
    Zoom(f64),
    Group,
    Ungroup,
    Delete,
    Cancel,
    Tool(CanvasTool),
    ArrangeFront,
    ArrangeBack,
    ArrangeForward,
    ArrangeBackward,
    Nudge(CanvasPoint),
}

fn canvas_keyboard_command(key: &str, modifiers: Modifiers) -> Option<CanvasKeyboardCommand> {
    if modifiers.secondary() {
        return match key {
            "a" => Some(CanvasKeyboardCommand::SelectAll),
            "c" => Some(CanvasKeyboardCommand::Copy),
            "x" => Some(CanvasKeyboardCommand::Cut),
            "v" => Some(CanvasKeyboardCommand::Paste),
            "z" if modifiers.shift => Some(CanvasKeyboardCommand::Redo),
            "z" => Some(CanvasKeyboardCommand::Undo),
            "y" => Some(CanvasKeyboardCommand::Redo),
            "=" | "+" => Some(CanvasKeyboardCommand::Zoom(1.1)),
            "-" => Some(CanvasKeyboardCommand::Zoom(1.0 / 1.1)),
            "g" if modifiers.shift => Some(CanvasKeyboardCommand::Ungroup),
            "g" => Some(CanvasKeyboardCommand::Group),
            _ => None,
        };
    }
    if modifiers.alt {
        return match key {
            "]" => Some(CanvasKeyboardCommand::ArrangeForward),
            "[" => Some(CanvasKeyboardCommand::ArrangeBackward),
            "z" => Some(CanvasKeyboardCommand::Tool(CanvasTool::ZoomOut)),
            _ => None,
        };
    }
    match key {
        "delete" | "backspace" => Some(CanvasKeyboardCommand::Delete),
        "escape" => Some(CanvasKeyboardCommand::Cancel),
        "v" => Some(CanvasKeyboardCommand::Tool(CanvasTool::Select)),
        "h" => Some(CanvasKeyboardCommand::Tool(CanvasTool::Hand)),
        "x" => Some(CanvasKeyboardCommand::Tool(CanvasTool::Connector)),
        "p" => Some(CanvasKeyboardCommand::Tool(CanvasTool::Pencil)),
        "t" => Some(CanvasKeyboardCommand::Tool(CanvasTool::Text)),
        "r" => Some(CanvasKeyboardCommand::Tool(CanvasTool::Rectangle)),
        "z" => Some(CanvasKeyboardCommand::Tool(CanvasTool::ZoomIn)),
        "]" => Some(CanvasKeyboardCommand::ArrangeFront),
        "[" => Some(CanvasKeyboardCommand::ArrangeBack),
        "up" | "arrowup" => Some(CanvasKeyboardCommand::Nudge(CanvasPoint {
            x: 0.0,
            y: if modifiers.shift { -10.0 } else { -1.0 },
        })),
        "right" | "arrowright" => Some(CanvasKeyboardCommand::Nudge(CanvasPoint {
            x: if modifiers.shift { 10.0 } else { 1.0 },
            y: 0.0,
        })),
        "down" | "arrowdown" => Some(CanvasKeyboardCommand::Nudge(CanvasPoint {
            x: 0.0,
            y: if modifiers.shift { 10.0 } else { 1.0 },
        })),
        "left" | "arrowleft" => Some(CanvasKeyboardCommand::Nudge(CanvasPoint {
            x: if modifiers.shift { -10.0 } else { -1.0 },
            y: 0.0,
        })),
        _ => None,
    }
}

