#[derive(Debug, Clone, Copy, Default, PartialEq, Eq)]
enum CrmGrouping {
    #[default]
    None,
    Stage,
    Owner,
}

impl CrmGrouping {
    const ALL: [Self; 3] = [Self::None, Self::Stage, Self::Owner];

    fn label(self) -> &'static str {
        match self {
            Self::None => "None",
            Self::Stage => "Stage",
            Self::Owner => "Owner",
        }
    }

    fn saved_view_id(self) -> Option<String> {
        match self {
            Self::None => None,
            Self::Stage => Some(format!("property:{CRM_COMPANY_STAGE_PROPERTY_ID}")),
            Self::Owner => Some(format!("property:{CRM_COMPANY_OWNER_PROPERTY_ID}")),
        }
    }

    fn from_saved_view_id(value: Option<&str>) -> Self {
        match value {
            Some(value)
                if value == format!("property:{CRM_COMPANY_STAGE_PROPERTY_ID}").as_str() =>
            {
                Self::Stage
            }
            Some(value)
                if value == format!("property:{CRM_COMPANY_OWNER_PROPERTY_ID}").as_str() =>
            {
                Self::Owner
            }
            _ => Self::None,
        }
    }
}

