#[serde(rename_all = "camelCase")]
struct CrmListColumns {
    stage: bool,
    owner: bool,
    revenue: bool,
}

impl Default for CrmListColumns {
    fn default() -> Self {
        Self {
            stage: true,
            owner: true,
            revenue: true,
        }
    }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum CrmListColumn {
    Stage,
    Owner,
    Revenue,
}

impl CrmListColumns {
    fn is_visible(self, column: CrmListColumn) -> bool {
        match column {
            CrmListColumn::Stage => self.stage,
            CrmListColumn::Owner => self.owner,
            CrmListColumn::Revenue => self.revenue,
        }
    }

    fn toggle(&mut self, column: CrmListColumn) {
        let visible = match column {
            CrmListColumn::Stage => &mut self.stage,
            CrmListColumn::Owner => &mut self.owner,
            CrmListColumn::Revenue => &mut self.revenue,
        };
        *visible = !*visible;
    }
}

impl CrmListColumn {
    const ALL: [Self; 3] = [Self::Stage, Self::Owner, Self::Revenue];

    fn label(self) -> &'static str {
        match self {
            Self::Stage => "Stage",
            Self::Owner => "Owner",
            Self::Revenue => "Revenue",
        }
    }
}

