/// Data groups fetched when a surface becomes visible. Startup used to request
/// every feature service at once, which made the native client slower than the
/// web reference despite GPUI's inexpensive paint path. Keeping this mapping
/// pure makes the request boundary reviewable and prevents feature additions
/// from silently expanding the signed-in startup fan-out.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum SectionResource {
    Inbox,
    Recent,
    Projects,
    RecentlyDeleted,
    Channels,
    ActiveCalls,
    AgentSettings,
    ScheduledActions,
    Reminders,
    Notifications,
    NotificationSettings,
    EmailLinks,
    EmailLabels,
    Calendars,
    Memory,
    Onboarding,
    StarterDocuments,
    McpServers,
    Pipedream,
    Bots,
    Webhooks,
    SavedViews,
    CrmSettings,
    DeveloperIntegrations,
    AccountAdministration,
    Tags,
    PropertyDefinitions,
    Imports,
}

fn section_resources(section: NavSection) -> &'static [SectionResource] {
    use SectionResource::*;
    match section {
        NavSection::Home => &[Recent],
        NavSection::Inbox => &[Inbox],
        NavSection::Search => &[Tags, PropertyDefinitions],
        NavSection::Mail => &[Inbox, EmailLinks, EmailLabels],
        NavSection::Channels => &[Channels],
        NavSection::Documents | NavSection::Tasks => &[Inbox, Projects, Tags, PropertyDefinitions],
        NavSection::Agents => &[Inbox, AgentSettings, ScheduledActions],
        NavSection::Calls => &[ActiveCalls, Channels, Tags, PropertyDefinitions],
        NavSection::CRM => &[Inbox, SavedViews, CrmSettings, Tags, PropertyDefinitions],
        NavSection::Files => &[Inbox, Projects, RecentlyDeleted],
        NavSection::Calendar => &[Calendars],
        NavSection::Activity => &[Notifications],
        NavSection::Reminders => &[Reminders],
        NavSection::Integrations => &[
            Onboarding,
            StarterDocuments,
            EmailLinks,
            McpServers,
            Pipedream,
            Bots,
            Webhooks,
            DeveloperIntegrations,
            Imports,
        ],
        NavSection::Settings => &[
            Onboarding,
            StarterDocuments,
            NotificationSettings,
            EmailLinks,
            EmailLabels,
            Calendars,
            Memory,
            McpServers,
            Pipedream,
            Bots,
            Webhooks,
            AgentSettings,
            ScheduledActions,
            SavedViews,
            CrmSettings,
            DeveloperIntegrations,
            AccountAdministration,
            Tags,
            PropertyDefinitions,
        ],
    }
}

