#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum ChannelComposerAttachmentKind {
    Image,
    Video,
    Document,
}

impl ChannelComposerAttachmentKind {
    fn from_mime_type(mime_type: &str) -> Self {
        if mime_type.starts_with("image/") {
            Self::Image
        } else if mime_type.starts_with("video/") {
            Self::Video
        } else {
            Self::Document
        }
    }

    fn entity_type(self) -> &'static str {
        match self {
            Self::Image => "static/image",
            Self::Video => "static/video",
            Self::Document => "document",
        }
    }

    fn from_entity_type(entity_type: &str) -> Self {
        match entity_type {
            "static/image" => Self::Image,
            "static/video" => Self::Video,
            _ => Self::Document,
        }
    }

    fn label(self) -> &'static str {
        match self {
            Self::Image => "Image",
            Self::Video => "Video",
            Self::Document => "Document",
        }
    }
}

#[derive(Debug, Clone, PartialEq, Eq)]
enum ChannelComposerAttachmentStatus {
    Reading,
    Uploading,
    Processing,
    Ready,
    Failed(String),
}

impl ChannelComposerAttachmentStatus {
    fn label(&self) -> &str {
        match self {
            Self::Reading => "Reading…",
            Self::Uploading => "Uploading…",
            Self::Processing => "Processing…",
            Self::Ready => "Ready",
            Self::Failed(error) => error,
        }
    }

    fn is_pending(&self) -> bool {
        matches!(self, Self::Reading | Self::Uploading | Self::Processing)
    }
}

