/// Zed's real single-line editor for every non-rich mutation field. The first
/// GPUI prototype painted field values into clickable divs and intercepted raw
/// key events at the window root; that looked unlike Zed and also lost native
/// selection, IME, undo, clipboard, and cursor behavior. These editor entities
/// keep the existing typed mutation payload while supplying Zed's input model.
struct MutationTextEditorState {
    generation: u64,
    field_index: usize,
    editor: Entity<ZedTextEditor>,
    _edit_subscription: Subscription,
    _focus_subscription: Subscription,
}

#[derive(Debug, Clone, Copy)]
struct LocalChannelTypingState {
    generation: u64,
    last_start: Instant,
}

impl LocalChannelTypingState {
    fn new(now: Instant) -> Self {
        Self {
            generation: 0,
            last_start: now,
        }
    }

    fn keystroke(&mut self, now: Instant) -> bool {
        const START_REFRESH: Duration = Duration::from_secs(4);
        let should_emit_start =
            self.generation == 0 || now.saturating_duration_since(self.last_start) >= START_REFRESH;
        self.generation = self.generation.wrapping_add(1).max(1);
        if should_emit_start {
            self.last_start = now;
        }
        should_emit_start
    }
}

#[derive(Debug, Clone, PartialEq, Eq, Hash)]
enum SnippetInsertionTarget {
    Document(String),
    Mutation { generation: u64 },
}

#[derive(Debug, Clone, PartialEq, Eq)]
struct SnippetTypeaheadSelection {
    context: DocumentSnippetContext,
    selected_index: usize,
}

impl SnippetTypeaheadSelection {
    fn apply(
        &mut self,
        context: DocumentSnippetContext,
        candidate_count: usize,
        command: SnippetTypeaheadCommand,
    ) -> Option<usize> {
        if self.context != context {
            self.context = context;
            self.selected_index = 0;
        }
        if candidate_count == 0 {
            self.selected_index = 0;
            return None;
        }
        self.selected_index = self.selected_index.min(candidate_count - 1);
        match command {
            SnippetTypeaheadCommand::Previous => {
                self.selected_index = if self.selected_index == 0 {
                    candidate_count - 1
                } else {
                    self.selected_index - 1
                };
                None
            }
            SnippetTypeaheadCommand::Next => {
                self.selected_index = (self.selected_index + 1) % candidate_count;
                None
            }
            SnippetTypeaheadCommand::Accept => Some(self.selected_index),
            SnippetTypeaheadCommand::Dismiss => None,
        }
    }
}

