    fn sync_sidebar_favorites(&mut self) {
        let Some(favorites) = self.workspace.favorites.loaded().cloned() else {
            self.layout_state.favorites.clear();
            return;
        };
        let mut favorites = favorites;
        favorites.sort_by_key(|favorite| favorite.sort_order);
        self.layout_state.favorites = favorites
            .into_iter()
            .map(|favorite| {
                let name = self
                    .workspace
                    .recent
                    .get(&favorite.entity_id)
                    .or_else(|| self.workspace.inbox.get(&favorite.entity_id))
                    .map(|item| item.title.clone())
                    .or_else(|| {
                        self.workspace
                            .channels
                            .get(&favorite.entity_id)
                            .map(|channel| channel.name.clone())
                    })
                    .or_else(|| {
                        self.open_entities
                            .values()
                            .find(|entity| entity.id() == favorite.entity_id)
                            .map(|entity| entity.title().to_owned())
                    })
                    .filter(|name| !name.trim().is_empty())
                    .unwrap_or_else(|| format!("{} {}", favorite.entity_type, favorite.entity_id));
                SidebarItemData {
                    entity_type: favorite.entity_type,
                    entity_id: favorite.entity_id,
                    name,
                    unread_count: 0,
                }
            })
            .collect();
    }

    fn open_favorite(&mut self, favorite: &SidebarItemData, cx: &mut Context<Self>) {
        if favorite.entity_type == EntityType::Channel {
            let channel = self
                .workspace
                .channels
                .get(&favorite.entity_id)
                .unwrap_or_else(|| {
                    Arc::new(ChannelSummary {
                        id: favorite.entity_id.clone(),
                        name: favorite.name.clone(),
                        channel_type: "public".into(),
                        preview: String::new(),
                        updated_at: String::new(),
                        raw: serde_json::Value::Null,
                    })
                });
            self.open_entity(OpenEntity::Channel(channel), cx);
            return;
        }

        let item = self
            .workspace
            .recent
            .get(&favorite.entity_id)
            .or_else(|| self.workspace.inbox.get(&favorite.entity_id))
            .unwrap_or_else(|| {
                Arc::new(InboxItem {
                    id: favorite.entity_id.clone(),
                    tag: entity_type_soup_tag(favorite.entity_type).into(),
                    sub_type: None,
                    entity_type: favorite.entity_type,
                    title: favorite.name.clone(),
                    subtitle: String::new(),
                    timestamp: String::new(),
                    raw: serde_json::Value::Null,
                })
            });
        self.open_entity(OpenEntity::Inbox(item), cx);
    }

