    fn load_crm_emails(
        &mut self,
        entity_type: EntityType,
        entity_id: String,
        detail: serde_json::Value,
        load_more: bool,
        force: bool,
        cx: &mut Context<Self>,
    ) {
        if !matches!(entity_type, EntityType::CrmCompany | EntityType::CrmContact) {
            return;
        }
        let key = format!("{entity_type}:{entity_id}");
        let preferences = self
            .crm_email_preferences
            .get(&key)
            .copied()
            .unwrap_or_default();
        let Some(request) = crm_email_soup_request(entity_type, &detail, preferences) else {
            self.workspace
                .crm_emails
                .entry(key)
                .or_default()
                .replace(Vec::new(), None);
            return;
        };

        let store = self.workspace.crm_emails.entry(key.clone()).or_default();
        if store.is_loading() || self.crm_email_loading_more.contains(&key) {
            return;
        }
        if !load_more && !force && store.is_ready() {
            return;
        }
        let cursor = if load_more {
            let Some(cursor) = store.next_cursor().map(ToOwned::to_owned) else {
                return;
            };
            self.crm_email_loading_more.insert(key.clone());
            Some(cursor)
        } else {
            store.begin_load(false);
            None
        };

        let api = self.api.clone();
        cx.spawn(async move |this, cx| {
            let result = api
                .list_soup_ast_items(&request, cursor.as_deref())
                .await
                .and_then(parse_soup_page);
            this.update(cx, |this, cx| {
                this.crm_email_loading_more.remove(&key);
                let store = this.workspace.crm_emails.entry(key).or_default();
                match result {
                    Ok(page) if load_more => store.append(page.items, page.next_cursor),
                    Ok(page) => store.replace(page.items, page.next_cursor),
                    Err(error) => store.fail(error.to_string()),
                }
                cx.notify();
            })?;
            anyhow::Ok(())
        })
        .detach();
    }

