    fn prepare_account_session_restore(&mut self, account_id: &str) {
        let session = self
            .account_sessions
            .get(account_id)
            .cloned()
            .unwrap_or_default();
        self.layout_state.active_section =
            parse_nav_section(&session.active_section).unwrap_or(NavSection::Inbox);
        self.list_query_states = session.list_query_states;
        self.active_list_saved_view_ids = session.active_list_saved_view_ids;
        self.pending_session_restore = (!session.open_entities.is_empty()
            || !session.navigation_history.is_empty())
        .then(|| PendingSessionRestore {
            entities: session.open_entities,
            active_tab_id: session.active_tab_id,
            navigation_history: session.navigation_history,
            navigation_history_index: session.navigation_history_index,
            detail_fullscreen: session.detail_fullscreen,
        });
    }

    fn sign_out(&mut self, window: &mut Window, cx: &mut Context<Self>) {
        self.auth_generation = self.auth_generation.wrapping_add(1);
        let signed_out_account = self.active_account_id.take();
        if let Some(account_id) = signed_out_account.as_ref() {
            self.saved_accounts
                .retain(|account| &account.user_id != account_id);
            self.account_sessions.remove(account_id);
        }
        self.reset_account_scoped_state(window, cx);
        self.auth_code.clear();
        self.session_notice = None;
        self.active_account_id = self
            .saved_accounts
            .iter()
            .find(|account| account.environment == self.environment)
            .map(|account| account.user_id.clone());
        if let Some(account_id) = self.active_account_id.clone() {
            self.prepare_account_session_restore(&account_id);
        }
        self.session = if self.active_account_id.is_some() {
            SessionState::Restoring
        } else {
            SessionState::SignedOut
        };
        self.persist_preferences(cx);

        if let Some(account_id) = signed_out_account {
            let credential_key = account_credentials_key(&account_id);
            let persistence = self.channel_outbox_persistence.clone();
            cx.spawn(async move |_, cx| {
                if let Some(persistence) = persistence {
                    let _ = persistence.clear_account(&account_id).await;
                }
                let _ = cx
                    .update(move |cx| cx.delete_credentials(&credential_key))
                    .await;
                anyhow::Ok(())
            })
            .detach();
        }
        if self.active_account_id.is_some() {
            self.restore_session(cx);
        }
        cx.notify();
    }

    fn register_saved_account(&mut self, user: &UserInfo, email: String) {
        self.saved_accounts
            .retain(|account| account.user_id != user.user_id);
        self.saved_accounts.push(SavedAccount {
            user_id: user.user_id.clone(),
            email,
            environment: self.environment.clone(),
        });
        self.active_account_id = Some(user.user_id.clone());
    }

    fn switch_account(&mut self, user_id: String, window: &mut Window, cx: &mut Context<Self>) {
        if self.active_account_id.as_deref() == Some(&user_id) {
            return;
        }
        self.snapshot_active_account_session();
        self.auth_generation = self.auth_generation.wrapping_add(1);
        self.reset_account_scoped_state(window, cx);
        self.active_account_id = Some(user_id.clone());
        self.prepare_account_session_restore(&user_id);
        self.session = SessionState::Restoring;
        self.persist_preferences(cx);
        self.restore_session(cx);
        cx.notify();
    }

    fn add_account(&mut self, window: &mut Window, cx: &mut Context<Self>) {
        self.snapshot_active_account_session();
        self.auth_generation = self.auth_generation.wrapping_add(1);
        self.reset_account_scoped_state(window, cx);
        self.active_account_id = None;
        self.auth_email.clear();
        self.auth_code.clear();
        self.active_auth_field = AuthField::Email;
        self.session = SessionState::SignedOut;
        self.persist_preferences(cx);
        cx.notify();
    }

    fn load_initial_workspace(&mut self, cx: &mut Context<Self>) {
        self.restore_channel_outbox(cx);
        if !self.realtime_running {
            self.layout_state.connection_status = ConnectionStatus::Connecting;
            self.start_realtime(cx);
        }

        // The sidebar needs favorites immediately and the server-owned
        // onboarding row determines whether setup must resume. Every other feature-specific
        // aggregate is fetched only for the visible section. The old startup
        // path launched more than twenty unrelated service requests before the
        // first useful interaction, overwhelming both the runtime and Macro's
        // gateways without improving the initial Inbox paint.
        self.load_favorites(false, cx);
        self.load_onboarding_state(false, cx);
        self.ensure_section_data(self.layout_state.active_section, cx);
        if let Some(view_id) = self.active_list_view_id(self.layout_state.active_section)
            && self.list_query_uses_server(view_id)
            && self
                .workspace
                .filtered_list_views
                .get(view_id)
                .is_none_or(|collection| !collection.is_ready())
        {
            self.load_filtered_list_view(view_id.to_owned(), true, cx);
        }
        self.restore_persisted_layout(cx);
        if let Some(link) = self.pending_deep_link.take() {
            self.navigate_deep_link(link, cx);
        }
    }

    fn restore_persisted_layout(&mut self, cx: &mut Context<Self>) {
        let Some(restore) = self.pending_session_restore.take() else {
            return;
        };
        self.restoring_session_layout = true;
        for entity in restore.entities {
            let entity = match entity {
                PersistedOpenEntity::Inbox {
                    id,
                    tag,
                    sub_type,
                    entity_type,
                    title,
                } => OpenEntity::Inbox(Arc::new(InboxItem {
                    raw: serde_json::json!({
                        "tag": tag,
                        "data": { "id": id }
                    }),
                    id,
                    tag,
                    sub_type,
                    entity_type,
                    title,
                    subtitle: "Restored from the previous session".into(),
                    timestamp: String::new(),
                })),
                PersistedOpenEntity::Channel {
                    id,
                    name,
                    channel_type,
                } => OpenEntity::Channel(Arc::new(ChannelSummary {
                    raw: serde_json::json!({
                        "id": id,
                        "name": name,
                        "channel_type": channel_type,
                    }),
                    id,
                    name,
                    channel_type,
                    preview: "Restored from the previous session".into(),
                    updated_at: String::new(),
                })),
            };
            self.open_entity(entity, cx);
        }

        let mut history = restore
            .navigation_history
            .into_iter()
            .filter_map(|location| match location {
                PersistedNavigation::Section { section } => {
                    parse_nav_section(&section).map(NavigationLocation::Section)
                }
                PersistedNavigation::Entity { tab_id, section } => {
                    let section = parse_nav_section(&section)?;
                    self.open_entities
                        .contains_key(&tab_id)
                        .then_some(NavigationLocation::Entity { tab_id, section })
                }
            })
            .collect::<Vec<_>>();
        if history.is_empty() {
            history.push(NavigationLocation::Section(
                self.layout_state.active_section,
            ));
        }
        self.navigation_history = history;
        self.navigation_history_index = restore
            .navigation_history_index
            .min(self.navigation_history.len().saturating_sub(1));
        let current = self
            .navigation_history
            .get(self.navigation_history_index)
            .cloned();
        if let Some(current) = current {
            self.apply_navigation_location(current);
        } else if let Some(active_tab_id) = restore.active_tab_id {
            for tab in &mut self.layout_state.tabs {
                tab.is_active = tab.entity_id == active_tab_id;
            }
        }
        self.detail_fullscreen = restore.detail_fullscreen && self.active_entity().is_some();
        self.restoring_session_layout = false;
        self.ensure_active_channel_view_session(cx);
        self.persist_preferences(cx);
        cx.notify();
    }

    fn start_token_refresh_loop(&mut self, cx: &mut Context<Self>) {
        let Some(account_id) = self.active_account_id.clone() else {
            return;
        };
        self.token_refresh_generation = self.token_refresh_generation.wrapping_add(1);
        let generation = self.token_refresh_generation;
        let credential_key = account_credentials_key(&account_id);
        let environment = self.environment.clone();
        let api = self.api.clone();
        let executor = cx.background_executor().clone();
        cx.spawn(async move |this, cx| {
            loop {
                executor.timer(Duration::from_secs(10 * 60)).await;
                let active = this.update(cx, |this, _| {
                    this.token_refresh_generation == generation
                        && this.active_account_id.as_deref() == Some(account_id.as_str())
                        && this.session.is_ready()
                })?;
                if !active {
                    return anyhow::Ok(());
                }

                let read_key = credential_key.clone();
                let stored = cx.update(move |cx| cx.read_credentials(&read_key)).await;
                let result = async {
                    let (_, bytes) = stored?
                        .ok_or_else(|| anyhow::anyhow!("saved account credentials are missing"))?;
                    let credentials: StoredCredentials = serde_json::from_slice(&bytes)?;
                    if credentials.environment != environment {
                        anyhow::bail!("saved account belongs to another environment");
                    }
                    let tokens = api
                        .refresh_tokens(&credentials.access_token, &credentials.refresh_token)
                        .await?;
                    let api_token = api.exchange_macro_api_token(&tokens.access_token).await?;
                    let user = api.me(&tokens.access_token).await?;
                    let updated = StoredCredentials {
                        environment: credentials.environment,
                        access_token: tokens.access_token,
                        refresh_token: tokens.refresh_token,
                        macro_api_token: api_token.macro_api_token,
                    };
                    let macro_api_token = updated.macro_api_token.clone();
                    let bytes = serde_json::to_vec(&updated)?;
                    let write_key = credential_key.clone();
                    cx.update(move |cx| cx.write_credentials(&write_key, "Macro", &bytes))
                        .await?;
                    anyhow::Ok((user, macro_api_token))
                }
                .await;

                this.update(cx, |this, cx| {
                    if this.token_refresh_generation != generation {
                        return;
                    }
                    match result {
                        Ok((user, macro_api_token)) => {
                            this.api.set_token(macro_api_token);
                            this.session = SessionState::Ready { user };
                        }
                        Err(error) => {
                            this.session_notice =
                                Some(format!("Session refresh will retry: {error}"));
                        }
                    }
                    cx.notify();
                })?;
            }
        })
        .detach();
    }

    fn load_inbox(&mut self, show_loading: bool, cx: &mut Context<Self>) {
        if self.layout_state.active_section == NavSection::Inbox {
            self.load_inbox_view(show_loading, cx);
        }
        if let Some(view_id) = list_view_id_for_section(self.layout_state.active_section)
            && self.list_query_uses_server(view_id)
        {
            self.load_filtered_list_view(view_id.to_owned(), show_loading, cx);
        }
        if self.workspace.inbox.is_loading() {
            return;
        }
        self.workspace.inbox.begin_load(!show_loading);
        self.metrics.record_top_level_request();
        let api = self.api.clone();
        cx.spawn(async move |this, cx| {
            let result = api
                .list_soup_items(40, None)
                .await
                .and_then(parse_soup_page);
            this.update(cx, |this, cx| {
                match result {
                    Ok(page) => {
                        this.workspace.inbox.replace(page.items, page.next_cursor);
                        this.sync_open_inbox_records();
                        this.sync_sidebar_favorites();
                        if this.layout_state.active_section == NavSection::CRM {
                            this.load_crm_company_properties(false, cx);
                        }
                    }
                    Err(error) => this.workspace.inbox.fail(error.to_string()),
                }
                this.update_primary_connection_status();
                cx.notify();
            })?;
            anyhow::Ok(())
        })
        .detach();
        cx.notify();
    }

    fn load_recent(&mut self, show_loading: bool, cx: &mut Context<Self>) {
        if self.workspace.recent.is_loading() {
            return;
        }
        self.workspace.recent.begin_load(!show_loading);
        self.metrics.record_top_level_request();
        let api = self.api.clone();
        let request = recent_soup_request();
        cx.spawn(async move |this, cx| {
            let result = api
                .list_soup_ast_items(&request, None)
                .await
                .and_then(parse_soup_page);
            this.update(cx, |this, cx| {
                match result {
                    Ok(page) => {
                        this.workspace.recent.replace(page.items, page.next_cursor);
                        this.sync_sidebar_favorites();
                    }
                    Err(error) => this.workspace.recent.fail(error.to_string()),
                }
                cx.notify();
            })?;
            anyhow::Ok(())
        })
        .detach();
        cx.notify();
    }

    fn load_snippets(&mut self, force: bool, cx: &mut Context<Self>) {
        if self.workspace.snippets.is_loading() || (!force && self.workspace.snippets.is_ready()) {
            return;
        }
        self.workspace.snippets.begin_load(force);
        self.metrics.record_top_level_request();
        let api = self.api.clone();
        let request = snippet_soup_request();
        cx.spawn(async move |this, cx| {
            let result = api
                .list_soup_ast_items(&request, None)
                .await
                .and_then(parse_soup_page);
            this.update(cx, |this, cx| {
                match result {
                    Ok(page) => this
                        .workspace
                        .snippets
                        .replace(page.items, page.next_cursor),
                    Err(error) => this.workspace.snippets.fail(error.to_string()),
                }
                cx.notify();
            })?;
            anyhow::Ok(())
        })
        .detach();
        cx.notify();
    }

    fn load_more_recent(&mut self, cx: &mut Context<Self>) {
        if self.recent_loading_more {
            return;
        }
        let Some(cursor) = self.workspace.recent.next_cursor().map(ToOwned::to_owned) else {
            return;
        };
        self.recent_loading_more = true;
        self.metrics.record_top_level_request();
        let api = self.api.clone();
        let request = recent_soup_request();
        cx.spawn(async move |this, cx| {
            let result = api
                .list_soup_ast_items(&request, Some(&cursor))
                .await
                .and_then(parse_soup_page);
            this.update(cx, |this, cx| {
                this.recent_loading_more = false;
                match result {
                    Ok(page) => {
                        this.workspace.recent.append(page.items, page.next_cursor);
                        this.sync_sidebar_favorites();
                    }
                    Err(error) => {
                        this.session_notice =
                            Some(format!("Unable to load more recent items: {error}"));
                    }
                }
                cx.notify();
            })?;
            anyhow::Ok(())
        })
        .detach();
        cx.notify();
    }

    fn list_query_state(&self, view_id: &str) -> ListQueryState {
        let mut state = self
            .list_query_states
            .get(view_id)
            .cloned()
            .unwrap_or_else(|| {
                if view_id == "inbox" {
                    ListQueryState::inbox_default()
                } else {
                    ListQueryState::default()
                }
            });
        if !ListGrouping::available_for(view_id).contains(&state.grouping) {
            state.grouping = ListGrouping::None;
        }
        if state.grouping != ListGrouping::None {
            state.sort = match state.sort {
                ListSort::CreatedAsc | ListSort::CreatedDesc => ListSort::CreatedDesc,
                ListSort::UpdatedAsc | ListSort::UpdatedDesc => ListSort::UpdatedDesc,
            };
        }
        state
    }

    fn list_query_uses_server(&self, view_id: &str) -> bool {
        let state = self.list_query_state(view_id);
        is_mail_list_view(view_id)
            || is_calls_list_view(view_id)
            || !state.tags.is_empty()
            || state.sort != ListSort::UpdatedDesc
            || state.grouping != ListGrouping::None
    }

    fn load_filtered_list_view(
        &mut self,
        view_id: String,
        show_loading: bool,
        cx: &mut Context<Self>,
    ) {
        if !self.list_query_uses_server(&view_id) || self.filtered_list_loading.contains(&view_id) {
            return;
        }
        self.workspace
            .filtered_list_views
            .entry(view_id.clone())
            .or_default()
            .begin_load(!show_loading);
        self.filtered_list_loading.insert(view_id.clone());
        let generation = self
            .filtered_list_generations
            .entry(view_id.clone())
            .and_modify(|generation| *generation = generation.wrapping_add(1))
            .or_insert(1)
            .to_owned();
        let state = self.list_query_state(&view_id);
        let request = filtered_list_soup_request(&view_id, &state);
        let group_by = soup_group_by_field(state.grouping);
        let grouped_sort = grouped_soup_sort(state.sort);
        self.metrics.record_top_level_request();
        let api = self.api.clone();
        cx.spawn(async move |this, cx| {
            let result = if let Some(group_by) = group_by {
                api.list_grouped_soup_ast_items(&request, &group_by, grouped_sort, 40)
                    .await
                    .and_then(parse_grouped_soup_initial_page)
                    .map(FilteredListPage::Grouped)
            } else {
                api.list_soup_ast_items(&request, None)
                    .await
                    .and_then(parse_soup_page)
                    .map(FilteredListPage::Flat)
            };
            this.update(cx, |this, cx| {
                if this.filtered_list_generations.get(&view_id) != Some(&generation) {
                    return;
                }
                this.filtered_list_loading.remove(&view_id);
                let collection = this
                    .workspace
                    .filtered_list_views
                    .entry(view_id.clone())
                    .or_default();
                match result {
                    Ok(FilteredListPage::Flat(page)) => {
                        collection.replace(page.items, page.next_cursor);
                        this.filtered_list_groups.remove(&view_id);
                    }
                    Ok(FilteredListPage::Grouped(page)) => {
                        collection.replace(page.items, None);
                        this.filtered_list_groups
                            .insert(view_id.clone(), page.groups);
                    }
                    Err(error) => collection.fail(error.to_string()),
                }
                this.update_primary_connection_status();
                cx.notify();
            })?;
            anyhow::Ok(())
        })
        .detach();
        cx.notify();
    }

    fn load_more_filtered_list_view(&mut self, view_id: String, cx: &mut Context<Self>) {
        let Some(cursor) = self
            .workspace
            .filtered_list_views
            .get(&view_id)
            .and_then(|collection| collection.next_cursor())
            .map(ToOwned::to_owned)
        else {
            return;
        };
        if self.filtered_list_loading_more.contains(&view_id) {
            return;
        }
        self.filtered_list_loading_more.insert(view_id.clone());
        let generation = self
            .filtered_list_generations
            .get(&view_id)
            .copied()
            .unwrap_or_default();
        let state = self.list_query_state(&view_id);
        let request = filtered_list_soup_request(&view_id, &state);
        self.metrics.record_top_level_request();
        let api = self.api.clone();
        cx.spawn(async move |this, cx| {
            let result = api
                .list_soup_ast_items(&request, Some(&cursor))
                .await
                .and_then(parse_soup_page);
            this.update(cx, |this, cx| {
                if this.filtered_list_generations.get(&view_id) != Some(&generation) {
                    return;
                }
                this.filtered_list_loading_more.remove(&view_id);
                match result {
                    Ok(page) => this
                        .workspace
                        .filtered_list_views
                        .entry(view_id.clone())
                        .or_default()
                        .append(page.items, page.next_cursor),
                    Err(error) => {
                        this.session_notice =
                            Some(format!("Unable to load more filtered items: {error}"));
                    }
                }
                cx.notify();
            })?;
            anyhow::Ok(())
        })
        .detach();
        cx.notify();
    }

    fn load_more_filtered_group(
        &mut self,
        view_id: String,
        group_key: String,
        cx: &mut Context<Self>,
    ) {
        let Some(group) = self
            .filtered_list_groups
            .get(&view_id)
            .and_then(|groups| groups.iter().find(|group| group.key == group_key))
            .cloned()
        else {
            return;
        };
        let Some(cursor) = group.next_cursor else {
            return;
        };
        let loading_key = filtered_group_loading_key(&view_id, &group_key);
        if !self.filtered_group_loading_more.insert(loading_key.clone()) {
            return;
        }
        let generation = self
            .filtered_list_generations
            .get(&view_id)
            .copied()
            .unwrap_or_default();
        let state = self.list_query_state(&view_id);
        let Some(group_by) = soup_group_by_field(state.grouping) else {
            self.filtered_group_loading_more.remove(&loading_key);
            return;
        };
        let request = filtered_list_soup_request(&view_id, &state);
        let grouped_sort = grouped_soup_sort(state.sort);
        self.metrics.record_top_level_request();
        let api = self.api.clone();
        cx.spawn(async move |this, cx| {
            let result = api
                .list_grouped_soup_ast_group_page(
                    &request,
                    &group_by,
                    &group_key,
                    grouped_sort,
                    40,
                    &cursor,
                )
                .await
                .and_then(parse_grouped_soup_group_page);
            this.update(cx, |this, cx| {
                this.filtered_group_loading_more.remove(&loading_key);
                if this.filtered_list_generations.get(&view_id) != Some(&generation) {
                    return;
                }
                match result {
                    Ok(page) if page.group.key == group_key => {
                        if let Err(error) = this.merge_filtered_group_page(&view_id, page) {
                            this.session_notice =
                                Some(format!("Unable to merge grouped items: {error}"));
                        }
                    }
                    Ok(page) => {
                        this.session_notice = Some(format!(
                            "Grouped pagination returned {:?} while loading {:?}",
                            page.group.key, group_key
                        ));
                    }
                    Err(error) => {
                        this.session_notice =
                            Some(format!("Unable to load more grouped items: {error}"));
                    }
                }
                cx.notify();
            })?;
            anyhow::Ok(())
        })
        .detach();
        cx.notify();
    }

    fn merge_filtered_group_page(
        &mut self,
        view_id: &str,
        page: GroupedInboxGroupPage,
    ) -> anyhow::Result<()> {
        let existing_items = self
            .workspace
            .filtered_list_views
            .get(view_id)
            .map(|collection| {
                collection
                    .snapshot()
                    .items
                    .into_iter()
                    .map(|item| item.as_ref().clone())
                    .collect::<Vec<_>>()
            })
            .unwrap_or_default();
        let groups = self
            .filtered_list_groups
            .get_mut(view_id)
            .context("grouped list metadata is missing")?;
        let ordered = merge_grouped_inbox_page(existing_items, groups, page)?;
        self.workspace
            .filtered_list_views
            .entry(view_id.to_owned())
            .or_default()
            .replace(ordered, None);
        Ok(())
    }

    fn update_list_query(
        &mut self,
        view_id: &str,
        update: impl FnOnce(&mut ListQueryState),
        cx: &mut Context<Self>,
    ) {
        let state = self
            .list_query_states
            .entry(view_id.to_owned())
            .or_insert_with(|| {
                if view_id == "inbox" {
                    ListQueryState::inbox_default()
                } else {
                    ListQueryState::default()
                }
            });
        update(state);
        self.active_list_saved_view_ids.remove(view_id);
        self.filtered_list_loading.remove(view_id);
        self.filtered_list_loading_more.remove(view_id);
        self.filtered_group_loading_more
            .retain(|key| !key.starts_with(&format!("{view_id}\0")));
        self.filtered_list_groups.remove(view_id);
        self.workspace.filtered_list_views.remove(view_id);
        self.list_interactions.remove(view_id);
        if view_id == "tasks" {
            self.task_selected_ids.clear();
        }
        self.filtered_list_generations
            .entry(view_id.to_owned())
            .and_modify(|generation| *generation = generation.wrapping_add(1))
            .or_insert(1);
        self.persist_preferences(cx);
        if view_id == "inbox" {
            self.inbox_interaction = ListInteraction::default();
            self.load_inbox_view(true, cx);
        } else if self.list_query_uses_server(view_id) {
            self.load_filtered_list_view(view_id.to_owned(), true, cx);
        }
        cx.notify();
    }

