    fn toggle_mail_link_filter(&mut self, view_id: &str, link_id: String, cx: &mut Context<Self>) {
        self.update_list_query(
            view_id,
            |state| {
                if let Some(index) = state
                    .email_link_ids
                    .iter()
                    .position(|candidate| candidate == &link_id)
                {
                    state.email_link_ids.remove(index);
                } else {
                    state.email_link_ids.push(link_id);
                    state.email_link_ids.sort();
                    state.email_link_ids.dedup();
                }
            },
            cx,
        );
    }

    fn clear_mail_link_filters(&mut self, view_id: &str, cx: &mut Context<Self>) {
        self.update_list_query(view_id, |state| state.email_link_ids.clear(), cx);
    }

    fn cycle_list_sort(&mut self, view_id: &str, cx: &mut Context<Self>) {
        self.update_list_query(
            view_id,
            |state| {
                let available: &[ListSort] = if state.grouping == ListGrouping::None {
                    &ListSort::ALL
                } else {
                    &[ListSort::UpdatedDesc, ListSort::CreatedDesc]
                };
                let index = available
                    .iter()
                    .position(|sort| *sort == state.sort)
                    .unwrap_or_default();
                state.sort = available[(index + 1) % available.len()];
            },
            cx,
        );
    }

    fn cycle_list_grouping(&mut self, view_id: &str, cx: &mut Context<Self>) {
        self.update_list_query(
            view_id,
            |state| {
                let available = ListGrouping::available_for(view_id);
                let index = available
                    .iter()
                    .position(|grouping| *grouping == state.grouping)
                    .unwrap_or_default();
                state.grouping = available[(index + 1) % available.len()];
                if state.grouping != ListGrouping::None {
                    state.sort = match state.sort {
                        ListSort::CreatedAsc | ListSort::CreatedDesc => ListSort::CreatedDesc,
                        ListSort::UpdatedAsc | ListSort::UpdatedDesc => ListSort::UpdatedDesc,
                    };
                }
            },
            cx,
        );
    }

    fn reset_list_query(&mut self, view_id: &str, cx: &mut Context<Self>) {
        self.update_list_query(
            view_id,
            |state| {
                *state = if view_id == "inbox" {
                    ListQueryState::inbox_default()
                } else {
                    ListQueryState::default()
                }
            },
            cx,
        );
    }

