    fn load_inbox_view(&mut self, show_loading: bool, cx: &mut Context<Self>) {
        if self.workspace.inbox_view.is_loading() {
            return;
        }
        self.workspace.inbox_view.begin_load(!show_loading);
        self.inbox_view_generation = self.inbox_view_generation.wrapping_add(1);
        let generation = self.inbox_view_generation;
        let tab = self.inbox_tab;
        let read_filter = self.list_query_state("inbox").read_filter;
        let signal_since = inbox_signal_since_now();
        let request = inbox_soup_request(tab, read_filter, &signal_since);
        self.metrics.record_top_level_request();
        let api = self.api.clone();
        cx.spawn(async move |this, cx| {
            let result = api
                .list_soup_ast_items(&request, None)
                .await
                .and_then(parse_soup_page);
            this.update(cx, |this, cx| {
                if this.inbox_view_generation != generation
                    || this.inbox_tab != tab
                    || this.list_query_state("inbox").read_filter != read_filter
                {
                    return;
                }
                match result {
                    Ok(page) => this
                        .workspace
                        .inbox_view
                        .replace(page.items, page.next_cursor),
                    Err(error) => this.workspace.inbox_view.fail(error.to_string()),
                }
                this.update_primary_connection_status();
                cx.notify();
            })?;
            anyhow::Ok(())
        })
        .detach();
        cx.notify();
    }

