    fn load_notification_settings(&mut self, force: bool, cx: &mut Context<Self>) {
        let preferences_ready = matches!(
            self.workspace.notification_preferences,
            DataState::Loaded(_) | DataState::Loading
        );
        let unsubscribes_ready = matches!(
            self.workspace.notification_unsubscribes,
            DataState::Loaded(_) | DataState::Loading
        );
        if !force && preferences_ready && unsubscribes_ready {
            return;
        }
        self.workspace.notification_preferences = DataState::Loading;
        self.workspace.notification_unsubscribes = DataState::Loading;
        let api = self.api.clone();
        cx.spawn(async move |this, cx| {
            let (preferences, unsubscribes) = futures::join!(
                api.get_notification_type_preferences(),
                api.list_notification_unsubscribes()
            );
            this.update(cx, |this, cx| {
                this.workspace.notification_preferences = match preferences {
                    Ok(preferences) => DataState::Loaded(preferences),
                    Err(error) => DataState::Failed(error.to_string()),
                };
                this.workspace.notification_unsubscribes = match unsubscribes {
                    Ok(unsubscribes) => DataState::Loaded(unsubscribes),
                    Err(error) => DataState::Failed(error.to_string()),
                };
                cx.notify();
            })?;
            anyhow::Ok(())
        })
        .detach();
        cx.notify();
    }

