    fn apply_crm_default_view_if_ready(&mut self) {
        if self.crm_default_view_applied
            || matches!(
                self.workspace.saved_views,
                DataState::Idle | DataState::Loading
            )
            || matches!(
                self.workspace.crm_team_settings,
                DataState::Idle | DataState::Loading
            )
        {
            return;
        }
        self.crm_default_view_applied = true;

        if let Some(view) = self.workspace.saved_views.loaded().and_then(|response| {
            response.views.iter().find(|view| {
                view.config.get("kind").and_then(serde_json::Value::as_str) == Some("crm")
                    && view
                        .config
                        .get("isDefault")
                        .and_then(serde_json::Value::as_bool)
                        == Some(true)
            })
        }) {
            let id = view.id.clone();
            let config = view.config.clone();
            self.apply_crm_view_config(Some(id), Some(CrmSavedViewScope::Personal), &config);
            return;
        }

        let Some(settings) = self.workspace.crm_team_settings.loaded() else {
            return;
        };
        let Some(default_id) = settings.default_team_view_id.as_deref() else {
            return;
        };
        let Ok(views) =
            serde_json::from_value::<Vec<TeamCrmSavedView>>(settings.team_views.clone())
        else {
            return;
        };
        if let Some(view) = views.into_iter().find(|view| view.id == default_id) {
            self.apply_crm_view_config(Some(view.id), Some(CrmSavedViewScope::Team), &view.config);
        }
    }

