    fn load_scheduled_email_drafts(&mut self, show_loading: bool, cx: &mut Context<Self>) {
        if !show_loading
            && matches!(
                self.workspace.scheduled_email_drafts,
                DataState::Loading | DataState::Loaded(_)
            )
        {
            return;
        }
        let mut link_ids = self
            .workspace
            .email_links
            .loaded()
            .map(|response| response.links.as_slice())
            .into_iter()
            .flatten()
            .map(|link| link.id.clone())
            .collect::<Vec<_>>();
        link_ids.sort();
        link_ids.dedup();
        self.workspace.scheduled_email_drafts = DataState::Loading;
        self.metrics.record_top_level_request();
        let api = self.api.clone();
        cx.spawn(async move |this, cx| {
            let result = async {
                let mut messages = Vec::new();
                if link_ids.is_empty() {
                    messages.extend(api.list_scheduled_email_drafts(1000, 0).await?.messages);
                } else {
                    for link_id in &link_ids {
                        messages.extend(
                            api.list_scheduled_email_drafts_for_link(1000, 0, Some(link_id))
                                .await?
                                .messages,
                        );
                    }
                }
                messages.sort_by(|left, right| {
                    left.scheduled_send_time.cmp(&right.scheduled_send_time)
                });
                messages.dedup_by(|left, right| left.db_id == right.db_id);
                anyhow::Ok(messages)
            }
            .await;
            this.update(cx, |this, cx| {
                this.workspace.scheduled_email_drafts = result
                    .map(DataState::Loaded)
                    .unwrap_or_else(|error| DataState::Failed(error.to_string()));
                cx.notify();
            })?;
            anyhow::Ok(())
        })
        .detach();
    }

