    fn complete_native_onboarding(&mut self, skipped: bool, cx: &mut Context<Self>) {
        let api = self.api.clone();
        self.session_notice = Some(if skipped {
            "Skipping setup…".into()
        } else {
            "Finishing setup…".into()
        });
        cx.spawn(async move |this, cx| {
            let result = api.complete_onboarding(skipped).await;
            let tutorial_result = if result.is_ok() {
                api.patch_user_tutorial(true).await
            } else {
                Ok(())
            };
            this.update(cx, |this, cx| {
                match (result, tutorial_result) {
                    (Ok(row), Ok(())) => {
                        if let DataState::Loaded(state) = &mut this.workspace.onboarding {
                            state.row = row;
                        } else {
                            this.workspace.onboarding = DataState::Idle;
                        }
                        this.session_notice = Some(if skipped {
                            "Setup skipped. You can still configure every service from Settings and Integrations."
                                .into()
                        } else {
                            "Setup completed".into()
                        });
                    }
                    (Ok(row), Err(error)) => {
                        if let DataState::Loaded(state) = &mut this.workspace.onboarding {
                            state.row = row;
                        }
                        this.session_notice = Some(format!(
                            "Setup was saved, but its legacy completion flag could not be synchronized: {error}. Use Repair setup state to retry."
                        ));
                    }
                    (Err(error), _) => {
                        this.session_notice = Some(format!("Setup could not be completed: {error}"));
                    }
                }
                cx.notify();
            })?;
            anyhow::Ok(())
        })
        .detach();
        cx.notify();
    }

    fn load_import_state(&mut self, show_loading: bool, cx: &mut Context<Self>) {
        if self.import_state_loading || !matches!(self.session, SessionState::Ready { .. }) {
            return;
        }
        self.import_state_loading = true;
        if show_loading || !matches!(self.workspace.import_state, DataState::Loaded(_)) {
            self.workspace.import_state = DataState::Loading;
        }
        self.metrics.record_top_level_request();
        let api = self.api.clone();
        cx.spawn(async move |this, cx| {
            let result = api.get_import_state().await;
            this.update(cx, |this, cx| {
                this.import_state_loading = false;
                let should_poll = result
                    .as_ref()
                    .is_ok_and(|state| state.anything_in_flight());
                match result {
                    Ok(state) => {
                        this.import_state_error = None;
                        this.workspace.import_state = DataState::Loaded(state);
                    }
                    Err(error) => {
                        let error = error.to_string();
                        this.import_state_error = Some(error.clone());
                        if !matches!(this.workspace.import_state, DataState::Loaded(_)) {
                            this.workspace.import_state = DataState::Failed(error);
                        }
                    }
                }
                if should_poll {
                    this.schedule_import_poll(cx);
                }
                cx.notify();
            })?;
            anyhow::Ok(())
        })
        .detach();
        cx.notify();
    }

    fn schedule_import_poll(&mut self, cx: &mut Context<Self>) {
        if self.import_poll_scheduled {
            return;
        }
        self.import_poll_scheduled = true;
        cx.spawn(async move |this, cx| {
            cx.background_executor().timer(Duration::from_secs(3)).await;
            this.update(cx, |this, cx| {
                this.import_poll_scheduled = false;
                let should_poll = matches!(this.session, SessionState::Ready { .. })
                    && this
                        .workspace
                        .import_state
                        .loaded()
                        .is_some_and(|state| state.anything_in_flight());
                if should_poll {
                    this.load_import_state(false, cx);
                }
            })?;
            anyhow::Ok(())
        })
        .detach();
    }

    fn run_import_entities(
        &mut self,
        import_ids: Vec<String>,
        discard_ids: Vec<String>,
        cx: &mut Context<Self>,
    ) {
        if import_ids.is_empty() && discard_ids.is_empty() {
            return;
        }
        let ids = import_ids
            .iter()
            .chain(&discard_ids)
            .cloned()
            .collect::<Vec<_>>();
        if ids
            .iter()
            .any(|id| self.import_mutations.contains(id.as_str()))
        {
            return;
        }
        self.import_mutations.extend(ids.iter().cloned());
        let import_id_set = import_ids.iter().cloned().collect::<HashSet<_>>();
        let discard_id_set = discard_ids.iter().cloned().collect::<HashSet<_>>();
        let previous_statuses = self
            .workspace
            .import_state
            .loaded()
            .map(|state| {
                state
                    .entities
                    .iter()
                    .filter(|entity| {
                        import_id_set.contains(&entity.id) || discard_id_set.contains(&entity.id)
                    })
                    .map(|entity| (entity.id.clone(), entity.status))
                    .collect::<HashMap<_, _>>()
            })
            .unwrap_or_default();
        if let Some(state) = self.workspace.import_state.loaded().cloned() {
            let mut optimistic = state;
            for entity in &mut optimistic.entities {
                if import_id_set.contains(&entity.id) {
                    entity.status = ImportEntityStatus::Importing;
                } else if discard_id_set.contains(&entity.id) {
                    entity.status = ImportEntityStatus::Discarded;
                }
            }
            self.workspace.import_state = DataState::Loaded(optimistic);
        }
        self.session_notice = Some(if discard_ids.is_empty() {
            format!("Importing {} workspace item(s)…", import_ids.len())
        } else if import_ids.is_empty() {
            format!("Discarding {} import item(s)…", discard_ids.len())
        } else {
            "Updating workspace imports…".into()
        });
        let request = RunImportRequest {
            discard_ids,
            import_ids,
        };
        let api = self.api.clone();
        cx.spawn(async move |this, cx| {
            let result = api.run_import(&request).await;
            this.update(cx, |this, cx| {
                for id in &ids {
                    this.import_mutations.remove(id);
                }
                match result {
                    Ok(outcome) => {
                        this.session_notice = Some(format!(
                            "{} importing · {} discarded",
                            outcome.importing, outcome.discarded
                        ));
                        this.load_import_state(false, cx);
                    }
                    Err(error) => {
                        if let DataState::Loaded(state) = &mut this.workspace.import_state {
                            for entity in &mut state.entities {
                                let expected = if import_id_set.contains(&entity.id) {
                                    Some(ImportEntityStatus::Importing)
                                } else if discard_id_set.contains(&entity.id) {
                                    Some(ImportEntityStatus::Discarded)
                                } else {
                                    None
                                };
                                if expected == Some(entity.status)
                                    && let Some(previous) = previous_statuses.get(&entity.id)
                                {
                                    entity.status = *previous;
                                }
                            }
                        }
                        this.session_notice = Some(format!("Import update failed: {error}"));
                    }
                }
                cx.notify();
            })?;
            anyhow::Ok(())
        })
        .detach();
        cx.notify();
    }

    fn update_import_run(&mut self, source: ImportSource, dismiss: bool, cx: &mut Context<Self>) {
        let mutation_key = format!(
            "{}:{}",
            source.as_str(),
            if dismiss { "dismiss" } else { "retry" }
        );
        if !self.import_mutations.insert(mutation_key.clone()) {
            return;
        }
        let previous = self.workspace.import_state.loaded().and_then(|state| {
            state
                .runs
                .iter()
                .find(|run| run.source == source)
                .map(|run| (run.status, run.error.clone()))
        });
        let optimistic_status = if dismiss {
            ImportRunStatus::Dismissed
        } else {
            ImportRunStatus::Running
        };
        if let Some(state) = self.workspace.import_state.loaded().cloned() {
            let mut optimistic = state;
            if let Some(run) = optimistic.runs.iter_mut().find(|run| run.source == source) {
                run.status = optimistic_status;
                run.error = None;
            }
            self.workspace.import_state = DataState::Loaded(optimistic);
        }
        self.session_notice = Some(format!(
            "{} {} import…",
            if dismiss { "Dismissing" } else { "Retrying" },
            source.display_name()
        ));
        let api = self.api.clone();
        cx.spawn(async move |this, cx| {
            let result = if dismiss {
                api.dismiss_import_run(source).await
            } else {
                api.retry_import_gather(source).await
            };
            this.update(cx, |this, cx| {
                this.import_mutations.remove(&mutation_key);
                match result {
                    Ok(()) => {
                        this.session_notice = Some(format!(
                            "{} import {}",
                            source.display_name(),
                            if dismiss {
                                "dismissed"
                            } else {
                                "retry started"
                            }
                        ));
                        this.load_import_state(false, cx);
                    }
                    Err(error) => {
                        if let Some((status, run_error)) = previous
                            && let DataState::Loaded(state) = &mut this.workspace.import_state
                            && let Some(run) =
                                state.runs.iter_mut().find(|run| run.source == source)
                            && run.status == optimistic_status
                        {
                            run.status = status;
                            run.error = run_error;
                        }
                        this.session_notice = Some(format!(
                            "Could not update {} import: {error}",
                            source.display_name()
                        ));
                    }
                }
                cx.notify();
            })?;
            anyhow::Ok(())
        })
        .detach();
        cx.notify();
    }

