    fn load_bots(&mut self, show_loading: bool, cx: &mut Context<Self>) {
        if !show_loading
            && matches!(
                self.workspace.bots,
                DataState::Loading | DataState::Loaded(_)
            )
        {
            return;
        }
        self.workspace.bots = DataState::Loading;
        self.metrics.record_top_level_request();
        let api = self.api.clone();
        cx.spawn(async move |this, cx| {
            let result = api.list_bots().await;
            let related = match &result {
                Ok(bots) => {
                    let bot_ids = bots.iter().map(|bot| bot.id.clone()).collect::<Vec<_>>();
                    let api_for_channels = api.clone();
                    let api_for_tokens = api.clone();
                    let (channels, tokens) = futures::join!(
                        futures::future::join_all(bot_ids.iter().map(|bot_id| {
                            let api = api_for_channels.clone();
                            let bot_id = bot_id.clone();
                            async move { (bot_id.clone(), api.list_bot_channels(&bot_id).await) }
                        })),
                        futures::future::join_all(bot_ids.iter().map(|bot_id| {
                            let api = api_for_tokens.clone();
                            let bot_id = bot_id.clone();
                            async move { (bot_id.clone(), api.list_bot_tokens(&bot_id).await) }
                        })),
                    );
                    Some((channels, tokens))
                }
                Err(_) => None,
            };
            this.update(cx, |this, cx| {
                if let Some((channels, tokens)) = related {
                    for (bot_id, result) in channels {
                        this.workspace.bot_channels.insert(
                            bot_id,
                            result
                                .map(DataState::Loaded)
                                .unwrap_or_else(|error| DataState::Failed(error.to_string())),
                        );
                    }
                    for (bot_id, result) in tokens {
                        this.workspace.bot_tokens.insert(
                            bot_id,
                            result
                                .map(DataState::Loaded)
                                .unwrap_or_else(|error| DataState::Failed(error.to_string())),
                        );
                    }
                }
                this.workspace.bots = result
                    .map(DataState::Loaded)
                    .unwrap_or_else(|error| DataState::Failed(error.to_string()));
                cx.notify();
            })?;
            anyhow::Ok(())
        })
        .detach();
    }

