    fn load_people_cache(&mut self, force: bool, cx: &mut Context<Self>) {
        if !force
            && matches!(
                self.workspace.contacts,
                DataState::Loading | DataState::Loaded(_)
            )
            && matches!(
                self.workspace.user_names,
                DataState::Loading | DataState::Loaded(_)
            )
        {
            return;
        }
        self.workspace.contacts = DataState::Loading;
        self.workspace.user_names = DataState::Loading;
        let current_user_id = match &self.session {
            SessionState::Ready { user } => Some(user.user_id.clone()),
            _ => None,
        };
        let team_user_ids = self
            .workspace
            .team
            .loaded()
            .and_then(Option::as_ref)
            .map(|team| {
                team.members
                    .iter()
                    .map(|member| member.user_id.clone())
                    .collect::<Vec<_>>()
            })
            .unwrap_or_default();
        let api = self.api.clone();
        cx.spawn(async move |this, cx| {
            let contacts = api.list_contacts().await;
            let mut user_ids = team_user_ids;
            if let Some(current_user_id) = current_user_id {
                user_ids.push(current_user_id);
            }
            if let Ok(contacts) = &contacts {
                user_ids.extend(contacts.contacts.iter().cloned());
            }
            user_ids.sort();
            user_ids.dedup();
            let names = if user_ids.is_empty() {
                Ok(macro_api::UserNamesResponse { names: Vec::new() })
            } else {
                api.get_user_names_with_email(user_ids).await
            };
            this.update(cx, |this, cx| {
                this.workspace.contacts = contacts
                    .map(DataState::Loaded)
                    .unwrap_or_else(|error| DataState::Failed(error.to_string()));
                this.workspace.user_names = names
                    .map(|response| {
                        DataState::Loaded(
                            response
                                .names
                                .into_iter()
                                .map(|name| (name.id.clone(), name))
                                .collect(),
                        )
                    })
                    .unwrap_or_else(|error| DataState::Failed(error.to_string()));
                cx.notify();
            })?;
            anyhow::Ok(())
        })
        .detach();
    }

    fn user_display_name(&self, user_id: &str, fallback: &str) -> String {
        self.workspace
            .user_names
            .loaded()
            .and_then(|names| names.get(user_id))
            .map(user_name_label)
            .filter(|name| !name.is_empty())
            .unwrap_or_else(|| fallback_user_label(fallback))
    }

    fn known_inbox_entity(
        &self,
        entity_type: EntityType,
        entity_id: &str,
    ) -> Option<Arc<InboxItem>> {
        self.open_entities
            .values()
            .find_map(|entity| match entity {
                OpenEntity::Inbox(item)
                    if item.entity_type == entity_type && item.id == entity_id =>
                {
                    Some(Arc::clone(item))
                }
                OpenEntity::Inbox(_) | OpenEntity::Channel(_) => None,
            })
            .or_else(|| {
                [
                    &self.workspace.inbox,
                    &self.workspace.recent,
                    &self.workspace.search_results,
                ]
                .into_iter()
                .find_map(|collection| {
                    collection
                        .get(entity_id)
                        .filter(|item| item.entity_type == entity_type)
                })
            })
    }

    fn entity_reference_label(&self, entity_type: EntityType, entity_id: &str) -> String {
        if entity_type == EntityType::User {
            return self.user_display_name(entity_id, "Workspace member");
        }
        if entity_type == EntityType::Channel {
            return self
                .workspace
                .channels
                .get(entity_id)
                .map(|channel| format!("#{}", channel.name))
                .unwrap_or_else(|| "Channel".into());
        }
        if entity_type == EntityType::Project {
            return self
                .workspace
                .projects
                .loaded()
                .and_then(|projects| projects.iter().find(|project| project.id == entity_id))
                .map(|project| project.name.clone())
                .unwrap_or_else(|| "Project".into());
        }
        self.known_inbox_entity(entity_type, entity_id)
            .map(|item| item.title.clone())
            .filter(|title| !title.trim().is_empty())
            .unwrap_or_else(|| entity_reference_fallback_label(entity_type).into())
    }

    fn open_linked_entity(
        &mut self,
        entity_type: EntityType,
        entity_id: String,
        cx: &mut Context<Self>,
    ) {
        if entity_type == EntityType::Channel {
            if let Some(channel) = self.workspace.channels.get(&entity_id) {
                self.open_entity(OpenEntity::Channel(channel), cx);
            } else {
                self.layout_state.active_section = NavSection::Channels;
                self.session_notice = Some(
                    "That channel is not in the loaded workspace. Refresh Channels to open it."
                        .into(),
                );
                cx.notify();
            }
            return;
        }
        if entity_type == EntityType::Project {
            if self
                .workspace
                .projects
                .loaded()
                .is_some_and(|projects| projects.iter().any(|project| project.id == entity_id))
            {
                self.layout_state.active_section = NavSection::Files;
                self.select_project(entity_id, cx);
            } else {
                self.layout_state.active_section = NavSection::Files;
                self.session_notice = Some(
                    "That project is not in the loaded workspace. Refresh Files to open it.".into(),
                );
                cx.notify();
            }
            return;
        }
        if entity_type == EntityType::User {
            let label = self.entity_reference_label(entity_type, &entity_id);
            self.session_notice = Some(format!("{label} is a workspace member"));
            cx.notify();
            return;
        }
        if let Some(item) = self.known_inbox_entity(entity_type, &entity_id) {
            self.open_entity(OpenEntity::Inbox(item), cx);
            return;
        }

        let label = self.entity_reference_label(entity_type, &entity_id);
        if entity_type_supports_direct_detail(entity_type) {
            self.open_entity(
                OpenEntity::Inbox(Arc::new(InboxItem {
                    id: entity_id,
                    tag: entity_type_soup_tag(entity_type).into(),
                    sub_type: None,
                    entity_type,
                    title: label,
                    subtitle: String::new(),
                    timestamp: String::new(),
                    raw: serde_json::Value::Null,
                })),
                cx,
            );
        } else {
            self.layout_state.active_section = NavSection::Search;
            self.session_notice = Some(format!(
                "{label} is not cached yet. Search can load the full record."
            ));
            cx.notify();
        }
    }

