    fn search_facets(&self) -> ListQueryState {
        self.list_query_state("search")
    }

    fn visible_search_results(&self) -> Vec<Arc<InboxItem>> {
        let facets = self.search_facets();
        self.workspace
            .search_results
            .snapshot()
            .items
            .into_iter()
            .filter(|item| search_scope_matches(facets.search_scope, item))
            .collect()
    }

    fn open_focused_search_result(&mut self, fullscreen: bool, cx: &mut Context<Self>) -> bool {
        let items = self.visible_search_results();
        let Some(item) = self
            .search_interaction
            .focused()
            .and_then(|index| items.get(index))
            .cloned()
        else {
            return false;
        };
        self.open_entity_with_mode(OpenEntity::Inbox(item), fullscreen, cx);
        true
    }

    fn run_unified_search(
        &mut self,
        _: &RunUnifiedSearch,
        _window: &mut Window,
        cx: &mut Context<Self>,
    ) {
        if !self.open_focused_search_result(true, cx) {
            self.load_search(false, cx);
        }
        cx.stop_propagation();
        cx.notify();
    }

    fn open_search_result_split(
        &mut self,
        _: &OpenSearchResultSplit,
        _window: &mut Window,
        cx: &mut Context<Self>,
    ) {
        if !self.open_focused_search_result(false, cx) {
            self.load_search(false, cx);
        }
        cx.stop_propagation();
        cx.notify();
    }

    fn select_next_search_result(
        &mut self,
        _: &SelectNextSearchResult,
        window: &mut Window,
        cx: &mut Context<Self>,
    ) {
        let result_count = self.visible_search_results().len();
        self.search_interaction.move_next(result_count);
        if result_count > 0 {
            window.focus(&self.search_results_focus_handle, cx);
        }
        cx.stop_propagation();
        cx.notify();
    }

    fn select_previous_search_result(
        &mut self,
        _: &SelectPreviousSearchResult,
        window: &mut Window,
        cx: &mut Context<Self>,
    ) {
        let result_count = self.visible_search_results().len();
        self.search_interaction.move_previous(result_count);
        if result_count > 0 {
            window.focus(&self.search_results_focus_handle, cx);
        }
        cx.stop_propagation();
        cx.notify();
    }

    fn update_search_facets(
        &mut self,
        update: impl FnOnce(&mut ListQueryState),
        cx: &mut Context<Self>,
    ) {
        update(self.list_query_states.entry("search".into()).or_default());
        self.workspace.search_results = Default::default();
        self.search_loading_more = false;
        self.search_generation = self.search_generation.wrapping_add(1);
        self.persist_preferences(cx);
        if self.search_query.trim().chars().count() >= 3 {
            self.load_search(false, cx);
        }
        cx.notify();
    }

    fn set_search_scope(&mut self, scope: SearchScope, cx: &mut Context<Self>) {
        self.update_search_facets(|state| state.search_scope = scope, cx);
    }

    fn toggle_search_tag(&mut self, tag: TagFilter, cx: &mut Context<Self>) {
        self.update_search_facets(|state| state.toggle_tag(tag), cx);
    }

    fn cycle_search_tag_mode(&mut self, cx: &mut Context<Self>) {
        self.update_search_facets(|state| state.tag_mode = state.tag_mode.toggle(), cx);
    }

    fn open_search_people(&mut self, cx: &mut Context<Self>) {
        self.open_mutation_dialog(
            MutationDialog::new(
                "Search people",
                "Apply",
                MutationKind::SetSearchPeople,
                vec![Self::mutation_field(
                    "User IDs or @mentions (comma separated)",
                    self.search_facets().mentioned_people.join(", "),
                    false,
                )],
            ),
            cx,
        );
    }

    fn invalidate_search_results(&mut self) {
        self.workspace.search_results = Default::default();
        self.search_interaction = ListInteraction::default();
        self.search_loading_more = false;
        self.search_generation = self.search_generation.wrapping_add(1);
    }

    fn load_search(&mut self, load_more: bool, cx: &mut Context<Self>) {
        let query = self.search_query.trim().to_owned();
        if query.chars().count() < 3 {
            self.workspace.search_results = Default::default();
            self.session_notice = Some("Search requires at least 3 characters.".into());
            cx.notify();
            return;
        }
        let cursor = if load_more {
            let Some(cursor) = self
                .workspace
                .search_results
                .next_cursor()
                .map(ToOwned::to_owned)
            else {
                return;
            };
            self.search_loading_more = true;
            Some(cursor)
        } else {
            self.workspace.search_results.begin_load(false);
            self.search_interaction = ListInteraction::default();
            self.search_generation = self.search_generation.wrapping_add(1);
            None
        };
        let generation = self.search_generation;
        let facets = self.search_facets();
        self.metrics.record_top_level_request();
        let api = self.api.clone();
        cx.spawn(async move |this, cx| {
            let request = unified_search_request(&query, &facets);
            let result = api
                .search(&request, 40, cursor.as_deref())
                .await
                .and_then(parse_search_page);
            this.update(cx, |this, cx| {
                if this.search_generation != generation {
                    return;
                }
                this.search_loading_more = false;
                match result {
                    Ok(page) if load_more => this
                        .workspace
                        .search_results
                        .append(page.items, page.next_cursor),
                    Ok(page) => this
                        .workspace
                        .search_results
                        .replace(page.items, page.next_cursor),
                    Err(error) => this.workspace.search_results.fail(error.to_string()),
                }
                cx.notify();
            })?;
            anyhow::Ok(())
        })
        .detach();
        cx.notify();
    }

    fn update_primary_connection_status(&mut self) {
        self.layout_state.connection_status = if matches!(
            (
                self.workspace.inbox.status(),
                self.workspace.channels.status()
            ),
            (LoadStatus::Failed(_), LoadStatus::Failed(_))
        ) {
            ConnectionStatus::Disconnected
        } else if self.workspace.inbox.is_ready() || self.workspace.channels.is_ready() {
            ConnectionStatus::Connected
        } else {
            ConnectionStatus::Connecting
        };
    }

    fn sync_open_inbox_records(&mut self) {
        for (tab_id, entity) in &mut self.open_entities {
            let OpenEntity::Inbox(current) = entity else {
                continue;
            };
            let Some(updated) = self.workspace.inbox.get(&current.id) else {
                continue;
            };
            *current = Arc::clone(&updated);
            if let Some(tab) = self
                .layout_state
                .tabs
                .iter_mut()
                .find(|tab| &tab.entity_id == tab_id)
            {
                tab.label = updated.title.clone().into();
            }
        }
    }

    fn sync_open_channel_records(&mut self) {
        for (tab_id, entity) in &mut self.open_entities {
            let OpenEntity::Channel(current) = entity else {
                continue;
            };
            let Some(updated) = self.workspace.channels.get(&current.id) else {
                continue;
            };
            *current = Arc::clone(&updated);
            if let Some(tab) = self
                .layout_state
                .tabs
                .iter_mut()
                .find(|tab| &tab.entity_id == tab_id)
            {
                tab.label = updated.name.clone().into();
            }
        }
    }

    fn apply_reconcile_plan(&mut self, plan: ReconcilePlan, cx: &mut Context<Self>) {
        for target in plan.targets() {
            match target {
                ReconcileTarget::Inbox => self.load_inbox(false, cx),
                ReconcileTarget::Channels => self.load_channels(false, cx),
                ReconcileTarget::ChannelMessages(channel_id) => {
                    let is_open = self.open_entities.values().any(|entity| {
                        matches!(entity, OpenEntity::Channel(channel) if channel.id == *channel_id)
                    });
                    if is_open {
                        self.refresh_channel_messages(channel_id.clone(), cx);
                    }
                    if let Some((active_channel_id, thread_id)) = self.active_channel_thread.clone()
                        && &active_channel_id == channel_id
                    {
                        self.load_channel_thread(active_channel_id, thread_id, true, cx);
                    }
                }
                ReconcileTarget::DocumentComments(document_id) => {
                    if self.workspace.document_comments.contains_key(document_id)
                        || self.document_editors.contains_key(document_id)
                    {
                        self.workspace.document_comments.remove(document_id);
                        self.load_document_comments(document_id.clone(), true, cx);
                    }
                }
                ReconcileTarget::ActiveCalls => self.load_active_calls(false, cx),
                ReconcileTarget::EmailLinks => self.load_email_links(false, cx),
                ReconcileTarget::MailViews => self.refresh_loaded_mail_views(cx),
                ReconcileTarget::Contacts => self.load_people_cache(true, cx),
                ReconcileTarget::Notifications => self.load_notifications(false, cx),
                ReconcileTarget::Favorites => self.load_favorites(true, cx),
                ReconcileTarget::PropertyDefinitions => self.load_property_definitions(true, cx),
                ReconcileTarget::StarterDocuments => self.load_starter_documents(true, cx),
                ReconcileTarget::Imports => self.load_import_state(false, cx),
                ReconcileTarget::EntityType(entity_type) => {
                    let prefix = format!("{entity_type}:");
                    self.workspace
                        .entity_details
                        .retain(|key, _| !key.starts_with(&prefix));
                    if let Some(OpenEntity::Inbox(item)) = self.active_entity().cloned()
                        && item.entity_type == *entity_type
                    {
                        let is_task = item.entity_type == EntityType::Document
                            && item.sub_type.as_deref() == Some("task");
                        let item_id = item.id.clone();
                        self.load_entity_detail(item, cx);
                        if is_task {
                            self.workspace.task_duplicates.remove(&item_id);
                            self.workspace.task_github_pull_requests.remove(&item_id);
                            self.load_task_duplicates(item_id.clone(), true, cx);
                            self.load_task_github_pull_requests(item_id, true, cx);
                        }
                    }
                }
                ReconcileTarget::Entity {
                    entity_type,
                    entity_id,
                } => {
                    let key = format!("{entity_type}:{entity_id}");
                    self.workspace.entity_details.remove(&key);
                    if let Some(OpenEntity::Inbox(item)) = self.active_entity().cloned()
                        && item.entity_type == *entity_type
                        && item.id == *entity_id
                    {
                        let is_task = item.entity_type == EntityType::Document
                            && item.sub_type.as_deref() == Some("task");
                        let item_id = item.id.clone();
                        self.load_entity_detail(item, cx);
                        if is_task {
                            self.workspace.task_duplicates.remove(&item_id);
                            self.workspace.task_github_pull_requests.remove(&item_id);
                            self.load_task_duplicates(item_id.clone(), true, cx);
                            self.load_task_github_pull_requests(item_id, true, cx);
                        }
                    }
                }
            }
        }
    }

    /// Recover the channel surfaces that can have missed gateway frames while
    /// the socket was disconnected. This deliberately does not invalidate the
    /// rest of the workspace: the channel index and each currently open
    /// timeline are authoritative refreshes, and an active thread is refreshed
    /// by the corresponding `ChannelMessages` target.
    fn reconcile_open_channels_after_reconnect(&mut self, cx: &mut Context<Self>) {
        let mut channel_ids = self
            .open_entities
            .values()
            .filter_map(|entity| match entity {
                OpenEntity::Channel(channel) => Some(channel.id.clone()),
                _ => None,
            })
            .collect::<Vec<_>>();
        if let Some((channel_id, _)) = &self.active_channel_thread {
            channel_ids.push(channel_id.clone());
        }
        channel_ids.sort();
        channel_ids.dedup();

        let mut document_ids = self
            .workspace
            .document_comments
            .keys()
            .chain(self.document_editors.keys())
            .cloned()
            .collect::<Vec<_>>();
        document_ids.sort();
        document_ids.dedup();

        let mut targets = Vec::with_capacity(channel_ids.len() + document_ids.len() + 1);
        targets.push(ReconcileTarget::Channels);
        targets.extend(
            channel_ids
                .into_iter()
                .map(ReconcileTarget::ChannelMessages),
        );
        targets.extend(
            document_ids
                .into_iter()
                .map(ReconcileTarget::DocumentComments),
        );
        self.apply_reconcile_plan(ReconcilePlan::new(targets), cx);
    }

    fn apply_agent_log_event(&mut self, event: AgentSessionLogEvent, cx: &mut Context<Self>) {
        let session_id = event.session_id;
        self.agent_log_buffers
            .entry(session_id.clone())
            .or_default()
            .push(event.entry);

        let key = format!("{}:{session_id}", EntityType::AgentSession);
        let detail_is_loaded = matches!(
            self.workspace.entity_details.get(&key),
            Some(DataState::Loaded(_))
        );
        if !detail_is_loaded {
            return;
        }

        let entries = self
            .agent_log_buffers
            .remove(&session_id)
            .unwrap_or_default();
        let retry_entries = entries.clone();
        let result = self
            .workspace
            .entity_details
            .get_mut(&key)
            .and_then(|state| match state {
                DataState::Loaded(detail) => Some(apply_agent_log_entries_to_detail(
                    detail,
                    &session_id,
                    entries,
                )),
                _ => None,
            });
        if let Some(Err(error)) = result {
            self.agent_log_buffers
                .entry(session_id)
                .or_default()
                .extend(retry_entries);
            self.session_notice = Some(format!(
                "A live agent update could not be reconciled: {error:#}"
            ));
        }
        cx.notify();
    }

    fn remove_soup_entity_from_lists(&mut self, entity_type: EntityType, entity_id: &str) {
        remove_inbox_entity(&mut self.workspace.inbox, entity_type, entity_id);
        remove_inbox_entity(&mut self.workspace.recent, entity_type, entity_id);
        remove_inbox_entity(&mut self.workspace.snippets, entity_type, entity_id);
        remove_inbox_entity(&mut self.workspace.inbox_view, entity_type, entity_id);
        remove_inbox_entity(&mut self.workspace.search_results, entity_type, entity_id);
        for collection in self.workspace.filtered_list_views.values_mut() {
            remove_inbox_entity(collection, entity_type, entity_id);
        }
        for collection in self.workspace.crm_emails.values_mut() {
            remove_inbox_entity(collection, entity_type, entity_id);
        }
        if entity_type == EntityType::Channel {
            self.workspace.channels.remove(entity_id);
            self.workspace.channel_messages.remove(entity_id);
            self.workspace.channel_participants.remove(entity_id);
            self.workspace.channel_bots.remove(entity_id);
        }
        if entity_type == EntityType::Reminder {
            self.workspace.reminders.remove(entity_id);
        }
    }

    fn handle_soup_realtime_patches(
        &mut self,
        patches: Vec<SoupRealtimePatch>,
        cx: &mut Context<Self>,
    ) {
        for patch in patches {
            match patch {
                SoupRealtimePatch::Updated {
                    entity_type,
                    entity_id,
                } => {
                    let key = format!("{entity_type}:{entity_id}");
                    self.soup_entity_tombstones.remove(&key);
                    let open_item = self.open_entities.values().find_map(|entity| match entity {
                        OpenEntity::Inbox(item)
                            if item.entity_type == entity_type && item.id == entity_id =>
                        {
                            Some(Arc::clone(item))
                        }
                        _ => None,
                    });
                    let open_channel = self.open_entities.values().any(|entity| {
                        matches!(entity, OpenEntity::Channel(channel)
                            if entity_type == EntityType::Channel && channel.id == entity_id)
                    });
                    let capabilities_cached = self.workspace.entity_permissions.contains_key(&key)
                        || self.workspace.entity_share_permissions.contains_key(&key)
                        || self.workspace.entity_properties.contains_key(&key)
                        || self.workspace.entity_backlinks.contains_key(&key);

                    if open_item.is_some() || open_channel || capabilities_cached {
                        self.load_entity_capabilities_targeted(
                            entity_type,
                            entity_id.clone(),
                            true,
                            true,
                            cx,
                        );
                    }
                    if let Some(item) = open_item {
                        self.workspace.entity_details.remove(&key);
                        self.load_entity_detail(item, cx);
                    }
                }
                SoupRealtimePatch::Deleted {
                    entity_type,
                    entity_id,
                } => {
                    let key = format!("{entity_type}:{entity_id}");
                    self.soup_entity_tombstones.insert(key.clone());
                    self.remove_soup_entity_from_lists(entity_type, &entity_id);
                    self.workspace.entity_details.remove(&key);
                    self.workspace.entity_share_permissions.remove(&key);
                    self.workspace.entity_properties.remove(&key);
                    self.workspace.entity_backlinks.remove(&key);
                    if permission_target_wire_type(entity_type).is_some() {
                        self.workspace
                            .entity_permissions
                            .insert(key, DataState::Loaded(EntityPermission::NoAccess));
                    }
                    if matches!(entity_type, EntityType::Document | EntityType::Skill) {
                        self.document_editors.remove(&entity_id);
                        self.document_searches.remove(&entity_id);
                        self.document_history_engines.remove(&entity_id);
                        self.document_history_previews.remove(&entity_id);
                        self.workspace.document_comments.remove(&entity_id);
                        self.canvas_models.remove(&entity_id);
                        self.canvas_remote_conflicts.remove(&entity_id);
                        self.stop_document_sync(&entity_id);
                    }
                }
            }
        }
        cx.notify();
    }

    fn start_soup_realtime(&mut self, generation: u64, cx: &mut Context<Self>) {
        let api = self.api.clone();
        let executor = cx.background_executor().clone();
        cx.spawn(async move |this, cx| {
            let mut retry_seconds = 1_u64;
            loop {
                let current = this.update(cx, |this, _| {
                    this.realtime_running && this.realtime_generation == generation
                })?;
                if !current {
                    return anyhow::Ok(());
                }

                match SoupUpdatesStream::connect(&api.soup_websocket_url()).await {
                    Ok(mut stream) => {
                        retry_seconds = 1;
                        this.update(cx, |this, cx| {
                            this.soup_realtime_error = None;
                            cx.notify();
                        })?;
                        loop {
                            match stream.recv().await {
                                Ok(Some(payload)) => {
                                    let patches = parse_soup_realtime_patches(&payload);
                                    if patches.is_empty() {
                                        continue;
                                    }
                                    this.update(cx, |this, cx| {
                                        if this.realtime_generation != generation {
                                            return;
                                        }
                                        this.last_realtime_event = Some("soup_updates".into());
                                        this.handle_soup_realtime_patches(patches, cx);
                                    })?;
                                }
                                Ok(None) => {
                                    this.update(cx, |this, _| {
                                        this.soup_realtime_error = Some(
                                            "Macro Soup subscription closed the socket".into(),
                                        );
                                    })?;
                                    break;
                                }
                                Err(error) => {
                                    this.update(cx, |this, _| {
                                        this.soup_realtime_error = Some(format!("{error:#}"));
                                    })?;
                                    break;
                                }
                            }
                        }
                    }
                    Err(error) => {
                        this.update(cx, |this, _| {
                            this.soup_realtime_error = Some(format!("{error:#}"));
                        })?;
                    }
                }

                let current = this.update(cx, |this, cx| {
                    let current = this.realtime_running && this.realtime_generation == generation;
                    if current {
                        cx.notify();
                    }
                    current
                })?;
                if !current {
                    return anyhow::Ok(());
                }
                executor.timer(Duration::from_secs(retry_seconds)).await;
                retry_seconds = (retry_seconds * 2).min(30);
            }
        })
        .detach();
    }

    fn start_realtime(&mut self, cx: &mut Context<Self>) {
        if self.realtime_running || self.api.token().is_none() {
            return;
        }
        self.realtime_running = true;
        self.realtime_generation = self.realtime_generation.wrapping_add(1);
        let generation = self.realtime_generation;
        self.start_soup_realtime(generation, cx);
        let api = self.api.clone();
        let executor = cx.background_executor().clone();
        cx.spawn(async move |this, cx| {
            let mut retry_seconds = 1_u64;
            let mut has_connected_once = false;
            loop {
                let current = this.update(cx, |this, _| {
                    this.realtime_running && this.realtime_generation == generation
                })?;
                if !current {
                    return anyhow::Ok(());
                }

                let url = api.websocket_url();
                match ConnectionStream::connect(&url).await {
                    Ok(mut stream) => {
                        let is_reconnect = has_connected_once;
                        has_connected_once = true;
                        retry_seconds = 1;
                        this.update(cx, |this, cx| {
                            this.layout_state.connection_status = ConnectionStatus::Connected;
                            this.realtime_error = None;
                            this.retry_pending_channel_messages(cx);
                            if is_reconnect {
                                this.reconcile_open_channels_after_reconnect(cx);
                            }
                            cx.notify();
                        })?;

                        loop {
                            enum SocketTick {
                                Message(anyhow::Result<Option<macro_api::WebSocketMessage>>),
                                Heartbeat,
                            }
                            let tick = {
                                let receive = stream.recv().fuse();
                                let heartbeat = executor.timer(Duration::from_millis(800)).fuse();
                                futures::pin_mut!(receive, heartbeat);
                                futures::select! {
                                    message = receive => SocketTick::Message(message),
                                    _ = heartbeat => SocketTick::Heartbeat,
                                }
                            };
                            match tick {
                                SocketTick::Heartbeat => {
                                    if let Err(error) = stream.send_text("ping").await {
                                        this.update(cx, |this, _| {
                                            this.realtime_error = Some(format!("{error:#}"));
                                        })?;
                                        break;
                                    }
                                }
                                SocketTick::Message(Ok(Some(message))) => {
                                    let event_type = message.message_type.clone();
                                    let plan = reconciliation_plan(&event_type, &message.data);
                                    let agent_log_event =
                                        parse_agent_session_log_event(&event_type, &message.data);
                                    let call_event = parse_call_event(&event_type, &message.data);
                                    let bulk_upload_event =
                                        parse_bulk_upload_event(&event_type, &message.data);
                                    let scheduled_action_event =
                                        parse_scheduled_action_event(&event_type, &message.data);
                                    let notification_status_update =
                                        parse_notification_status_update(
                                            &event_type,
                                            &message.data,
                                        );
                                    let comms_typing_event =
                                        parse_comms_typing_event(&event_type, &message.data);
                                    let comms_realtime_event =
                                        parse_comms_realtime_event(&event_type, &message.data);
                                    let event_data = message.data.clone();
                                    this.update(cx, |this, cx| {
                                        if this.realtime_generation != generation {
                                            return;
                                        }
                                        this.last_realtime_event = Some(event_type.clone());
                                        if event_type == "notification" {
                                            this.post_native_notification(&event_data, cx);
                                        }
                                        if let Some(call_event) = call_event {
                                            this.handle_call_event(call_event, cx);
                                        }
                                        if let Some(bulk_upload_event) = bulk_upload_event {
                                            this.handle_bulk_upload_event(bulk_upload_event, cx);
                                        }
                                        if let Some(scheduled_action_event) = scheduled_action_event
                                        {
                                            this.handle_scheduled_action_event(
                                                scheduled_action_event,
                                                cx,
                                            );
                                        }
                                        if let Some(notification_status_update) =
                                            notification_status_update
                                        {
                                            this.handle_notification_status_update(
                                                notification_status_update,
                                                cx,
                                            );
                                        }
                                        if let Some(comms_typing_event) = comms_typing_event {
                                            this.handle_comms_typing_event(comms_typing_event, cx);
                                        }
                                        if let Some(comms_realtime_event) = comms_realtime_event {
                                            this.handle_comms_realtime_event(
                                                comms_realtime_event,
                                                cx,
                                            );
                                        }
                                        if let Some(agent_log_event) = agent_log_event {
                                            this.apply_agent_log_event(agent_log_event, cx);
                                        } else {
                                            this.apply_reconcile_plan(plan, cx);
                                        }
                                        cx.notify();
                                    })?;
                                }
                                SocketTick::Message(Ok(None)) => {
                                    this.update(cx, |this, _| {
                                        this.realtime_error =
                                            Some("Connection gateway closed the socket".into());
                                    })?;
                                    break;
                                }
                                SocketTick::Message(Err(error)) => {
                                    this.update(cx, |this, _| {
                                        this.realtime_error = Some(format!("{error:#}"));
                                    })?;
                                    break;
                                }
                            }
                        }
                    }
                    Err(error) => {
                        this.update(cx, |this, _| {
                            this.realtime_error = Some(format!("{error:#}"));
                        })?;
                    }
                }

                let current = this.update(cx, |this, cx| {
                    let current = this.realtime_running && this.realtime_generation == generation;
                    if current {
                        this.layout_state.connection_status = ConnectionStatus::Disconnected;
                        // Typing is intentionally ephemeral and the gateway has
                        // no resumable cursor for it. Never display stale remote
                        // presence across a transport gap.
                        this.channel_typing_users.clear();
                        this.metrics.record_reconnect();
                        cx.notify();
                    }
                    current
                })?;
                if !current {
                    return anyhow::Ok(());
                }
                executor.timer(Duration::from_secs(retry_seconds)).await;
                retry_seconds = (retry_seconds * 2).min(30);
            }
        })
        .detach();
    }

    fn load_more_inbox(&mut self, cx: &mut Context<Self>) {
        let Some(cursor) = self.workspace.inbox.next_cursor().map(ToOwned::to_owned) else {
            return;
        };
        if self.inbox_loading_more {
            return;
        }
        self.inbox_loading_more = true;
        self.metrics.record_top_level_request();
        let api = self.api.clone();
        cx.spawn(async move |this, cx| {
            let result = api
                .list_soup_items(40, Some(&cursor))
                .await
                .and_then(parse_soup_page);
            this.update(cx, |this, cx| {
                this.inbox_loading_more = false;
                match result {
                    Ok(next) => {
                        this.workspace.inbox.append(next.items, next.next_cursor);
                        this.sync_open_inbox_records();
                        if this.layout_state.active_section == NavSection::CRM {
                            this.load_crm_company_properties(false, cx);
                        }
                    }
                    Err(error) => {
                        this.session_notice =
                            Some(format!("Unable to load more inbox items: {error}"))
                    }
                }
                cx.notify();
            })?;
            anyhow::Ok(())
        })
        .detach();
        cx.notify();
    }

    fn load_more_inbox_view(&mut self, cx: &mut Context<Self>) {
        let Some(cursor) = self
            .workspace
            .inbox_view
            .next_cursor()
            .map(ToOwned::to_owned)
        else {
            return;
        };
        if self.inbox_view_loading_more {
            return;
        }
        self.inbox_view_loading_more = true;
        let generation = self.inbox_view_generation;
        let tab = self.inbox_tab;
        let read_filter = self.list_query_state("inbox").read_filter;
        let signal_since = inbox_signal_since_now();
        let request = inbox_soup_request(tab, read_filter, &signal_since);
        self.metrics.record_top_level_request();
        let api = self.api.clone();
        cx.spawn(async move |this, cx| {
            let result = api
                .list_soup_ast_items(&request, Some(&cursor))
                .await
                .and_then(parse_soup_page);
            this.update(cx, |this, cx| {
                if this.inbox_view_generation != generation
                    || this.inbox_tab != tab
                    || this.list_query_state("inbox").read_filter != read_filter
                {
                    return;
                }
                this.inbox_view_loading_more = false;
                match result {
                    Ok(next) => this
                        .workspace
                        .inbox_view
                        .append(next.items, next.next_cursor),
                    Err(error) => {
                        this.session_notice =
                            Some(format!("Unable to load more inbox items: {error}"));
                    }
                }
                cx.notify();
            })?;
            anyhow::Ok(())
        })
        .detach();
        cx.notify();
    }

    fn load_more_channels(&mut self, cx: &mut Context<Self>) {
        let Some(cursor) = self.workspace.channels.next_cursor().map(ToOwned::to_owned) else {
            return;
        };
        if self.channels_loading_more {
            return;
        }
        self.channels_loading_more = true;
        self.metrics.record_top_level_request();
        let api = self.api.clone();
        cx.spawn(async move |this, cx| {
            let result = api
                .list_channels(Some(100), Some(&cursor))
                .await
                .and_then(parse_channel_page);
            this.update(cx, |this, cx| {
                this.channels_loading_more = false;
                match result {
                    Ok(next) => {
                        this.workspace.channels.append(next.items, next.next_cursor);
                        this.sync_open_channel_records();
                    }
                    Err(error) => {
                        this.session_notice = Some(format!("Unable to load more channels: {error}"))
                    }
                }
                cx.notify();
            })?;
            anyhow::Ok(())
        })
        .detach();
        cx.notify();
    }

    fn load_channel_messages(
        &mut self,
        channel_id: String,
        load_more: bool,
        cx: &mut Context<Self>,
    ) {
        let load = if load_more {
            ChannelMessageLoad::Older
        } else {
            ChannelMessageLoad::Initial
        };
        self.load_channel_message_page(channel_id, load, cx);
    }

    fn refresh_channel_messages(&mut self, channel_id: String, cx: &mut Context<Self>) {
        self.load_channel_message_page(channel_id, ChannelMessageLoad::Refresh, cx);
    }

    fn load_newer_channel_messages(&mut self, channel_id: String, cx: &mut Context<Self>) {
        self.load_channel_message_page(channel_id, ChannelMessageLoad::Newer, cx);
    }

    fn load_channel_messages_around(
        &mut self,
        channel_id: String,
        message_id: String,
        cx: &mut Context<Self>,
    ) {
        self.load_channel_message_page(channel_id, ChannelMessageLoad::Around(message_id), cx);
    }

    fn schedule_channel_message_target_clear(
        &mut self,
        target: ChannelMessageTarget,
        cx: &mut Context<Self>,
    ) {
        if !self.channel_message_target_is_loaded(&target) {
            return;
        }
        let executor = cx.background_executor().clone();
        cx.spawn(async move |this, cx| {
            executor.timer(Duration::from_secs(1)).await;
            this.update(cx, |this, cx| {
                if this.channel_message_target.as_ref() == Some(&target) {
                    this.channel_message_target = None;
                    cx.notify();
                }
            })?;
            anyhow::Ok(())
        })
        .detach();
    }

    fn channel_message_target_is_loaded(&self, target: &ChannelMessageTarget) -> bool {
        let root_loaded = self
            .workspace
            .channel_messages
            .get(&target.channel_id)
            .and_then(|messages| messages.get(&target.message_id))
            .is_some();
        if !root_loaded {
            return false;
        }
        target.reply_id.as_ref().is_none_or(|reply_id| {
            self.workspace
                .channel_thread_replies
                .get(&channel_thread_key(&target.channel_id, &target.message_id))
                .and_then(|replies| replies.get(reply_id))
                .is_some()
        })
    }

    fn channel_message_scroll_anchor(&self, channel_id: &str) -> Option<String> {
        let scroll_handle = self.channel_message_scroll_handles.get(channel_id)?;
        let rendered_top_index = uniform_list_logical_top_index(scroll_handle);
        let snapshot = self.workspace.channel_messages.get(channel_id)?.snapshot();
        channel_message_anchor_id(
            rendered_top_index,
            snapshot
                .items
                .iter()
                .rev()
                .map(|message| message.id.as_str()),
        )
    }

    fn load_channel_message_page(
        &mut self,
        channel_id: String,
        load: ChannelMessageLoad,
        cx: &mut Context<Self>,
    ) {
        self.channel_message_scroll_handles
            .entry(channel_id.clone())
            .or_default();
        let page_key = load.page_key(&channel_id);
        let scroll_anchor_message_id = matches!(
            load,
            ChannelMessageLoad::Refresh | ChannelMessageLoad::Older
        )
        .then(|| self.channel_message_scroll_anchor(&channel_id))
        .flatten();
        let (cursor, previous_cursor, load_around_message_id, generation) = match &load {
            ChannelMessageLoad::Initial => {
                if self
                    .workspace
                    .channel_messages
                    .get(&channel_id)
                    .is_some_and(|messages| messages.is_loading() || messages.is_ready())
                {
                    return;
                }
                self.workspace
                    .channel_messages
                    .entry(channel_id.clone())
                    .or_default()
                    .begin_load(false);
                let generation = self
                    .channel_message_generations
                    .entry(channel_id.clone())
                    .or_default();
                *generation = generation.wrapping_add(1);
                (None, None, None, *generation)
            }
            ChannelMessageLoad::Refresh => {
                let messages = self
                    .workspace
                    .channel_messages
                    .entry(channel_id.clone())
                    .or_default();
                if messages.is_loading() {
                    return;
                }
                messages.begin_load(true);
                let generation = self
                    .channel_message_generations
                    .entry(channel_id.clone())
                    .or_default();
                *generation = generation.wrapping_add(1);
                (None, None, None, *generation)
            }
            ChannelMessageLoad::Around(message_id) => {
                self.workspace
                    .channel_messages
                    .entry(channel_id.clone())
                    .or_default()
                    .begin_load(true);
                let generation = self
                    .channel_message_generations
                    .entry(channel_id.clone())
                    .or_default();
                *generation = generation.wrapping_add(1);
                (None, None, Some(message_id.clone()), *generation)
            }
            ChannelMessageLoad::Older => {
                let Some(cursor) = self
                    .workspace
                    .channel_messages
                    .get(&channel_id)
                    .and_then(|messages| messages.next_cursor().map(ToOwned::to_owned))
                else {
                    return;
                };
                let Some(page_key) = page_key.as_ref() else {
                    unreachable!()
                };
                if !self.channel_message_page_loads.insert(page_key.clone()) {
                    return;
                }
                let generation = *self
                    .channel_message_generations
                    .entry(channel_id.clone())
                    .or_default();
                (Some(cursor), None, None, generation)
            }
            ChannelMessageLoad::Newer => {
                let Some(previous_cursor) = self
                    .workspace
                    .channel_messages
                    .get(&channel_id)
                    .and_then(|messages| messages.previous_cursor().map(ToOwned::to_owned))
                else {
                    return;
                };
                let Some(page_key) = page_key.as_ref() else {
                    unreachable!()
                };
                if !self.channel_message_page_loads.insert(page_key.clone()) {
                    return;
                }
                let generation = *self
                    .channel_message_generations
                    .entry(channel_id.clone())
                    .or_default();
                (None, Some(previous_cursor), None, generation)
            }
        };

        let limit = if matches!(load, ChannelMessageLoad::Older | ChannelMessageLoad::Newer) {
            100
        } else {
            50
        };
        self.metrics.record_top_level_request();
        let api = self.api.clone();
        cx.spawn(async move |this, cx| {
            let result = api
                .list_channel_messages_window(
                    &channel_id,
                    limit,
                    cursor.as_deref(),
                    previous_cursor.as_deref(),
                    load_around_message_id.as_deref(),
                )
                .await
                .and_then(parse_message_page);
            this.update(cx, |this, cx| {
                if let Some(page_key) = page_key.as_ref() {
                    this.channel_message_page_loads.remove(page_key);
                }
                if this
                    .channel_message_generations
                    .get(&channel_id)
                    .copied()
                    .unwrap_or_default()
                    != generation
                {
                    return;
                }
                let messages = this
                    .workspace
                    .channel_messages
                    .entry(channel_id.clone())
                    .or_default();
                let (target_index, anchor_index, scroll_to_bottom, restore_latest) = match result {
                    Ok(page) => match load {
                        ChannelMessageLoad::Older => {
                            messages.append(page.items, page.next_cursor);
                            let snapshot = messages.snapshot();
                            let target_index = channel_target_message_index(
                                this.channel_message_target.as_ref(),
                                &channel_id,
                                snapshot
                                    .items
                                    .iter()
                                    .rev()
                                    .map(|message| message.id.as_str()),
                            );
                            let anchor_index =
                                scroll_anchor_message_id.as_deref().and_then(|anchor_id| {
                                    channel_rendered_message_index(
                                        anchor_id,
                                        snapshot
                                            .items
                                            .iter()
                                            .rev()
                                            .map(|message| message.id.as_str()),
                                    )
                                });
                            (target_index, anchor_index, false, false)
                        }
                        ChannelMessageLoad::Newer => {
                            messages.prepend(page.items, page.previous_cursor);
                            let target_index = channel_target_message_index(
                                this.channel_message_target.as_ref(),
                                &channel_id,
                                messages
                                    .snapshot()
                                    .items
                                    .iter()
                                    .rev()
                                    .map(|message| message.id.as_str()),
                            );
                            (target_index, None, false, false)
                        }
                        ChannelMessageLoad::Initial
                        | ChannelMessageLoad::Refresh
                        | ChannelMessageLoad::Around(_) => {
                            let local_delivery_rows = messages
                                .snapshot()
                                .items
                                .into_iter()
                                .filter(|message| channel_delivery_status(&message.raw).is_some())
                                .collect::<Vec<_>>();
                            messages.replace_window(
                                page.items,
                                page.next_cursor,
                                page.previous_cursor,
                            );
                            for message in local_delivery_rows.into_iter().rev() {
                                if messages.get(&message.id).is_none() {
                                    messages.upsert_front(message.as_ref().clone());
                                }
                            }
                            let snapshot = messages.snapshot();
                            let target_index = channel_target_message_index(
                                this.channel_message_target.as_ref(),
                                &channel_id,
                                snapshot
                                    .items
                                    .iter()
                                    .rev()
                                    .map(|message| message.id.as_str()),
                            );
                            let anchor_index =
                                scroll_anchor_message_id.as_deref().and_then(|anchor_id| {
                                    channel_rendered_message_index(
                                        anchor_id,
                                        snapshot
                                            .items
                                            .iter()
                                            .rev()
                                            .map(|message| message.id.as_str()),
                                    )
                                });
                            let scroll_to_bottom = matches!(load, ChannelMessageLoad::Initial)
                                || (matches!(load, ChannelMessageLoad::Refresh)
                                    && anchor_index.is_none()
                                    && target_index.is_none());
                            (target_index, anchor_index, scroll_to_bottom, false)
                        }
                    },
                    Err(error) => {
                        messages.fail(error.to_string());
                        (
                            None,
                            None,
                            false,
                            matches!(load, ChannelMessageLoad::Around(_)),
                        )
                    }
                };
                let target_to_clear = target_index
                    .and_then(|_| this.channel_message_target.as_ref().cloned());
                if let Some(scroll_handle) = this.channel_message_scroll_handles.get(&channel_id) {
                    if let Some(target_index) = target_index {
                        scroll_handle.scroll_to_item_strict(target_index, ScrollStrategy::Center);
                    } else if let Some(anchor_index) = anchor_index {
                        scroll_handle.scroll_to_item_strict(anchor_index, ScrollStrategy::Top);
                    } else if scroll_to_bottom {
                        scroll_handle.scroll_to_bottom();
                    }
                }
                if let Some(target) = target_to_clear {
                    this.schedule_channel_message_target_clear(target, cx);
                }
                if restore_latest {
                    this.channel_message_target = None;
                    this.session_notice = Some(
                        "That linked channel message is no longer available; showing the latest messages"
                            .into(),
                    );
                    this.refresh_channel_messages(channel_id.clone(), cx);
                }
                cx.notify();
            })?;
            anyhow::Ok(())
        })
        .detach();
        cx.notify();
    }

    fn open_channel_thread(
        &mut self,
        channel_id: String,
        message_id: String,
        cx: &mut Context<Self>,
    ) {
        let key = channel_thread_key(&channel_id, &message_id);
        self.channel_thread_scroll_handles.entry(key).or_default();
        self.active_channel_thread = Some((channel_id.clone(), message_id.clone()));
        self.load_channel_thread(channel_id, message_id, false, cx);
    }

    fn load_channel_thread(
        &mut self,
        channel_id: String,
        message_id: String,
        force: bool,
        cx: &mut Context<Self>,
    ) {
        let key = channel_thread_key(&channel_id, &message_id);
        self.channel_thread_scroll_handles
            .entry(key.clone())
            .or_default();
        let replies = self
            .workspace
            .channel_thread_replies
            .entry(key.clone())
            .or_default();
        if !force {
            if replies.is_ready() {
                let snapshot = replies.snapshot();
                let did_scroll = self
                    .channel_thread_scroll_handles
                    .get(&key)
                    .and_then(|scroll_handle| {
                        scroll_channel_thread_to_target(
                            scroll_handle,
                            self.channel_message_target.as_ref(),
                            &channel_id,
                            &message_id,
                            snapshot.items.iter().map(|reply| reply.id.as_str()),
                        )
                    })
                    .is_some();
                if did_scroll {
                    if let Some(target) = self.channel_message_target.clone() {
                        self.schedule_channel_message_target_clear(target, cx);
                    }
                    cx.notify();
                } else if let Some(scroll_handle) = self.channel_thread_scroll_handles.get(&key) {
                    scroll_handle.scroll_to_bottom();
                    cx.notify();
                }
                return;
            }
            if replies.is_loading() {
                return;
            }
        }
        replies.begin_load(force);
        self.metrics.record_top_level_request();
        let api = self.api.clone();
        cx.spawn(async move |this, cx| {
            let result = api
                .list_channel_thread_replies(&channel_id, &message_id)
                .await
                .and_then(parse_thread_replies);
            this.update(cx, |this, cx| {
                let replies = this
                    .workspace
                    .channel_thread_replies
                    .entry(key.clone())
                    .or_default();
                let target_index = match result {
                    Ok(items) => {
                        let local_delivery_rows = replies
                            .snapshot()
                            .items
                            .into_iter()
                            .filter(|reply| channel_delivery_status(&reply.raw).is_some())
                            .collect::<Vec<_>>();
                        replies.replace(items, None);
                        for reply in local_delivery_rows {
                            if replies.get(&reply.id).is_none() {
                                replies.upsert(reply.as_ref().clone());
                            }
                        }
                        channel_target_reply_index(
                            this.channel_message_target.as_ref(),
                            &channel_id,
                            &message_id,
                            replies
                                .snapshot()
                                .items
                                .iter()
                                .map(|reply| reply.id.as_str()),
                        )
                    }
                    Err(error) => {
                        replies.fail(error.to_string());
                        None
                    }
                };
                if let Some(scroll_handle) = this.channel_thread_scroll_handles.get(&key) {
                    if let Some(target_index) = target_index {
                        scroll_handle.scroll_to_item_strict(target_index, ScrollStrategy::Center);
                        if let Some(target) = this.channel_message_target.clone() {
                            this.schedule_channel_message_target_clear(target, cx);
                        }
                    } else if !force {
                        scroll_handle.scroll_to_bottom();
                    }
                }
                cx.notify();
            })?;
            anyhow::Ok(())
        })
        .detach();
        cx.notify();
    }

    fn load_channel_participants(
        &mut self,
        channel_id: String,
        force: bool,
        cx: &mut Context<Self>,
    ) {
        if !force
            && matches!(
                self.workspace.channel_participants.get(&channel_id),
                Some(DataState::Loading | DataState::Loaded(_))
            )
        {
            return;
        }
        self.workspace
            .channel_participants
            .insert(channel_id.clone(), DataState::Loading);
        self.metrics.record_top_level_request();
        let api = self.api.clone();
        cx.spawn(async move |this, cx| {
            let result = api.list_channel_participants(&channel_id).await;
            this.update(cx, |this, cx| {
                this.workspace.channel_participants.insert(
                    channel_id,
                    result
                        .map(DataState::Loaded)
                        .unwrap_or_else(|error| DataState::Failed(error.to_string())),
                );
                cx.notify();
            })?;
            anyhow::Ok(())
        })
        .detach();
        cx.notify();
    }

    fn submit_auth(&mut self, cx: &mut Context<Self>) {
        if matches!(
            self.session,
            SessionState::AwaitingCode { .. } | SessionState::Verifying { .. }
        ) || !self.auth_code.trim().is_empty()
        {
            self.verify_passwordless(cx);
        } else if !self.session.is_busy() {
            self.begin_passwordless(cx);
        }
    }

    fn auth_key_down(&mut self, event: &KeyDownEvent, window: &mut Window, cx: &mut Context<Self>) {
        if self.session.is_ready() {
            if self.command_palette_open {
                self.command_palette_key_down(event, cx);
            } else if self.mutation_dialog.is_some() {
                self.mutation_key_down(event, window, cx);
            } else {
                let started = Instant::now();
                if self.workspace_key_down(event, window, cx) {
                    let metrics = Arc::clone(&self.metrics);
                    window.on_next_frame_presented(move |_, _| {
                        metrics.record_input_to_paint(started.elapsed());
                    });
                }
            }
            return;
        }

        let key = event.keystroke.key.as_str();
        if event.keystroke.modifiers.secondary() && key == "v" {
            if let Some(text) = cx.read_from_clipboard().and_then(|item| item.text()) {
                match self.active_auth_field {
                    AuthField::Email => self.auth_email.push_str(text.trim()),
                    AuthField::Code => self.auth_code.push_str(text.trim()),
                }
                cx.notify();
            }
            cx.stop_propagation();
            return;
        }

        match key {
            "tab" => {
                self.active_auth_field = match self.active_auth_field {
                    AuthField::Email => AuthField::Code,
                    AuthField::Code => AuthField::Email,
                };
                cx.stop_propagation();
                cx.notify();
            }
            "backspace" => {
                match self.active_auth_field {
                    AuthField::Email => {
                        self.auth_email.pop();
                    }
                    AuthField::Code => {
                        self.auth_code.pop();
                    }
                }
                cx.stop_propagation();
                cx.notify();
            }
            "enter" => {
                self.submit_auth(cx);
                cx.stop_propagation();
            }
            _ if !event.keystroke.modifiers.control
                && !event.keystroke.modifiers.alt
                && !event.keystroke.modifiers.platform
                && !event.keystroke.modifiers.function =>
            {
                if let Some(character) = &event.keystroke.key_char {
                    match self.active_auth_field {
                        AuthField::Email => self.auth_email.push_str(character),
                        AuthField::Code => self.auth_code.push_str(character),
                    }
                    cx.stop_propagation();
                    cx.notify();
                }
            }
            _ => {}
        }
    }

    fn visible_inbox_items(&self) -> Vec<Arc<InboxItem>> {
        let read_filter = self.list_query_state("inbox").read_filter;
        self.workspace
            .inbox_view
            .snapshot()
            .items
            .into_iter()
            .filter(|item| read_filter.matches(is_unread(&item.tag, &item.raw)))
            .collect()
    }

    fn visible_shared_list_items(&self, view_id: &str) -> Vec<Arc<InboxItem>> {
        let query_state = self.list_query_state(view_id);
        let snapshot = if self.list_query_uses_server(view_id) {
            self.workspace
                .filtered_list_views
                .get(view_id)
                .map(|collection| collection.snapshot())
                .unwrap_or_else(|| macro_store::NormalizedCollection::default().snapshot())
        } else {
            self.workspace.inbox.snapshot()
        };
        let Some(filter) = soup_filter_for_list_view(view_id) else {
            return Vec::new();
        };
        let mut items = snapshot
            .items
            .into_iter()
            .filter(|item| filter.matches(item))
            .collect::<Vec<_>>();
        if query_state.grouping == ListGrouping::EntityType {
            items.sort_by(|left, right| {
                left.entity_type
                    .to_string()
                    .cmp(&right.entity_type.to_string())
                    .then_with(|| right.timestamp.cmp(&left.timestamp))
            });
        }
        items
    }

    fn workspace_key_down(
        &mut self,
        event: &KeyDownEvent,
        window: &mut Window,
        cx: &mut Context<Self>,
    ) -> bool {
        if self.command_palette_open {
            return false;
        }
        if event.keystroke.key == "escape" && self.detail_fullscreen {
            self.detail_fullscreen = false;
            self.persist_preferences(cx);
            cx.stop_propagation();
            cx.notify();
            return true;
        }
        if self.layout_state.active_section == NavSection::Search {
            return self.search_key_down(event, window, cx);
        }
        if self.layout_state.active_section == NavSection::Files {
            return self.file_tree_key_down(event, window, cx);
        }
        if self.layout_state.active_section == NavSection::Activity {
            return self.activity_key_down(event, cx);
        }
        if self.layout_state.active_section == NavSection::Reminders {
            return self.reminders_key_down(event, cx);
        }
        if self.layout_state.active_section == NavSection::Calls {
            return self.calls_key_down(event, cx);
        }
        if self.layout_state.active_section == NavSection::CRM {
            return self.crm_key_down(event, cx);
        }
        if self.layout_state.active_section != NavSection::Inbox {
            return self.shared_list_key_down(event, cx);
        }
        let items = self.visible_inbox_items();
        let ids = items.iter().map(|item| item.id.clone()).collect::<Vec<_>>();
        let key = event.keystroke.key.as_str();
        match key {
            "j" | "down" => self.inbox_interaction.move_next(items.len()),
            "k" | "up" => self.inbox_interaction.move_previous(items.len()),
            "x" => self.inbox_interaction.toggle_selected(&ids),
            "enter" | "space" | "e" => {
                if key == "e" && self.inbox_interaction.selected_count() > 0 {
                    self.mark_selected_inbox_items_done(cx);
                    cx.stop_propagation();
                    cx.notify();
                    return true;
                }
                if let Some(action) =
                    self.inbox_interaction
                        .action(&ids, key, event.keystroke.modifiers.shift)
                    && let Some(item) = items.iter().find(|item| item.id == action_id(&action))
                {
                    match action {
                        ListAction::Open(_) => self.open_entity_with_mode(
                            OpenEntity::Inbox(Arc::clone(item)),
                            true,
                            cx,
                        ),
                        ListAction::OpenSplit(_) => self.open_entity_with_mode(
                            OpenEntity::Inbox(Arc::clone(item)),
                            false,
                            cx,
                        ),
                        ListAction::Preview(_) => self.open_entity_with_mode(
                            OpenEntity::Inbox(Arc::clone(item)),
                            false,
                            cx,
                        ),
                        ListAction::MarkDone(_) => self.mark_inbox_item_done(Arc::clone(item), cx),
                    }
                }
            }
            _ => return false,
        }
        cx.stop_propagation();
        cx.notify();
        true
    }

    fn shared_list_key_down(&mut self, event: &KeyDownEvent, cx: &mut Context<Self>) -> bool {
        let Some(view_id) = self.active_list_view_id(self.layout_state.active_section) else {
            return false;
        };
        if view_id == "files" {
            return false;
        }
        let items = self.visible_shared_list_items(view_id);
        let ids = items.iter().map(|item| item.id.clone()).collect::<Vec<_>>();
        let key = event.keystroke.key.as_str();
        match key {
            "j" | "down" => self
                .list_interactions
                .entry(view_id.into())
                .or_default()
                .move_next(items.len()),
            "k" | "up" => self
                .list_interactions
                .entry(view_id.into())
                .or_default()
                .move_previous(items.len()),
            "x" => {
                if is_calls_list_view(view_id) {
                    return false;
                }
                let focused = self
                    .list_interactions
                    .entry(view_id.into())
                    .or_default()
                    .focused()
                    .and_then(|index| items.get(index))
                    .map(|item| item.id.clone());
                if let Some(focused) = focused {
                    if view_id == "tasks" {
                        self.toggle_task_selected(focused, cx);
                    } else {
                        self.list_interactions
                            .entry(view_id.into())
                            .or_default()
                            .toggle_selected_id(&focused);
                    }
                }
            }
            "e" if is_mail_list_view(view_id) => {
                let targets =
                    selected_or_focused_list_items(self.list_interactions.get(view_id), &items);
                if targets.is_empty() {
                    return false;
                }
                if event.keystroke.modifiers.shift {
                    self.set_email_items_archived(targets, false, cx);
                } else {
                    self.mark_inbox_items_done(targets, cx);
                }
            }
            "u" if is_mail_list_view(view_id) => {
                let targets =
                    selected_or_focused_list_items(self.list_interactions.get(view_id), &items);
                if targets.is_empty() {
                    return false;
                }
                let read = event.keystroke.modifiers.shift;
                for item in targets {
                    self.set_email_thread_read(
                        item.id.clone(),
                        inbox_email_link_id(&item),
                        read,
                        cx,
                    );
                }
            }
            "enter" | "space" | "e" => {
                if key == "e" {
                    if is_calls_list_view(view_id) {
                        return false;
                    }
                    let selected = if view_id == "tasks" {
                        self.task_selected_ids.clone()
                    } else {
                        self.list_interactions
                            .get(view_id)
                            .map(|interaction| {
                                interaction
                                    .selected_ids()
                                    .map(ToOwned::to_owned)
                                    .collect::<HashSet<_>>()
                            })
                            .unwrap_or_default()
                    };
                    if !selected.is_empty() {
                        let selected_items = items
                            .iter()
                            .filter(|item| selected.contains(&item.id))
                            .cloned()
                            .collect::<Vec<_>>();
                        if !selected_items.is_empty() {
                            self.mark_inbox_items_done(selected_items, cx);
                        }
                        cx.stop_propagation();
                        cx.notify();
                        return true;
                    }
                }
                let action = self.list_interactions.get(view_id).and_then(|interaction| {
                    interaction.action(&ids, key, event.keystroke.modifiers.shift)
                });
                if let Some(action) = action
                    && let Some(item) = items.iter().find(|item| item.id == action_id(&action))
                {
                    match action {
                        ListAction::Open(_) => self.open_entity_with_mode(
                            OpenEntity::Inbox(Arc::clone(item)),
                            true,
                            cx,
                        ),
                        ListAction::OpenSplit(_) | ListAction::Preview(_) => self
                            .open_entity_with_mode(OpenEntity::Inbox(Arc::clone(item)), false, cx),
                        ListAction::MarkDone(_) => self.mark_inbox_item_done(Arc::clone(item), cx),
                    }
                }
            }
            _ => return false,
        }
        cx.stop_propagation();
        cx.notify();
        true
    }

    fn activity_key_down(&mut self, event: &KeyDownEvent, cx: &mut Context<Self>) -> bool {
        let items = self.workspace.notifications.snapshot().items;
        let ids = items
            .iter()
            .map(|item| item.0.id.clone())
            .collect::<Vec<_>>();
        let key = event.keystroke.key.as_str();
        match key {
            "j" | "down" => self
                .list_interactions
                .entry("activity".into())
                .or_default()
                .move_next(items.len()),
            "k" | "up" => self
                .list_interactions
                .entry("activity".into())
                .or_default()
                .move_previous(items.len()),
            "x" => self
                .list_interactions
                .entry("activity".into())
                .or_default()
                .toggle_selected(&ids),
            "enter" | "space" => {
                let Some(index) = self
                    .list_interactions
                    .get("activity")
                    .and_then(ListInteraction::focused)
                else {
                    return false;
                };
                let Some(item) = items.get(index) else {
                    return false;
                };
                self.activate_activity_notification(item.0.clone(), cx);
            }
            "e" => {
                let interaction = self.list_interactions.entry("activity".into()).or_default();
                let mut targets = interaction
                    .selected_ids()
                    .map(ToOwned::to_owned)
                    .collect::<Vec<_>>();
                if targets.is_empty()
                    && let Some(id) = interaction.focused().and_then(|index| ids.get(index))
                {
                    targets.push(id.clone());
                }
                if targets.is_empty() {
                    return false;
                }
                interaction.clear_selected();
                self.mutate_notifications(targets, NotificationMutation::Done(true), cx);
            }
            _ => return false,
        }
        cx.stop_propagation();
        cx.notify();
        true
    }

    fn reminders_key_down(&mut self, event: &KeyDownEvent, cx: &mut Context<Self>) -> bool {
        let items = self.workspace.reminders.snapshot().items;
        let ids = items
            .iter()
            .map(|item| item.0.id.clone())
            .collect::<Vec<_>>();
        let key = event.keystroke.key.as_str();
        match key {
            "j" | "down" => self
                .list_interactions
                .entry("reminders".into())
                .or_default()
                .move_next(items.len()),
            "k" | "up" => self
                .list_interactions
                .entry("reminders".into())
                .or_default()
                .move_previous(items.len()),
            "x" => self
                .list_interactions
                .entry("reminders".into())
                .or_default()
                .toggle_selected(&ids),
            "enter" | "space" => {
                let Some(index) = self
                    .list_interactions
                    .get("reminders")
                    .and_then(ListInteraction::focused)
                else {
                    return false;
                };
                let Some(item) = items.get(index) else {
                    return false;
                };
                self.open_edit_reminder(item.as_ref().clone(), cx);
            }
            "e" => {
                let interaction = self
                    .list_interactions
                    .entry("reminders".into())
                    .or_default();
                let mut targets = interaction
                    .selected_ids()
                    .map(ToOwned::to_owned)
                    .collect::<Vec<_>>();
                if targets.is_empty()
                    && let Some(id) = interaction.focused().and_then(|index| ids.get(index))
                {
                    targets.push(id.clone());
                }
                if targets.is_empty() {
                    return false;
                }
                interaction.clear_selected();
                self.complete_reminders(targets, cx);
            }
            _ => return false,
        }
        cx.stop_propagation();
        cx.notify();
        true
    }

    fn crm_key_down(&mut self, event: &KeyDownEvent, cx: &mut Context<Self>) -> bool {
        let items = self.visible_crm_list_items();
        if items.is_empty() {
            return false;
        }
        let key = event.keystroke.key.as_str();
        match key {
            "j" | "down" => self
                .list_interactions
                .entry("crm".into())
                .or_default()
                .move_next(items.len()),
            "k" | "up" => self
                .list_interactions
                .entry("crm".into())
                .or_default()
                .move_previous(items.len()),
            "x" => {
                let Some(entity_id) = self
                    .list_interactions
                    .entry("crm".into())
                    .or_default()
                    .focused()
                    .and_then(|index| items.get(index))
                    .map(|item| item.id.clone())
                else {
                    return false;
                };
                self.toggle_crm_selection(entity_id, cx);
            }
            "enter" | "space" => {
                let Some(item) = self
                    .list_interactions
                    .get("crm")
                    .and_then(ListInteraction::focused)
                    .and_then(|index| items.get(index))
                    .cloned()
                else {
                    return false;
                };
                self.open_entity_with_mode(
                    OpenEntity::Inbox(item),
                    key == "enter" && !event.keystroke.modifiers.shift,
                    cx,
                );
            }
            _ => return false,
        }
        cx.stop_propagation();
        cx.notify();
        true
    }

    fn calls_key_down(&mut self, event: &KeyDownEvent, cx: &mut Context<Self>) -> bool {
        let key = event.keystroke.key.as_str();
        let calls = self
            .workspace
            .active_calls
            .loaded()
            .cloned()
            .unwrap_or_default();
        let active_focused = self
            .list_interactions
            .get("active-calls")
            .and_then(ListInteraction::focused)
            .is_some();

        if key == "a" && !calls.is_empty() {
            self.list_interactions
                .entry("active-calls".into())
                .or_default()
                .set_focused(0, calls.len());
        } else if active_focused {
            match key {
                "escape" => self
                    .list_interactions
                    .entry("active-calls".into())
                    .or_default()
                    .clear_focused(),
                "j" | "down" => self
                    .list_interactions
                    .entry("active-calls".into())
                    .or_default()
                    .move_next(calls.len()),
                "k" | "up" => self
                    .list_interactions
                    .entry("active-calls".into())
                    .or_default()
                    .move_previous(calls.len()),
                "enter" | "space" => {
                    let Some(channel_id) = self
                        .list_interactions
                        .get("active-calls")
                        .and_then(ListInteraction::focused)
                        .and_then(|index| calls.get(index))
                        .map(|call| call.channel_id.clone())
                    else {
                        return false;
                    };
                    if self.native_call.as_ref().is_some_and(|call| {
                        call.channel_id == channel_id
                            && call.connection != NativeCallConnection::Disconnected
                    }) || self.joining_call_channel.as_deref() == Some(channel_id.as_str())
                    {
                        return false;
                    }
                    self.join_native_call(channel_id, cx);
                }
                _ => return false,
            }
        } else {
            return self.shared_list_key_down(event, cx);
        }
        cx.stop_propagation();
        cx.notify();
        true
    }

    fn search_key_down(
        &mut self,
        event: &KeyDownEvent,
        window: &mut Window,
        cx: &mut Context<Self>,
    ) -> bool {
        if self.search_editor.focus_handle(cx).is_focused(window) {
            return false;
        }
        if event.keystroke.key == "escape" && self.search_results_focus_handle.is_focused(window) {
            window.focus(&self.search_editor.focus_handle(cx), cx);
            cx.stop_propagation();
            cx.notify();
            return true;
        }
        let result_count = self.visible_search_results().len();
        let key = event.keystroke.key.as_str();
        match key {
            "j" | "down" => self.search_interaction.move_next(result_count),
            "k" | "up" => self.search_interaction.move_previous(result_count),
            "enter" => {
                if !self.open_focused_search_result(!event.keystroke.modifiers.shift, cx) {
                    self.load_search(false, cx);
                }
            }
            "space" => {
                if !self.open_focused_search_result(false, cx) {
                    return false;
                }
            }
            _ => return false,
        }
        cx.stop_propagation();
        cx.notify();
        true
    }

    fn file_tree_key_down(
        &mut self,
        event: &KeyDownEvent,
        window: &mut Window,
        cx: &mut Context<Self>,
    ) -> bool {
        if !self.file_tree_focus_handle.is_focused(window) {
            return false;
        }
        let projects = self
            .workspace
            .projects
            .loaded()
            .cloned()
            .unwrap_or_default();
        let nodes = project_tree_nodes(&projects);
        self.file_tree_interaction.reconcile(&nodes);
        match event.keystroke.key.as_str() {
            "j" | "down" => self.file_tree_interaction.move_next(&nodes),
            "k" | "up" => self.file_tree_interaction.move_previous(&nodes),
            "right" => self.file_tree_interaction.expand_or_descend(&nodes),
            "left" => self.file_tree_interaction.collapse_or_ascend(&nodes),
            "home" => self.file_tree_interaction.move_home(&nodes),
            "end" => self.file_tree_interaction.move_end(&nodes),
            "enter" | "space" => {
                let Some(project_id) = self.file_tree_interaction.focused_id().map(str::to_owned)
                else {
                    return false;
                };
                self.select_project(project_id, cx);
            }
            _ => return false,
        }
        cx.stop_propagation();
        cx.notify();
        true
    }

    fn mark_inbox_item_done(&mut self, item: Arc<InboxItem>, cx: &mut Context<Self>) {
        self.mark_inbox_items_done(vec![item], cx);
    }

    fn mark_selected_inbox_items_done(&mut self, cx: &mut Context<Self>) {
        let selected = self
            .inbox_interaction
            .selected_ids()
            .collect::<HashSet<_>>();
        let items = self
            .visible_inbox_items()
            .into_iter()
            .filter(|item| selected.contains(item.id.as_str()))
            .collect::<Vec<_>>();
        if items.is_empty() {
            return;
        }
        self.mark_inbox_items_done(items, cx);
    }

    fn mark_selected_shared_list_items_done(&mut self, view_id: &str, cx: &mut Context<Self>) {
        let selected = self
            .list_interactions
            .get(view_id)
            .map(|interaction| {
                interaction
                    .selected_ids()
                    .map(ToOwned::to_owned)
                    .collect::<HashSet<_>>()
            })
            .unwrap_or_default();
        let items = self
            .visible_shared_list_items(view_id)
            .into_iter()
            .filter(|item| selected.contains(&item.id))
            .collect::<Vec<_>>();
        if !items.is_empty() {
            self.mark_inbox_items_done(items, cx);
        }
    }

    fn refresh_loaded_mail_views(&mut self, cx: &mut Context<Self>) {
        let view_ids = self
            .workspace
            .filtered_list_views
            .keys()
            .filter(|view_id| is_mail_list_view(view_id))
            .cloned()
            .collect::<Vec<_>>();
        for view_id in view_ids {
            self.load_filtered_list_view(view_id, false, cx);
        }
    }

    fn mark_inbox_items_done(&mut self, items: Vec<Arc<InboxItem>>, cx: &mut Context<Self>) {
        let targets = items
            .iter()
            .filter_map(|item| notification_entity_input(item))
            .collect::<Vec<_>>();
        let email_targets = items
            .iter()
            .filter(|item| item.entity_type == EntityType::EmailThread)
            .map(|item| (item.id.clone(), inbox_email_link_id(item)))
            .collect::<Vec<_>>();
        let reminder_ids = items
            .iter()
            .filter(|item| item.entity_type == EntityType::Reminder)
            .map(|item| item.id.clone())
            .collect::<Vec<_>>();
        let actionable = items
            .iter()
            .filter(|item| notification_entity_input(item).is_some())
            .count();
        if actionable == 0 {
            self.session_notice = Some("The selected items do not support Mark Done.".into());
            cx.notify();
            return;
        }
        let api = self.api.clone();
        self.session_notice = Some(format!("Marking {actionable} item(s) done…"));
        cx.spawn(async move |this, cx| {
            let mut errors = Vec::new();
            let mut archived_email_targets = Vec::new();
            for (email_id, link_id) in &email_targets {
                match api
                    .set_thread_archived_for_link(email_id, true, link_id.as_deref())
                    .await
                {
                    Ok(_) => archived_email_targets.push((email_id.clone(), link_id.clone())),
                    Err(error) => errors.push(format!("email {email_id}: {error}")),
                }
            }
            let mut completed_reminder_ids = Vec::new();
            for reminder_id in &reminder_ids {
                match api
                    .update_reminder(
                        reminder_id,
                        &UpdateReminderRequest {
                            completed: Some(true),
                            ..Default::default()
                        },
                    )
                    .await
                {
                    Ok(_) => completed_reminder_ids.push(reminder_id.clone()),
                    Err(error) => errors.push(format!("reminder {reminder_id}: {error}")),
                }
            }
            let notification_ids = match api
                .update_notifications_for_entities(targets, NotificationUpdateOperation::MarkDone)
                .await
            {
                Ok(ids) => ids,
                Err(error) => {
                    errors.push(format!("notifications: {error}"));
                    Vec::new()
                }
            };
            this.update(cx, |this, cx| {
                this.inbox_interaction.clear_selected();
                for interaction in this.list_interactions.values_mut() {
                    interaction.clear_selected();
                }
                this.task_selected_ids.clear();
                if !archived_email_targets.is_empty()
                    || !completed_reminder_ids.is_empty()
                    || !notification_ids.is_empty()
                {
                    this.pending_undo = Some(UndoAction::MarkEntitiesUndone {
                        email_targets: archived_email_targets,
                        notification_ids,
                        reminder_ids: completed_reminder_ids,
                    });
                }
                this.session_notice = Some(if errors.is_empty() {
                    format!("Marked {actionable} item(s) done")
                } else {
                    format!("Mark Done partially failed: {}", errors.join(" · "))
                });
                this.load_inbox(false, cx);
                if !email_targets.is_empty() {
                    this.refresh_loaded_mail_views(cx);
                }
                this.load_notifications(false, cx);
                if !reminder_ids.is_empty() {
                    this.load_reminders(false, cx);
                }
                cx.notify();
            })?;
            anyhow::Ok(())
        })
        .detach();
    }

    fn archive_email_thread(
        &mut self,
        thread_id: String,
        link_id: Option<String>,
        cx: &mut Context<Self>,
    ) {
        let api = self.api.clone();
        self.session_notice = Some("Archiving email…".into());
        cx.spawn(async move |this, cx| {
            let result = api
                .set_thread_archived_for_link(&thread_id, true, link_id.as_deref())
                .await;
            this.update(cx, |this, cx| {
                match result {
                    Ok(_) => {
                        this.session_notice = Some("Email archived".into());
                        this.pending_undo = Some(UndoAction::UnarchiveEmail {
                            thread_id: thread_id.clone(),
                            link_id,
                        });
                        this.apply_reconcile_plan(
                            ReconcilePlan::new([
                                ReconcileTarget::Inbox,
                                ReconcileTarget::Entity {
                                    entity_type: EntityType::EmailThread,
                                    entity_id: thread_id,
                                },
                            ]),
                            cx,
                        );
                        this.refresh_loaded_mail_views(cx);
                    }
                    Err(error) => {
                        this.session_notice = Some(format!("Email archive failed: {error}"));
                    }
                }
                cx.notify();
            })?;
            anyhow::Ok(())
        })
        .detach();
    }

    fn set_email_items_archived(
        &mut self,
        items: Vec<Arc<InboxItem>>,
        archived: bool,
        cx: &mut Context<Self>,
    ) {
        let targets = items
            .into_iter()
            .map(|item| (item.id.clone(), inbox_email_link_id(&item)))
            .collect::<Vec<_>>();
        if targets.is_empty() {
            return;
        }
        let api = self.api.clone();
        self.session_notice = Some(if archived {
            "Archiving selected email…".into()
        } else {
            "Restoring selected email…".into()
        });
        cx.spawn(async move |this, cx| {
            let mut failures = Vec::new();
            let mut changed = 0_usize;
            for (thread_id, link_id) in &targets {
                match api
                    .set_thread_archived_for_link(thread_id, archived, link_id.as_deref())
                    .await
                {
                    Ok(_) => changed += 1,
                    Err(error) => failures.push(format!("{thread_id}: {error}")),
                }
            }
            this.update(cx, |this, cx| {
                for interaction in this.list_interactions.values_mut() {
                    interaction.clear_selected();
                }
                this.session_notice = Some(if failures.is_empty() {
                    format!(
                        "{} {changed} email thread{}",
                        if archived { "Archived" } else { "Restored" },
                        if changed == 1 { "" } else { "s" }
                    )
                } else {
                    format!(
                        "Email triage partially failed ({} changed): {}",
                        changed,
                        failures.join(" · ")
                    )
                });
                this.load_inbox(false, cx);
                this.refresh_loaded_mail_views(cx);
                cx.notify();
            })?;
            anyhow::Ok(())
        })
        .detach();
    }

    fn mutate_email_label(
        &mut self,
        thread_id: String,
        link_id: Option<String>,
        label_name: impl Into<String>,
        value: bool,
        cx: &mut Context<Self>,
    ) {
        let label_name = label_name.into();
        let Some(label_id) = self
            .workspace
            .email_labels
            .loaded()
            .and_then(|labels| email_label_id(labels, link_id.as_deref(), &label_name))
        else {
            self.session_notice = Some(format!(
                "The {label_name} label is not available for this inbox; refresh integrations"
            ));
            cx.notify();
            return;
        };
        let api = self.api.clone();
        self.session_notice = Some(format!("Updating {label_name}…"));
        cx.spawn(async move |this, cx| {
            let result = api
                .set_thread_label_for_link(&thread_id, &label_id, value, link_id.as_deref())
                .await;
            this.update(cx, |this, cx| {
                match result {
                    Ok(_) => {
                        this.session_notice = Some(format!("Email {label_name} updated"));
                        let key = format!("{}:{thread_id}", EntityType::EmailThread);
                        this.workspace.entity_details.remove(&key);
                        if let Some(OpenEntity::Inbox(item)) = this.open_entities.get(&key).cloned()
                        {
                            this.load_entity_detail(item, cx);
                        }
                        this.load_inbox(false, cx);
                        this.refresh_loaded_mail_views(cx);
                    }
                    Err(error) => {
                        this.session_notice = Some(format!("Email update failed: {error}"));
                    }
                }
                cx.notify();
            })?;
            anyhow::Ok(())
        })
        .detach();
    }

    fn set_email_thread_read(
        &mut self,
        thread_id: String,
        link_id: Option<String>,
        read: bool,
        cx: &mut Context<Self>,
    ) {
        if !read {
            self.mutate_email_label(thread_id, link_id, "UNREAD", true, cx);
            return;
        }
        let api = self.api.clone();
        self.session_notice = Some("Marking email read…".into());
        cx.spawn(async move |this, cx| {
            let result = api
                .mark_thread_seen_for_link(&thread_id, link_id.as_deref())
                .await;
            this.update(cx, |this, cx| {
                match result {
                    Ok(_) => {
                        this.session_notice = Some("Email marked read".into());
                        let key = format!("{}:{thread_id}", EntityType::EmailThread);
                        this.workspace.entity_details.remove(&key);
                        if let Some(OpenEntity::Inbox(item)) = this.open_entities.get(&key).cloned()
                        {
                            this.load_entity_detail(item, cx);
                        }
                        this.load_inbox(false, cx);
                        this.refresh_loaded_mail_views(cx);
                    }
                    Err(error) => {
                        this.session_notice = Some(format!("Email update failed: {error}"));
                    }
                }
                cx.notify();
            })?;
            anyhow::Ok(())
        })
        .detach();
    }

    fn classify_email_sender(
        &mut self,
        email_address: String,
        link_id: Option<String>,
        important: bool,
        cx: &mut Context<Self>,
    ) {
        let api = self.api.clone();
        let classification = if important { "Signal" } else { "Noise" };
        self.session_notice = Some(format!(
            "Moving future mail from {email_address} to {classification}…"
        ));
        cx.spawn(async move |this, cx| {
            let result = api
                .upsert_email_filter(
                    &UpsertEmailFilterRequest {
                        email_address: Some(email_address.clone()),
                        email_domain: None,
                        is_important: important,
                    },
                    link_id.as_deref(),
                )
                .await;
            this.update(cx, |this, cx| {
                match result {
                    Ok(response) => {
                        this.pending_undo = Some(UndoAction::DeleteEmailFilter {
                            filter_id: response.filter.id,
                            link_id,
                        });
                        this.session_notice = Some(format!(
                            "Future mail from {email_address} will appear in {classification}"
                        ));
                        this.load_inbox(false, cx);
                    }
                    Err(error) => {
                        this.session_notice = Some(format!("Sender rule failed: {error}"));
                    }
                }
                cx.notify();
            })?;
            anyhow::Ok(())
        })
        .detach();
    }

    fn block_email_sender(
        &mut self,
        email_address: String,
        link_id: Option<String>,
        cx: &mut Context<Self>,
    ) {
        let api = self.api.clone();
        self.session_notice = Some(format!("Blocking {email_address}…"));
        cx.spawn(async move |this, cx| {
            let result = api
                .block_email_sender(&email_address, link_id.as_deref())
                .await;
            this.update(cx, |this, cx| {
                match result {
                    Ok(()) => {
                        this.pending_undo = Some(UndoAction::UnblockEmailSender {
                            email_address: email_address.clone(),
                            link_id,
                        });
                        this.session_notice = Some(format!("Blocked {email_address}"));
                        this.load_inbox(false, cx);
                    }
                    Err(error) => {
                        this.session_notice = Some(format!("Block sender failed: {error}"));
                    }
                }
                cx.notify();
            })?;
            anyhow::Ok(())
        })
        .detach();
    }

    fn mutation_field(
        label: &'static str,
        value: impl Into<String>,
        multiline: bool,
    ) -> MutationField {
        MutationField {
            label,
            value: value.into(),
            multiline,
            sensitive: false,
        }
    }

    fn sensitive_mutation_field(label: &'static str) -> MutationField {
        MutationField {
            label,
            value: String::new(),
            multiline: false,
            sensitive: true,
        }
    }

    fn open_mutation_dialog(&mut self, dialog: MutationDialog, cx: &mut Context<Self>) {
        if let Some(kind) = self
            .mutation_dialog
            .as_ref()
            .map(|dialog| dialog.kind.clone())
        {
            self.discard_document_comment_draft_for_kind(&kind, cx);
        }
        self.command_palette_open = false;
        self.mutation_dialog_generation = self.mutation_dialog_generation.wrapping_add(1);
        self.mutation_editor = None;
        self.mutation_text_editors.clear();
        self.snippet_typeahead_selections
            .retain(|target, _| matches!(target, SnippetInsertionTarget::Document(_)));
        self.snippet_insertions
            .retain(|target| matches!(target, SnippetInsertionTarget::Document(_)));
        self.mutation_dialog = Some(dialog);
        cx.notify();
    }

    fn dismiss_mutation_dialog(&mut self, cx: &mut Context<Self>) {
        let typing_target = self
            .mutation_dialog
            .as_ref()
            .and_then(|dialog| mutation_channel_typing_target(&dialog.kind));
        if let Some(kind) = self
            .mutation_dialog
            .as_ref()
            .map(|dialog| dialog.kind.clone())
        {
            self.discard_document_comment_draft_for_kind(&kind, cx);
        }
        self.mutation_dialog = None;
        self.mutation_editor = None;
        self.mutation_text_editors.clear();
        if let Some((channel_id, thread_id)) = typing_target {
            self.stop_local_channel_typing(channel_id, thread_id, cx);
        }
        cx.notify();
    }

    /// Multiline mutation bodies use Zed's native editor instead of the
    /// key-by-key placeholder control. This supplies real IME composition,
    /// selection, undo/redo, find, and rich clipboard behavior to channel
    /// messages, mail, comments, agent prompts, tasks, and document forms.
    fn ensure_mutation_editor(&mut self, window: &mut Window, cx: &mut Context<Self>) {
        let Some((field_index, initial_text)) = self.mutation_dialog.as_ref().and_then(|dialog| {
            dialog
                .fields
                .iter()
                .enumerate()
                .find(|(_, field)| field.multiline)
                .map(|(index, field)| (index, field.value.clone()))
        }) else {
            self.mutation_editor = None;
            return;
        };
        let generation = self.mutation_dialog_generation;
        if self
            .mutation_editor
            .as_ref()
            .is_some_and(|state| state.generation == generation && state.field_index == field_index)
        {
            return;
        }

        let editor = cx.new(|cx| {
            let initial_lexical_state = markdown_to_lexical_state(&initial_text);
            let initial_visible_text = lexical_state_to_markdown(&initial_lexical_state);
            let mut editor = NativeDocumentEditor::new(
                format!("mutation:{generation}:{field_index}"),
                "Composer".into(),
                initial_visible_text,
                false,
                window,
                cx,
            );
            editor.mark_saved_with_lexical_state(initial_lexical_state, cx);
            editor
        });
        let subscription =
            cx.subscribe_in(&editor, window, move |this, editor, event, window, cx| {
                if !this.mutation_editor.as_ref().is_some_and(|state| {
                    state.generation == generation && state.field_index == field_index
                }) {
                    return;
                }
                match event {
                    DocumentEditorEvent::Changed => {
                        let text = editor.read(cx).text(cx);
                        let typing_target = this.mutation_dialog.as_mut().and_then(|dialog| {
                            let target = mutation_channel_typing_target(&dialog.kind);
                            if let Some(field) = dialog.fields.get_mut(field_index) {
                                field.value = text;
                                dialog.error = None;
                            }
                            target
                        });
                        if let Some((channel_id, thread_id)) = typing_target {
                            this.record_channel_typing_keystroke(channel_id, thread_id, cx);
                        }
                        this.schedule_email_draft_autosave(cx);
                    }
                    DocumentEditorEvent::SelectionChanged => {}
                    DocumentEditorEvent::SnippetTypeahead(command) => {
                        this.handle_snippet_typeahead_command(
                            SnippetInsertionTarget::Mutation { generation },
                            *command,
                            window,
                            cx,
                        );
                    }
                }
                cx.notify();
            });
        self.mutation_editor = Some(MutationEditorState {
            generation,
            field_index,
            editor,
            _subscription: subscription,
        });
        self.load_snippets(false, cx);
    }

    fn ensure_mutation_text_editors(&mut self, window: &mut Window, cx: &mut Context<Self>) {
        let Some(dialog) = self.mutation_dialog.as_ref() else {
            self.mutation_text_editors.clear();
            return;
        };
        let picker_search_field = match dialog.kind {
            MutationKind::InsertDocumentMention { .. } if !dialog.show_advanced => {
                Some(DOCUMENT_MENTION_SEARCH_FIELD)
            }
            MutationKind::CreateEntityLink { .. } => Some(ENTITY_LINK_SEARCH_FIELD),
            MutationKind::AddCanvasEntityMention { .. } => Some(CANVAS_ENTITY_SEARCH_FIELD),
            _ => None,
        };
        let focus_picker_search = picker_search_field == Some(dialog.active_field);
        let generation = self.mutation_dialog_generation;
        let expected_fields = dialog
            .fields
            .iter()
            .enumerate()
            .filter(|(_, field)| !field.multiline)
            .map(|(index, field)| (index, field.label, field.value.clone(), field.sensitive))
            .collect::<Vec<_>>();
        let current_fields = self
            .mutation_text_editors
            .iter()
            .filter(|state| state.generation == generation)
            .map(|state| state.field_index)
            .collect::<HashSet<_>>();
        let expected_indexes = expected_fields
            .iter()
            .map(|(index, _, _, _)| *index)
            .collect::<HashSet<_>>();
        if current_fields == expected_indexes
            && self
                .mutation_text_editors
                .iter()
                .all(|state| state.generation == generation)
        {
            return;
        }

        self.mutation_text_editors.clear();
        for (field_index, label, initial_value, sensitive) in expected_fields {
            let editor = cx.new(|cx| {
                let mut editor = ZedTextEditor::single_line(window, cx);
                editor.set_placeholder_text(&mutation_field_placeholder(label), window, cx);
                editor.set_text(initial_value, window, cx);
                editor.set_masked(sensitive, cx);
                editor
            });
            let edit_subscription =
                cx.subscribe_in(&editor, window, move |this, editor, event, _, cx| {
                    if !matches!(event, ZedEditorEvent::BufferEdited)
                        || this.mutation_dialog_generation != generation
                    {
                        return;
                    }
                    let value = editor.read(cx).text(cx);
                    if let Some(dialog) = this.mutation_dialog.as_mut()
                        && let Some(field) = dialog.fields.get_mut(field_index)
                    {
                        field.value = value;
                        dialog.active_field = field_index;
                        dialog.error = None;
                        if (matches!(dialog.kind, MutationKind::InsertDocumentMention { .. })
                            && field_index == DOCUMENT_MENTION_SEARCH_FIELD)
                            || (matches!(dialog.kind, MutationKind::CreateEntityLink { .. })
                                && field_index == ENTITY_LINK_SEARCH_FIELD)
                            || (matches!(dialog.kind, MutationKind::AddCanvasEntityMention { .. })
                                && field_index == CANVAS_ENTITY_SEARCH_FIELD)
                        {
                            dialog.picker_selected_index = 0;
                        }
                    }
                    this.schedule_email_draft_autosave(cx);
                    cx.notify();
                });
            let focus_handle = editor.read(cx).focus_handle(cx);
            let focus_subscription = cx.on_focus_in(&focus_handle, window, move |this, _, cx| {
                if this.mutation_dialog_generation != generation {
                    return;
                }
                if let Some(dialog) = this.mutation_dialog.as_mut() {
                    dialog.active_field = field_index;
                }
                cx.notify();
            });
            self.mutation_text_editors.push(MutationTextEditorState {
                generation,
                field_index,
                editor,
                _edit_subscription: edit_subscription,
                _focus_subscription: focus_subscription,
            });
        }
        if focus_picker_search
            && let Some(editor) =
                self.mutation_text_editor(picker_search_field.expect("picker field is known"))
        {
            window.focus(&editor.read(cx).focus_handle(cx), cx);
        }
    }

    fn mutation_text_editor(&self, field_index: usize) -> Option<Entity<ZedTextEditor>> {
        self.mutation_text_editors
            .iter()
            .find(|state| {
                state.generation == self.mutation_dialog_generation
                    && state.field_index == field_index
            })
            .map(|state| state.editor.clone())
    }

    fn set_mutation_field_value(
        &mut self,
        field_index: usize,
        value: String,
        window: &mut Window,
        cx: &mut Context<Self>,
    ) {
        let Some(dialog) = self.mutation_dialog.as_mut() else {
            return;
        };
        let Some(field) = dialog.fields.get_mut(field_index) else {
            return;
        };
        field.value.clone_from(&value);
        dialog.active_field = field_index;
        dialog.error = None;
        if (matches!(dialog.kind, MutationKind::InsertDocumentMention { .. })
            && field_index == DOCUMENT_MENTION_SEARCH_FIELD)
            || (matches!(dialog.kind, MutationKind::CreateEntityLink { .. })
                && field_index == ENTITY_LINK_SEARCH_FIELD)
            || (matches!(dialog.kind, MutationKind::AddCanvasEntityMention { .. })
                && field_index == CANVAS_ENTITY_SEARCH_FIELD)
        {
            dialog.picker_selected_index = 0;
        }
        if let Some(editor) = self.mutation_text_editor(field_index)
            && editor.read(cx).text(cx) != value
        {
            editor.update(cx, |editor, cx| editor.set_text(value, window, cx));
        }
        self.schedule_email_draft_autosave(cx);
        cx.notify();
    }

    fn format_mutation_editor(
        &mut self,
        command: MarkdownCommand,
        window: &mut Window,
        cx: &mut Context<Self>,
    ) {
        let Some(editor) = self
            .mutation_editor
            .as_ref()
            .map(|state| state.editor.clone())
        else {
            return;
        };
        editor.update(cx, |editor, cx| {
            editor.apply_markdown_command(command, window, cx);
        });
        cx.notify();
    }

    fn mutation_editor_macro_markdown(&self, cx: &App) -> Option<String> {
        let state = self.mutation_editor.as_ref()?;
        (state.generation == self.mutation_dialog_generation)
            .then(|| state.editor.read(cx).lexical_source().cloned())
            .flatten()
            .map(|source| lexical_state_to_macro_markdown(&source))
    }

    fn insert_email_body_mention(
        &mut self,
        user_id: String,
        email: String,
        display_name: String,
        window: &mut Window,
        cx: &mut Context<Self>,
    ) {
        let Some(editor) = self
            .mutation_editor
            .as_ref()
            .filter(|state| state.generation == self.mutation_dialog_generation)
            .map(|state| state.editor.clone())
        else {
            return;
        };
        let insertion = editor.update(cx, |editor, cx| {
            editor.insert_macro_mention(
                MacroInlineMention::User {
                    user_id,
                    email: email.clone(),
                    display_name,
                },
                window,
                cx,
            )
        });
        match insertion {
            Ok(()) => {
                if let Some(dialog) = self.mutation_dialog.as_mut() {
                    let already_recipient = [0, 3, 4].into_iter().any(|index| {
                        dialog.fields.get(index).is_some_and(|field| {
                            comma_separated_values(&field.value)
                                .iter()
                                .any(|candidate| candidate.eq_ignore_ascii_case(&email))
                        })
                    });
                    if !already_recipient && let Some(cc) = dialog.fields.get_mut(3) {
                        append_email_recipient(&mut cc.value, &email);
                        dialog.email_show_cc = true;
                        self.session_notice = Some(format!("{email} added to Cc"));
                    }
                    dialog.active_field = 2;
                    dialog.error = None;
                }
                self.schedule_email_draft_autosave(cx);
            }
            Err(error) => {
                if let Some(dialog) = self.mutation_dialog.as_mut() {
                    dialog.error = Some(format!("Could not insert mention: {error}"));
                }
            }
        }
        cx.notify();
    }

    fn insert_channel_composer_mention(
        &mut self,
        mention: MacroInlineMention,
        references: Vec<SimpleMention>,
        window: &mut Window,
        cx: &mut Context<Self>,
    ) {
        let Some(editor) = self
            .mutation_editor
            .as_ref()
            .filter(|state| state.generation == self.mutation_dialog_generation)
            .map(|state| state.editor.clone())
        else {
            return;
        };
        let insertion = editor.update(cx, |editor, cx| {
            editor.insert_macro_mention(mention, window, cx)
        });
        match insertion {
            Ok(()) => {
                if let Some(dialog) = self.mutation_dialog.as_mut() {
                    if let Some(field) = dialog.fields.get_mut(1) {
                        field.value = merged_channel_mentions(&field.value, references);
                    }
                    dialog.active_field = 0;
                    dialog.error = None;
                }
            }
            Err(error) => {
                if let Some(dialog) = self.mutation_dialog.as_mut() {
                    dialog.error = Some(format!("Could not insert mention: {error}"));
                }
            }
        }
        cx.notify();
    }

    /// Debounces email draft persistence without blocking the native editor.
    /// Draft writes are serialized per composer so a slow response can never
    /// overwrite a newer local edit or create a second server draft.
    fn schedule_email_draft_autosave(&mut self, cx: &mut Context<Self>) {
        let dialog_generation = self.mutation_dialog_generation;
        let Some(dialog) = self.mutation_dialog.as_mut() else {
            return;
        };
        if !matches!(
            dialog.kind,
            MutationKind::ComposeEmail | MutationKind::ReplyEmail { .. }
        ) || dialog.busy
        {
            return;
        }
        dialog.email_autosave_generation = dialog.email_autosave_generation.wrapping_add(1);
        dialog.email_autosave_pending = true;
        dialog.email_autosave_error = None;
        let autosave_generation = dialog.email_autosave_generation;
        cx.spawn(async move |this, cx| {
            cx.background_executor()
                .timer(Duration::from_millis(500))
                .await;
            this.update(cx, |this, cx| {
                let should_save = this.mutation_dialog.as_ref().is_some_and(|dialog| {
                    this.mutation_dialog_generation == dialog_generation
                        && dialog.email_autosave_generation == autosave_generation
                        && dialog.email_autosave_pending
                        && !dialog.busy
                });
                if should_save {
                    this.begin_email_draft_autosave(dialog_generation, autosave_generation, cx);
                }
            })?;
            anyhow::Ok(())
        })
        .detach();
    }

    fn retry_email_draft_autosave(&mut self, cx: &mut Context<Self>) {
        let Some(dialog) = self.mutation_dialog.as_mut() else {
            return;
        };
        if !matches!(
            dialog.kind,
            MutationKind::ComposeEmail | MutationKind::ReplyEmail { .. }
        ) || dialog.busy
            || dialog.email_autosave_in_flight
        {
            return;
        }
        dialog.email_autosave_error = None;
        self.schedule_email_draft_autosave(cx);
    }

    fn begin_email_draft_autosave(
        &mut self,
        dialog_generation: u64,
        autosave_generation: u64,
        cx: &mut Context<Self>,
    ) {
        if self.mutation_dialog_generation != dialog_generation {
            return;
        }
        let editor_body_macro = self.mutation_editor_macro_markdown(cx);
        let Some(dialog) = self.mutation_dialog.as_mut() else {
            return;
        };
        if dialog.busy
            || dialog.email_autosave_generation != autosave_generation
            || !dialog.email_autosave_pending
        {
            return;
        }
        if dialog.email_autosave_in_flight {
            return;
        }

        let values = dialog
            .fields
            .iter()
            .map(|field| field.value.clone())
            .collect::<Vec<_>>();
        let (thread_id, replying_to_id) = match &dialog.kind {
            MutationKind::ComposeEmail => (None, None),
            MutationKind::ReplyEmail {
                thread_id,
                replying_to_id,
            } => (Some(thread_id.clone()), Some(replying_to_id.clone())),
            _ => return,
        };
        let attachment_count = dialog.email_attachments.len();
        let forwarded_attachment_ids = dialog
            .email_attachments
            .iter()
            .filter(|attachment| attachment.kind == EmailDraftAttachmentKind::Forwarded)
            .map(|attachment| attachment.id.clone())
            .collect::<Vec<_>>();
        let mut draft = match email_autosave_draft_from_values_with_body(
            &values,
            thread_id,
            replying_to_id,
            attachment_count,
            editor_body_macro.as_deref(),
            dialog.email_appended_quote.as_ref(),
            dialog.email_include_signature,
        ) {
            Ok(draft) => draft,
            Err(error) => {
                dialog.email_autosave_pending = false;
                dialog.email_autosave_error = Some(error.to_string());
                cx.notify();
                return;
            }
        };
        let existing_draft_id = dialog.email_draft_id.clone();
        let requested_link_id = dialog
            .email_link_id
            .clone()
            .or_else(|| values.get(7).filter(|value| !value.is_empty()).cloned());
        let send_time = values
            .get(5)
            .is_some_and(|action| action.eq_ignore_ascii_case("schedule"))
            .then(|| values.get(6).cloned().unwrap_or_default())
            .filter(|value| !value.trim().is_empty());

        if let Some(draft) = draft.as_mut() {
            draft.db_id = existing_draft_id.clone();
        } else if existing_draft_id.is_none() {
            dialog.email_autosave_pending = false;
            dialog.email_last_saved_fingerprint = None;
            dialog.email_autosave_error = None;
            cx.notify();
            return;
        }

        let fingerprint = serde_json::to_string(&(
            draft.as_ref(),
            send_time.as_ref(),
            requested_link_id.as_ref(),
            dialog
                .email_attachments
                .iter()
                .map(|attachment| attachment.id.as_str())
                .collect::<Vec<_>>(),
        ))
        .unwrap_or_default();
        if dialog.email_last_saved_fingerprint.as_deref() == Some(fingerprint.as_str()) {
            dialog.email_autosave_pending = false;
            dialog.email_autosave_error = None;
            return;
        }

        dialog.email_autosave_pending = false;
        dialog.email_autosave_in_flight = true;
        dialog.email_autosave_error = None;
        let api = self.api.clone();
        cx.spawn(async move |this, cx| {
            let result = match draft {
                Some(draft) => create_email_draft_with_forwarded(
                    &api,
                    draft,
                    send_time,
                    requested_link_id.as_deref(),
                    &forwarded_attachment_ids,
                )
                .await
                .map(Some),
                None => api
                    .delete_email_draft_for_link(
                        existing_draft_id.as_deref().unwrap_or_default(),
                        requested_link_id.as_deref(),
                    )
                    .await
                    .map(|()| None),
            };
            this.update(cx, |this, cx| {
                if this.mutation_dialog_generation != dialog_generation {
                    return;
                }
                let mut continue_generation = None;
                if let Some(dialog) = this.mutation_dialog.as_mut() {
                    dialog.email_autosave_in_flight = false;
                    match result {
                        Ok(Some(saved)) => {
                            dialog.email_draft_id = saved.draft.db_id;
                            dialog.email_link_id = Some(saved.draft.link_id);
                            dialog.email_last_saved_fingerprint = Some(fingerprint);
                            dialog.email_autosave_error = None;
                        }
                        Ok(None) => {
                            dialog.email_draft_id = None;
                            dialog.email_last_saved_fingerprint = None;
                            dialog.email_autosave_error = None;
                        }
                        Err(error) => {
                            dialog.email_autosave_error =
                                Some(format!("Draft autosave failed: {error}"));
                        }
                    }
                    if dialog.email_autosave_pending {
                        continue_generation = Some(dialog.email_autosave_generation);
                    }
                }
                if let Some(generation) = continue_generation {
                    this.begin_email_draft_autosave(dialog_generation, generation, cx);
                }
                cx.notify();
            })?;
            anyhow::Ok(())
        })
        .detach();
        cx.notify();
    }

    fn open_set_entity_property(
        &mut self,
        entity_type: EntityType,
        entity_id: String,
        property: macro_entity::EntityProperty,
        cx: &mut Context<Self>,
    ) {
        if !self.can_edit_entity(entity_type, &entity_id) {
            self.session_notice = Some("You do not have edit access to this entity.".into());
            cx.notify();
            return;
        }
        let hint = match property.data_type.as_str() {
            "BOOLEAN" => "Value (true/false)",
            "NUMBER" | "SELECT_NUMBER" => "Value or option ID(s)",
            "DATE" => "ISO date or timestamp",
            "ENTITY" => "Entity reference(s), TYPE:ID",
            "LINK" => "URL(s), comma separated",
            "SELECT_STRING" | "TAG" => "Option ID(s), comma separated",
            _ => "Value",
        };
        let mut fields = vec![Self::mutation_field(
            hint,
            property_input_value(&property.value),
            false,
        )];
        if property.data_type == "ENTITY" {
            fields.push(Self::mutation_field(
                "Search people, documents, tasks, and companies",
                "",
                false,
            ));
        }
        let mut dialog = MutationDialog::new(
            "Edit property",
            "Save property",
            MutationKind::SetEntityProperty {
                entity_type,
                entity_id,
                property_id: property.definition_id.clone(),
                data_type: property.data_type.clone(),
                is_multi_select: property.is_multi_select,
            },
            fields,
        );
        dialog.property_editor = Some(PropertyEditorSpec {
            display_name: property.display_name,
            data_type: property.data_type,
            is_multi_select: property.is_multi_select,
            options: property.options,
        });
        self.open_mutation_dialog(dialog, cx);
    }

