    fn open_update_entity_sharing(
        &mut self,
        entity_type: EntityType,
        entity_id: String,
        cx: &mut Context<Self>,
    ) {
        if !self.can_edit_entity(entity_type, &entity_id) {
            self.session_notice = Some("You do not have permission to change sharing.".into());
            cx.notify();
            return;
        }
        if !self.workspace.channels.is_ready() {
            self.load_channels(false, cx);
        }
        if entity_type == EntityType::EmailThread {
            self.open_mutation_dialog(
                MutationDialog::new(
                    "Share email thread",
                    "Share view-only",
                    MutationKind::UpdateEntitySharing {
                        entity_type,
                        entity_id,
                    },
                    vec![Self::mutation_field("Channel", "", false)],
                ),
                cx,
            );
            return;
        }
        let key = format!("{entity_type}:{entity_id}");
        let current = self
            .workspace
            .entity_share_permissions
            .get(&key)
            .and_then(DataState::loaded);
        let link_share = current
            .and_then(|permissions| permissions.link_share)
            .map(|share| match share {
                ApiLinkShare::Public => "public",
                ApiLinkShare::Team => "team",
            })
            .unwrap_or("none");
        let access = current
            .and_then(|permissions| permissions.link_share_access_level)
            .map(share_access_label)
            .unwrap_or("view");
        self.open_mutation_dialog(
            MutationDialog::new(
                "Share entity",
                "Update sharing",
                MutationKind::UpdateEntitySharing {
                    entity_type,
                    entity_id,
                },
                vec![
                    Self::mutation_field("Link visibility (none/public/team)", link_share, false),
                    Self::mutation_field("Link access (view/comment/edit)", access, false),
                    Self::mutation_field("Channel ID to add (optional)", "", false),
                    Self::mutation_field("Channel access (view/comment/edit)", "view", false),
                ],
            ),
            cx,
        );
    }

    fn remove_entity_channel_share(
        &mut self,
        entity_type: EntityType,
        entity_id: String,
        channel_id: String,
        cx: &mut Context<Self>,
    ) {
        if !self.can_edit_entity(entity_type, &entity_id) {
            if let Some(dialog) = self.mutation_dialog.as_mut() {
                dialog.error = Some("You do not have permission to change sharing.".into());
            }
            cx.notify();
            return;
        }
        let api = self.api.clone();
        let request = remove_channel_share_request(channel_id.clone());
        if let Some(dialog) = self.mutation_dialog.as_mut() {
            dialog.busy = true;
            dialog.error = None;
        }
        cx.spawn(async move |this, cx| {
            let result = match entity_type {
                EntityType::Document | EntityType::Skill => {
                    api.update_document_share_permissions(&entity_id, &request)
                        .await
                }
                EntityType::Project => {
                    api.update_project_share_permissions(&entity_id, &request)
                        .await
                }
                EntityType::ChannelMessage | EntityType::EmailThread => {
                    api.update_thread_share_permissions(&entity_id, &request)
                        .await
                }
                _ => Err(anyhow::anyhow!(
                    "This entity type does not expose share permissions"
                )),
            };
            this.update(cx, |this, cx| {
                if let Some(dialog) = this.mutation_dialog.as_mut() {
                    dialog.busy = false;
                }
                match result {
                    Ok(_) => {
                        let key = format!("{entity_type}:{entity_id}");
                        this.workspace.entity_share_permissions.remove(&key);
                        this.load_entity_capabilities(entity_type, entity_id.clone(), true, cx);
                        let channel_label = this
                            .workspace
                            .channels
                            .get(&channel_id)
                            .map(|channel| channel.name.clone())
                            .unwrap_or_else(|| channel_id.clone());
                        this.session_notice =
                            Some(format!("Removed #{channel_label} from sharing"));
                    }
                    Err(error) => {
                        if let Some(dialog) = this.mutation_dialog.as_mut() {
                            dialog.error = Some(format!("Removing channel access failed: {error}"));
                        }
                    }
                }
                cx.notify();
            })?;
            anyhow::Ok(())
        })
        .detach();
        cx.notify();
    }

    fn open_new_document_comment(&mut self, document_id: String, cx: &mut Context<Self>) {
        self.load_people_cache(false, cx);
        let selection = self
            .document_editors
            .get(&document_id)
            .cloned()
            .and_then(|editor| {
                editor.update(cx, |editor, cx| {
                    let selection = editor.selected_markdown_range(cx)?;
                    let text = editor.text(cx);
                    let selected_text = text.get(selection.clone())?.to_owned();
                    Some((selection.start, selection.end, selected_text))
                })
            })
            .filter(|(start, end, _)| start < end);
        let mark_id = format!("DISCUSSION:{}", uuid::Uuid::new_v4());
        if let Some((start, end, _)) = selection.as_ref() {
            self.apply_document_comment_draft(&document_id, *start..*end, &mark_id, cx);
        }
        self.open_mutation_dialog(
            MutationDialog::new(
                "New comment",
                "Comment",
                MutationKind::NewDocumentComment {
                    document_id,
                    mark_id,
                    selection,
                },
                vec![
                    Self::mutation_field("Comment", "", true),
                    Self::mutation_field("Mention people", "", false),
                ],
            ),
            cx,
        );
    }

    fn apply_document_comment_draft(
        &mut self,
        document_id: &str,
        selection: std::ops::Range<usize>,
        mark_id: &str,
        cx: &mut Context<Self>,
    ) -> bool {
        let Some(editor) = self.document_editors.get(document_id).cloned() else {
            return false;
        };
        if editor.read(cx).remote_conflict().is_some() {
            return false;
        }
        let Some(source) = editor.read(cx).lexical_source().cloned() else {
            return false;
        };
        let current = editor.read(cx).text(cx);
        let Ok(projected) = project_markdown_edits(&source, &current) else {
            return false;
        };
        let Ok(draft) = anchor_document_comment_draft(&projected, selection, mark_id) else {
            return false;
        };
        editor.update(cx, |editor, cx| {
            editor.accept_lexical_annotation_state(draft, cx)
        });
        true
    }

    fn discard_document_comment_draft_for_kind(
        &mut self,
        kind: &MutationKind,
        cx: &mut Context<Self>,
    ) {
        let MutationKind::NewDocumentComment {
            document_id,
            mark_id,
            selection: Some(_),
        } = kind
        else {
            return;
        };
        let Some(editor) = self.document_editors.get(document_id).cloned() else {
            return;
        };
        let Some(source) = editor.read(cx).lexical_source().cloned() else {
            return;
        };
        let without_draft = remove_document_comment_mark(&source, mark_id);
        if without_draft != source {
            editor.update(cx, |editor, cx| {
                editor.accept_lexical_annotation_state(without_draft, cx)
            });
        }
    }

