    fn print_document(&mut self, document_id: &str, name: &str, cx: &mut Context<Self>) {
        let Some(editor) = self.document_editors.get(document_id) else {
            self.session_notice = Some("Open the document before printing it.".into());
            cx.notify();
            return;
        };
        let markdown = editor.read(cx).text(cx);
        let html = printable_document_html(name, &markdown);
        let directory = std::env::temp_dir().join("macro-gpui-print");
        let path = directory.join(format!("{}.html", uuid::Uuid::new_v4()));
        let result = std::fs::create_dir_all(&directory).and_then(|_| std::fs::write(&path, html));
        match result {
            Ok(()) => {
                cx.open_with_system(&path);
                self.session_notice = Some("Print preview opened in your default browser".into());
            }
            Err(error) => {
                self.session_notice = Some(format!("Print preview could not be created: {error}"));
            }
        }
        cx.notify();
    }

    fn download_document(
        &mut self,
        document_id: String,
        suggested_name: String,
        cx: &mut Context<Self>,
    ) {
        let receiver =
            cx.prompt_for_new_path(std::path::Path::new(""), Some(suggested_name.as_str()));
        let api = self.api.clone();
        cx.spawn(async move |this, cx| {
            let destination = match receiver.await {
                Ok(Ok(Some(path))) => path,
                Ok(Ok(None)) => return anyhow::Ok(()),
                Ok(Err(error)) => {
                    this.update(cx, |this, cx| {
                        this.session_notice = Some(format!("Save dialog failed: {error}"));
                        cx.notify();
                    })?;
                    return anyhow::Ok(());
                }
                Err(error) => {
                    this.update(cx, |this, cx| {
                        this.session_notice = Some(format!("Save dialog closed: {error}"));
                        cx.notify();
                    })?;
                    return anyhow::Ok(());
                }
            };
            this.update(cx, |this, cx| {
                this.session_notice = Some(format!(
                    "Downloading {}…",
                    destination
                        .file_name()
                        .and_then(|name| name.to_str())
                        .unwrap_or("file")
                ));
                cx.notify();
            })?;
            let result = async {
                let bytes = api.download_document_bytes(&document_id).await?;
                let write_path = destination.clone();
                cx.background_spawn(async move {
                    std::fs::write(&write_path, bytes)
                        .with_context(|| format!("failed to write {}", write_path.display()))
                })
                .await?;
                anyhow::Ok(())
            }
            .await;
            this.update(cx, |this, cx| {
                match result {
                    Ok(()) => {
                        cx.reveal_path(&destination);
                        this.session_notice = Some(format!("Saved {}", destination.display()));
                    }
                    Err(error) => {
                        this.session_notice = Some(format!("Download failed: {error:#}"));
                    }
                }
                cx.notify();
            })?;
            anyhow::Ok(())
        })
        .detach();
    }

    fn download_agent_artifact(&mut self, artifact: AgentArtifact, cx: &mut Context<Self>) {
        let filename = agent_artifact_filename(&artifact);
        let receiver = cx.prompt_for_new_path(std::path::Path::new(""), Some(filename.as_str()));
        cx.spawn(async move |this, cx| {
            let destination = match receiver.await {
                Ok(Ok(Some(path))) => path,
                Ok(Ok(None)) => return anyhow::Ok(()),
                Ok(Err(error)) => {
                    this.update(cx, |this, cx| {
                        this.session_notice = Some(format!("Save dialog failed: {error}"));
                        cx.notify();
                    })?;
                    return anyhow::Ok(());
                }
                Err(error) => {
                    this.update(cx, |this, cx| {
                        this.session_notice = Some(format!("Save dialog closed: {error}"));
                        cx.notify();
                    })?;
                    return anyhow::Ok(());
                }
            };
            this.update(cx, |this, cx| {
                this.session_notice = Some(format!("Saving {filename}…"));
                cx.notify();
            })?;
            let write_path = destination.clone();
            let result = cx
                .background_spawn(async move {
                    let bytes = artifact
                        .decoded_data()?
                        .context("agent artifact has no downloadable payload")?;
                    std::fs::write(&write_path, bytes)
                        .with_context(|| format!("failed to write {}", write_path.display()))
                })
                .await;
            this.update(cx, |this, cx| {
                match result {
                    Ok(()) => {
                        cx.reveal_path(&destination);
                        this.session_notice = Some(format!("Saved {}", destination.display()));
                    }
                    Err(error) => {
                        this.session_notice = Some(format!("Artifact download failed: {error:#}"));
                    }
                }
                cx.notify();
            })?;
            anyhow::Ok(())
        })
        .detach();
    }

    fn pick_and_upload_files(&mut self, cx: &mut Context<Self>) {
        let receiver = cx.prompt_for_paths(PathPromptOptions {
            files: true,
            directories: false,
            multiple: true,
            prompt: Some("Upload files to Macro".into()),
        });
        let project_id = self.active_project_id.clone();
        cx.spawn(async move |this, cx| {
            let paths = match receiver.await {
                Ok(Ok(Some(paths))) => paths,
                Ok(Ok(None)) => return anyhow::Ok(()),
                Ok(Err(error)) => {
                    this.update(cx, |this, cx| {
                        this.session_notice = Some(format!("File picker failed: {error}"));
                        cx.notify();
                    })?;
                    return anyhow::Ok(());
                }
                Err(error) => {
                    this.update(cx, |this, cx| {
                        this.session_notice = Some(format!("File picker closed: {error}"));
                        cx.notify();
                    })?;
                    return anyhow::Ok(());
                }
            };
            this.update(cx, |this, cx| {
                for path in paths {
                    this.start_file_upload(path, project_id.clone(), cx);
                }
                cx.notify();
            })?;
            anyhow::Ok(())
        })
        .detach();
    }

    fn start_file_upload(
        &mut self,
        path: PathBuf,
        project_id: Option<String>,
        cx: &mut Context<Self>,
    ) {
        let file_name = path
            .file_name()
            .and_then(|value| value.to_str())
            .unwrap_or("upload")
            .to_owned();
        if let Some(control) = self.file_upload_controls.get(&file_name) {
            control.cancel();
        }
        let generation = self
            .file_upload_generations
            .entry(file_name.clone())
            .and_modify(|generation| *generation = generation.wrapping_add(1))
            .or_insert(1)
            .to_owned();
        let control = UploadControl::default();
        self.file_upload_controls
            .insert(file_name.clone(), control.clone());
        self.file_upload_sources
            .insert(file_name.clone(), path.clone());
        self.file_upload_projects
            .insert(file_name.clone(), project_id.clone());
        self.file_uploads
            .insert(file_name.clone(), "Preparing…".into());

        let (progress_tx, mut progress_rx) = futures::channel::mpsc::unbounded::<UploadProgress>();
        let progress_name = file_name.clone();
        cx.spawn(async move |this, cx| {
            while let Some(progress) = progress_rx.next().await {
                this.update(cx, |this, cx| {
                    if this.file_upload_generations.get(&progress_name) != Some(&generation) {
                        return;
                    }
                    let percent = if progress.total_bytes == 0 {
                        100
                    } else {
                        ((progress.uploaded_bytes.saturating_mul(100) / progress.total_bytes)
                            .min(100)) as u32
                    };
                    this.file_uploads.insert(
                        progress_name.clone(),
                        format!(
                            "Uploading {percent}% · {} / {}",
                            byte_size_label(progress.uploaded_bytes),
                            byte_size_label(progress.total_bytes)
                        ),
                    );
                    cx.notify();
                })?;
            }
            anyhow::Ok(())
        })
        .detach();

        let api = self.api.clone();
        cx.spawn(async move |this, cx| {
            let mime_type = mime_type_for_path(&path).to_owned();
            let result = api
                .upload_document_path_with_progress(
                    &file_name,
                    &mime_type,
                    path,
                    MAX_GENERAL_UPLOAD_BYTES,
                    project_id.clone(),
                    control.clone(),
                    Some(progress_tx),
                )
                .await;
            let result = match result {
                Ok(document) if !control.is_cancelled() => {
                    this.update(cx, |this, cx| {
                        if this.file_upload_generations.get(&file_name) == Some(&generation) {
                            this.file_uploads
                                .insert(file_name.clone(), "Finalizing…".into());
                            cx.notify();
                        }
                    })?;
                    let readiness = wait_for_document_content_ready(&api, &document, cx).await;
                    if control.is_cancelled() {
                        let _ = api.delete_document(&document.document_id).await;
                        Err(anyhow::anyhow!("upload cancelled"))
                    } else {
                        Ok((document, readiness))
                    }
                }
                Ok(document) => {
                    let _ = api.delete_document(&document.document_id).await;
                    Err(anyhow::anyhow!("upload cancelled"))
                }
                Err(error) => Err(error),
            };
            this.update(cx, |this, cx| {
                if this.file_upload_generations.get(&file_name) != Some(&generation) {
                    return;
                }
                this.file_upload_controls.remove(&file_name);
                match result {
                    Ok((document, UploadReadiness::Ready)) => {
                        this.file_uploads.remove(&file_name);
                        this.file_upload_sources.remove(&file_name);
                        this.file_upload_projects.remove(&file_name);
                        this.session_notice = Some(format!(
                            "Uploaded {} ({})",
                            document.document_name, document.document_id
                        ));
                        this.apply_reconcile_plan(ReconcilePlan::new([ReconcileTarget::Inbox]), cx);
                        if let Some(project_id) = project_id.clone() {
                            this.workspace.project_contents.remove(&project_id);
                            this.load_project_content(project_id, true, cx);
                        }
                    }
                    Ok((document, UploadReadiness::StillProcessing(reason))) => {
                        this.file_uploads.remove(&file_name);
                        this.file_upload_sources.remove(&file_name);
                        this.file_upload_projects.remove(&file_name);
                        this.session_notice = Some(format!(
                            "Uploaded {}; backend processing is still pending{}",
                            document.document_name,
                            reason
                                .as_deref()
                                .map(|reason| format!(": {reason}"))
                                .unwrap_or_default()
                        ));
                        this.apply_reconcile_plan(ReconcilePlan::new([ReconcileTarget::Inbox]), cx);
                        if let Some(project_id) = project_id.clone() {
                            this.workspace.project_contents.remove(&project_id);
                            this.load_project_content(project_id, true, cx);
                        }
                    }
                    Err(_) if control.is_cancelled() => {
                        this.file_uploads
                            .insert(file_name.clone(), "Cancelled".into());
                        this.session_notice = Some(format!("Cancelled upload {file_name}"));
                    }
                    Err(error) => {
                        this.file_uploads
                            .insert(file_name.clone(), format!("Failed: {error}"));
                        this.session_notice =
                            Some(format!("Could not upload {file_name}: {error}"));
                    }
                }
                cx.notify();
            })?;
            anyhow::Ok(())
        })
        .detach();
        cx.notify();
    }

    fn cancel_file_upload(&mut self, file_name: &str, cx: &mut Context<Self>) {
        if let Some(control) = self.file_upload_controls.get(file_name) {
            control.cancel();
            self.file_uploads
                .insert(file_name.to_owned(), "Cancelling…".into());
            cx.notify();
        }
    }

    fn retry_file_upload(&mut self, file_name: &str, cx: &mut Context<Self>) {
        let Some(path) = self.file_upload_sources.get(file_name).cloned() else {
            self.session_notice = Some("The original upload file is no longer available.".into());
            cx.notify();
            return;
        };
        let project_id = self.file_upload_projects.get(file_name).cloned().flatten();
        self.start_file_upload(path, project_id, cx);
    }

    fn dismiss_file_upload(&mut self, file_name: &str, cx: &mut Context<Self>) {
        if self.file_upload_controls.contains_key(file_name) {
            return;
        }
        self.file_uploads.remove(file_name);
        self.file_upload_sources.remove(file_name);
        self.file_upload_projects.remove(file_name);
        self.file_upload_generations.remove(file_name);
        cx.notify();
    }

    fn pick_and_upload_zip_folder(&mut self, cx: &mut Context<Self>) {
        let receiver = cx.prompt_for_paths(PathPromptOptions {
            files: true,
            directories: false,
            multiple: false,
            prompt: Some("Import a zip archive as a Macro folder".into()),
        });
        let api = self.api.clone();
        let parent_id = self.active_project_id.clone();
        let executor = cx.background_executor().clone();
        cx.spawn(async move |this, cx| {
            let Some(path) = receiver
                .await
                .map_err(|error| anyhow::anyhow!("folder picker closed: {error}"))??
                .and_then(|paths| paths.into_iter().next())
            else {
                return anyhow::Ok(());
            };
            let archive_name = path
                .file_name()
                .and_then(|value| value.to_str())
                .unwrap_or("folder.zip")
                .to_owned();
            if path
                .extension()
                .and_then(|value| value.to_str())
                .is_none_or(|extension| !extension.eq_ignore_ascii_case("zip"))
            {
                this.update(cx, |this, cx| {
                    this.session_notice = Some("Folder import requires a .zip archive".into());
                    cx.notify();
                })?;
                return anyhow::Ok(());
            }
            this.update(cx, |this, cx| {
                this.file_uploads
                    .insert(archive_name.clone(), "Reading archive…".into());
                cx.notify();
            })?;
            let read_path = path.clone();
            let bytes = cx
                .background_spawn(async move {
                    read_bounded_file(&read_path, MAX_GENERAL_UPLOAD_BYTES)
                })
                .await;
            let bytes = match bytes {
                Ok(bytes) => bytes,
                Err(error) => {
                    this.update(cx, |this, cx| {
                        this.file_uploads
                            .insert(archive_name.clone(), format!("Failed: {error}"));
                        this.session_notice = Some(format!(
                            "Could not read folder archive {archive_name}: {error}"
                        ));
                        cx.notify();
                    })?;
                    return anyhow::Ok(());
                }
            };
            this.update(cx, |this, cx| {
                this.file_uploads
                    .insert(archive_name.clone(), "Uploading archive…".into());
                cx.notify();
            })?;
            let result = api
                .upload_zip_folder_bytes(&archive_name, bytes, parent_id)
                .await;
            let request_id = match result {
                Ok(upload) => {
                    let request_id = upload.request_id;
                    this.update(cx, |this, cx| {
                        this.file_uploads
                            .insert(archive_name.clone(), "Extracting folder…".into());
                        this.folder_upload_requests
                            .insert(request_id.clone(), archive_name.clone());
                        this.session_notice = Some(format!(
                            "Uploaded {archive_name}; waiting for folder extraction"
                        ));
                        cx.notify();
                    })?;
                    request_id
                }
                Err(error) => {
                    this.update(cx, |this, cx| {
                        this.file_uploads
                            .insert(archive_name.clone(), format!("Failed: {error}"));
                        this.session_notice =
                            Some(format!("Could not import {archive_name}: {error:#}"));
                        cx.notify();
                    })?;
                    return anyhow::Ok(());
                }
            };

            // Macro web waits five minutes for the correlated gateway event.
            // Preserve the pending import until then and provide an explicit
            // recovery message if the terminal frame never arrives.
            executor.timer(Duration::from_secs(300)).await;
            this.update(cx, |this, cx| {
                if this.folder_upload_requests.remove(&request_id).is_some() {
                    this.file_uploads.remove(&archive_name);
                    this.session_notice = Some(format!(
                        "Folder import is taking longer than expected for {archive_name}; refresh Files to reconcile it"
                    ));
                    this.load_projects(true, cx);
                    cx.notify();
                }
            })?;
            anyhow::Ok(())
        })
        .detach();
    }

    fn pick_channel_attachments(
        &mut self,
        channel_id: String,
        thread_id: Option<String>,
        cx: &mut Context<Self>,
    ) {
        let matching_composer = self.mutation_dialog.as_ref().is_some_and(|dialog| {
            matches!(
                (&dialog.kind, thread_id.as_deref()),
                (MutationKind::NewChannelMessage { channel_id: open }, None)
                    if open == &channel_id
            ) || matches!(
                (&dialog.kind, thread_id.as_deref()),
                (
                    MutationKind::ReplyChannelMessage {
                        channel_id: open,
                        thread_id: open_thread,
                    },
                    Some(thread),
                ) if open == &channel_id && open_thread == thread
            ) || matches!(
                (&dialog.kind, thread_id.as_deref()),
                (MutationKind::EditChannelMessage { channel_id: open, .. }, None)
                    if open == &channel_id
            )
        });
        if !matching_composer {
            match thread_id.as_deref() {
                Some(thread_id) => {
                    self.open_channel_reply(channel_id.clone(), thread_id.to_owned(), cx)
                }
                None => self.open_channel_message(channel_id.clone(), cx),
            }
        }
        let generation = self.mutation_dialog_generation;
        let receiver = cx.prompt_for_paths(PathPromptOptions {
            files: true,
            directories: false,
            multiple: true,
            prompt: Some("Attach files to channel message".into()),
        });
        cx.spawn(async move |this, cx| {
            let paths = match receiver.await {
                Ok(Ok(Some(paths))) => paths,
                Ok(Ok(None)) => return anyhow::Ok(()),
                Ok(Err(error)) => {
                    this.update(cx, |this, cx| {
                        this.session_notice = Some(format!("File picker failed: {error}"));
                        cx.notify();
                    })?;
                    return anyhow::Ok(());
                }
                Err(error) => {
                    this.update(cx, |this, cx| {
                        this.session_notice = Some(format!("File picker closed: {error}"));
                        cx.notify();
                    })?;
                    return anyhow::Ok(());
                }
            };
            this.update(cx, |this, cx| {
                if this.mutation_dialog_generation != generation {
                    return;
                }
                for path in paths {
                    let name = path
                        .file_name()
                        .and_then(|value| value.to_str())
                        .unwrap_or("attachment")
                        .to_owned();
                    let mime_type = mime_type_for_path(&path).to_owned();
                    let kind = ChannelComposerAttachmentKind::from_mime_type(&mime_type);
                    let local_id = uuid::Uuid::new_v4().to_string();
                    if let Some(dialog) = this.mutation_dialog.as_mut() {
                        dialog
                            .channel_attachments
                            .push(ChannelComposerAttachmentState {
                                local_id: local_id.clone(),
                                server_attachment_id: None,
                                entity_id: None,
                                name,
                                kind,
                                source_path: path.clone(),
                                preview_path: matches!(
                                    kind,
                                    ChannelComposerAttachmentKind::Image
                                        | ChannelComposerAttachmentKind::Video
                                )
                                .then_some(path.clone()),
                                width: None,
                                height: None,
                                status: ChannelComposerAttachmentStatus::Reading,
                            });
                    }
                    this.begin_channel_attachment_upload(
                        generation, local_id, path, mime_type, kind, cx,
                    );
                }
                cx.notify();
            })?;
            anyhow::Ok(())
        })
        .detach();
    }

    fn begin_channel_attachment_upload(
        &mut self,
        generation: u64,
        local_id: String,
        path: PathBuf,
        mime_type: String,
        kind: ChannelComposerAttachmentKind,
        cx: &mut Context<Self>,
    ) {
        let api = self.api.clone();
        cx.spawn(async move |this, cx| {
            let read_path = path.clone();
            let file = cx
                .background_spawn(async move {
                    let bytes = read_bounded_file(&read_path, MAX_GENERAL_UPLOAD_BYTES)?;
                    let dimensions = (kind == ChannelComposerAttachmentKind::Image)
                        .then(|| {
                            image::load_from_memory(&bytes)
                                .ok()
                                .map(|image| image.dimensions())
                        })
                        .flatten();
                    anyhow::Ok((bytes, dimensions))
                })
                .await;
            let (bytes, dimensions) = match file {
                Ok(file) => file,
                Err(error) => {
                    this.update(cx, |this, cx| {
                        this.fail_channel_attachment(generation, &local_id, error.to_string());
                        cx.notify();
                    })?;
                    return anyhow::Ok(());
                }
            };
            this.update(cx, |this, cx| {
                this.update_channel_attachment(generation, &local_id, |attachment| {
                    attachment.status = ChannelComposerAttachmentStatus::Uploading;
                    if let Some((width, height)) = dimensions {
                        attachment.width = Some(width);
                        attachment.height = Some(height);
                    }
                });
                cx.notify();
            })?;
            let file_name = path
                .file_name()
                .and_then(|value| value.to_str())
                .unwrap_or("attachment")
                .to_owned();
            let result = match kind {
                ChannelComposerAttachmentKind::Image | ChannelComposerAttachmentKind::Video => api
                    .upload_static_file(&file_name, &mime_type, bytes)
                    .await
                    .map(|upload| upload.id),
                ChannelComposerAttachmentKind::Document => {
                    let uploaded = api
                        .upload_document_bytes(&file_name, &mime_type, bytes, None)
                        .await;
                    if uploaded.is_ok() {
                        this.update(cx, |this, cx| {
                            this.update_channel_attachment(generation, &local_id, |attachment| {
                                attachment.status = ChannelComposerAttachmentStatus::Processing;
                            });
                            cx.notify();
                        })?;
                    }
                    match uploaded {
                        Ok(document) => {
                            let _ = wait_for_document_content_ready(&api, &document, cx).await;
                            Ok(document.document_id)
                        }
                        Err(error) => Err(error),
                    }
                }
            };
            this.update(cx, |this, cx| {
                match result {
                    Ok(entity_id) => {
                        this.update_channel_attachment(generation, &local_id, |attachment| {
                            attachment.entity_id = Some(entity_id);
                            attachment.status = ChannelComposerAttachmentStatus::Ready;
                        });
                    }
                    Err(error) => {
                        this.fail_channel_attachment(generation, &local_id, error.to_string());
                    }
                }
                cx.notify();
            })?;
            anyhow::Ok(())
        })
        .detach();
    }

    fn update_channel_attachment(
        &mut self,
        generation: u64,
        local_id: &str,
        update: impl FnOnce(&mut ChannelComposerAttachmentState),
    ) {
        if self.mutation_dialog_generation != generation {
            return;
        }
        let Some(attachment) = self.mutation_dialog.as_mut().and_then(|dialog| {
            dialog
                .channel_attachments
                .iter_mut()
                .find(|attachment| attachment.local_id == local_id)
        }) else {
            return;
        };
        update(attachment);
    }

    fn fail_channel_attachment(&mut self, generation: u64, local_id: &str, error: String) {
        self.update_channel_attachment(generation, local_id, |attachment| {
            attachment.status = ChannelComposerAttachmentStatus::Failed(error);
        });
    }

    fn retry_channel_attachment(&mut self, local_id: String, cx: &mut Context<Self>) {
        let generation = self.mutation_dialog_generation;
        let Some((path, kind)) = self.mutation_dialog.as_mut().and_then(|dialog| {
            dialog
                .channel_attachments
                .iter_mut()
                .find(|attachment| attachment.local_id == local_id)
                .map(|attachment| {
                    attachment.entity_id = None;
                    attachment.status = ChannelComposerAttachmentStatus::Reading;
                    (attachment.source_path.clone(), attachment.kind)
                })
        }) else {
            return;
        };
        let mime_type = mime_type_for_path(&path).to_owned();
        self.begin_channel_attachment_upload(generation, local_id, path, mime_type, kind, cx);
        cx.notify();
    }

    fn remove_channel_attachment(&mut self, local_id: &str, cx: &mut Context<Self>) {
        if let Some(dialog) = self.mutation_dialog.as_mut() {
            dialog
                .channel_attachments
                .retain(|attachment| attachment.local_id != local_id);
        }
        cx.notify();
    }

    fn set_task_status(
        &mut self,
        document_id: String,
        option_id: &'static str,
        label: &'static str,
        cx: &mut Context<Self>,
    ) {
        let api = self.api.clone();
        self.session_notice = Some(format!("Setting task to {label}…"));
        cx.spawn(async move |this, cx| {
            let result = api.set_task_status(&document_id, option_id).await;
            this.update(cx, |this, cx| {
                match result {
                    Ok(()) => {
                        this.session_notice = Some(format!("Task status: {label}"));
                        let key = format!("{}:{document_id}", EntityType::Document);
                        this.workspace.entity_properties.remove(&key);
                        this.load_entity_capabilities(
                            EntityType::Document,
                            document_id.clone(),
                            true,
                            cx,
                        );
                        this.apply_reconcile_plan(
                            ReconcilePlan::new([
                                ReconcileTarget::Inbox,
                                ReconcileTarget::Entity {
                                    entity_type: EntityType::Document,
                                    entity_id: document_id,
                                },
                            ]),
                            cx,
                        );
                    }
                    Err(error) => {
                        this.session_notice = Some(format!("Task status failed: {error}"));
                    }
                }
                cx.notify();
            })?;
            anyhow::Ok(())
        })
        .detach();
    }

    fn toggle_task_selected(&mut self, document_id: String, cx: &mut Context<Self>) {
        if self.task_bulk_mutating {
            return;
        }
        if !self.task_selected_ids.remove(&document_id) {
            self.task_selected_ids.insert(document_id);
        }
        cx.notify();
    }

    fn bulk_set_task_status(
        &mut self,
        option_id: &'static str,
        label: &'static str,
        cx: &mut Context<Self>,
    ) {
        if self.task_bulk_mutating || self.task_selected_ids.is_empty() {
            return;
        }
        let document_ids = self.task_selected_ids.iter().cloned().collect::<Vec<_>>();
        let count = document_ids.len();
        let api = self.api.clone();
        self.task_bulk_mutating = true;
        self.session_notice = Some(format!("Setting {count} tasks to {label}…"));
        cx.spawn(async move |this, cx| {
            let results = futures::stream::iter(document_ids.into_iter().map(|document_id| {
                let api = api.clone();
                async move {
                    let result = api.set_task_status(&document_id, option_id).await;
                    (document_id, result)
                }
            }))
            .buffer_unordered(6)
            .collect::<Vec<_>>()
            .await;
            this.update(cx, |this, cx| {
                this.task_bulk_mutating = false;
                let mut applied_ids = Vec::new();
                let mut failures = Vec::new();
                for (document_id, result) in results {
                    match result {
                        Ok(()) => applied_ids.push(document_id),
                        Err(error) => failures.push((document_id, error.to_string())),
                    }
                }

                let failed_ids = failures
                    .iter()
                    .map(|(document_id, _)| document_id.as_str())
                    .collect::<HashSet<_>>();
                this.task_selected_ids
                    .retain(|document_id| failed_ids.contains(document_id.as_str()));
                for document_id in &applied_ids {
                    this.workspace
                        .entity_properties
                        .remove(&format!("{}:{document_id}", EntityType::Document));
                }

                if !applied_ids.is_empty() {
                    if let Some(OpenEntity::Inbox(item)) = this.active_entity().cloned()
                        && item.entity_type == EntityType::Document
                        && item.sub_type.as_deref() == Some("task")
                        && applied_ids.contains(&item.id)
                    {
                        this.load_entity_capabilities(
                            EntityType::Document,
                            item.id.clone(),
                            true,
                            cx,
                        );
                    }
                    this.apply_reconcile_plan(
                        ReconcilePlan::new([
                            ReconcileTarget::Inbox,
                            ReconcileTarget::EntityType(EntityType::Document),
                        ]),
                        cx,
                    );
                }

                this.session_notice = Some(bulk_task_status_notice(
                    label,
                    count,
                    applied_ids.len(),
                    &failures,
                ));
                cx.notify();
            })?;
            anyhow::Ok(())
        })
        .detach();
        cx.notify();
    }

    fn bulk_mutate_task_tag(
        &mut self,
        property_id: String,
        option_id: String,
        label: String,
        add: bool,
        cx: &mut Context<Self>,
    ) {
        if self.task_bulk_mutating || self.task_selected_ids.is_empty() {
            return;
        }
        let document_ids = self.task_selected_ids.iter().cloned().collect::<Vec<_>>();
        let count = document_ids.len();
        let request = BulkUpdateEntitiesPropertyOptionsRequest {
            add_option_ids: add.then_some(vec![option_id.clone()]).unwrap_or_default(),
            entities: document_ids
                .iter()
                .cloned()
                .map(|entity_id| PropertyTargetReference {
                    entity_id,
                    entity_type: "DOCUMENT".into(),
                })
                .collect(),
            property_id,
            remove_option_ids: (!add).then_some(vec![option_id]).unwrap_or_default(),
        };
        let verb = if add { "Adding" } else { "Removing" };
        let api = self.api.clone();
        self.task_bulk_mutating = true;
        self.session_notice = Some(format!("{verb} tag {label} for {count} tasks…"));
        cx.spawn(async move |this, cx| {
            let result = api.bulk_update_entities_property_options(&request).await;
            this.update(cx, |this, cx| {
                this.task_bulk_mutating = false;
                match result {
                    Ok(response) => {
                        let mut applied_ids = Vec::new();
                        let mut failures = Vec::new();
                        for outcome in response.results {
                            if outcome.status == "applied" {
                                applied_ids.push(outcome.entity_id);
                            } else {
                                failures.push((
                                    outcome.entity_id,
                                    outcome
                                        .error
                                        .unwrap_or_else(|| outcome.status.replace('_', " ")),
                                ));
                            }
                        }
                        let returned_ids = applied_ids
                            .iter()
                            .chain(failures.iter().map(|(document_id, _)| document_id))
                            .cloned()
                            .collect::<HashSet<String>>();
                        failures.extend(
                            document_ids
                                .iter()
                                .filter(|document_id| !returned_ids.contains(document_id.as_str()))
                                .cloned()
                                .map(|document_id| {
                                    (document_id, "backend omitted an entity result".into())
                                }),
                        );
                        for document_id in &applied_ids {
                            this.workspace
                                .entity_properties
                                .remove(&format!("{}:{document_id}", EntityType::Document));
                        }
                        if !applied_ids.is_empty() {
                            this.apply_reconcile_plan(
                                ReconcilePlan::new([
                                    ReconcileTarget::Inbox,
                                    ReconcileTarget::EntityType(EntityType::Document),
                                ]),
                                cx,
                            );
                        }
                        this.session_notice = Some(bulk_task_tag_notice(
                            &label,
                            add,
                            count,
                            applied_ids.len(),
                            &failures,
                        ));
                    }
                    Err(error) => {
                        this.session_notice = Some(format!(
                            "Could not {} tag {label}: {error}",
                            if add { "add" } else { "remove" }
                        ));
                    }
                }
                cx.notify();
            })?;
            anyhow::Ok(())
        })
        .detach();
        cx.notify();
    }

    fn dismiss_task_duplicates(
        &mut self,
        document_id: String,
        match_ids: Vec<String>,
        cx: &mut Context<Self>,
    ) {
        if match_ids.is_empty() {
            return;
        }
        let count = match_ids.len();
        let api = self.api.clone();
        self.session_notice = Some("Dismissing duplicate matches…".into());
        cx.spawn(async move |this, cx| {
            let result = api.dismiss_task_duplicates(&document_id, match_ids).await;
            this.update(cx, |this, cx| {
                match result {
                    Ok(_) => {
                        this.session_notice = Some(format!(
                            "Dismissed {count} duplicate match{}",
                            if count == 1 { "" } else { "es" }
                        ));
                        this.workspace.task_duplicates.remove(&document_id);
                        this.load_task_duplicates(document_id, true, cx);
                    }
                    Err(error) => {
                        this.session_notice = Some(format!("Could not dismiss duplicate: {error}"));
                    }
                }
                cx.notify();
            })?;
            anyhow::Ok(())
        })
        .detach();
    }

    fn rsvp_calendar_event(
        &mut self,
        event_id: String,
        response: AttendeeResponseStatus,
        cx: &mut Context<Self>,
    ) {
        let label = match response {
            AttendeeResponseStatus::NeedsAction => "No response",
            AttendeeResponseStatus::Accepted => "Accepted",
            AttendeeResponseStatus::Declined => "Declined",
            AttendeeResponseStatus::Tentative => "Tentative",
        };
        let api = self.api.clone();
        self.session_notice = Some(format!("Updating RSVP to {label}…"));
        cx.spawn(async move |this, cx| {
            let result = api
                .rsvp_calendar_event(
                    &event_id,
                    &RsvpCalendarEventRequest {
                        recurrence_id: None,
                        response,
                        scope: Some("all".into()),
                    },
                )
                .await;
            this.update(cx, |this, cx| {
                match result {
                    Ok(_) => {
                        this.session_notice = Some(format!("RSVP updated: {label}"));
                        this.apply_reconcile_plan(
                            ReconcilePlan::new([
                                ReconcileTarget::Inbox,
                                ReconcileTarget::Entity {
                                    entity_type: EntityType::CalendarEvent,
                                    entity_id: event_id,
                                },
                            ]),
                            cx,
                        );
                    }
                    Err(error) => {
                        this.session_notice = Some(format!("RSVP failed: {error}"));
                    }
                }
                cx.notify();
            })?;
            anyhow::Ok(())
        })
        .detach();
    }

