    fn toggle_entity_tag(
        &mut self,
        entity_type: EntityType,
        entity_id: String,
        property_definition_id: String,
        option_id: String,
        selected: bool,
        cx: &mut Context<Self>,
    ) {
        if !self.can_edit_entity(entity_type, &entity_id) {
            self.session_notice = Some("You do not have edit access to this entity.".into());
            cx.notify();
            return;
        }
        let Some(wire_type) = property_target_wire_type(entity_type) else {
            self.session_notice = Some("This entity type does not support tags.".into());
            cx.notify();
            return;
        };
        let wire_type = wire_type.to_owned();
        let api = self.api.clone();
        self.session_notice = Some(if selected {
            "Removing tag…".into()
        } else {
            "Adding tag…".into()
        });
        cx.spawn(async move |this, cx| {
            let result = if selected {
                api.remove_entity_property_option(
                    &wire_type,
                    &entity_id,
                    &property_definition_id,
                    &option_id,
                )
                .await
            } else {
                api.add_entity_property_option(
                    &wire_type,
                    &entity_id,
                    &property_definition_id,
                    &option_id,
                )
                .await
            };
            this.update(cx, |this, cx| {
                match result {
                    Ok(()) => {
                        this.session_notice = Some(if selected {
                            "Tag removed".into()
                        } else {
                            "Tag added".into()
                        });
                        let key = format!("{entity_type}:{entity_id}");
                        this.workspace.entity_properties.remove(&key);
                        this.load_entity_capabilities(entity_type, entity_id.clone(), true, cx);
                    }
                    Err(error) => this.session_notice = Some(format!("Tag update failed: {error}")),
                }
                cx.notify();
            })?;
            anyhow::Ok(())
        })
        .detach();
    }

    fn connected_email_link_choices(&self) -> Vec<(String, String)> {
        self.workspace
            .email_links
            .loaded()
            .map(|response| response.links.as_slice())
            .into_iter()
            .flatten()
            .map(|link| (link.id.clone(), link.email_address.clone()))
            .collect()
    }

    fn email_recipient_choices(&self) -> Vec<(String, String, String)> {
        let Some(contacts) = self.workspace.contacts.loaded() else {
            return Vec::new();
        };
        let names = self.workspace.user_names.loaded();
        let mut choices = contacts
            .contacts
            .iter()
            .filter_map(|id| {
                let email = email_address_from_identity(id)?;
                let label = names
                    .and_then(|names| names.get(id))
                    .map(user_name_label)
                    .filter(|label| !label.is_empty())
                    .unwrap_or_else(|| email.clone());
                Some((id.clone(), email, label))
            })
            .collect::<Vec<_>>();
        choices.sort_by(|left, right| {
            left.2
                .to_ascii_lowercase()
                .cmp(&right.2.to_ascii_lowercase())
                .then_with(|| left.1.cmp(&right.1))
        });
        choices.dedup_by(|left, right| left.1.eq_ignore_ascii_case(&right.1));
        choices
    }

