    fn open_email_message_draft(
        &mut self,
        message: serde_json::Value,
        fallback_thread_id: String,
        fallback_link_id: Option<String>,
        cx: &mut Context<Self>,
    ) {
        self.load_people_cache(false, cx);
        let Some(draft_id) = json_first_text(&message, &[&["db_id"], &["id"]]) else {
            self.session_notice = Some("This draft has no editable server ID.".into());
            cx.notify();
            return;
        };
        let link_id = json_first_text(&message, &[&["link_id"], &["linkId"]]).or(fallback_link_id);
        let thread_id = json_first_text(
            &message,
            &[
                &["thread_db_id"],
                &["threadDbId"],
                &["thread_id"],
                &["threadId"],
            ],
        )
        .unwrap_or(fallback_thread_id);
        let replying_to_id = json_first_text(&message, &[&["replying_to_id"], &["replyingToId"]]);
        let to = json_email_contact_list(&message, "to").join(", ");
        let cc = json_email_contact_list(&message, "cc").join(", ");
        let bcc = json_email_contact_list(&message, "bcc").join(", ");
        let subject = json_text(&message, &["subject"]).unwrap_or_default();
        let body = json_first_text(
            &message,
            &[
                &["body_macro"],
                &["bodyMacro"],
                &["body_text"],
                &["bodyText"],
            ],
        )
        .unwrap_or_else(|| email_message_body(&message));
        let schedule_time = json_first_text(
            &message,
            &[
                &["scheduled_send_time"],
                &["scheduledSendTime"],
                &["send_time"],
                &["sendTime"],
            ],
        )
        .unwrap_or_default();
        let scheduled = !schedule_time.is_empty();
        let agent_authored = json_bool(
            &message,
            &[
                "agent_authored",
                "agentAuthored",
                "created_by_agent",
                "createdByAgent",
            ],
        )
        .unwrap_or(false)
            || json_first_text(
                &message,
                &[
                    &["agent_session_id"],
                    &["agentSessionId"],
                    &["created_by_agent_id"],
                ],
            )
            .is_some();
        let kind = if let Some(replying_to_id) = replying_to_id {
            MutationKind::ReplyEmail {
                thread_id,
                replying_to_id,
            }
        } else {
            MutationKind::ComposeEmail
        };
        let mut dialog = MutationDialog::new(
            if agent_authored {
                "Review agent email draft"
            } else if scheduled {
                "Edit scheduled email"
            } else {
                "Edit email draft"
            },
            if scheduled {
                "Save schedule"
            } else {
                "Save draft"
            },
            kind,
            vec![
                Self::mutation_field("To (comma separated)", to, false),
                Self::mutation_field("Subject", subject, false),
                Self::mutation_field("Message", body, true),
                Self::mutation_field("Cc (comma separated)", cc.clone(), false),
                Self::mutation_field("Bcc (comma separated)", bcc.clone(), false),
                Self::mutation_field(
                    "Action (send/draft/schedule)",
                    if scheduled { "schedule" } else { "draft" },
                    false,
                ),
                Self::mutation_field("Schedule time (ISO, if scheduled)", schedule_time, false),
                Self::mutation_field(
                    "From inbox ID (optional)",
                    link_id.clone().unwrap_or_default(),
                    false,
                ),
            ],
        );
        dialog.email_draft_id = Some(draft_id);
        dialog.email_link_id = link_id;
        dialog.email_attachments = email_draft_attachments_from_message(&message);
        dialog.email_show_cc = !cc.is_empty();
        dialog.email_show_bcc = !bcc.is_empty();
        dialog.email_agent_authored = agent_authored;
        dialog.email_last_saved_fingerprint = Some("server-draft".into());
        self.open_mutation_dialog(dialog, cx);
    }

