    fn email_body_markdown(
        &self,
        message_id: &str,
        markdown: String,
        cx: &mut Context<Self>,
    ) -> Entity<Markdown> {
        let mut cache = self.email_body_markdown.borrow_mut();
        if let Some((cached_source, entity)) = cache.get(message_id)
            && cached_source == &markdown
        {
            return entity.clone();
        }
        let source = markdown.clone();
        let entity = cx.new(|cx| Markdown::new(source.into(), None, None, cx));
        cache.insert(message_id.to_owned(), (markdown, entity.clone()));
        entity
    }

