    fn open_email_attachment(
        &mut self,
        attachment_id: String,
        filename: String,
        cx: &mut Context<Self>,
    ) {
        let filename = safe_download_filename(&filename, "email-attachment");
        let receiver = cx.prompt_for_new_path(std::path::Path::new(""), Some(filename.as_str()));
        let api = self.api.clone();
        cx.spawn(async move |this, cx| {
            let destination = match receiver.await {
                Ok(Ok(Some(path))) => path,
                Ok(Ok(None)) => return anyhow::Ok(()),
                Ok(Err(error)) => {
                    this.update(cx, |this, cx| {
                        this.session_notice = Some(format!("Save dialog failed: {error}"));
                        cx.notify();
                    })?;
                    return anyhow::Ok(());
                }
                Err(error) => {
                    this.update(cx, |this, cx| {
                        this.session_notice = Some(format!("Save dialog closed: {error}"));
                        cx.notify();
                    })?;
                    return anyhow::Ok(());
                }
            };
            this.update(cx, |this, cx| {
                this.session_notice = Some(format!("Downloading {filename}…"));
                cx.notify();
            })?;
            let result = async {
                let response = api.get_email_attachment(&attachment_id).await?;
                let bytes = response
                    .attachment
                    .decoded_data()?
                    .context("attachment is not available for download yet")?;
                let write_path = destination.clone();
                cx.background_spawn(async move {
                    std::fs::write(&write_path, bytes)
                        .with_context(|| format!("failed to write {}", write_path.display()))
                })
                .await?;
                anyhow::Ok(())
            }
            .await;
            this.update(cx, |this, cx| {
                match result {
                    Ok(()) => {
                        cx.reveal_path(&destination);
                        this.session_notice = Some(format!("Saved {}", destination.display()));
                    }
                    Err(error) => {
                        this.session_notice = Some(format!("Could not save {filename}: {error:#}"));
                    }
                }
                cx.notify();
            })?;
            anyhow::Ok(())
        })
        .detach();
    }

    fn open_email_attachment_document(
        &mut self,
        attachment_id: String,
        filename: String,
        cx: &mut Context<Self>,
    ) {
        if attachment_id.is_empty() {
            self.session_notice = Some("This attachment is not available yet.".into());
            cx.notify();
            return;
        }
        let api = self.api.clone();
        self.session_notice = Some(format!("Opening {filename}…"));
        cx.spawn(async move |this, cx| {
            let result = api.get_email_attachment_document_id(&attachment_id).await;
            this.update(cx, |this, cx| {
                match result {
                    Ok(response) => {
                        let document_id = response.document_id.clone();
                        let raw = serde_json::to_value(response)
                            .unwrap_or_else(|_| serde_json::Value::Null);
                        this.open_entity(
                            OpenEntity::Inbox(Arc::new(InboxItem {
                                id: document_id,
                                tag: "document".into(),
                                sub_type: email_attachment_sub_type(&filename),
                                entity_type: EntityType::Document,
                                title: filename.clone(),
                                subtitle: "Email attachment".into(),
                                timestamp: String::new(),
                                raw,
                            })),
                            cx,
                        );
                        this.session_notice = Some(format!("Opened {filename}"));
                    }
                    Err(error) => {
                        this.session_notice = Some(format!("Could not open {filename}: {error}"));
                    }
                }
                cx.notify();
            })?;
            anyhow::Ok(())
        })
        .detach();
    }

    fn pick_email_draft_attachments(&mut self, cx: &mut Context<Self>) {
        let editor_body_macro = self.mutation_editor_macro_markdown(cx);
        let Some(dialog) = self.mutation_dialog.as_ref() else {
            return;
        };
        let (thread_id, replying_to_id) = match &dialog.kind {
            MutationKind::ComposeEmail => (None, None),
            MutationKind::ReplyEmail {
                thread_id,
                replying_to_id,
            } => (Some(thread_id.clone()), Some(replying_to_id.clone())),
            _ => return,
        };
        if dialog.busy {
            return;
        }
        let values = dialog
            .fields
            .iter()
            .map(|field| field.value.trim().to_owned())
            .collect::<Vec<_>>();
        let forwarded_attachment_ids = dialog
            .email_attachments
            .iter()
            .filter(|attachment| attachment.kind == EmailDraftAttachmentKind::Forwarded)
            .map(|attachment| attachment.id.clone())
            .collect::<Vec<_>>();
        let existing_attachment_bytes = dialog
            .email_attachments
            .iter()
            .map(|attachment| attachment.size)
            .sum::<u64>();
        let include_signature = dialog.email_include_signature;
        let appended_quote = dialog.email_appended_quote.clone();
        let existing_draft_id = dialog.email_draft_id.clone();
        let requested_link_id = dialog
            .email_link_id
            .clone()
            .or_else(|| values.get(7).filter(|value| !value.is_empty()).cloned());
        let receiver = cx.prompt_for_paths(PathPromptOptions {
            files: true,
            directories: false,
            multiple: true,
            prompt: Some("Attach files to email".into()),
        });
        let api = self.api.clone();
        cx.spawn(async move |this, cx| {
            let paths = match receiver.await {
                Ok(Ok(Some(paths))) => paths,
                Ok(Ok(None)) => return anyhow::Ok(()),
                Ok(Err(error)) => {
                    this.update(cx, |this, cx| {
                        if let Some(dialog) = this.mutation_dialog.as_mut() {
                            dialog.error = Some(format!("File picker failed: {error}"));
                        }
                        cx.notify();
                    })?;
                    return anyhow::Ok(());
                }
                Err(error) => {
                    this.update(cx, |this, cx| {
                        if let Some(dialog) = this.mutation_dialog.as_mut() {
                            dialog.error = Some(format!("File picker closed: {error}"));
                        }
                        cx.notify();
                    })?;
                    return anyhow::Ok(());
                }
            };
            if paths.is_empty() {
                return anyhow::Ok(());
            }
            this.update(cx, |this, cx| {
                if let Some(dialog) = this.mutation_dialog.as_mut() {
                    dialog.busy = true;
                    dialog.error = None;
                }
                cx.notify();
            })?;

            let result = async {
                let selected_paths = paths.clone();
                cx.background_spawn(async move {
                    let selected_bytes = selected_paths.iter().try_fold(0_u64, |total, path| {
                        let size = bounded_file_size(path, MAX_EMAIL_ATTACHMENTS_BYTES)?;
                        total
                            .checked_add(size)
                            .context("email attachment size overflow")
                    })?;
                    anyhow::ensure!(
                        existing_attachment_bytes
                            .checked_add(selected_bytes)
                            .is_some_and(|total| total < MAX_EMAIL_ATTACHMENTS_BYTES),
                        "total attachments exceed Macro's 18 MB limit"
                    );
                    anyhow::Ok(())
                })
                .await?;
                let mut draft = email_draft_from_values_with_policy_and_body(
                    &values,
                    thread_id.clone(),
                    replying_to_id.clone(),
                    false,
                    editor_body_macro.as_deref(),
                    appended_quote.as_ref(),
                    include_signature,
                )?;
                draft.db_id = existing_draft_id;
                let saved = create_email_draft_with_forwarded(
                    &api,
                    draft,
                    None,
                    requested_link_id.as_deref(),
                    &forwarded_attachment_ids,
                )
                .await?;
                let draft_id = saved
                    .draft
                    .db_id
                    .clone()
                    .context("email service created a draft without an ID")?;
                let link_id = saved.draft.link_id.clone();
                let mut uploaded = Vec::new();
                for path in paths {
                    let file_name = path
                        .file_name()
                        .and_then(|value| value.to_str())
                        .unwrap_or("attachment")
                        .to_owned();
                    let read_path = path.clone();
                    let bytes = cx
                        .background_spawn(async move {
                            read_bounded_file(&read_path, MAX_EMAIL_ATTACHMENTS_BYTES)
                        })
                        .await?;
                    let size = bytes.len() as u64;
                    let attachment = api
                        .upload_email_draft_attachment(&draft_id, Some(&link_id), &file_name, bytes)
                        .await?;
                    uploaded.push(EmailDraftAttachmentState {
                        id: attachment.attachment_id,
                        name: file_name,
                        size,
                        kind: EmailDraftAttachmentKind::Uploaded,
                    });
                }
                anyhow::Ok((draft_id, link_id, uploaded))
            }
            .await;

            this.update(cx, |this, cx| {
                if let Some(dialog) = this.mutation_dialog.as_mut() {
                    dialog.busy = false;
                    match result {
                        Ok((draft_id, link_id, attachments)) => {
                            let count = attachments.len();
                            dialog.email_draft_id = Some(draft_id);
                            dialog.email_link_id = Some(link_id);
                            dialog.email_attachments.extend(attachments);
                            this.session_notice = Some(format!(
                                "{count} email attachment{} uploaded",
                                if count == 1 { "" } else { "s" }
                            ));
                        }
                        Err(error) => {
                            dialog.error = Some(format!("Attachment upload failed: {error:#}"));
                        }
                    }
                }
                cx.notify();
            })?;
            anyhow::Ok(())
        })
        .detach();
    }

    fn remove_email_draft_attachment(
        &mut self,
        attachment_id: String,
        kind: EmailDraftAttachmentKind,
        cx: &mut Context<Self>,
    ) {
        let Some(dialog) = self.mutation_dialog.as_mut() else {
            return;
        };
        let Some(draft_id) = dialog.email_draft_id.clone() else {
            dialog
                .email_attachments
                .retain(|attachment| attachment.id != attachment_id || attachment.kind != kind);
            self.schedule_email_draft_autosave(cx);
            cx.notify();
            return;
        };
        if dialog.busy {
            return;
        }
        let link_id = dialog.email_link_id.clone();
        dialog.busy = true;
        let api = self.api.clone();
        cx.spawn(async move |this, cx| {
            let result = match kind {
                EmailDraftAttachmentKind::Uploaded => {
                    api.remove_email_draft_attachment_for_link(
                        &draft_id,
                        &attachment_id,
                        link_id.as_deref(),
                    )
                    .await
                }
                EmailDraftAttachmentKind::Forwarded => {
                    api.remove_forwarded_email_attachment(
                        &draft_id,
                        &attachment_id,
                        link_id.as_deref(),
                    )
                    .await
                }
            };
            this.update(cx, |this, cx| {
                if let Some(dialog) = this.mutation_dialog.as_mut() {
                    dialog.busy = false;
                    match result {
                        Ok(()) => dialog.email_attachments.retain(|attachment| {
                            attachment.id != attachment_id || attachment.kind != kind
                        }),
                        Err(error) => {
                            dialog.error = Some(format!("Could not remove attachment: {error}"))
                        }
                    }
                }
                cx.notify();
            })?;
            anyhow::Ok(())
        })
        .detach();
    }

