    fn open_edit_task_properties(&mut self, document_id: String, cx: &mut Context<Self>) {
        if !self.can_edit_entity(EntityType::Document, &document_id) {
            self.session_notice = Some("You do not have permission to edit this task.".into());
            cx.notify();
            return;
        }
        let key = format!("{}:{document_id}", EntityType::Document);
        let Some(DataState::Loaded(properties)) = self.workspace.entity_properties.get(&key) else {
            self.load_entity_capabilities(EntityType::Document, document_id, true, cx);
            self.session_notice =
                Some("Task properties are still loading; try again shortly.".into());
            cx.notify();
            return;
        };
        let existing_property_ids = properties
            .properties
            .iter()
            .filter(|property| !property.entity_property_id.is_empty())
            .map(|property| {
                (
                    property.definition_id.clone(),
                    property.entity_property_id.clone(),
                )
            })
            .collect();
        let values = task_planning_dialog_values(&properties.properties);
        self.open_mutation_dialog(
            MutationDialog::new(
                "Edit task details",
                "Save details",
                MutationKind::EditTaskProperties {
                    document_id,
                    existing_property_ids,
                },
                vec![
                    Self::mutation_field("Status", values[0].clone(), false),
                    Self::mutation_field("Priority", values[1].clone(), false),
                    Self::mutation_field("Assignees", values[2].clone(), false),
                    Self::mutation_field("Due date", values[3].clone(), false),
                    Self::mutation_field("Parent task", values[4].clone(), false),
                    Self::mutation_field("Dependencies", values[5].clone(), false),
                    Self::mutation_field("Effort", values[6].clone(), false),
                    Self::mutation_field("Story points", values[7].clone(), false),
                    Self::mutation_field("Related documents", values[8].clone(), false),
                ],
            ),
            cx,
        );
    }

