    fn restore_deleted_item(
        &mut self,
        entity_type: EntityType,
        entity_id: String,
        cx: &mut Context<Self>,
    ) {
        self.session_notice = Some("Restoring item…".into());
        let api = self.api.clone();
        cx.spawn(async move |this, cx| {
            let result = match entity_type {
                EntityType::Document => api.restore_document(&entity_id).await.map(|_| ()),
                EntityType::Project => api.restore_project(&entity_id).await,
                EntityType::Chat => api.restore_chat(&entity_id).await,
                _ => Err(anyhow::anyhow!("This item type cannot be restored")),
            };
            this.update(cx, |this, cx| {
                match result {
                    Ok(()) => {
                        this.session_notice = Some("Item restored".into());
                        this.workspace.recently_deleted = DataState::Idle;
                        this.workspace.projects = DataState::Idle;
                        this.workspace.project_contents.clear();
                        this.load_recently_deleted(true, cx);
                        this.load_projects(true, cx);
                        this.apply_reconcile_plan(ReconcilePlan::new([ReconcileTarget::Inbox]), cx);
                    }
                    Err(error) => {
                        this.session_notice = Some(format!("Restore failed: {error}"));
                    }
                }
                cx.notify();
            })?;
            anyhow::Ok(())
        })
        .detach();
        cx.notify();
    }

