    fn bulk_mutate_crm_tag(
        &mut self,
        company_ids: Vec<String>,
        property_id: String,
        option_id: String,
        label: String,
        add: bool,
        cx: &mut Context<Self>,
    ) {
        if self.crm_bulk_mutating || company_ids.is_empty() {
            return;
        }
        let count = company_ids.len();
        let request = BulkUpdateEntitiesPropertyOptionsRequest {
            add_option_ids: add.then_some(vec![option_id.clone()]).unwrap_or_default(),
            entities: company_ids
                .iter()
                .cloned()
                .map(|entity_id| PropertyTargetReference {
                    entity_id,
                    entity_type: "COMPANY".into(),
                })
                .collect(),
            property_id,
            remove_option_ids: (!add).then_some(vec![option_id]).unwrap_or_default(),
        };
        let api = self.api.clone();
        self.crm_bulk_mutating = true;
        self.session_notice = Some(format!(
            "{} tag {label} for {count} companies…",
            if add { "Adding" } else { "Removing" }
        ));
        cx.spawn(async move |this, cx| {
            let result = api.bulk_update_entities_property_options(&request).await;
            this.update(cx, |this, cx| {
                this.crm_bulk_mutating = false;
                match result {
                    Ok(response) => {
                        let mut applied_ids = Vec::new();
                        let mut failures = Vec::new();
                        for outcome in response.results {
                            if outcome.status == "applied" {
                                applied_ids.push(outcome.entity_id);
                            } else {
                                failures.push((
                                    outcome.entity_id,
                                    outcome
                                        .error
                                        .unwrap_or_else(|| outcome.status.replace('_', " ")),
                                ));
                            }
                        }
                        let returned_ids = applied_ids
                            .iter()
                            .chain(failures.iter().map(|(company_id, _)| company_id))
                            .cloned()
                            .collect::<HashSet<_>>();
                        failures.extend(
                            company_ids
                                .iter()
                                .filter(|company_id| !returned_ids.contains(company_id.as_str()))
                                .cloned()
                                .map(|company_id| {
                                    (company_id, "backend omitted an entity result".into())
                                }),
                        );
                        let failed_ids = failures
                            .iter()
                            .map(|(company_id, _)| company_id.as_str())
                            .collect::<HashSet<_>>();
                        for company_id in &company_ids {
                            if !failed_ids.contains(company_id.as_str()) {
                                this.crm_selected_ids.remove(company_id);
                            }
                        }
                        for company_id in &applied_ids {
                            this.workspace
                                .entity_properties
                                .remove(&format!("{}:{company_id}", EntityType::CrmCompany));
                        }
                        if !applied_ids.is_empty() {
                            this.apply_reconcile_plan(
                                ReconcilePlan::new([
                                    ReconcileTarget::Inbox,
                                    ReconcileTarget::EntityType(EntityType::CrmCompany),
                                ]),
                                cx,
                            );
                        }
                        this.session_notice = Some(bulk_crm_tag_notice(
                            &label,
                            add,
                            count,
                            applied_ids.len(),
                            &failures,
                        ));
                    }
                    Err(error) => {
                        this.session_notice = Some(format!(
                            "Could not {} CRM tag {label}: {error}",
                            if add { "add" } else { "remove" }
                        ));
                    }
                }
                cx.notify();
            })?;
            anyhow::Ok(())
        })
        .detach();
        cx.notify();
    }

    fn bulk_set_crm_stage(
        &mut self,
        company_ids: Vec<String>,
        definition_id: String,
        stage: CrmStage,
        cx: &mut Context<Self>,
    ) {
        if company_ids.is_empty() || self.crm_bulk_mutating {
            return;
        }
        let (_, stages) = self.active_crm_stages();
        let mut previous = HashMap::new();
        let mut eligible = Vec::new();
        let mut skipped = 0usize;
        for company_id in company_ids {
            let current = self.crm_company_stage_id(&company_id, &definition_id, &stages);
            if !self.can_move_company_from_stage(current.as_deref(), &stages) {
                skipped += 1;
                continue;
            }
            if current.as_deref() == Some(stage.id.as_str())
                || (current.is_none() && stage.id == "__unstaged__")
            {
                continue;
            }
            previous.insert(company_id.clone(), current);
            self.crm_optimistic_stages
                .insert(company_id.clone(), stage.id.clone());
            eligible.push(company_id);
        }
        if eligible.is_empty() {
            self.session_notice = Some(if skipped > 0 {
                "Your workspace role cannot move the selected closed deals.".into()
            } else {
                "The selected companies already use that stage.".into()
            });
            cx.notify();
            return;
        }

        let value = if stage.id == "__unstaged__" {
            serde_json::Value::Null
        } else {
            serde_json::to_value(SetPropertyValue::SelectOption {
                option_id: stage.id.clone(),
            })
            .unwrap_or(serde_json::Value::Null)
        };
        let api = self.api.clone();
        let count = eligible.len();
        self.crm_bulk_mutating = true;
        self.session_notice = Some(format!("Updating {count} CRM stage values…"));
        cx.spawn(async move |this, cx| {
            let results = futures::future::join_all(eligible.iter().map(|company_id| {
                let api = api.clone();
                let company_id = company_id.clone();
                let definition_id = definition_id.clone();
                let value = value.clone();
                async move {
                    let result = api
                        .set_entity_property("COMPANY", &company_id, &definition_id, &value)
                        .await;
                    (company_id, result)
                }
            }))
            .await;
            this.update(cx, |this, cx| {
                this.crm_bulk_mutating = false;
                let failed = results.iter().filter(|(_, result)| result.is_err()).count();
                for (company_id, result) in results {
                    if result.is_err() {
                        if let Some(Some(previous_stage)) = previous.get(&company_id) {
                            this.crm_optimistic_stages
                                .insert(company_id.clone(), previous_stage.clone());
                        } else {
                            this.crm_optimistic_stages.remove(&company_id);
                        }
                    } else {
                        this.crm_optimistic_stages.remove(&company_id);
                        this.crm_selected_ids.remove(&company_id);
                    }
                    let key = format!("{}:{company_id}", EntityType::CrmCompany);
                    this.workspace.entity_properties.remove(&key);
                    this.load_entity_properties(EntityType::CrmCompany, company_id, true, cx);
                }
                this.session_notice = Some(if failed == 0 {
                    format!("Updated {count} CRM stage values")
                } else {
                    format!("Updated {}; {failed} failed", count - failed)
                });
                cx.notify();
            })?;
            anyhow::Ok(())
        })
        .detach();
        cx.notify();
    }

    fn can_edit_crm_stages(&self) -> bool {
        let required = self
            .workspace
            .crm_team_settings
            .loaded()
            .map(|settings| settings.edit_stages_role)
            .unwrap_or(CrmPermissionRole::Admin);
        crm_role_satisfies(self.current_team_role(), required)
    }

