    fn reorder_crm_stage(
        &mut self,
        definition_id: String,
        option_id: String,
        display_order: i64,
        sibling_option_id: String,
        sibling_display_order: i64,
        cx: &mut Context<Self>,
    ) {
        if !self.can_edit_crm_stages() {
            self.session_notice = Some("Your workspace role cannot reorder CRM stages.".into());
            cx.notify();
            return;
        }
        let api = self.api.clone();
        self.session_notice = Some("Reordering CRM stage…".into());
        cx.spawn(async move |this, cx| {
            let result = async {
                api.update_property_option(
                    &definition_id,
                    &option_id,
                    &UpdatePropertyOptionRequest {
                        display_order: Some(display_order),
                        ..Default::default()
                    },
                )
                .await?;
                api.update_property_option(
                    &definition_id,
                    &sibling_option_id,
                    &UpdatePropertyOptionRequest {
                        display_order: Some(sibling_display_order),
                        ..Default::default()
                    },
                )
                .await
            }
            .await;
            this.update(cx, |this, cx| {
                match result {
                    Ok(_) => {
                        this.session_notice = Some("CRM stage reordered".into());
                        this.workspace.property_definitions = DataState::Idle;
                        this.load_property_definitions(true, cx);
                    }
                    Err(error) => {
                        this.session_notice = Some(format!("Unable to reorder CRM stage: {error}"));
                    }
                }
                cx.notify();
            })?;
            anyhow::Ok(())
        })
        .detach();
        cx.notify();
    }

    fn set_crm_stage_closed(&mut self, stage_id: String, closed: bool, cx: &mut Context<Self>) {
        if !self.is_current_team_admin() {
            self.session_notice = Some("Only workspace admins can configure closed stages.".into());
            cx.notify();
            return;
        }
        let (_, stages) = self.active_crm_stages();
        let mut ids = self
            .workspace
            .crm_team_settings
            .loaded()
            .and_then(|settings| settings.closed_stage_ids.clone())
            .unwrap_or_else(|| {
                stages
                    .iter()
                    .filter(|stage| is_closed_crm_stage_label(&stage.label))
                    .map(|stage| stage.id.clone())
                    .collect()
            });
        ids.retain(|id| id != &stage_id);
        if closed {
            ids.push(stage_id);
        }
        self.update_crm_governance(
            UpdateCrmTeamSettingsRequest {
                closed_stage_ids: Some(Some(ids)),
                ..Default::default()
            },
            "Closed-stage configuration updated",
            cx,
        );
    }

    fn set_crm_permission_role(
        &mut self,
        setting: &'static str,
        role: CrmPermissionRole,
        cx: &mut Context<Self>,
    ) {
        if !self.is_current_team_admin() {
            self.session_notice = Some("Only workspace admins can change CRM governance.".into());
            cx.notify();
            return;
        }
        let mut request = UpdateCrmTeamSettingsRequest::default();
        match setting {
            "edit_stages" => request.edit_stages_role = Some(role),
            "move_closed_deals" => request.move_closed_deals_role = Some(role),
            "delete_records" => request.delete_records_role = Some(role),
            _ => return,
        }
        self.update_crm_governance(request, "CRM permissions updated", cx);
    }

    fn update_crm_governance(
        &mut self,
        request: UpdateCrmTeamSettingsRequest,
        success_message: &'static str,
        cx: &mut Context<Self>,
    ) {
        let api = self.api.clone();
        self.session_notice = Some("Updating CRM settings…".into());
        cx.spawn(async move |this, cx| {
            let result = api.update_crm_team_settings(&request).await;
            this.update(cx, |this, cx| {
                match result {
                    Ok(settings) => {
                        this.workspace.crm_team_settings = DataState::Loaded(settings);
                        this.session_notice = Some(success_message.into());
                    }
                    Err(error) => {
                        this.session_notice =
                            Some(format!("Unable to update CRM settings: {error}"));
                    }
                }
                cx.notify();
            })?;
            anyhow::Ok(())
        })
        .detach();
        cx.notify();
    }

    fn current_crm_view_config(&self) -> serde_json::Value {
        let is_default = (self.active_crm_saved_view_scope == Some(CrmSavedViewScope::Personal))
            .then(|| {
                self.active_crm_saved_view_id
                    .as_deref()
                    .and_then(|active_id| {
                        self.workspace.saved_views.loaded().and_then(|response| {
                            response
                                .views
                                .iter()
                                .find(|view| view.id == active_id)
                                .and_then(|view| view.config.get("isDefault"))
                                .and_then(serde_json::Value::as_bool)
                        })
                    })
                    .unwrap_or(false)
            });
        serde_json::to_value(CrmViewConfig {
            kind: "crm".into(),
            filters: None,
            client_filters: None,
            search_text: (!self.crm_search_query.is_empty()).then(|| self.crm_search_query.clone()),
            group_by: if self.crm_view_mode == CrmViewMode::Board {
                Some(format!("property:{CRM_COMPANY_STAGE_PROPERTY_ID}"))
            } else {
                self.crm_grouping.saved_view_id()
            },
            active_tab: Some(
                match self.crm_entity_scope {
                    CrmEntityScope::All => "all",
                    CrmEntityScope::Companies => "companies",
                    CrmEntityScope::Contacts => "contacts",
                }
                .into(),
            ),
            sort: vec![
                match self.crm_sort {
                    CrmSort::UpdatedDesc => "updated_desc",
                    CrmSort::NameAsc => "name_asc",
                    CrmSort::NameDesc => "name_desc",
                }
                .into(),
            ],
            view_mode: Some(self.crm_view_mode),
            is_default,
            stage_filter: self.crm_stage_filter.iter().cloned().collect(),
            owner_filter: self.crm_owner_filter.iter().cloned().collect(),
            extra: HashMap::new(),
        })
        .unwrap_or_else(|_| serde_json::json!({"kind":"crm"}))
    }

    fn apply_crm_view_config(
        &mut self,
        saved_view_id: Option<String>,
        scope: Option<CrmSavedViewScope>,
        config: &serde_json::Value,
    ) {
        let Ok(config) = serde_json::from_value::<CrmViewConfig>(config.clone()) else {
            self.session_notice = Some("This saved view has an invalid CRM configuration".into());
            return;
        };
        if config.kind != "crm" {
            self.session_notice = Some("This saved view belongs to another Macro surface".into());
            return;
        }
        self.crm_search_query = config.search_text.unwrap_or_default();
        self.crm_entity_scope = match config.active_tab.as_deref() {
            Some("companies" | "company") => CrmEntityScope::Companies,
            Some("contacts" | "contact") => CrmEntityScope::Contacts,
            _ => CrmEntityScope::All,
        };
        self.crm_sort = match config.sort.first().map(String::as_str) {
            Some("name_asc" | "name") => CrmSort::NameAsc,
            Some("name_desc") => CrmSort::NameDesc,
            _ => CrmSort::UpdatedDesc,
        };
        self.crm_view_mode = config.view_mode.unwrap_or_default();
        self.crm_grouping = CrmGrouping::from_saved_view_id(config.group_by.as_deref());
        self.crm_stage_filter = config.stage_filter.into_iter().collect();
        self.crm_owner_filter = config.owner_filter.into_iter().collect();
        self.active_crm_saved_view_id = saved_view_id;
        self.active_crm_saved_view_scope = scope;
    }

    fn reset_crm_view(&mut self, cx: &mut Context<Self>) {
        self.crm_search_query.clear();
        self.crm_entity_scope = CrmEntityScope::default();
        self.crm_sort = CrmSort::default();
        self.crm_view_mode = CrmViewMode::default();
        self.crm_grouping = CrmGrouping::default();
        self.crm_stage_filter.clear();
        self.crm_owner_filter.clear();
        self.active_crm_saved_view_id = None;
        self.active_crm_saved_view_scope = None;
        cx.notify();
    }

