    fn set_crm_saved_view_default(
        &mut self,
        saved_view_id: String,
        make_default: bool,
        cx: &mut Context<Self>,
    ) {
        let previous_default = self.workspace.saved_views.loaded().and_then(|response| {
            response
                .views
                .iter()
                .find(|view| {
                    view.config
                        .get("isDefault")
                        .and_then(serde_json::Value::as_bool)
                        == Some(true)
                })
                .map(|view| view.id.clone())
        });
        let api = self.api.clone();
        self.session_notice = Some("Updating default CRM view…".into());
        cx.spawn(async move |this, cx| {
            let result = async {
                if let Some(previous_default) = previous_default
                    && previous_default != saved_view_id
                {
                    api.patch_saved_view(
                        &previous_default,
                        &PatchSavedViewRequest {
                            name: None,
                            config: Some(serde_json::json!({"isDefault":false})),
                        },
                    )
                    .await?;
                }
                if make_default {
                    api.patch_saved_view(
                        &saved_view_id,
                        &PatchSavedViewRequest {
                            name: None,
                            config: Some(serde_json::json!({"isDefault":true})),
                        },
                    )
                    .await
                } else {
                    api.patch_saved_view(
                        &saved_view_id,
                        &PatchSavedViewRequest {
                            name: None,
                            config: Some(serde_json::json!({"isDefault":false})),
                        },
                    )
                    .await
                }
            }
            .await;
            this.update(cx, |this, cx| {
                match result {
                    Ok(()) => {
                        this.session_notice = Some("Default CRM view updated".into());
                        this.workspace.saved_views = DataState::Idle;
                        this.load_saved_views(true, cx);
                    }
                    Err(error) => {
                        this.session_notice =
                            Some(format!("Unable to update default CRM view: {error}"));
                    }
                }
                cx.notify();
            })?;
            anyhow::Ok(())
        })
        .detach();
        cx.notify();
    }

    fn active_crm_stages(&self) -> (String, Vec<CrmStage>) {
        const SYSTEM_STAGE_DEFINITION_ID: &str = "00000001-0000-0000-0000-000000000010";
        let team_definition =
            self.workspace
                .property_definitions
                .loaded()
                .and_then(|definitions| {
                    definitions.iter().find(|entry| {
                        let definition = entry.definition();
                        definition.display_name == "Stage"
                            && definition.data_type == "SELECT_STRING"
                            && !definition.is_system
                            && matches!(definition.owner, macro_api::PropertyOwner::Team { .. })
                            && !entry.options().is_empty()
                    })
                });
        if let Some(entry) = team_definition {
            let mut options = entry.options().to_vec();
            options.sort_by_key(|option| option.display_order);
            let stages = options
                .into_iter()
                .map(|option| {
                    let label = option.label();
                    CrmStage {
                        id: option.id,
                        label,
                    }
                })
                .filter(|stage| !stage.label.trim().is_empty())
                .collect::<Vec<_>>();
            if !stages.is_empty() {
                return (entry.definition().id.clone(), stages);
            }
        }
        (SYSTEM_STAGE_DEFINITION_ID.into(), default_crm_stages())
    }

    fn crm_company_stage_id(
        &self,
        company_id: &str,
        active_definition_id: &str,
        stages: &[CrmStage],
    ) -> Option<String> {
        const SYSTEM_STAGE_DEFINITION_ID: &str = "00000001-0000-0000-0000-000000000010";
        if let Some(stage_id) = self.crm_optimistic_stages.get(company_id) {
            if stage_id == "__unstaged__" {
                return None;
            }
            return Some(stage_id.clone());
        }
        let properties = self
            .workspace
            .entity_properties
            .get(&format!("{}:{company_id}", EntityType::CrmCompany))
            .and_then(DataState::loaded)?;
        let option_for = |definition_id: &str| {
            properties
                .properties
                .iter()
                .find(|property| property.definition_id == definition_id)
                .and_then(|property| match &property.value {
                    PropertyValue::SelectOptions(ids) => ids.first().cloned(),
                    _ => None,
                })
        };
        if let Some(stage_id) = option_for(active_definition_id)
            && stages.iter().any(|stage| stage.id == stage_id)
        {
            return Some(stage_id);
        }
        if active_definition_id != SYSTEM_STAGE_DEFINITION_ID
            && let Some(legacy_id) = option_for(SYSTEM_STAGE_DEFINITION_ID)
            && let Some(legacy_label) = system_crm_stage_label(&legacy_id)
        {
            return stages
                .iter()
                .find(|stage| stage.label.eq_ignore_ascii_case(legacy_label))
                .map(|stage| stage.id.clone());
        }
        None
    }

    fn crm_company_property_label(&self, company_id: &str, definition_name: &str) -> String {
        let Some(property) = self
            .workspace
            .entity_properties
            .get(&format!("{}:{company_id}", EntityType::CrmCompany))
            .and_then(DataState::loaded)
            .and_then(|properties| {
                properties
                    .properties
                    .iter()
                    .find(|property| property.display_name == definition_name)
            })
        else {
            return "—".into();
        };
        match (&property.value, definition_name) {
            (PropertyValue::EntityReferences(references), "Owner") => {
                let labels = references
                    .iter()
                    .map(|reference| {
                        self.workspace
                            .user_names
                            .loaded()
                            .and_then(|users| users.get(&reference.entity_id))
                            .map(user_name_label)
                            .unwrap_or_else(|| fallback_user_label(&reference.entity_id))
                    })
                    .collect::<Vec<_>>();
                if labels.is_empty() {
                    "—".into()
                } else {
                    labels.join(", ")
                }
            }
            (PropertyValue::Number(value), "Revenue") => format_usd(*value),
            _ => property_value_label(&property.value, &property.options),
        }
    }

    fn crm_company_property_input(&self, company_id: &str, definition_name: &str) -> String {
        self.workspace
            .entity_properties
            .get(&format!("{}:{company_id}", EntityType::CrmCompany))
            .and_then(DataState::loaded)
            .and_then(|properties| {
                properties
                    .properties
                    .iter()
                    .find(|property| property.display_name == definition_name)
                    .map(|property| property_input_value(&property.value))
            })
            .unwrap_or_default()
    }

    fn crm_company_owner_ids(&self, company_id: &str) -> Vec<String> {
        self.workspace
            .entity_properties
            .get(&format!("{}:{company_id}", EntityType::CrmCompany))
            .and_then(DataState::loaded)
            .and_then(|properties| {
                properties
                    .properties
                    .iter()
                    .find(|property| property.display_name == "Owner")
                    .and_then(|property| match &property.value {
                        PropertyValue::EntityReferences(references) => Some(
                            references
                                .iter()
                                .map(|reference| reference.entity_id.clone())
                                .collect(),
                        ),
                        _ => None,
                    })
            })
            .unwrap_or_default()
    }

    fn crm_list_entries(
        &self,
        items: Vec<Arc<InboxItem>>,
        stage_definition_id: &str,
        stages: &[CrmStage],
    ) -> Vec<CrmListEntry> {
        if self.crm_grouping == CrmGrouping::None {
            return items.into_iter().map(CrmListEntry::Record).collect();
        }

        let mut groups = Vec::<(String, Vec<Arc<InboxItem>>)>::new();
        for item in items {
            let label = if item.entity_type != EntityType::CrmCompany {
                "Contacts".to_owned()
            } else {
                match self.crm_grouping {
                    CrmGrouping::None => unreachable!(),
                    CrmGrouping::Stage => self
                        .crm_company_stage_id(&item.id, stage_definition_id, stages)
                        .and_then(|stage_id| {
                            stages
                                .iter()
                                .find(|stage| stage.id == stage_id)
                                .map(|stage| stage.label.clone())
                        })
                        .unwrap_or_else(|| "Unstaged".into()),
                    CrmGrouping::Owner => {
                        let owner = self.crm_company_property_label(&item.id, "Owner");
                        if owner == "—" {
                            "Unassigned".into()
                        } else {
                            owner
                        }
                    }
                }
            };
            if let Some((_, entries)) = groups.iter_mut().find(|(name, _)| name == &label) {
                entries.push(item);
            } else {
                groups.push((label, vec![item]));
            }
        }

        groups.sort_by(|(left, _), (right, _)| match self.crm_grouping {
            CrmGrouping::Stage => {
                let rank = |label: &str| {
                    stages
                        .iter()
                        .position(|stage| stage.label == label)
                        .unwrap_or_else(|| {
                            stages.len()
                                + match label {
                                    "Unstaged" => 0,
                                    "Contacts" => 1,
                                    _ => 2,
                                }
                        })
                };
                rank(left).cmp(&rank(right)).then_with(|| left.cmp(right))
            }
            CrmGrouping::Owner => left.cmp(right),
            CrmGrouping::None => std::cmp::Ordering::Equal,
        });

        groups
            .into_iter()
            .flat_map(|(label, records)| {
                let count = records.len();
                std::iter::once(CrmListEntry::Group { label, count })
                    .chain(records.into_iter().map(CrmListEntry::Record))
            })
            .collect()
    }

    fn filtered_sorted_crm_items(&self, items: Vec<Arc<InboxItem>>) -> Vec<Arc<InboxItem>> {
        let query = self.crm_search_query.trim().to_lowercase();
        let (stage_definition_id, crm_stages) = self.active_crm_stages();
        let mut items = items
            .into_iter()
            .filter(|item| {
                let stage_matches = item.entity_type != EntityType::CrmCompany
                    || self.crm_stage_filter.is_empty()
                    || self
                        .crm_company_stage_id(&item.id, &stage_definition_id, &crm_stages)
                        .map_or_else(
                            || self.crm_stage_filter.contains("NO_STAGE"),
                            |stage_id| self.crm_stage_filter.contains(&stage_id),
                        );
                let owner_matches = item.entity_type != EntityType::CrmCompany
                    || self.crm_owner_filter.is_empty()
                    || self
                        .crm_company_owner_ids(&item.id)
                        .iter()
                        .any(|owner_id| self.crm_owner_filter.contains(owner_id));
                self.crm_entity_scope.matches(item)
                    && stage_matches
                    && owner_matches
                    && (query.is_empty()
                        || item.title.to_lowercase().contains(&query)
                        || item.subtitle.to_lowercase().contains(&query)
                        || item.raw.to_string().to_lowercase().contains(&query))
            })
            .collect::<Vec<_>>();
        match self.crm_sort {
            CrmSort::UpdatedDesc => items.sort_by(|a, b| b.timestamp.cmp(&a.timestamp)),
            CrmSort::NameAsc => items.sort_by_cached_key(|item| item.title.to_lowercase()),
            CrmSort::NameDesc => {
                items.sort_by_cached_key(|item| std::cmp::Reverse(item.title.to_lowercase()))
            }
        }
        items
    }

    fn visible_crm_list_items(&self) -> Vec<Arc<InboxItem>> {
        if self.crm_view_mode != CrmViewMode::List {
            return Vec::new();
        }
        let items = self.filtered_sorted_crm_items(self.workspace.inbox.snapshot().items);
        let (stage_definition_id, stages) = self.active_crm_stages();
        self.crm_list_entries(items, &stage_definition_id, &stages)
            .into_iter()
            .filter_map(|entry| match entry {
                CrmListEntry::Record(item) => Some(item),
                CrmListEntry::Group { .. } => None,
            })
            .collect()
    }

    fn can_move_company_from_stage(&self, stage_id: Option<&str>, stages: &[CrmStage]) -> bool {
        let Some(stage_id) = stage_id else {
            return true;
        };
        let closed = self
            .workspace
            .crm_team_settings
            .loaded()
            .and_then(|settings| settings.closed_stage_ids.as_ref())
            .map(|ids| ids.iter().any(|id| id == stage_id))
            .unwrap_or_else(|| {
                stages
                    .iter()
                    .find(|stage| stage.id == stage_id)
                    .is_some_and(|stage| is_closed_crm_stage_label(&stage.label))
            });
        if !closed {
            return true;
        }
        let required = self
            .workspace
            .crm_team_settings
            .loaded()
            .map(|settings| settings.move_closed_deals_role)
            .unwrap_or(CrmPermissionRole::Admin);
        crm_role_satisfies(self.current_team_role(), required)
    }

    fn current_team_role(&self) -> Option<TeamRole> {
        let user_id = match &self.session {
            SessionState::Ready { user } => user.user_id.as_str(),
            _ => return None,
        };
        self.workspace
            .team
            .loaded()
            .and_then(Option::as_ref)
            .and_then(|team| {
                team.members
                    .iter()
                    .find(|member| member.user_id == user_id)
                    .map(|member| member.role)
            })
    }

    fn is_current_team_admin(&self) -> bool {
        matches!(
            self.current_team_role(),
            Some(TeamRole::Admin | TeamRole::Owner)
        )
    }

    fn can_delete_crm_records(&self) -> bool {
        let required = self
            .workspace
            .crm_team_settings
            .loaded()
            .map(|settings| settings.delete_records_role)
            .unwrap_or(CrmPermissionRole::Admin);
        crm_role_satisfies(self.current_team_role(), required)
    }

    fn set_crm_company_stage(
        &mut self,
        company_id: String,
        definition_id: String,
        stage: CrmStage,
        cx: &mut Context<Self>,
    ) {
        let (_, stages) = self.active_crm_stages();
        let previous = self.crm_company_stage_id(&company_id, &definition_id, &stages);
        if previous.as_deref() == Some(stage.id.as_str())
            || (previous.is_none() && stage.id == "__unstaged__")
        {
            return;
        }
        if !self.can_move_company_from_stage(previous.as_deref(), &stages) {
            self.session_notice =
                Some("Your team role cannot move a company out of a closed pipeline stage".into());
            cx.notify();
            return;
        }

        self.crm_optimistic_stages
            .insert(company_id.clone(), stage.id.clone());
        self.session_notice = Some(format!("Moving company to {}…", stage.label));
        let property_value = if stage.id == "__unstaged__" {
            serde_json::Value::Null
        } else {
            serde_json::json!({
                "type":"select_option",
                "option_id":stage.id
            })
        };
        let api = self.api.clone();
        cx.spawn(async move |this, cx| {
            let result = api
                .set_entity_property("COMPANY", &company_id, &definition_id, &property_value)
                .await;
            this.update(cx, |this, cx| {
                match result {
                    Ok(_) => {
                        this.session_notice = Some(format!("Company moved to {}", stage.label));
                        this.workspace
                            .entity_properties
                            .remove(&format!("{}:{company_id}", EntityType::CrmCompany));
                        this.load_entity_properties(
                            EntityType::CrmCompany,
                            company_id.clone(),
                            true,
                            cx,
                        );
                    }
                    Err(error) => {
                        if let Some(previous) = previous {
                            this.crm_optimistic_stages
                                .insert(company_id.clone(), previous);
                        } else {
                            this.crm_optimistic_stages.remove(&company_id);
                        }
                        this.session_notice = Some(format!("Unable to move company: {error}"));
                    }
                }
                cx.notify();
            })?;
            anyhow::Ok(())
        })
        .detach();
        cx.notify();
    }

