    fn validate_webhook(&mut self, webhook_id: String, cx: &mut Context<Self>) {
        let api = self.api.clone();
        self.session_notice = Some("Sending signed webhook validation…".into());
        cx.spawn(async move |this, cx| {
            let result = api.validate_webhook(&webhook_id).await;
            this.update(cx, |this, cx| {
                match result {
                    Ok(validation) => {
                        this.session_notice = Some(if validation.is_valid {
                            format!(
                                "Webhook validated{}",
                                validation
                                    .response_status
                                    .map(|status| format!(" (HTTP {status})"))
                                    .unwrap_or_default()
                            )
                        } else {
                            format!(
                                "Webhook validation failed{}{}",
                                validation
                                    .response_status
                                    .map(|status| format!(" (HTTP {status})"))
                                    .unwrap_or_default(),
                                validation
                                    .message
                                    .map(|message| format!(": {message}"))
                                    .unwrap_or_default()
                            )
                        });
                        this.workspace.webhooks = DataState::Idle;
                        this.load_webhooks(true, cx);
                    }
                    Err(error) => {
                        this.session_notice = Some(format!("Webhook validation failed: {error}"));
                    }
                }
                cx.notify();
            })?;
            anyhow::Ok(())
        })
        .detach();
    }

