    fn pick_and_upload_profile_picture(&mut self, cx: &mut Context<Self>) {
        let receiver = cx.prompt_for_paths(PathPromptOptions {
            files: true,
            directories: false,
            multiple: false,
            prompt: Some("Choose a profile picture".into()),
        });
        cx.spawn(async move |this, cx| {
            let path = match receiver.await {
                Ok(Ok(Some(paths))) => paths.into_iter().next(),
                Ok(Ok(None)) => None,
                Ok(Err(error)) => {
                    this.update(cx, |this, cx| {
                        this.session_notice =
                            Some(format!("Profile picture picker failed: {error}"));
                        cx.notify();
                    })?;
                    return anyhow::Ok(());
                }
                Err(error) => {
                    this.update(cx, |this, cx| {
                        this.session_notice =
                            Some(format!("Profile picture picker closed: {error}"));
                        cx.notify();
                    })?;
                    return anyhow::Ok(());
                }
            };
            if let Some(path) = path {
                this.update(cx, |this, cx| this.upload_profile_picture_path(path, cx))?;
            }
            anyhow::Ok(())
        })
        .detach();
    }

    fn upload_profile_picture_path(&mut self, path: PathBuf, cx: &mut Context<Self>) {
        const MAX_PROFILE_PICTURE_BYTES: usize = 16 * 1_000_000;

        let content_type = mime_type_for_path(&path).to_owned();
        if !content_type.starts_with("image/") {
            self.session_notice = Some("Choose an image file for your profile picture".into());
            cx.notify();
            return;
        }
        let file_name = path
            .file_name()
            .and_then(|name| name.to_str())
            .unwrap_or("profile-picture")
            .to_owned();
        let current_user_id = match &self.session {
            SessionState::Ready { user } => user.user_id.clone(),
            _ => return,
        };
        self.session_notice = Some("Uploading profile picture…".into());
        cx.notify();
        let api = self.api.clone();
        let static_files_base_url = api.config().static_files_base_url.clone();
        cx.spawn(async move |this, cx| {
            let read_path = path.clone();
            let bytes = cx
                .background_spawn(async move {
                    read_bounded_file(&read_path, MAX_PROFILE_PICTURE_BYTES as u64)
                })
                .await;
            let result: anyhow::Result<String> = async {
                let bytes = bytes?;
                anyhow::ensure!(
                    bytes.len() <= MAX_PROFILE_PICTURE_BYTES,
                    "image is larger than 16 MB"
                );
                let uploaded = api
                    .upload_static_file(&file_name, &content_type, bytes)
                    .await?;
                let url = format!(
                    "{}/file/{}",
                    static_files_base_url.trim_end_matches('/'),
                    urlencoding::encode(&uploaded.id)
                );
                api.put_profile_picture(&url).await?;
                Ok(url)
            }
            .await;
            this.update(cx, |this, cx| {
                match result {
                    Ok(url) => {
                        if let DataState::Loaded(pictures) = &mut this.workspace.profile_pictures {
                            pictures
                                .pictures
                                .retain(|picture| picture.id != current_user_id);
                            pictures.pictures.push(macro_api::UserProfilePicture {
                                checksum: None,
                                id: current_user_id,
                                url,
                            });
                        } else {
                            this.workspace.profile_pictures = DataState::Idle;
                            this.load_account_administration(true, cx);
                        }
                        this.session_notice = Some("Profile picture updated".into());
                    }
                    Err(error) => {
                        this.session_notice =
                            Some(format!("Profile picture could not be updated: {error:#}"));
                    }
                }
                cx.notify();
            })?;
            anyhow::Ok(())
        })
        .detach();
    }

    fn remove_profile_picture(&mut self, cx: &mut Context<Self>) {
        let current_user_id = match &self.session {
            SessionState::Ready { user } => user.user_id.clone(),
            _ => return,
        };
        self.session_notice = Some("Removing profile picture…".into());
        cx.notify();
        let api = self.api.clone();
        cx.spawn(async move |this, cx| {
            let result = api.put_profile_picture("").await;
            this.update(cx, |this, cx| {
                match result {
                    Ok(()) => {
                        if let DataState::Loaded(pictures) = &mut this.workspace.profile_pictures {
                            pictures
                                .pictures
                                .retain(|picture| picture.id != current_user_id);
                        } else {
                            this.workspace.profile_pictures = DataState::Idle;
                        }
                        this.session_notice = Some("Profile picture removed".into());
                    }
                    Err(error) => {
                        this.session_notice =
                            Some(format!("Profile picture could not be removed: {error}"));
                    }
                }
                cx.notify();
            })?;
            anyhow::Ok(())
        })
        .detach();
    }

