    fn run_document_search(
        &mut self,
        document_id: &str,
        state: DocumentSearchState,
        action: &str,
        window: &mut Window,
        cx: &mut Context<Self>,
    ) -> Result<String, String> {
        let Some(editor) = self.document_editors.get(document_id).cloned() else {
            return Err("The document editor is no longer open".into());
        };
        let result = match action {
            "next" => editor
                .update(cx, |editor, cx| {
                    editor.select_document_search_match(
                        &state.query,
                        state.options,
                        false,
                        window,
                        cx,
                    )
                })
                .map(|range| {
                    range.map_or_else(|| "No matches".into(), |_| "Selected next match".into())
                }),
            "previous" => editor
                .update(cx, |editor, cx| {
                    editor.select_document_search_match(
                        &state.query,
                        state.options,
                        true,
                        window,
                        cx,
                    )
                })
                .map(|range| {
                    range.map_or_else(|| "No matches".into(), |_| "Selected previous match".into())
                }),
            "replace" => editor
                .update(cx, |editor, cx| {
                    editor.replace_current_document_search_match(
                        &state.query,
                        &state.replacement,
                        state.options,
                        window,
                        cx,
                    )
                })
                .map(|replaced| {
                    if replaced {
                        "Replaced current match".into()
                    } else {
                        "No matches".into()
                    }
                }),
            "replace-all" => editor
                .update(cx, |editor, cx| {
                    editor.replace_all_document_search_matches(
                        &state.query,
                        &state.replacement,
                        state.options,
                        window,
                        cx,
                    )
                })
                .map(|count| {
                    format!(
                        "Replaced {count} match{}",
                        if count == 1 { "" } else { "es" }
                    )
                }),
            _ => Err("Action must be next, previous, replace, or replace-all".into()),
        }?;
        self.document_searches.insert(document_id.to_owned(), state);
        Ok(result)
    }

    fn repeat_document_search(
        &mut self,
        document_id: &str,
        backwards: bool,
        window: &mut Window,
        cx: &mut Context<Self>,
    ) {
        let Some(state) = self.document_searches.get(document_id).cloned() else {
            self.open_document_find_replace(document_id.to_owned(), cx);
            return;
        };
        match self.run_document_search(
            document_id,
            state,
            if backwards { "previous" } else { "next" },
            window,
            cx,
        ) {
            Ok(message) => self.session_notice = Some(message),
            Err(error) => self.session_notice = Some(error),
        }
        cx.notify();
    }

    fn persist_document_editor(
        &mut self,
        document_id: String,
        show_feedback: bool,
        cx: &mut Context<Self>,
    ) {
        let Some(editor) = self.document_editors.get(&document_id).cloned() else {
            return;
        };
        if editor.read(cx).read_only() || self.document_saves.contains(&document_id) {
            return;
        }
        if editor.read(cx).remote_conflict().is_some() {
            self.session_notice = Some(
                "Resolve the concurrent document edit before saving; no version has been overwritten"
                    .into(),
            );
            cx.notify();
            return;
        }
        let name = editor.read(cx).name().to_owned();
        let markdown = editor.read(cx).text(cx);
        let lexical_source = editor.read(cx).lexical_source().cloned();
        let collaboration = self.document_syncs.get(&document_id).and_then(|sync| {
            sync.initialized.then(|| {
                (
                    sync.client.clone(),
                    sync.crdt.clone(),
                    matches!(sync.status, SyncStatus::Connected),
                )
            })
        });
        self.document_saves.insert(document_id.clone());
        if show_feedback {
            self.session_notice = Some("Saving document…".into());
        }
        let api = self.api.clone();
        cx.spawn(async move |this, cx| {
            let result = async {
                api.rename_document(&document_id, &name).await?;
                if let Some((client, crdt, connected)) = collaboration {
                    let lexical_state = match lexical_source.as_ref() {
                        Some(source) => project_markdown_edits(source, &markdown)?,
                        None => markdown_to_lexical_state(&markdown),
                    };
                    let update = if contains_document_comment_marks(&lexical_state) {
                        crdt.replace_annotation_state(&lexical_state)?
                    } else {
                        crdt.replace_markdown_state(&lexical_state)?
                    };
                    client.queue_update(vec![update]).await?;
                    anyhow::Ok((
                        if connected {
                            "Document saved and queued for collaboration"
                        } else {
                            "Document saved offline; it will sync after reconnecting"
                        },
                        Some(lexical_state),
                        markdown,
                    ))
                } else {
                    // Compatibility fallback while the first authenticated
                    // collaboration snapshot is still arriving.
                    api.simple_save_markdown(&document_id, &markdown).await?;
                    anyhow::Ok((
                        "Document saved through compatibility service",
                        None,
                        markdown,
                    ))
                }
            }
            .await;
            this.update(cx, |this, cx| {
                this.document_saves.remove(&document_id);
                match result {
                    Ok((message, lexical_state, saved_markdown)) => {
                        let unchanged = this
                            .document_editors
                            .get(&document_id)
                            .cloned()
                            .is_some_and(|editor| {
                                editor.update(cx, |editor, cx| {
                                    editor.acknowledge_saved_projection(
                                        &saved_markdown,
                                        lexical_state,
                                        cx,
                                    )
                                })
                            });
                        if show_feedback {
                            this.session_notice = Some(message.into());
                        }
                        let key = format!("{}:{}", EntityType::Document, document_id);
                        this.workspace.entity_details.remove(&key);
                        this.publish_document_selection(&document_id, cx);
                        if !unchanged {
                            this.schedule_document_autosync(document_id.clone(), cx);
                        }
                        if show_feedback {
                            this.apply_reconcile_plan(
                                ReconcilePlan::new([
                                    ReconcileTarget::Inbox,
                                    ReconcileTarget::Entity {
                                        entity_type: EntityType::Document,
                                        entity_id: document_id.clone(),
                                    },
                                ]),
                                cx,
                            );
                        }
                    }
                    Err(error) => {
                        this.session_notice = Some(format!("Document save failed: {error}"));
                    }
                }
                cx.notify();
            })?;
            anyhow::Ok(())
        })
        .detach();
    }

    fn apply_document_comment_anchor(
        &mut self,
        anchor: PendingDocumentCommentAnchor,
        cx: &mut Context<Self>,
    ) {
        let document_id = anchor.document_id.clone();
        let Some(editor) = self.document_editors.get(&document_id).cloned() else {
            self.pending_document_comment_anchors
                .entry(document_id)
                .or_default()
                .push(anchor);
            self.session_notice = Some(
                "Comment created; its text anchor will attach when the document is reopened".into(),
            );
            return;
        };
        let sync_ready = self
            .document_syncs
            .get(&document_id)
            .is_some_and(|sync| sync.initialized);
        let source = editor.read(cx).lexical_source().cloned();
        if !sync_ready || source.is_none() {
            self.pending_document_comment_anchors
                .entry(document_id)
                .or_default()
                .push(anchor);
            self.session_notice = Some(
                "Comment created; its text anchor will attach after collaboration syncs".into(),
            );
            return;
        }
        if editor.read(cx).remote_conflict().is_some() {
            self.pending_document_comment_anchors
                .entry(document_id)
                .or_default()
                .push(anchor);
            self.session_notice = Some(
                "Comment created; resolve the document conflict to attach its text anchor".into(),
            );
            return;
        }

        let current = editor.read(cx).text(cx);
        let source = source.expect("checked above");
        let projected = match project_markdown_edits(&source, &current) {
            Ok(projected) => projected,
            Err(error) => {
                self.session_notice = Some(format!(
                    "Comment created, but its text anchor could not preserve this document schema: {error}"
                ));
                return;
            }
        };
        let annotated = if let Some(finalized) =
            finalize_document_comment_mark(&projected, &anchor.mark_id, anchor.thread_id)
        {
            finalized
        } else {
            let Some((start, end)) = rebase_document_comment_selection(
                &current,
                anchor.selection,
                &anchor.selected_text,
            ) else {
                self.session_notice = Some(
                    "Comment created, but the selected text changed ambiguously; it remains available in the document discussion sidebar"
                        .into(),
                );
                return;
            };
            match anchor_document_comment(&projected, start..end, &anchor.mark_id, anchor.thread_id)
            {
                Ok(annotated) => annotated,
                Err(error) => {
                    self.session_notice = Some(format!(
                        "Comment created, but the selected text could not be anchored: {error}"
                    ));
                    return;
                }
            }
        };
        let (client, update) = {
            let Some(sync) = self.document_syncs.get(&document_id) else {
                self.pending_document_comment_anchors
                    .entry(document_id)
                    .or_default()
                    .push(anchor);
                return;
            };
            match sync.crdt.replace_annotation_state(&annotated) {
                Ok(update) => (sync.client.clone(), update),
                Err(error) => {
                    self.session_notice = Some(format!(
                        "Comment created, but its collaboration anchor failed: {error:#}"
                    ));
                    return;
                }
            }
        };

        editor.update(cx, |editor, cx| {
            editor.accept_lexical_annotation_state(annotated, cx)
        });
        self.publish_document_selection(&document_id, cx);
        self.refresh_document_awareness(&document_id, cx);
        self.session_notice = Some("Comment created and anchored to the selected text".into());
        cx.spawn(async move |this, cx| {
            let result = client.queue_update(vec![update]).await;
            this.update(cx, |this, cx| {
                if let Err(error) = result {
                    if let Some(sync) = this.document_syncs.get_mut(&document_id) {
                        sync.error = Some(format!(
                            "Document comment anchor could not be queued durably: {error:#}"
                        ));
                    }
                    this.session_notice = Some(format!(
                        "Comment was created, but its text anchor could not be queued: {error:#}"
                    ));
                }
                cx.notify();
            })?;
            anyhow::Ok(())
        })
        .detach();
    }

    fn remove_document_comment_anchor(
        &mut self,
        document_id: &str,
        mark_id: String,
        cx: &mut Context<Self>,
    ) {
        let Some(editor) = self.document_editors.get(document_id).cloned() else {
            self.pending_document_comment_unanchors
                .entry(document_id.to_owned())
                .or_default()
                .push(mark_id);
            return;
        };
        let Some(sync) = self
            .document_syncs
            .get(document_id)
            .filter(|sync| sync.initialized)
        else {
            self.pending_document_comment_unanchors
                .entry(document_id.to_owned())
                .or_default()
                .push(mark_id);
            return;
        };
        let Some(source) = editor.read(cx).lexical_source().cloned() else {
            self.pending_document_comment_unanchors
                .entry(document_id.to_owned())
                .or_default()
                .push(mark_id);
            return;
        };
        let without_mark = remove_document_comment_mark(&source, &mark_id);
        if without_mark == source {
            return;
        }
        let update = match sync.crdt.replace_annotation_state(&without_mark) {
            Ok(update) => update,
            Err(error) => {
                self.session_notice = Some(format!(
                    "Comment was deleted, but its text highlight could not be removed: {error:#}"
                ));
                return;
            }
        };
        let client = sync.client.clone();
        editor.update(cx, |editor, cx| {
            editor.accept_lexical_annotation_state(without_mark, cx)
        });
        self.publish_document_selection(document_id, cx);
        self.refresh_document_awareness(document_id, cx);
        let document_id = document_id.to_owned();
        cx.spawn(async move |this, cx| {
            let result = client.queue_update(vec![update]).await;
            this.update(cx, |this, cx| {
                if let Err(error) = result {
                    if let Some(sync) = this.document_syncs.get_mut(&document_id) {
                        sync.error = Some(format!(
                            "Document comment removal could not be queued durably: {error:#}"
                        ));
                    }
                    this.session_notice = Some(format!(
                        "Comment was deleted, but its text highlight could not be queued: {error:#}"
                    ));
                }
                cx.notify();
            })?;
            anyhow::Ok(())
        })
        .detach();
    }

    fn flush_pending_document_comment_anchors(
        &mut self,
        document_id: &str,
        cx: &mut Context<Self>,
    ) {
        if let Some(mark_ids) = self.pending_document_comment_unanchors.remove(document_id) {
            for mark_id in mark_ids {
                self.remove_document_comment_anchor(document_id, mark_id, cx);
            }
        }
        let Some(anchors) = self.pending_document_comment_anchors.remove(document_id) else {
            return;
        };
        for anchor in anchors {
            self.apply_document_comment_anchor(anchor, cx);
        }
    }

    fn toggle_document_pinned_property(
        &mut self,
        document_id: &str,
        property_id: &str,
        cx: &mut Context<Self>,
    ) {
        let Some(editor) = self.document_editors.get(document_id).cloned() else {
            return;
        };
        let changed = editor.update(cx, |editor, cx| {
            editor.toggle_pinned_property(property_id, cx)
        });
        if !changed {
            self.session_notice = Some(
                "Pinned-property state is available after collaboration finishes syncing".into(),
            );
        }
        cx.notify();
    }

    fn close_document_editor(&mut self, document_id: String, cx: &mut Context<Self>) {
        let dirty = self
            .document_editors
            .get(&document_id)
            .is_some_and(|editor| editor.read(cx).is_dirty());
        if dirty {
            self.open_mutation_dialog(
                MutationDialog::new(
                    "Discard document changes?",
                    "Discard changes",
                    MutationKind::DiscardDocumentEdits { document_id },
                    vec![Self::mutation_field("Type DISCARD to confirm", "", false)],
                ),
                cx,
            );
        } else {
            self.document_editors.remove(&document_id);
            self.document_searches.remove(&document_id);
            self.stop_document_sync(&document_id);
            cx.notify();
        }
    }

    fn add_canvas_node(
        &mut self,
        document_id: String,
        kind: CanvasNodeKind,
        cx: &mut Context<Self>,
    ) {
        let Some(model) = self.canvas_models.get_mut(&document_id) else {
            return;
        };
        let center = model
            .viewport
            .screen_to_canvas(CanvasPoint { x: 420.0, y: 260.0 });
        self.insert_canvas_node_at(document_id, kind, center, cx);
    }

    fn insert_canvas_node_at(
        &mut self,
        document_id: String,
        kind: CanvasNodeKind,
        center: CanvasPoint,
        cx: &mut Context<Self>,
    ) -> bool {
        let mut node = match kind {
            CanvasNodeKind::Text { text, .. } => CanvasNode::text(text, center.x, center.y),
            CanvasNodeKind::Shape { shape } => CanvasNode::shape(shape, center.x, center.y),
            other => CanvasNode::new(other, center.x, center.y, 180.0, 100.0),
        };
        node.x -= node.width / 2.0;
        node.y -= node.height / 2.0;
        self.insert_canvas_node(document_id, node, cx)
    }

    fn insert_canvas_node(
        &mut self,
        document_id: String,
        node: CanvasNode,
        cx: &mut Context<Self>,
    ) -> bool {
        let Some(model) = self.canvas_models.get_mut(&document_id) else {
            return false;
        };
        match model.add_node(node) {
            Ok(_) => {
                self.canvas_tools
                    .insert(document_id.clone(), CanvasTool::Select);
                self.canvas_changed(document_id, cx);
                cx.notify();
                true
            }
            Err(error) => {
                self.session_notice = Some(format!("Canvas edit failed: {error:#}"));
                cx.notify();
                false
            }
        }
    }

    fn select_canvas_node(
        &mut self,
        document_id: &str,
        node_id: &str,
        additive: bool,
        cx: &mut Context<Self>,
    ) {
        if let Some(model) = self.canvas_models.get_mut(document_id) {
            if additive {
                model.toggle_node_selection(node_id);
            } else {
                model.select_only(node_id);
            }
            cx.notify();
        }
    }

