    fn pick_and_upload_canvas_media(
        &mut self,
        document_id: String,
        video: bool,
        cx: &mut Context<Self>,
    ) {
        let receiver = cx.prompt_for_paths(PathPromptOptions {
            files: true,
            directories: false,
            multiple: false,
            prompt: Some(if video {
                "Add video to canvas".into()
            } else {
                "Add image to canvas".into()
            }),
        });
        cx.spawn(async move |this, cx| {
            let Some(path) = receiver
                .await
                .map_err(|error| anyhow::anyhow!("media picker closed: {error}"))??
                .and_then(|paths| paths.into_iter().next())
            else {
                return anyhow::Ok(());
            };
            this.update(cx, |this, cx| {
                this.upload_canvas_media_path(document_id, path, video, None, cx)
            })?;
            anyhow::Ok(())
        })
        .detach();
    }

    fn upload_canvas_media_path(
        &mut self,
        document_id: String,
        path: PathBuf,
        video: bool,
        canvas_position: Option<CanvasPoint>,
        cx: &mut Context<Self>,
    ) {
        let file_name = path
            .file_name()
            .and_then(|name| name.to_str())
            .unwrap_or(if video {
                "canvas-video"
            } else {
                "canvas-image"
            })
            .to_owned();
        let content_type = mime_type_for_path(&path).to_owned();
        let compatible = if video {
            content_type.starts_with("video/")
        } else {
            content_type.starts_with("image/")
        };
        if !compatible {
            self.session_notice = Some(format!(
                "Select a compatible {} file",
                if video { "video" } else { "image" }
            ));
            cx.notify();
            return;
        }

        self.file_uploads
            .insert(file_name.clone(), "Uploading to canvas…".into());
        cx.notify();
        let api = self.api.clone();
        cx.spawn(async move |this, cx| {
            let read_path = path.clone();
            let bytes = cx
                .background_spawn(
                    async move { read_bounded_file(&read_path, MAX_GENERAL_UPLOAD_BYTES) },
                )
                .await;
            // From this point onward the upload is visible in `file_uploads`,
            // so funnel both local I/O and network failures through the same
            // completion path. An early `?` here used to strand an eternal
            // "Uploading to canvas…" row when a selected file disappeared or
            // became unreadable before the background read completed.
            let upload = match bytes {
                Ok(bytes) => {
                    api.upload_static_file(&file_name, &content_type, bytes)
                        .await
                }
                Err(error) => Err(error),
            };
            this.update(cx, |this, cx| {
                this.file_uploads.remove(&file_name);
                match upload {
                    Ok(upload) => {
                        let mut inserted = false;
                        if let Some(model) = this.canvas_models.get_mut(&document_id) {
                            let center = canvas_position.unwrap_or_else(|| {
                                model
                                    .viewport
                                    .screen_to_canvas(CanvasPoint { x: 420.0, y: 260.0 })
                            });
                            let (width, height) = if video {
                                (480.0, 270.0)
                            } else {
                                (320.0, 220.0)
                            };
                            let kind = if video {
                                CanvasNodeKind::Video {
                                    status: MediaStatus::Static,
                                    uuid: upload.id,
                                    flip_x: false,
                                    flip_y: false,
                                }
                            } else {
                                CanvasNodeKind::Image {
                                    status: MediaStatus::Static,
                                    uuid: upload.id,
                                    flip_x: false,
                                    flip_y: false,
                                }
                            };
                            let mut node = CanvasNode::new(
                                kind,
                                center.x - width / 2.0,
                                center.y - height / 2.0,
                                width,
                                height,
                            );
                            node.style = Some(CanvasStyle {
                                stroke_color: Some("transparent".into()),
                                stroke_width: Some(0.0),
                                ..Default::default()
                            });
                            match model.add_node(node) {
                                Ok(_) => {
                                    inserted = true;
                                    this.canvas_tools
                                        .insert(document_id.clone(), CanvasTool::Select);
                                    this.session_notice =
                                        Some(format!("Added {file_name} to canvas"));
                                }
                                Err(error) => {
                                    this.session_notice = Some(format!(
                                        "Canvas media could not be inserted: {error:#}"
                                    ));
                                }
                            }
                        } else {
                            this.session_notice =
                                Some("Canvas was closed before the media upload finished".into());
                        }
                        if inserted {
                            this.canvas_changed(document_id.clone(), cx);
                        }
                    }
                    Err(error) => {
                        this.session_notice =
                            Some(format!("Canvas media upload failed: {error:#}"));
                    }
                }
                cx.notify();
            })?;
            anyhow::Ok(())
        })
        .detach();
    }

