    fn arrange_canvas_selection(&mut self, document_id: &str, front: bool, cx: &mut Context<Self>) {
        if let Some(model) = self.canvas_models.get_mut(document_id) {
            if front {
                model.bring_selected_to_front();
            } else {
                model.send_selected_to_back();
            }
            self.canvas_changed(document_id.to_owned(), cx);
            cx.notify();
        }
    }

    fn step_canvas_selection(&mut self, document_id: &str, forward: bool, cx: &mut Context<Self>) {
        if let Some(model) = self.canvas_models.get_mut(document_id) {
            let changed = if forward {
                model.bring_selected_forward()
            } else {
                model.send_selected_backward()
            };
            if changed {
                self.canvas_changed(document_id.to_owned(), cx);
            }
            cx.notify();
        }
    }

