                    let value = if values[0].is_empty() {
                        serde_json::Value::Null
                    } else {
                        serde_json::to_value(SetPropertyValue::EntityReference {
                            reference: macro_api::PropertyEntityReference {
                                entity_id: values[0].clone(),
                                entity_type: "USER".into(),
                                specific_message_id: None,
                            },
                        })
                        .unwrap_or(serde_json::Value::Null)
                    };
                    let count = company_ids.len();
                    let results = futures::future::join_all(company_ids.iter().map(|company_id| {
                        let api = api.clone();
                        let company_id = company_id.clone();
                        let value = value.clone();
                        async move {
                            api.set_entity_property(
                                "COMPANY",
                                &company_id,
                                CRM_COMPANY_OWNER_PROPERTY_ID,
                                &value,
                            )
                            .await
                        }
                    }))
                    .await;
                    let failed = results.iter().filter(|result| result.is_err()).count();
                    if failed == 0 {
                        Ok(format!("Updated {count} CRM owners"))
                    } else {
                        Ok(format!(
                            "Updated {}; {failed} owner updates failed",
                            count - failed
                        ))
                    }
