    fn export_canvas_svg(
        &mut self,
        document_id: String,
        canvas_name: String,
        cx: &mut Context<Self>,
    ) {
        let Some(model) = self.canvas_models.get(&document_id) else {
            self.session_notice = Some("Canvas is not loaded".into());
            cx.notify();
            return;
        };
        let svg = match model.canvas().to_svg() {
            Ok(svg) => svg,
            Err(error) => {
                self.session_notice = Some(format!("Canvas export failed: {error:#}"));
                cx.notify();
                return;
            }
        };
        let mut filename = safe_download_filename(&canvas_name, "canvas");
        if !filename.to_ascii_lowercase().ends_with(".svg") {
            filename.push_str(".svg");
        }
        let receiver = cx.prompt_for_new_path(std::path::Path::new(""), Some(&filename));
        cx.spawn(async move |this, cx| {
            let destination = match receiver.await {
                Ok(Ok(Some(path))) => path,
                Ok(Ok(None)) => return anyhow::Ok(()),
                Ok(Err(error)) => {
                    this.update(cx, |this, cx| {
                        this.session_notice = Some(format!("Save dialog failed: {error}"));
                        cx.notify();
                    })?;
                    return anyhow::Ok(());
                }
                Err(error) => {
                    this.update(cx, |this, cx| {
                        this.session_notice = Some(format!("Save dialog closed: {error}"));
                        cx.notify();
                    })?;
                    return anyhow::Ok(());
                }
            };
            this.update(cx, |this, cx| {
                this.session_notice = Some(format!("Exporting {filename}…"));
                cx.notify();
            })?;
            let write_path = destination.clone();
            let result = cx
                .background_spawn(async move {
                    std::fs::write(&write_path, svg.as_bytes())
                        .with_context(|| format!("failed to write {}", write_path.display()))
                })
                .await;
            this.update(cx, |this, cx| {
                match result {
                    Ok(()) => {
                        cx.reveal_path(&destination);
                        this.session_notice =
                            Some(format!("Exported canvas to {}", destination.display()));
                    }
                    Err(error) => {
                        this.session_notice = Some(format!("Canvas export failed: {error:#}"));
                    }
                }
                cx.notify();
            })?;
            anyhow::Ok(())
        })
        .detach();
    }

    fn retry_agent_prompt(&mut self, session_id: String, prompt: String, cx: &mut Context<Self>) {
        if !self.agent_prompt_retries.insert(session_id.clone()) {
            return;
        }
        let api = self.api.clone();
        self.session_notice = Some("Retrying the failed agent turn…".into());
        cx.spawn(async move |this, cx| {
            let result = api
                .control_agent_session(&session_id, &AgentAction::Prompt { prompt })
                .await;
            this.update(cx, |this, cx| {
                this.agent_prompt_retries.remove(&session_id);
                match result {
                    Ok(_) => {
                        this.session_notice = Some("Agent retry accepted".into());
                        this.apply_reconcile_plan(
                            ReconcilePlan::new([ReconcileTarget::Entity {
                                entity_type: EntityType::AgentSession,
                                entity_id: session_id,
                            }]),
                            cx,
                        );
                    }
                    Err(error) => {
                        this.session_notice = Some(format!("Agent retry failed: {error}"));
                    }
                }
                cx.notify();
            })?;
            anyhow::Ok(())
        })
        .detach();
        cx.notify();
    }

