    fn start_gmail_link(&mut self, scopes: &'static str, cx: &mut Context<Self>) {
        let api = self.api.clone();
        // Macro's authentication service explicitly allows this native handoff.
        // The browser redirects into the registered application scheme after
        // Google consent, where `handle_open_urls` refreshes the linked inboxes.
        let callback = "macro://inbox-link-callback";
        self.session_notice = Some("Preparing Google authorization…".into());
        cx.spawn(async move |this, cx| {
            let result = api.init_gmail_link(callback, scopes).await;
            this.update(cx, |this, cx| {
                match result {
                    Ok(response) => {
                        this.open_safe_external_url(
                            &response.authorization_url,
                            "Finish Google consent in the browser; Macro will reopen automatically"
                                .to_owned(),
                            "Google authorization",
                            cx,
                        );
                    }
                    Err(error) => {
                        this.session_notice = Some(format!("Could not connect Gmail: {error}"));
                    }
                }
                cx.notify();
            })?;
            anyhow::Ok(())
        })
        .detach();
    }

    fn complete_email_link(&mut self, link_id: String, force_share: bool, cx: &mut Context<Self>) {
        let api = self.api.clone();
        self.session_notice = Some(if force_share {
            "Confirming shared inbox access…".into()
        } else {
            "Finishing inbox connection…".into()
        });
        cx.spawn(async move |this, cx| {
            let result = api.init_email_link(Some(&link_id), force_share).await;
            this.update(cx, |this, cx| {
                match result {
                    Ok(_) => {
                        this.session_notice = Some("Inbox connected".into());
                        this.load_email_links(true, cx);
                        this.load_email_labels(false, cx);
                        this.load_inbox(false, cx);
                        this.refresh_loaded_mail_views(cx);
                    }
                    Err(error)
                        if error
                            .downcast_ref::<MacroHttpError>()
                            .and_then(|error| error.code.as_deref())
                            == Some("ALREADY_INITIALIZED") =>
                    {
                        this.session_notice = Some("Inbox is already connected".into());
                        this.load_email_links(true, cx);
                    }
                    Err(error)
                        if error
                            .downcast_ref::<MacroHttpError>()
                            .and_then(|error| error.code.as_deref())
                            == Some("NO_GMAIL_GRANT") =>
                    {
                        this.session_notice = Some(
                            "Gmail access was not granted. Reconnect the inbox and approve the requested Google permissions."
                                .into(),
                        );
                        this.load_email_links(true, cx);
                    }
                    Err(error) => {
                        let conflict = error
                            .downcast_ref::<MacroHttpError>()
                            .and_then(MacroHttpError::shared_inbox_conflict);
                        if let Some(conflict) = conflict
                            && !force_share
                        {
                            this.open_mutation_dialog(
                                MutationDialog::new(
                                    "Share connected inbox",
                                    "Share inbox",
                                    MutationKind::ForceShareEmailLink {
                                        link_id: link_id.clone(),
                                    },
                                    vec![Self::mutation_field(
                                        "Type SHARE to confirm",
                                        "",
                                        false,
                                    )],
                                ),
                                cx,
                            );
                            this.session_notice = Some(format!(
                                "{} is connected by {}. Confirm to use Macro's shared-inbox access.",
                                conflict.email_address, conflict.existing_owner_email
                            ));
                        } else {
                            this.session_notice = Some(format!(
                                "Inbox connection could not be completed: {error}"
                            ));
                        }
                    }
                }
                cx.notify();
            })?;
            anyhow::Ok(())
        })
        .detach();
    }

