    fn open_billing_checkout(&mut self, cx: &mut Context<Self>) {
        let api = self.api.clone();
        let app_url = match self.environment.as_str() {
            "local" => "http://localhost:3000/app",
            "dev" => "https://dev.macro.com/app",
            _ => "https://macro.com/app",
        };
        let request = CreateCheckoutSessionRequest {
            cancel_url: format!("{app_url}?subscriptionCancel=true"),
            discount: None,
            success_url: format!("{app_url}/?subscriptionSuccess=true"),
        };
        self.session_notice = Some("Preparing secure checkout…".into());
        cx.spawn(async move |this, cx| {
            let result = api.create_checkout_session(&request).await;
            this.update(cx, |this, cx| {
                match result {
                    Ok(response) => {
                        this.open_safe_external_url(
                            &response.url,
                            "Checkout opened in your browser",
                            "Billing checkout",
                            cx,
                        );
                    }
                    Err(error) => {
                        this.session_notice = Some(format!("Could not start checkout: {error}"));
                    }
                }
                cx.notify();
            })?;
            anyhow::Ok(())
        })
        .detach();
    }

    fn open_billing_portal(&mut self, cx: &mut Context<Self>) {
        let api = self.api.clone();
        let return_url = match self.environment.as_str() {
            "local" => "http://localhost:3000/app",
            "dev" => "https://dev.macro.com/app",
            _ => "https://macro.com/app",
        }
        .to_owned();
        self.session_notice = Some("Preparing billing portal…".into());
        cx.spawn(async move |this, cx| {
            let result = api
                .create_portal_session(&CreatePortalSessionRequest { return_url })
                .await;
            this.update(cx, |this, cx| {
                match result {
                    Ok(response) => {
                        this.open_safe_external_url(
                            &response.url,
                            "Billing portal opened in your browser",
                            "Billing portal",
                            cx,
                        );
                    }
                    Err(error) => {
                        this.session_notice =
                            Some(format!("Could not open billing portal: {error}"));
                    }
                }
                cx.notify();
            })?;
            anyhow::Ok(())
        })
        .detach();
    }

    fn render_auth_input(
        &self,
        field: AuthField,
        label: &'static str,
        placeholder: &'static str,
        cx: &mut Context<Self>,
    ) -> AnyElement {
        let colors = macro_colors(cx);
        let value = match field {
            AuthField::Email => self.auth_email.clone(),
            AuthField::Code => self.auth_code.clone(),
        };
        let active = self.active_auth_field == field;
        v_flex()
            .gap_2()
            .child(
                div()
                    .text_xs()
                    .font_weight(FontWeight::MEDIUM)
                    .text_color(colors.ink_muted)
                    .child(label),
            )
            .child(
                h_flex()
                    .id(match field {
                        AuthField::Email => "auth-email",
                        AuthField::Code => "auth-code",
                    })
                    .h(px(42.0))
                    .px_3()
                    .rounded_lg()
                    .border_1()
                    .border_color(if active { colors.accent } else { colors.border })
                    .bg(colors.surface)
                    .cursor_text()
                    .on_click(cx.listener(move |this, _, window, cx| {
                        this.active_auth_field = field;
                        window.focus(&this.focus_handle, cx);
                        cx.notify();
                    }))
                    .child(
                        div()
                            .text_sm()
                            .text_color(if value.is_empty() {
                                colors.ink_placeholder
                            } else {
                                colors.ink
                            })
                            .child(if value.is_empty() {
                                placeholder.to_owned()
                            } else {
                                value
                            }),
                    ),
            )
            .into_any_element()
    }

    fn render_auth(&self, cx: &mut Context<Self>) -> AnyElement {
        let colors = macro_colors(cx);
        let show_code = matches!(
            self.session,
            SessionState::AwaitingCode { .. } | SessionState::Verifying { .. }
        ) || !self.auth_code.is_empty();
        let is_sso = matches!(self.session, SessionState::SsoRequired { .. });
        let busy = self.session.is_busy();
        let pending_email = match &self.session {
            SessionState::AwaitingCode { email } | SessionState::Verifying { email } => {
                email.as_str()
            }
            _ => self.auth_email.as_str(),
        };
        let title = if show_code {
            "Check your email"
        } else {
            "Sign in to Macro"
        };
        let description = if show_code {
            "Enter the one-time code to connect this native client."
        } else {
            "Use your Macro account to load your real inbox and channels."
        };
        let primary_label = match self.session {
            SessionState::Restoring => "Restoring session…",
            SessionState::SendingCode => "Sending code…",
            SessionState::Verifying { .. } => "Signing in…",
            _ if show_code => "Verify and continue",
            _ => "Send sign-in code",
        };
        let saved_accounts = self
            .saved_accounts
            .iter()
            .filter(|account| account.environment == self.environment)
            .cloned()
            .collect::<Vec<_>>();

        let card = v_flex()
            .w(px(440.0))
            .p_6()
            .gap_5()
            .rounded_xl()
            .border_1()
            .border_color(colors.border)
            .bg(colors.panel)
            .shadow_lg()
            .child(
                h_flex()
                    .gap_3()
                    .child(
                        div()
                            .w(px(36.0))
                            .h(px(36.0))
                            .rounded_lg()
                            .bg(colors.accent_background)
                            .flex()
                            .items_center()
                            .justify_center()
                            .font_weight(FontWeight::BOLD)
                            .text_color(colors.ink)
                            .child("M"),
                    )
                    .child(
                        v_flex()
                            .gap_1()
                            .child(
                                div()
                                    .text_xl()
                                    .font_weight(FontWeight::SEMIBOLD)
                                    .text_color(colors.ink)
                                    .child(title),
                            )
                            .child(
                                div()
                                    .text_sm()
                                    .text_color(colors.ink_subtle)
                                    .child(description),
                            ),
                    ),
            )
            .when(!show_code && !is_sso, |this| {
                this.child(self.render_auth_input(AuthField::Email, "Email", "you@company.com", cx))
            })
            .when(show_code, |this| {
                this.child(
                    div()
                        .text_xs()
                        .text_color(colors.ink_subtle)
                        .child(format!("Code sent to {pending_email}")),
                )
                .child(self.render_auth_input(
                    AuthField::Code,
                    "One-time code",
                    "Enter code",
                    cx,
                ))
            })
            .when_some(self.session_notice.clone(), |this, notice| {
                this.child(
                    div()
                        .id("auth-session-notice")
                        .role(Role::Status)
                        .aria_label(notice.clone())
                        .p_3()
                        .rounded_lg()
                        .bg(colors.surface)
                        .text_xs()
                        .text_color(colors.ink_muted)
                        .child(notice),
                )
            })
            .when_some(
                match &self.session {
                    SessionState::Failed { message } => Some(message.clone()),
                    _ => None,
                },
                |this, error| {
                    this.child(
                        div()
                            .p_3()
                            .rounded_lg()
                            .bg(colors.failure.opacity(0.12))
                            .text_xs()
                            .text_color(colors.failure)
                            .child(error),
                    )
                },
            )
            .when(!is_sso, |this| {
                this.child(
                    macro_button("auth-submit", primary_label)
                        .style(ButtonStyle::Tinted(TintColor::Accent))
                        .size(ButtonSize::Large)
                        .full_width()
                        .disabled(busy)
                        .on_click(cx.listener(|this, _, _, cx| {
                            this.submit_auth(cx);
                        })),
                )
            })
            .when(show_code && !busy, |this| {
                this.child(
                    macro_button("auth-back", "Use a different email")
                        .style(ButtonStyle::Transparent)
                        .size(ButtonSize::Medium)
                        .full_width()
                        .on_click(cx.listener(|this, _, _, cx| {
                            this.auth_code.clear();
                            this.active_auth_field = AuthField::Email;
                            this.session = SessionState::SignedOut;
                            cx.notify();
                        })),
                )
            })
            .when(
                !saved_accounts.is_empty() && !show_code && !is_sso,
                |this| {
                    this.child(
                        v_flex()
                            .gap_2()
                            .child(
                                div()
                                    .text_xs()
                                    .text_color(colors.ink_subtle)
                                    .child("Or continue with a saved account"),
                            )
                            .children(saved_accounts.into_iter().map(|account| {
                                let account_id = account.user_id.clone();
                                h_flex()
                                    .id(format!("auth-saved-account-{account_id}"))
                                    .px_3()
                                    .py_2()
                                    .gap_2()
                                    .rounded_md()
                                    .border_1()
                                    .border_color(colors.border)
                                    .cursor_pointer()
                                    .role(Role::Button)
                                    .aria_label_from_id()
                                    .focusable()
                                    .tab_stop(true)
                                    .focus_visible(|this| this.bg(colors.hover))
                                    .hover(|this| this.bg(colors.hover))
                                    .on_click(cx.listener(move |this, _, window, cx| {
                                        this.switch_account(account_id.clone(), window, cx)
                                    }))
                                    .child(Avatar::new(account.email.clone()).size(22.0))
                                    .child(
                                        div()
                                            .text_sm()
                                            .text_color(colors.ink)
                                            .child(account.email.clone()),
                                    )
                            })),
                    )
                },
            )
            .child(
                div()
                    .text_xs()
                    .text_color(colors.ink_disabled)
                    .child(format!("Environment: {}", self.environment)),
            );

        let card = match &self.session {
            SessionState::SsoRequired { email, url } => {
                let url = url.clone();
                card.child(
                    v_flex()
                        .gap_3()
                        .child(
                            div()
                                .text_sm()
                                .text_color(colors.warning)
                                .child(format!("{email} must sign in through your organization.")),
                        )
                        .child(
                            div()
                                .text_xs()
                                .text_color(colors.ink_subtle)
                                .child(
                                    "Complete sign-in in your browser. Macro will return securely to this app and finish automatically.",
                                ),
                        )
                        .child(
                            macro_button("open-sso", "Open organization sign-in")
                                .style(ButtonStyle::Tinted(TintColor::Accent))
                                .size(ButtonSize::Large)
                                .full_width()
                                .on_click(cx.listener(move |this, _, _, cx| {
                                    this.open_safe_external_url(
                                        &url,
                                        "Organization sign-in opened",
                                        "Organization sign-in",
                                        cx,
                                    );
                                })),
                        )
                        .child(
                            macro_button("sso-back", "Use a different email")
                                .style(ButtonStyle::Transparent)
                                .size(ButtonSize::Medium)
                                .full_width()
                                .on_click(cx.listener(|this, _, _, cx| {
                                    this.session = SessionState::SignedOut;
                                    this.active_auth_field = AuthField::Email;
                                    cx.notify();
                                })),
                        ),
                )
            }
            _ => card,
        };

        div()
            .size_full()
            .flex()
            .items_center()
            .justify_center()
            .bg(colors.background)
            .child(card)
            .into_any_element()
    }

    fn toggle_sidebar(&mut self, _: &ToggleSidebar, _window: &mut Window, cx: &mut Context<Self>) {
        self.layout_state.sidebar_expanded = !self.layout_state.sidebar_expanded;
        self.persist_preferences(cx);
        cx.notify();
    }

    fn undo_last_triage(&mut self, cx: &mut Context<Self>) {
        let Some(action) = self.pending_undo.take() else {
            return;
        };
        self.session_notice = Some("Undoing…".into());
        let api = self.api.clone();
        cx.spawn(async move |this, cx| {
            let (result, targets) = match action.clone() {
                UndoAction::UndoEmailSend {
                    draft_id,
                    link_id,
                    dialog,
                } => {
                    let mut targets = vec![ReconcileTarget::Inbox];
                    if let MutationKind::ReplyEmail { thread_id, .. } = &dialog.kind {
                        targets.push(ReconcileTarget::Entity {
                            entity_type: EntityType::EmailThread,
                            entity_id: thread_id.clone(),
                        });
                    }
                    (
                        unschedule_email_with_retry(&api, &draft_id, link_id.as_deref(), cx).await,
                        targets,
                    )
                }
                UndoAction::UnarchiveEmail { thread_id, link_id } => (
                    api.set_thread_archived_for_link(&thread_id, false, link_id.as_deref())
                        .await
                        .map(|_| ()),
                    vec![
                        ReconcileTarget::Inbox,
                        ReconcileTarget::Entity {
                            entity_type: EntityType::EmailThread,
                            entity_id: thread_id,
                        },
                    ],
                ),
                UndoAction::MarkTaskIncomplete { document_id } => (
                    api.set_task_completed(&document_id, false).await,
                    vec![
                        ReconcileTarget::Inbox,
                        ReconcileTarget::Entity {
                            entity_type: EntityType::Document,
                            entity_id: document_id,
                        },
                    ],
                ),
                UndoAction::MarkEntitiesUndone {
                    email_targets,
                    notification_ids,
                    reminder_ids,
                } => {
                    let mut failures = Vec::new();
                    for (email_id, link_id) in email_targets {
                        if let Err(error) = api
                            .set_thread_archived_for_link(&email_id, false, link_id.as_deref())
                            .await
                        {
                            failures.push(format!("email {email_id}: {error}"));
                        }
                    }
                    if !notification_ids.is_empty()
                        && let Err(error) =
                            api.mark_notifications_done(notification_ids, false).await
                    {
                        failures.push(format!("notifications: {error}"));
                    }
                    for reminder_id in reminder_ids {
                        if let Err(error) = api
                            .update_reminder(
                                &reminder_id,
                                &UpdateReminderRequest {
                                    completed: Some(false),
                                    ..Default::default()
                                },
                            )
                            .await
                        {
                            failures.push(format!("reminder {reminder_id}: {error}"));
                        }
                    }
                    let result = if failures.is_empty() {
                        Ok(())
                    } else {
                        Err(anyhow::anyhow!(failures.join(" · ")))
                    };
                    (
                        result,
                        vec![ReconcileTarget::Inbox, ReconcileTarget::Notifications],
                    )
                }
                UndoAction::DeleteEmailFilter { filter_id, link_id } => (
                    api.delete_email_filter(&filter_id, link_id.as_deref())
                        .await,
                    vec![ReconcileTarget::Inbox],
                ),
                UndoAction::UnblockEmailSender {
                    email_address,
                    link_id,
                } => (
                    api.unblock_email_sender(&email_address, link_id.as_deref())
                        .await,
                    vec![ReconcileTarget::Inbox],
                ),
                UndoAction::RestoreDocument { document_id } => (
                    api.restore_document(&document_id).await.map(|_| ()),
                    vec![ReconcileTarget::Inbox],
                ),
                UndoAction::RestoreProject { project_id } => (
                    api.restore_project(&project_id).await,
                    vec![ReconcileTarget::Inbox],
                ),
            };
            this.update(cx, |this, cx| {
                match result {
                    Ok(()) => {
                        if let UndoAction::UndoEmailSend {
                            draft_id,
                            link_id,
                            dialog,
                        } = action.clone()
                        {
                            let mut dialog = *dialog;
                            dialog.busy = false;
                            dialog.error = None;
                            dialog.email_draft_id = Some(draft_id);
                            dialog.email_link_id = link_id;
                            dialog.email_autosave_in_flight = false;
                            dialog.email_autosave_pending = false;
                            dialog.email_autosave_error = None;
                            dialog.email_last_saved_fingerprint = None;
                            this.open_mutation_dialog(dialog, cx);
                            this.session_notice = Some("Send cancelled · draft restored".into());
                        } else {
                            this.session_notice = Some("Change undone".into());
                        }
                        if matches!(&action, UndoAction::RestoreProject { .. }) {
                            this.workspace.projects = DataState::Idle;
                            this.load_projects(true, cx);
                        }
                        if matches!(&action, UndoAction::MarkEntitiesUndone { .. }) {
                            this.load_reminders(false, cx);
                            this.load_notifications(false, cx);
                        }
                        this.workspace.recently_deleted = DataState::Idle;
                        this.load_recently_deleted(true, cx);
                        this.apply_reconcile_plan(ReconcilePlan::new(targets), cx);
                    }
                    Err(error) => {
                        this.pending_undo = Some(action);
                        this.session_notice = Some(format!("Undo failed: {error}"));
                    }
                }
                cx.notify();
            })?;
            anyhow::Ok(())
        })
        .detach();
        cx.notify();
    }

    fn update_reminder_state(
        &mut self,
        reminder_id: String,
        request: UpdateReminderRequest,
        success: &'static str,
        cx: &mut Context<Self>,
    ) {
        self.session_notice = Some("Updating reminder…".into());
        let api = self.api.clone();
        cx.spawn(async move |this, cx| {
            let result = api.update_reminder(&reminder_id, &request).await;
            this.update(cx, |this, cx| {
                match result {
                    Ok(_) => {
                        this.session_notice = Some(success.into());
                        this.load_reminders(false, cx);
                        this.load_inbox(false, cx);
                    }
                    Err(error) => {
                        this.session_notice = Some(format!("Reminder update failed: {error}"));
                    }
                }
                cx.notify();
            })?;
            anyhow::Ok(())
        })
        .detach();
        cx.notify();
    }

    fn complete_reminders(&mut self, reminder_ids: Vec<String>, cx: &mut Context<Self>) {
        if reminder_ids.is_empty() {
            return;
        }
        let requested_count = reminder_ids.len();
        self.session_notice = Some(format!("Completing {requested_count} reminder(s)…"));
        let api = self.api.clone();
        cx.spawn(async move |this, cx| {
            let mut completed = Vec::new();
            let mut failures = Vec::new();
            for reminder_id in reminder_ids {
                match api
                    .update_reminder(
                        &reminder_id,
                        &UpdateReminderRequest {
                            completed: Some(true),
                            ..Default::default()
                        },
                    )
                    .await
                {
                    Ok(_) => completed.push(reminder_id),
                    Err(error) => failures.push(error.to_string()),
                }
            }
            this.update(cx, |this, cx| {
                if !completed.is_empty() {
                    this.pending_undo = Some(UndoAction::MarkEntitiesUndone {
                        email_targets: Vec::new(),
                        notification_ids: Vec::new(),
                        reminder_ids: completed.clone(),
                    });
                }
                this.session_notice = Some(if failures.is_empty() {
                    format!("Completed {} reminder(s)", completed.len())
                } else {
                    format!(
                        "Completed {} of {requested_count} reminder(s) · {} failed",
                        completed.len(),
                        failures.len()
                    )
                });
                this.load_reminders(false, cx);
                this.load_inbox(false, cx);
                cx.notify();
            })?;
            anyhow::Ok(())
        })
        .detach();
        cx.notify();
    }

    fn open_command_palette(
        &mut self,
        _: &OpenCommandPalette,
        _window: &mut Window,
        cx: &mut Context<Self>,
    ) {
        self.command_palette_open = true;
        self.command_palette_query.clear();
        self.command_palette_selected = 0;
        cx.notify();
    }

    fn close_command_palette(
        &mut self,
        _: &CloseCommandPalette,
        _window: &mut Window,
        cx: &mut Context<Self>,
    ) {
        self.command_palette_open = false;
        self.command_palette_query.clear();
        self.command_palette_selected = 0;
        if !self
            .mutation_dialog
            .as_ref()
            .is_some_and(|dialog| dialog.busy)
        {
            self.dismiss_mutation_dialog(cx);
        }
        cx.notify();
    }

    fn execute_palette_command(&mut self, command: PaletteCommand, cx: &mut Context<Self>) {
        self.command_palette_open = false;
        self.command_palette_query.clear();
        self.command_palette_selected = 0;
        match command.kind {
            PaletteCommandKind::Section(section) => self.navigate_to(section, cx),
            PaletteCommandKind::ToggleSidebar => {
                self.layout_state.sidebar_expanded = !self.layout_state.sidebar_expanded;
                self.persist_preferences(cx);
            }
            PaletteCommandKind::NavigateBack => self.navigate_back(cx),
            PaletteCommandKind::NavigateForward => self.navigate_forward(cx),
            PaletteCommandKind::NewDocument => self.open_new_document(cx),
            PaletteCommandKind::CloseActiveTab => {
                if let Some(tab_id) = self
                    .layout_state
                    .tabs
                    .iter()
                    .find(|tab| tab.is_active)
                    .map(|tab| tab.entity_id.clone())
                {
                    self.close_tab(&tab_id, cx);
                }
            }
            PaletteCommandKind::ReopenClosedTab => {
                if let Some(entity) = self.closed_entities.pop() {
                    self.open_entity(entity, cx);
                }
            }
            PaletteCommandKind::SelectNextTab => self.cycle_entity_tab(1, cx),
            PaletteCommandKind::SelectPreviousTab => self.cycle_entity_tab(-1, cx),
            PaletteCommandKind::ToggleDetailFullscreen => {
                if self.active_entity().is_some() {
                    self.detail_fullscreen = !self.detail_fullscreen;
                    self.persist_preferences(cx);
                }
            }
            PaletteCommandKind::CopyTaskBranchName => self.copy_active_task_branch_name_from_ui(cx),
        }
        cx.notify();
    }

    fn command_palette_key_down(&mut self, event: &KeyDownEvent, cx: &mut Context<Self>) {
        let key = event.keystroke.key.as_str();
        let commands = filtered_palette_commands(
            &self.command_palette_query,
            self.active_entity().is_some(),
            !self.closed_entities.is_empty(),
        );
        match key {
            "escape" => {
                self.command_palette_open = false;
                self.command_palette_query.clear();
                self.command_palette_selected = 0;
            }
            "up" => {
                if !commands.is_empty() {
                    self.command_palette_selected = if self.command_palette_selected == 0 {
                        commands.len() - 1
                    } else {
                        self.command_palette_selected - 1
                    };
                }
            }
            "down" => {
                if !commands.is_empty() {
                    self.command_palette_selected =
                        (self.command_palette_selected + 1) % commands.len();
                }
            }
            "enter" => {
                if let Some(command) = commands.get(self.command_palette_selected).copied() {
                    self.execute_palette_command(command, cx);
                }
            }
            "backspace" => {
                self.command_palette_query.pop();
                self.command_palette_selected = 0;
            }
            "v" if event.keystroke.modifiers.secondary() => {
                if let Some(text) = cx.read_from_clipboard().and_then(|item| item.text()) {
                    self.command_palette_query.push_str(&text);
                    self.command_palette_selected = 0;
                }
            }
            _ if !event.keystroke.modifiers.control
                && !event.keystroke.modifiers.alt
                && !event.keystroke.modifiers.platform
                && !event.keystroke.modifiers.function =>
            {
                if let Some(character) = &event.keystroke.key_char {
                    self.command_palette_query.push_str(character);
                    self.command_palette_selected = 0;
                }
            }
            _ => return,
        }
        cx.stop_propagation();
        cx.notify();
    }

    fn new_document(&mut self, _: &NewDocument, _window: &mut Window, cx: &mut Context<Self>) {
        self.open_new_document(cx);
    }

    fn quit(&mut self, _: &Quit, _window: &mut Window, cx: &mut Context<Self>) {
        cx.quit();
    }

    fn render_command_palette(&self, cx: &mut Context<Self>) -> AnyElement {
        let colors = macro_colors(cx);
        let commands = filtered_palette_commands(
            &self.command_palette_query,
            self.active_entity().is_some(),
            !self.closed_entities.is_empty(),
        );
        let commands_empty = commands.is_empty();
        let query = self.command_palette_query.clone();

        div()
            .id("command-palette-backdrop")
            .absolute()
            .inset_0()
            .flex()
            .items_start()
            .justify_center()
            .pt_20()
            .bg(hsla(0.0, 0.0, 0.0, 0.45))
            .on_click(|_, window, cx| {
                window.dispatch_action(CloseCommandPalette.boxed_clone(), cx);
            })
            .child(
                v_flex()
                    .id("command-palette")
                    .w(px(520.0))
                    .max_h(px(520.0))
                    .rounded_lg()
                    .border_1()
                    .border_color(colors.border)
                    .bg(colors.panel)
                    .shadow_lg()
                    .overflow_hidden()
                    .on_click(|_, _, cx| cx.stop_propagation())
                    .child(
                        h_flex()
                            .h(px(48.0))
                            .px_4()
                            .gap_2()
                            .border_b_1()
                            .border_color(colors.border)
                            .child(div().text_color(colors.ink_subtle).child("⌘K"))
                            .child(
                                div()
                                    .flex_1()
                                    .text_sm()
                                    .text_color(if query.is_empty() {
                                        colors.ink_placeholder
                                    } else {
                                        colors.ink
                                    })
                                    .child(if query.is_empty() {
                                        "Type a command or workspace area".to_owned()
                                    } else {
                                        query
                                    }),
                            )
                            .child(
                                div()
                                    .text_xs()
                                    .text_color(colors.ink_disabled)
                                    .child("↑↓ · Enter · Esc"),
                            ),
                    )
                    .child(
                        v_flex()
                            .id("command-palette-items")
                            .p_2()
                            .gap_1()
                            .overflow_y_scroll()
                            .when(commands_empty, |this| {
                                this.child(
                                    div()
                                        .px_3()
                                        .py_4()
                                        .text_sm()
                                        .text_color(colors.ink_muted)
                                        .child("No matching commands"),
                                )
                            })
                            .children(commands.into_iter().enumerate().map(|(index, command)| {
                                let icon = match command.kind {
                                    PaletteCommandKind::Section(section) => section.icon(),
                                    PaletteCommandKind::NewDocument => EntityType::Document,
                                    PaletteCommandKind::CopyTaskBranchName => EntityType::Document,
                                    PaletteCommandKind::ToggleSidebar
                                    | PaletteCommandKind::NavigateBack
                                    | PaletteCommandKind::NavigateForward
                                    | PaletteCommandKind::CloseActiveTab
                                    | PaletteCommandKind::ReopenClosedTab
                                    | PaletteCommandKind::SelectNextTab
                                    | PaletteCommandKind::SelectPreviousTab
                                    | PaletteCommandKind::ToggleDetailFullscreen => {
                                        EntityType::ForeignEntity
                                    }
                                };
                                h_flex()
                                    .id(("command-palette-item", index))
                                    .h(px(36.0))
                                    .px_3()
                                    .gap_3()
                                    .rounded_md()
                                    .bg(if index == self.command_palette_selected {
                                        colors.selected
                                    } else {
                                        hsla(0.0, 0.0, 0.0, 0.0)
                                    })
                                    .cursor_pointer()
                                    .role(Role::Button)
                                    .aria_label_from_id()
                                    .focusable()
                                    .tab_stop(true)
                                    .focus_visible(|this| this.bg(colors.hover))
                                    .hover(|this| this.bg(colors.hover))
                                    .on_click(cx.listener(move |this, _, _, cx| {
                                        this.execute_palette_command(command, cx)
                                    }))
                                    .child(EntityIcon::new(icon).size(16.0))
                                    .child(
                                        div()
                                            .flex_1()
                                            .text_sm()
                                            .text_color(colors.ink)
                                            .child(command.label),
                                    )
                                    .when(!command.shortcut.is_empty(), |this| {
                                        this.child(
                                            div()
                                                .text_xs()
                                                .text_color(colors.ink_disabled)
                                                .child(command.shortcut),
                                        )
                                    })
                            })),
                    ),
            )
            .into_any_element()
    }

    fn render_paywall(&self, state: &PaywallState, cx: &mut Context<Self>) -> AnyElement {
        let colors = macro_colors(cx);
        let (current_user_id, can_manage_subscription, has_paid_access) = match &self.session {
            SessionState::Ready { user } => (
                user.user_id.as_str(),
                user.permissions
                    .iter()
                    .any(|permission| permission == "write:stripe_subscription"),
                user.permissions
                    .iter()
                    .any(|permission| permission == "read:professional_features"),
            ),
            _ => ("", false, false),
        };
        let billing_owner = self
            .workspace
            .team
            .loaded()
            .and_then(|team| team.as_ref())
            .is_none_or(|team| team.team.owner_id == current_user_id);
        let can_upgrade = can_manage_subscription && billing_owner;
        let cta_label = if has_paid_access {
            "Manage subscription"
        } else {
            "Upgrade now"
        };

        div()
            .id("paywall-backdrop")
            .absolute()
            .inset_0()
            .flex()
            .items_center()
            .justify_center()
            .bg(hsla(0.0, 0.0, 0.0, 0.55))
            .on_click(cx.listener(|this, _, _, cx| {
                this.paywall = None;
                cx.notify();
            }))
            .child(
                v_flex()
                    .id("paywall-dialog")
                    .w(px(680.0))
                    .rounded_lg()
                    .border_1()
                    .border_color(colors.border)
                    .bg(colors.panel)
                    .shadow_lg()
                    .overflow_hidden()
                    .on_click(|_, _, cx| cx.stop_propagation())
                    .child(
                        h_flex()
                            .p_6()
                            .gap_6()
                            .items_start()
                            .child(
                                v_flex()
                                    .flex_1()
                                    .gap_2()
                                    .child(
                                        div()
                                            .text_xl()
                                            .font_weight(FontWeight::SEMIBOLD)
                                            .text_color(colors.ink)
                                            .child(state.key.title()),
                                    )
                                    .child(
                                        div()
                                            .text_sm()
                                            .text_color(colors.ink_muted)
                                            .child(state.key.description()),
                                    )
                                    .when_some(state.server_message.clone(), |this, message| {
                                        this.child(
                                            div()
                                                .mt_2()
                                                .text_xs()
                                                .text_color(colors.ink_subtle)
                                                .child(message),
                                        )
                                    }),
                            )
                            .child(
                                v_flex()
                                    .w(px(300.0))
                                    .p_4()
                                    .gap_3()
                                    .rounded_md()
                                    .bg(colors.surface)
                                    .child(
                                        div()
                                            .text_sm()
                                            .font_weight(FontWeight::SEMIBOLD)
                                            .text_color(colors.ink)
                                            .child("Premium features"),
                                    )
                                    .children(
                                        [
                                            "All agents and models",
                                            "No watermark and AI projections",
                                            "Multiple email inboxes and calls",
                                            "Teams and 1 TB storage",
                                        ]
                                        .into_iter()
                                        .map(|label| {
                                            h_flex()
                                                .gap_2()
                                                .child(
                                                    div()
                                                        .size(px(7.0))
                                                        .rounded_full()
                                                        .bg(colors.success),
                                                )
                                                .child(
                                                    div()
                                                        .text_xs()
                                                        .text_color(colors.ink_muted)
                                                        .child(label),
                                                )
                                        }),
                                    ),
                            ),
                    )
                    .child(
                        h_flex()
                            .px_6()
                            .py_4()
                            .justify_between()
                            .border_t_1()
                            .border_color(colors.border)
                            .child(div().text_xs().text_color(colors.ink_subtle).child(
                                if billing_owner {
                                    "$40 per seat / per month"
                                } else {
                                    "Subscription changes are managed by your workspace owner."
                                },
                            ))
                            .child(
                                h_flex()
                                    .gap_2()
                                    .child(
                                        macro_button("dismiss-paywall", "Dismiss")
                                            .style(ButtonStyle::Transparent)
                                            .size(ButtonSize::Medium)
                                            .on_click(cx.listener(|this, _, _, cx| {
                                                this.paywall = None;
                                                cx.notify();
                                            })),
                                    )
                                    .when(can_upgrade, |this| {
                                        this.child(
                                            macro_button("upgrade-from-paywall", cta_label)
                                                .style(ButtonStyle::Tinted(TintColor::Accent))
                                                .size(ButtonSize::Medium)
                                                .on_click(cx.listener(move |this, _, _, cx| {
                                                    this.paywall = None;
                                                    if has_paid_access {
                                                        this.open_billing_portal(cx)
                                                    } else {
                                                        this.open_billing_checkout(cx)
                                                    }
                                                })),
                                        )
                                    }),
                            ),
                    ),
            )
            .into_any_element()
    }

    fn render_snippet_typeahead(
        &self,
        target: SnippetInsertionTarget,
        context: &DocumentSnippetContext,
        source_document_id: Option<&str>,
        cx: &mut Context<Self>,
    ) -> AnyElement {
        let colors = macro_colors(cx);
        let snapshot = self.workspace.snippets.snapshot();
        let candidates = snippet_candidates(snapshot.items, &context.query, source_document_id);
        let selected_index = self
            .snippet_typeahead_selections
            .get(&target)
            .filter(|selection| selection.context == *context)
            .map(|selection| selection.selected_index)
            .unwrap_or(0)
            .min(candidates.len().saturating_sub(1));
        let inserting = self.snippet_insertions.contains(&target);
        v_flex()
            .id(match &target {
                SnippetInsertionTarget::Document(document_id) => {
                    format!("document-snippet-menu-{document_id}")
                }
                SnippetInsertionTarget::Mutation { generation } => {
                    format!("mutation-snippet-menu-{generation}")
                }
            })
            .max_w(px(440.0))
            .p_1()
            .gap_0p5()
            .rounded_md()
            .border_1()
            .border_color(colors.border)
            .bg(colors.panel)
            .shadow_md()
            .child(
                h_flex()
                    .px_2()
                    .py_1()
                    .gap_2()
                    .child(
                        div()
                            .flex_1()
                            .text_xs()
                            .font_weight(FontWeight::SEMIBOLD)
                            .text_color(colors.ink_subtle)
                            .child(if context.query.is_empty() {
                                "INSERT SNIPPET".to_owned()
                            } else {
                                format!("INSERT SNIPPET · {}", context.query)
                            }),
                    )
                    .child(
                        div()
                            .text_xs()
                            .text_color(colors.ink_disabled)
                            .child(if inserting {
                                "Inserting…"
                            } else {
                                "↑↓ Navigate · Enter insert · Esc close"
                            }),
                    ),
            )
            .child(match snapshot.status {
                LoadStatus::Idle | LoadStatus::Loading => div()
                    .px_2()
                    .py_2()
                    .text_xs()
                    .text_color(colors.ink_muted)
                    .child("Loading personal and team snippets…")
                    .into_any_element(),
                LoadStatus::Failed(error) => {
                    let retry_target = target.clone();
                    h_flex()
                        .px_2()
                        .py_2()
                        .gap_2()
                        .child(
                            div()
                                .flex_1()
                                .text_xs()
                                .text_color(colors.failure)
                                .child(format!("Snippets unavailable: {error}")),
                        )
                        .child(
                            macro_button(
                                match retry_target {
                                    SnippetInsertionTarget::Document(_) => {
                                        "retry-document-snippets"
                                    }
                                    SnippetInsertionTarget::Mutation { .. } => {
                                        "retry-mutation-snippets"
                                    }
                                },
                                "Retry",
                            )
                            .style(ButtonStyle::Transparent)
                            .size(ButtonSize::Compact)
                            .on_click(cx.listener(|this, _, _, cx| {
                                this.load_snippets(true, cx);
                                cx.stop_propagation();
                            })),
                        )
                        .into_any_element()
                }
                LoadStatus::Ready if candidates.is_empty() => div()
                    .px_2()
                    .py_2()
                    .text_xs()
                    .text_color(colors.ink_muted)
                    .child(if context.query.is_empty() {
                        "No snippets are available.".to_owned()
                    } else {
                        format!("No snippets match \"{}\".", context.query)
                    })
                    .into_any_element(),
                LoadStatus::Ready => {
                    v_flex()
                        .gap_0p5()
                        .children(candidates.into_iter().take(8).enumerate().map(
                            |(index, snippet)| {
                                let snippet_id = snippet.id.clone();
                                let snippet_name = snippet.title.clone();
                                let target = target.clone();
                                h_flex()
                                    .id(("snippet-typeahead-item", index))
                                    .px_2()
                                    .py_1()
                                    .gap_2()
                                    .rounded_sm()
                                    .when(index == selected_index, |this| this.bg(colors.selected))
                                    .when(!inserting, |this| {
                                        this.cursor_pointer()
                                            .role(Role::Button)
                                            .aria_label_from_id()
                                            .focusable()
                                            .tab_stop(true)
                                            .focus_visible(|this| this.bg(colors.hover))
                                    })
                                    .hover(|this| this.bg(colors.hover))
                                    .when(!inserting, |this| {
                                        this.on_click(cx.listener(move |this, _, window, cx| {
                                            match &target {
                                                SnippetInsertionTarget::Document(document_id) => {
                                                    this.insert_document_snippet(
                                                        document_id.clone(),
                                                        snippet_id.clone(),
                                                        snippet_name.clone(),
                                                        window,
                                                        cx,
                                                    );
                                                }
                                                SnippetInsertionTarget::Mutation { generation }
                                                    if *generation
                                                        == this.mutation_dialog_generation =>
                                                {
                                                    this.insert_mutation_snippet(
                                                        snippet_id.clone(),
                                                        snippet_name.clone(),
                                                        window,
                                                        cx,
                                                    );
                                                }
                                                SnippetInsertionTarget::Mutation { .. } => {}
                                            }
                                            cx.stop_propagation();
                                        }))
                                    })
                                    .child(
                                        EntityIcon::new(EntityType::Document)
                                            .size(14.0)
                                            .color(colors.ink_muted),
                                    )
                                    .child(
                                        v_flex()
                                            .min_w_0()
                                            .flex_1()
                                            .child(
                                                div()
                                                    .truncate()
                                                    .text_sm()
                                                    .text_color(colors.ink)
                                                    .child(snippet.title.clone()),
                                            )
                                            .when(!snippet.subtitle.is_empty(), |this| {
                                                this.child(
                                                    div()
                                                        .truncate()
                                                        .text_xs()
                                                        .text_color(colors.ink_muted)
                                                        .child(snippet.subtitle.clone()),
                                                )
                                            }),
                                    )
                            },
                        ))
                        .into_any_element()
                }
            })
            .into_any_element()
    }

