    fn render_mutation_text_field(
        &self,
        field_index: usize,
        dialog: &MutationDialog,
        window: &mut Window,
        cx: &mut Context<Self>,
    ) -> AnyElement {
        let Some(field) = dialog.fields.get(field_index) else {
            return div().into_any_element();
        };
        let Some(editor) = self.mutation_text_editor(field_index) else {
            return InputFrame::new()
                .active(dialog.active_field == field_index)
                .child(
                    Label::new(if field.value.is_empty() {
                        mutation_field_placeholder(field.label)
                    } else if field.sensitive {
                        "•".repeat(field.value.chars().count().min(32))
                    } else {
                        field.value.clone()
                    })
                    .size(LabelSize::Default)
                    .color(if field.value.is_empty() {
                        Color::Placeholder
                    } else {
                        Color::Default
                    }),
                )
                .into_any_element();
        };
        let active = editor.read(cx).is_focused(window);
        let focus = editor.read(cx).focus_handle(cx);
        let tab_focus = focus.clone().tab_index(0).tab_stop(true);
        let weak_editor = editor.downgrade();
        let value = if field.sensitive {
            "•".repeat(field.value.chars().count().min(32))
        } else {
            field.value.clone()
        };
        let placeholder = mutation_field_placeholder(field.label);
        InputFrame::new()
            .active(active)
            .child(
                div()
                    .id(("mutation-text-input", field_index))
                    .role(Role::TextInput)
                    .aria_label(field.label)
                    .aria_value(value)
                    .aria_placeholder(placeholder)
                    .track_focus(&tab_focus)
                    .on_a11y_action(AccessibleAction::SetValue, move |data, window, cx| {
                        let Some(gpui::accesskit::ActionData::Value(text)) = data else {
                            return;
                        };
                        let Some(editor) = weak_editor.upgrade() else {
                            return;
                        };
                        editor.update(cx, |editor, cx| {
                            editor.set_text(text.to_string(), window, cx)
                        });
                    })
                    .w_full()
                    .h(px(24.0))
                    .child(editor),
            )
            .into_any_element()
    }

    fn render_mutation_dropdown(
        &self,
        id: impl Into<ElementId>,
        field_index: usize,
        aria_label: &'static str,
        options: Vec<(String, String)>,
        window: &mut Window,
        cx: &mut Context<Self>,
    ) -> AnyElement {
        let value = self
            .mutation_dialog
            .as_ref()
            .and_then(|dialog| dialog.fields.get(field_index))
            .map(|field| field.value.clone())
            .unwrap_or_default();
        let display = options
            .iter()
            .find(|(option_value, _)| option_value.eq_ignore_ascii_case(&value))
            .map(|(_, label)| label.clone())
            .unwrap_or_else(|| {
                if value.trim().is_empty() {
                    "None".into()
                } else {
                    value.clone()
                }
            });
        let weak = cx.weak_entity();
        let selected_value = value.clone();
        let menu = ContextMenu::build(window, cx, move |mut menu, _, _| {
            for (option_value, label) in options {
                let weak = weak.clone();
                let selected = option_value.eq_ignore_ascii_case(&selected_value);
                menu = menu.toggleable_entry(
                    label,
                    selected,
                    IconPosition::Start,
                    None,
                    move |window, cx| {
                        _ = weak.update(cx, |this, cx| {
                            this.set_mutation_field_value(
                                field_index,
                                option_value.clone(),
                                window,
                                cx,
                            );
                        });
                    },
                );
            }
            menu
        });
        DropdownMenu::new(id, display, menu)
            .style(DropdownStyle::Outlined)
            .trigger_size(ButtonSize::Medium)
            .full_width(true)
            .tab_index(0isize)
            .aria_label(aria_label)
            .aria_value(value)
            .into_any_element()
    }

    fn render_task_assignee_dropdown(
        &self,
        field_index: usize,
        window: &mut Window,
        cx: &mut Context<Self>,
    ) -> AnyElement {
        let selected_ids = self
            .mutation_dialog
            .as_ref()
            .and_then(|dialog| dialog.fields.get(field_index))
            .map(|field| comma_separated_values(&field.value))
            .unwrap_or_default();
        let mut choices = self
            .workspace
            .user_names
            .loaded()
            .map(|names| {
                names
                    .keys()
                    .map(|user_id| (user_id.clone(), self.user_display_name(user_id, user_id)))
                    .collect::<Vec<_>>()
            })
            .unwrap_or_default();
        for user_id in &selected_ids {
            if !choices.iter().any(|(candidate, _)| candidate == user_id) {
                choices.push((
                    user_id.clone(),
                    self.user_display_name(user_id, "Unknown person"),
                ));
            }
        }
        choices.sort_by(|left, right| left.1.cmp(&right.1));
        choices.dedup_by(|left, right| left.0 == right.0);
        if choices.is_empty() {
            let dialog = self
                .mutation_dialog
                .as_ref()
                .expect("active mutation dialog");
            return self.render_mutation_text_field(field_index, dialog, window, cx);
        }

        let display = if selected_ids.is_empty() {
            "Unassigned".to_owned()
        } else {
            selected_ids
                .iter()
                .map(|user_id| self.user_display_name(user_id, "Unknown person"))
                .collect::<Vec<_>>()
                .join(", ")
        };
        let weak = cx.weak_entity();
        let selected = selected_ids.clone();
        let menu = ContextMenu::build(window, cx, move |mut menu, _, _| {
            let clear_weak = weak.clone();
            menu = menu
                .header("Assignees")
                .toggleable_entry(
                    "Unassigned",
                    selected.is_empty(),
                    IconPosition::Start,
                    None,
                    move |window, cx| {
                        _ = clear_weak.update(cx, |this, cx| {
                            this.set_mutation_field_value(field_index, String::new(), window, cx)
                        });
                    },
                )
                .separator();
            for (user_id, label) in choices {
                let weak = weak.clone();
                menu = menu.toggleable_entry(
                    label,
                    selected.iter().any(|selected| selected == &user_id),
                    IconPosition::Start,
                    None,
                    move |window, cx| {
                        _ = weak.update(cx, |this, cx| {
                            let mut assignees = this
                                .mutation_dialog
                                .as_ref()
                                .and_then(|dialog| dialog.fields.get(field_index))
                                .map(|field| comma_separated_values(&field.value))
                                .unwrap_or_default();
                            if let Some(index) =
                                assignees.iter().position(|assignee| assignee == &user_id)
                            {
                                assignees.remove(index);
                            } else {
                                assignees.push(user_id.clone());
                            }
                            this.set_mutation_field_value(
                                field_index,
                                assignees.join(", "),
                                window,
                                cx,
                            );
                        });
                    },
                );
            }
            menu
        });
        DropdownMenu::new("task-assignees", display.clone(), menu)
            .style(DropdownStyle::Outlined)
            .trigger_size(ButtonSize::Medium)
            .full_width(true)
            .tab_index(0)
            .aria_label("Assignees")
            .aria_value(display)
            .into_any_element()
    }

    fn render_comment_mention_dropdown(
        &self,
        field_index: usize,
        window: &mut Window,
        cx: &mut Context<Self>,
    ) -> AnyElement {
        let selected_ids = self
            .mutation_dialog
            .as_ref()
            .and_then(|dialog| dialog.fields.get(field_index))
            .map(|field| comma_separated_values(&field.value))
            .unwrap_or_default();
        let mut choices = self
            .workspace
            .user_names
            .loaded()
            .map(|names| {
                names
                    .keys()
                    .map(|user_id| (user_id.clone(), self.user_display_name(user_id, user_id)))
                    .collect::<Vec<_>>()
            })
            .unwrap_or_default();
        for user_id in &selected_ids {
            if !choices.iter().any(|(candidate, _)| candidate == user_id) {
                choices.push((
                    user_id.clone(),
                    self.user_display_name(user_id, "Unknown person"),
                ));
            }
        }
        choices.sort_by(|left, right| left.1.cmp(&right.1));
        choices.dedup_by(|left, right| left.0 == right.0);

        let display = if selected_ids.is_empty() {
            if choices.is_empty() {
                "People are still loading…".to_owned()
            } else {
                "No mentions".to_owned()
            }
        } else {
            selected_ids
                .iter()
                .map(|user_id| self.user_display_name(user_id, "Unknown person"))
                .collect::<Vec<_>>()
                .join(", ")
        };
        let weak = cx.weak_entity();
        let selected = selected_ids.clone();
        let menu = ContextMenu::build(window, cx, move |mut menu, _, _| {
            let clear_weak = weak.clone();
            menu = menu
                .header("Mention people")
                .toggleable_entry(
                    "No mentions",
                    selected.is_empty(),
                    IconPosition::Start,
                    None,
                    move |window, cx| {
                        _ = clear_weak.update(cx, |this, cx| {
                            this.set_mutation_field_value(field_index, String::new(), window, cx)
                        });
                    },
                )
                .separator();
            for (user_id, label) in choices {
                let weak = weak.clone();
                menu = menu.toggleable_entry(
                    label,
                    selected.iter().any(|selected| selected == &user_id),
                    IconPosition::Start,
                    None,
                    move |window, cx| {
                        _ = weak.update(cx, |this, cx| {
                            let mut mentions = this
                                .mutation_dialog
                                .as_ref()
                                .and_then(|dialog| dialog.fields.get(field_index))
                                .map(|field| comma_separated_values(&field.value))
                                .unwrap_or_default();
                            if let Some(index) =
                                mentions.iter().position(|mention| mention == &user_id)
                            {
                                mentions.remove(index);
                            } else {
                                mentions.push(user_id.clone());
                            }
                            this.set_mutation_field_value(
                                field_index,
                                mentions.join(", "),
                                window,
                                cx,
                            );
                        });
                    },
                );
            }
            menu
        });
        DropdownMenu::new("document-comment-mentions", display.clone(), menu)
            .style(DropdownStyle::Outlined)
            .trigger_size(ButtonSize::Medium)
            .full_width(true)
            .tab_index(0)
            .aria_label("Mention people")
            .aria_value(display)
            .into_any_element()
    }

    fn render_task_mutation_fields(
        &self,
        dialog: &MutationDialog,
        indexes: TaskComposerFieldIndexes,
        window: &mut Window,
        cx: &mut Context<Self>,
    ) -> AnyElement {
        let status_options = vec![
            ("not started".into(), "Not started".into()),
            ("in progress".into(), "In progress".into()),
            ("in review".into(), "In review".into()),
            ("completed".into(), "Completed".into()),
            ("canceled".into(), "Canceled".into()),
        ];
        let priority_options = vec![
            ("none".into(), "No priority".into()),
            ("low".into(), "Low".into()),
            ("medium".into(), "Medium".into()),
            ("high".into(), "High".into()),
            ("urgent".into(), "Urgent".into()),
        ];
        let effort_options = vec![
            ("none".into(), "No estimate".into()),
            ("small".into(), "Small".into()),
            ("medium".into(), "Medium".into()),
            ("large".into(), "Large".into()),
        ];
        let today = chrono::Local::now().date_naive();
        let date_options = vec![
            (String::new(), "No due date".into()),
            (today.to_string(), "Today".into()),
            (
                (today + chrono::Days::new(1)).to_string(),
                "Tomorrow".into(),
            ),
            (
                (today + chrono::Days::new(7)).to_string(),
                "Next week".into(),
            ),
        ];

        let mut content = v_flex().w_full().gap_4();
        if let Some(title_index) = indexes.title {
            content = content.child(
                FormField::new("Task title")
                    .required(true)
                    .child(self.render_mutation_text_field(title_index, dialog, window, cx)),
            );
        }
        if let Some(details_index) = indexes.details
            && let Some(editor) = self
                .mutation_editor
                .as_ref()
                .filter(|state| {
                    state.generation == self.mutation_dialog_generation
                        && state.field_index == details_index
                })
                .map(|state| state.editor.clone())
        {
            let snippet_context = editor.update(cx, |editor, cx| editor.snippet_context(cx));
            content = content.child(
                FormField::new("Description").child(
                    InputFrame::new()
                        .active(dialog.active_field == details_index)
                        .multiline(true)
                        .child(
                            v_flex()
                                .w_full()
                                .gap_1()
                                .child(self.render_mutation_format_toolbar(cx))
                                .when_some(snippet_context, |this, context| {
                                    this.child(self.render_snippet_typeahead(
                                        SnippetInsertionTarget::Mutation {
                                            generation: self.mutation_dialog_generation,
                                        },
                                        &context,
                                        None,
                                        cx,
                                    ))
                                })
                                .child(div().w_full().h(px(88.0)).child(editor)),
                        ),
                ),
            );
        }

        content = content.child(
            FormSection::titled("Properties")
                .description("Set the fields your team uses most. Additional links stay out of the way until needed.")
                .child(
                    PropertyGrid::new()
                        .child(
                            FormField::new("Status").child(self.render_mutation_dropdown(
                                "task-status",
                                indexes.status,
                                "Status",
                                status_options,
                                window,
                                cx,
                            )),
                        )
                        .child(
                            FormField::new("Priority").child(self.render_mutation_dropdown(
                                "task-priority",
                                indexes.priority,
                                "Priority",
                                priority_options,
                                window,
                                cx,
                            )),
                        )
                        .child(
                            FormField::new("Assignees").child(
                                self.render_task_assignee_dropdown(indexes.assignees, window, cx),
                            ),
                        )
                        .child(
                            FormField::new("Due date")
                                .description("Choose a preset or type an ISO date under More options.")
                                .child(self.render_mutation_dropdown(
                                    "task-due-date",
                                    indexes.due_date,
                                    "Due date",
                                    date_options,
                                    window,
                                    cx,
                                )),
                        )
                        .child(
                            FormField::new("Effort").child(self.render_mutation_dropdown(
                                "task-effort",
                                indexes.effort,
                                "Effort",
                                effort_options,
                                window,
                                cx,
                            )),
                        )
                        .child(
                            FormField::new("Story points").child(
                                self.render_mutation_text_field(
                                    indexes.story_points,
                                    dialog,
                                    window,
                                    cx,
                                ),
                            ),
                        ),
                ),
        );

        let toggle_label = if dialog.show_advanced {
            "Hide more options"
        } else {
            "More options"
        };
        content = content.child(
            macro_button("toggle-task-advanced", toggle_label)
                .style(ButtonStyle::Subtle)
                .size(ButtonSize::Compact)
                .start_icon(if dialog.show_advanced {
                    Icon::new(IconName::ChevronDownUp).size(IconSize::XSmall)
                } else {
                    Icon::new(IconName::ChevronDown).size(IconSize::XSmall)
                })
                .on_click(cx.listener(|this, _, _, cx| {
                    if let Some(dialog) = this.mutation_dialog.as_mut() {
                        dialog.show_advanced = !dialog.show_advanced;
                    }
                    cx.notify();
                })),
        );

        if dialog.show_advanced {
            let mut advanced = PropertyGrid::new()
                .child(
                    FormField::new("Custom due date")
                        .description("Use YYYY-MM-DD or RFC3339.")
                        .child(self.render_mutation_text_field(
                            indexes.due_date,
                            dialog,
                            window,
                            cx,
                        )),
                )
                .child(
                    FormField::new("Parent task")
                        .description("Paste a Macro task link or ID.")
                        .child(self.render_mutation_text_field(indexes.parent, dialog, window, cx)),
                )
                .child(
                    FormField::new("Dependencies")
                        .description("Paste task links or IDs, separated by commas.")
                        .child(self.render_mutation_text_field(
                            indexes.dependencies,
                            dialog,
                            window,
                            cx,
                        )),
                )
                .child(
                    FormField::new("Related documents")
                        .description("Paste document links or IDs, separated by commas.")
                        .child(self.render_mutation_text_field(
                            indexes.related_documents,
                            dialog,
                            window,
                            cx,
                        )),
                );
            if let Some(project_index) = indexes.project {
                let mut project_options = vec![(String::new(), "No project".into())];
                project_options.extend(
                    self.workspace
                        .projects
                        .loaded()
                        .into_iter()
                        .flatten()
                        .map(|project| (project.id.clone(), project.name.clone())),
                );
                advanced = advanced.child(FormField::new("Project").child(
                    self.render_mutation_dropdown(
                        "task-project",
                        project_index,
                        "Project",
                        project_options,
                        window,
                        cx,
                    ),
                ));
            }
            if let Some(team_index) = indexes.team {
                let mut team_options = vec![(String::new(), "Personal".into())];
                if let Some(team) = self.workspace.team.loaded().and_then(Option::as_ref) {
                    team_options.push((team.team.id.clone(), team.team.name.clone()));
                }
                advanced = advanced.child(FormField::new("Workspace").child(
                    self.render_mutation_dropdown(
                        "task-team",
                        team_index,
                        "Workspace",
                        team_options,
                        window,
                        cx,
                    ),
                ));
            }
            if let Some(share_index) = indexes.share_with_team {
                advanced = advanced.child(FormField::new("Visibility").child(
                    self.render_mutation_dropdown(
                        "task-visibility",
                        share_index,
                        "Visibility",
                        vec![
                            ("true".into(), "Shared with team".into()),
                            ("false".into(), "Private".into()),
                        ],
                        window,
                        cx,
                    ),
                ));
            }
            content = content.child(
                FormSection::titled("More options")
                    .contained(true)
                    .child(advanced),
            );
        }

        content.into_any_element()
    }

    fn render_email_mention_toolbar(
        &self,
        choices: &[(String, String, String)],
        busy: bool,
        cx: &mut Context<Self>,
    ) -> AnyElement {
        let colors = macro_colors(cx);
        h_flex()
            .gap_1()
            .flex_wrap()
            .child(
                div()
                    .px_1()
                    .py_0p5()
                    .text_xs()
                    .text_color(colors.ink_subtle)
                    .child("Mention"),
            )
            .children(
                choices
                    .iter()
                    .take(6)
                    .enumerate()
                    .map(|(index, (user_id, email, label))| {
                        let user_id = user_id.clone();
                        let email = email.clone();
                        let label = label.clone();
                        let display = format!("@{label}");
                        div()
                            .id(("email-body-mention", index))
                            .px_2()
                            .py_0p5()
                            .rounded_full()
                            .border_1()
                            .border_color(colors.border_variant)
                            .bg(colors.background)
                            .text_xs()
                            .text_color(colors.ink)
                            .when(!busy, |this| {
                                this.cursor_pointer()
                                    .role(Role::Button)
                                    .aria_label_from_id()
                                    .focusable()
                                    .tab_stop(true)
                                    .focus_visible(|this| this.bg(colors.hover))
                                    .on_click(cx.listener(move |this, _, window, cx| {
                                        this.insert_email_body_mention(
                                            user_id.clone(),
                                            email.clone(),
                                            label.clone(),
                                            window,
                                            cx,
                                        );
                                        cx.stop_propagation();
                                    }))
                            })
                            .child(display)
                    }),
            )
            .into_any_element()
    }

    fn render_document_mention_picker(
        &self,
        document_id: &str,
        choices: &[DocumentMentionChoice],
        dialog: &MutationDialog,
        busy: bool,
        window: &mut Window,
        cx: &mut Context<Self>,
    ) -> AnyElement {
        let colors = macro_colors(cx);
        let document_id = document_id.to_owned();
        let show_custom = dialog.show_advanced;
        let selected_index = dialog
            .picker_selected_index
            .min(choices.len().saturating_sub(1));
        v_flex()
            .id("document-mention-picker")
            .gap_2()
            .child(
                h_flex()
                    .justify_between()
                    .child(
                        v_flex()
                            .gap_0p5()
                            .child(
                                Label::new("People and workspace entities")
                                    .size(LabelSize::Small)
                                    .color(Color::Default),
                            )
                            .child(
                                Label::new("Choose a result to insert it at the current caret.")
                                    .size(LabelSize::Small)
                                    .color(Color::Muted),
                            ),
                    )
                    .child(
                        macro_button(
                            "toggle-custom-document-mention",
                            if show_custom {
                                "Hide custom"
                            } else {
                                "Custom mention…"
                            },
                        )
                        .style(ButtonStyle::Transparent)
                        .size(ButtonSize::Compact)
                        .disabled(busy)
                        .on_click(cx.listener(|this, _, window, cx| {
                            let mut focus_field = DOCUMENT_MENTION_SEARCH_FIELD;
                            if let Some(dialog) = this.mutation_dialog.as_mut() {
                                dialog.show_advanced = !dialog.show_advanced;
                                focus_field = if dialog.show_advanced {
                                    0
                                } else {
                                    DOCUMENT_MENTION_SEARCH_FIELD
                                };
                                dialog.active_field = focus_field;
                                dialog.error = None;
                            }
                            if let Some(editor) = this.mutation_text_editor(focus_field) {
                                window.focus(&editor.read(cx).focus_handle(cx), cx);
                            }
                            cx.notify();
                        })),
                    ),
            )
            .child(
                v_flex()
                    .gap_1()
                    .child(
                        Label::new("Search")
                            .size(LabelSize::Small)
                            .color(Color::Muted),
                    )
                    .child(self.render_mutation_text_field(
                        DOCUMENT_MENTION_SEARCH_FIELD,
                        dialog,
                        window,
                        cx,
                    )),
            )
            .child(
                v_flex()
                    .id("document-mention-results")
                    .role(Role::List)
                    .aria_label("Mention results")
                    .max_h(px(360.0))
                    .overflow_y_scroll()
                    .rounded_md()
                    .border_1()
                    .border_color(colors.border_variant)
                    .bg(colors.background)
                    .when(choices.is_empty(), |this| {
                        this.child(
                            v_flex()
                                .p_4()
                                .items_center()
                                .gap_1()
                                .child(
                                    Label::new("No matching mention results")
                                        .size(LabelSize::Small)
                                        .color(Color::Muted),
                                )
                                .child(
                                    Label::new("Try another search or use Custom mention.")
                                        .size(LabelSize::Small)
                                        .color(Color::Muted),
                                ),
                        )
                    })
                    .children(choices.iter().take(40).enumerate().map(|(index, choice)| {
                        let mention = choice.mention.clone();
                        let target_document_id = document_id.clone();
                        ZedListItem::new(("document-mention-choice", index))
                            .aria_role(Role::Button)
                            .aria_label(format!("Insert {}", choice.mention.visible_token()))
                            .aria_keyshortcuts("Enter Space")
                            .tab_index(0)
                            .toggle_state(index == selected_index)
                            .disabled(busy)
                            .start_slot(EntityIcon::new(choice.entity_type).size(16.0))
                            .child(
                                v_flex()
                                    .flex_1()
                                    .min_w_0()
                                    .gap_0p5()
                                    .child(
                                        Label::new(choice.mention.visible_token())
                                            .size(LabelSize::Small)
                                            .color(Color::Default),
                                    )
                                    .child(
                                        Label::new(choice.detail.clone())
                                            .size(LabelSize::Small)
                                            .color(Color::Muted),
                                    ),
                            )
                            .on_click(cx.listener(move |this, _, window, cx| {
                                this.choose_document_mention(
                                    &target_document_id,
                                    mention.clone(),
                                    window,
                                    cx,
                                )
                            }))
                    })),
            )
            .into_any_element()
    }

