                        div()
                            .id(("crm-stage-filter", index))
                            .px_2()
                            .py_1()
                            .rounded_sm()
                            .border_1()
                            .border_color(if selected {
                                colors.accent
                            } else {
                                colors.border_variant
                            })
                            .cursor_pointer()
                            .role(Role::Button)
                            .aria_label_from_id()
                            .focusable()
                            .tab_stop(true)
                            .focus_visible(|this| this.bg(colors.hover))
                            .bg(if selected {
                                colors.selected
                            } else {
                                colors.background.opacity(0.0)
                            })
