// === Application Entry Point ===

fn configured_environment() -> (MacroEnvironment, &'static str) {
    match std::env::var("MACRO_ENVIRONMENT")
        .unwrap_or_else(|_| "prod".into())
        .to_lowercase()
        .as_str()
    {
        "local" => (MacroEnvironment::Local, "local"),
        "dev" | "development" => (MacroEnvironment::Dev, "dev"),
        _ => (MacroEnvironment::Prod, "prod"),
    }
}

fn configured_update_manifest_url() -> Option<String> {
    std::env::var("MACRO_UPDATE_MANIFEST_URL")
        .ok()
        .filter(|value| !value.trim().is_empty())
        .or_else(|| {
            option_env!("MACRO_UPDATE_MANIFEST_URL")
                .filter(|value| !value.trim().is_empty())
                .map(str::to_owned)
        })
        .or_else(|| {
            let base = option_env!("MACRO_UPDATE_BASE_URL")?
                .trim()
                .trim_end_matches('/');
            (!base.is_empty()).then(|| format!("{base}/update-manifest.json"))
        })
}

fn installed_version() -> &'static str {
    option_env!("MACRO_VERSION").unwrap_or(env!("CARGO_PKG_VERSION"))
}

fn parse_https_update_manifest_url(value: &str) -> Option<url::Url> {
    let url = url::Url::parse(value).ok()?;
    (url.scheme() == "https" && url.host_str().is_some()).then_some(url)
}

fn compiled_update_team_identifier() -> Option<String> {
    option_env!("MACRO_TEAM_IDENTIFIER")
        .map(str::trim)
        .filter(|identifier| {
            !identifier.is_empty() && identifier.bytes().all(|byte| byte.is_ascii_alphanumeric())
        })
        .map(str::to_owned)
}

fn preferences_path() -> std::path::PathBuf {
    paths::config_dir().join("macro-gpui/preferences.json")
}

fn account_credentials_key(user_id: &str) -> String {
    account_credentials_key_in_namespace(credentials_key(), user_id)
}

fn auth_transition_matches(
    current_generation: u64,
    current_account_id: Option<&str>,
    transition_generation: u64,
    transition_account_id: Option<&str>,
) -> bool {
    current_generation == transition_generation && current_account_id == transition_account_id
}

fn account_credentials_key_in_namespace(namespace: &str, user_id: &str) -> String {
    format!("{}/account/{}", namespace, urlencoding::encode(user_id))
}

fn credential_lookup_keys(user_id: Option<&str>) -> Vec<String> {
    let current_namespace = credentials_key();
    let legacy_namespace = legacy_credentials_key();
    let mut keys = Vec::with_capacity(4);
    if let Some(user_id) = user_id {
        keys.push(account_credentials_key_in_namespace(
            current_namespace,
            user_id,
        ));
    }
    keys.push(current_namespace.to_owned());
    if let Some(user_id) = user_id {
        keys.push(account_credentials_key_in_namespace(
            legacy_namespace,
            user_id,
        ));
    }
    keys.push(legacy_namespace.to_owned());
    keys.dedup();
    keys
}

