struct LoadedAppPreferences {
    preferences: AppPreferences,
    writable: bool,
    warning: Option<String>,
}

fn load_app_preferences_state() -> LoadedAppPreferences {
    load_app_preferences_state_from(&preferences_path())
}

fn load_app_preferences() -> AppPreferences {
    load_app_preferences_state().preferences
}

fn load_app_preferences_state_from(path: &std::path::Path) -> LoadedAppPreferences {
    let bytes = match std::fs::read(path) {
        Ok(bytes) => bytes,
        Err(error) if error.kind() == std::io::ErrorKind::NotFound => {
            return LoadedAppPreferences {
                preferences: AppPreferences::default(),
                writable: true,
                warning: None,
            };
        }
        Err(error) => {
            return LoadedAppPreferences {
                preferences: AppPreferences::default(),
                writable: false,
                warning: Some(format!(
                    "Settings could not be read and will not be overwritten: {error}"
                )),
            };
        }
    };
    let mut preferences = match serde_json::from_slice::<AppPreferences>(&bytes) {
        Ok(preferences) => preferences,
        Err(error) => {
            let backup = invalid_preferences_backup_path(path);
            let backed_up = std::fs::rename(path, &backup).is_ok();
            return LoadedAppPreferences {
                preferences: AppPreferences::default(),
                writable: backed_up,
                warning: Some(if backed_up {
                    format!(
                        "Unreadable settings were preserved at {} and defaults were restored: {error}",
                        backup.display()
                    )
                } else {
                    format!(
                        "Settings are unreadable and will not be overwritten until the file is recovered: {error}"
                    )
                }),
            };
        }
    };
    if preferences.schema_version > APP_PREFERENCES_SCHEMA_VERSION {
        return LoadedAppPreferences {
            preferences: AppPreferences::default(),
            writable: false,
            warning: Some(format!(
                "Settings use newer schema {} and will not be overwritten by this build.",
                preferences.schema_version
            )),
        };
    }

    preferences.schema_version = APP_PREFERENCES_SCHEMA_VERSION;
    preferences.sidebar_width = preferences
        .sidebar_width
        .clamp(MIN_SIDEBAR_WIDTH, MAX_SIDEBAR_WIDTH);
    preferences.detail_split_position = preferences.detail_split_position.clamp(0.2, 0.8);
    preferences.navigation_history_index = preferences
        .navigation_history_index
        .min(preferences.navigation_history.len().saturating_sub(1));
    for session in preferences.account_sessions.values_mut() {
        session.navigation_history_index = session
            .navigation_history_index
            .min(session.navigation_history.len().saturating_sub(1));
    }
    LoadedAppPreferences {
        preferences,
        writable: true,
        warning: None,
    }
}

fn invalid_preferences_backup_path(path: &std::path::Path) -> std::path::PathBuf {
    let timestamp = SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .unwrap_or_default()
        .as_millis();
    let filename = path
        .file_name()
        .and_then(|name| name.to_str())
        .unwrap_or("preferences.json");
    path.with_file_name(format!("{filename}.invalid-{timestamp}"))
}

fn write_app_preferences_atomically(
    path: &std::path::Path,
    preferences: &AppPreferences,
    epoch: u64,
    current_epoch: &AtomicU64,
    write_lock: &Mutex<()>,
) -> anyhow::Result<bool> {
    use std::io::Write as _;

    let parent = path
        .parent()
        .context("settings path has no parent directory")?;
    std::fs::create_dir_all(parent)?;
    let filename = path
        .file_name()
        .and_then(|name| name.to_str())
        .unwrap_or("preferences.json");
    let temporary =
        path.with_file_name(format!(".{filename}.{}.{}.tmp", std::process::id(), epoch));
    let json = serde_json::to_vec_pretty(preferences)?;
    let mut options = std::fs::OpenOptions::new();
    options.write(true).create_new(true);
    #[cfg(unix)]
    {
        use std::os::unix::fs::OpenOptionsExt as _;
        options.mode(0o600);
    }
    let result = (|| -> anyhow::Result<bool> {
        let mut file = options.open(&temporary)?;
        file.write_all(&json)?;
        file.sync_all()?;
        drop(file);

        let _guard = write_lock
            .lock()
            .map_err(|_| anyhow::anyhow!("settings write lock was poisoned"))?;
        if current_epoch.load(Ordering::Acquire) != epoch {
            std::fs::remove_file(&temporary)?;
            return Ok(false);
        }
        std::fs::rename(&temporary, path)?;
        #[cfg(unix)]
        {
            use std::os::unix::fs::PermissionsExt as _;
            let permissions = std::fs::Permissions::from_mode(0o600);
            std::fs::set_permissions(path, permissions)?;
        }
        if let Ok(directory) = std::fs::File::open(parent) {
            let _ = directory.sync_all();
        }
        Ok(true)
    })();
    if result.is_err() {
        let _ = std::fs::remove_file(&temporary);
    }
    result
}

fn apply_theme_preference(preference: ThemePreference, appearance: WindowAppearance, cx: &mut App) {
    match preference {
        ThemePreference::System => {
            macro_theme::sync_zed_theme_with_system(appearance, cx);
        }
        ThemePreference::Light => {
            macro_theme::apply_zed_theme("One Light", cx);
        }
        ThemePreference::Dark => {
            macro_theme::apply_zed_theme(theme::DEFAULT_DARK_THEME, cx);
        }
    }
}

fn json_value<'a>(value: &'a serde_json::Value, path: &[&str]) -> Option<&'a serde_json::Value> {
    let mut current = value;
    for key in path {
        current = current.get(*key)?;
    }
    Some(current)
}

fn json_text(value: &serde_json::Value, path: &[&str]) -> Option<String> {
    match json_value(value, path)? {
        serde_json::Value::String(value) if !value.trim().is_empty() => Some(value.clone()),
        serde_json::Value::Number(value) => Some(value.to_string()),
        serde_json::Value::Bool(value) => Some(value.to_string()),
        _ => None,
    }
}

fn json_first_text(value: &serde_json::Value, paths: &[&[&str]]) -> Option<String> {
    paths.iter().find_map(|path| json_text(value, path))
}

fn json_any_text(value: &serde_json::Value, keys: &[&str]) -> Option<String> {
    keys.iter().find_map(|key| json_text(value, &[*key]))
}

fn agent_retryable_prompt(transcript: &AgentTranscript) -> Option<String> {
    let failed_turn = transcript.messages.iter().rev().find_map(|message| {
        (!message.author.is_user() && matches!(message.stop, Some(AgentStopReason::Failed { .. })))
            .then_some(message.turn)
    })?;
    let prompt = transcript
        .messages
        .iter()
        .rev()
        .find(|message| message.turn == failed_turn && message.author.is_user())?
        .parts
        .iter()
        .filter_map(|part| match part {
            AgentTranscriptPart::Text { text } => Some(text.trim()),
            _ => None,
        })
        .filter(|text| !text.is_empty())
        .collect::<Vec<_>>()
        .join("\n");
    (!prompt.is_empty()).then_some(prompt)
}

fn agent_control_confirmation(action: &str) -> Option<&'static str> {
    match action {
        "compact" => Some("COMPACT"),
        "stop" => Some("STOP"),
        _ => None,
    }
}

fn json_bool(value: &serde_json::Value, path: &[&str]) -> Option<bool> {
    json_value(value, path)?.as_bool()
}

fn apply_agent_log_entries_to_detail(
    detail: &mut serde_json::Value,
    session_id: &str,
    entries: impl IntoIterator<Item = AgentSessionLogEntry>,
) -> anyhow::Result<()> {
    let object = detail
        .as_object_mut()
        .ok_or_else(|| anyhow::anyhow!("agent detail is not an object"))?;
    let log_value = object
        .get("_gpuiLog")
        .cloned()
        .ok_or_else(|| anyhow::anyhow!("agent detail has no protocol snapshot"))?;
    let mut log: macro_api::AgentSessionLogResponse = serde_json::from_value(log_value)?;
    for entry in entries {
        if !log.entries.contains(&entry) {
            log.entries.push(entry);
        }
    }
    // The snapshot is oldest-first and the gateway appends in durable-log
    // order, so retaining insertion order preserves same-timestamp frames.
    let transcript = fold_agent_session_log(session_id, &log)?;
    object.insert("_gpuiTranscript".into(), serde_json::to_value(transcript)?);
    object.insert("_gpuiLog".into(), serde_json::to_value(log)?);
    object.remove("_gpuiLogError");
    Ok(())
}

fn render_agent_transcript_message(
    index: usize,
    message: AgentTranscriptMessage,
    bot: &macro_api::AgentSessionBot,
    colors: &macro_theme::MacroColors,
    cx: &mut Context<MacroApp>,
) -> AnyElement {
    let is_user = message.author.is_user();
    let author = message.author.label(bot).to_owned();
    let failure = match &message.stop {
        Some(AgentStopReason::Failed { message }) => Some(message.clone()),
        Some(AgentStopReason::MaxTokens) => Some("The model reached its token limit".into()),
        Some(AgentStopReason::MaxTurnRequests) => {
            Some("The agent reached its turn-request limit".into())
        }
        Some(AgentStopReason::Refusal) => Some("The agent declined this request".into()),
        Some(AgentStopReason::Cancelled) => Some("This turn was cancelled".into()),
        Some(AgentStopReason::Other { reason }) => Some(format!("Turn ended: {reason}")),
        Some(AgentStopReason::EndTurn) | None => None,
    };
    let parts = message
        .parts
        .into_iter()
        .enumerate()
        .map(|(part_index, part)| render_agent_transcript_part(index, part_index, part, colors, cx))
        .collect::<Vec<_>>();
    let card = v_flex()
        .id(("agent-transcript-message", index))
        .max_w(px(760.0))
        .gap_2()
        .when(is_user, |this| {
            this.p_3()
                .rounded_lg()
                .border_1()
                .border_color(colors.border_variant)
                .bg(colors.surface)
        })
        .child(
            div()
                .text_xs()
                .font_weight(FontWeight::SEMIBOLD)
                .text_color(if is_user {
                    colors.ink_muted
                } else {
                    colors.accent
                })
                .child(author),
        )
        .children(parts)
        .when_some(failure, |this, failure| {
            this.child(
                v_flex()
                    .p_2()
                    .gap_1()
                    .rounded_md()
                    .border_1()
                    .border_color(colors.failure.opacity(0.45))
                    .bg(colors.failure.opacity(0.08))
                    .child(
                        div()
                            .text_xs()
                            .font_weight(FontWeight::SEMIBOLD)
                            .text_color(colors.failure)
                            .child("Agent stopped"),
                    )
                    .child(div().text_sm().text_color(colors.ink).child(failure)),
            )
        });

    if is_user {
        h_flex()
            .w_full()
            .justify_end()
            .child(card)
            .into_any_element()
    } else {
        card.into_any_element()
    }
}

fn render_agent_transcript_part(
    message_index: usize,
    part_index: usize,
    part: AgentTranscriptPart,
    colors: &macro_theme::MacroColors,
    cx: &mut Context<MacroApp>,
) -> AnyElement {
    let element_id: SharedString =
        format!("agent-transcript-part-{message_index}-{part_index}").into();
    match part {
        AgentTranscriptPart::Text { text } => div()
            .id(element_id)
            .text_sm()
            .text_color(colors.ink)
            .child(text)
            .into_any_element(),
        AgentTranscriptPart::Thought { text } => v_flex()
            .id(element_id)
            .gap_1()
            .pl_3()
            .py_1()
            .border_l_2()
            .border_color(colors.accent.opacity(0.55))
            .child(
                div()
                    .text_xs()
                    .font_weight(FontWeight::SEMIBOLD)
                    .text_color(colors.ink_subtle)
                    .child("REASONING"),
            )
            .child(div().text_sm().text_color(colors.ink_muted).child(text))
            .into_any_element(),
        AgentTranscriptPart::Artifact { artifact } => render_agent_artifact(artifact, colors, cx),
        AgentTranscriptPart::ToolUse {
            label,
            status,
            detail,
            artifacts,
            ..
        } => {
            let status_color = match status {
                AgentToolStatus::Completed => colors.success,
                AgentToolStatus::Failed => colors.failure,
                AgentToolStatus::Running => colors.accent,
                AgentToolStatus::Pending => colors.ink_subtle,
            };
            let artifact_elements = artifacts
                .into_iter()
                .map(|artifact| render_agent_artifact(artifact, colors, cx))
                .collect::<Vec<_>>();
            v_flex()
                .id(element_id)
                .rounded_md()
                .border_1()
                .border_color(colors.border_variant)
                .overflow_hidden()
                .child(
                    h_flex()
                        .px_3()
                        .py_2()
                        .justify_between()
                        .bg(colors.surface)
                        .child(
                            div()
                                .text_sm()
                                .font_weight(FontWeight::SEMIBOLD)
                                .text_color(colors.ink)
                                .child(label),
                        )
                        .child(
                            div()
                                .text_xs()
                                .text_color(status_color)
                                .child(status.label()),
                        ),
                )
                .child(render_agent_tool_detail(detail, colors))
                .when(!artifact_elements.is_empty(), |this| {
                    this.child(v_flex().p_3().pt_0().gap_2().children(artifact_elements))
                })
                .into_any_element()
        }
        AgentTranscriptPart::Permission {
            options, outcome, ..
        } => {
            let pending = matches!(outcome, AgentPermissionOutcome::Pending);
            let label = outcome.label(&options);
            v_flex()
                .id(element_id)
                .px_3()
                .py_2()
                .gap_1()
                .rounded_md()
                .border_1()
                .border_color(if pending {
                    colors.warning.opacity(0.55)
                } else {
                    colors.border_variant
                })
                .bg(if pending {
                    colors.warning.opacity(0.08)
                } else {
                    colors.surface
                })
                .child(
                    div()
                        .text_sm()
                        .font_weight(FontWeight::SEMIBOLD)
                        .text_color(colors.ink)
                        .child("Permission requested"),
                )
                .child(div().text_xs().text_color(colors.ink_muted).child(label))
                .into_any_element()
        }
        AgentTranscriptPart::Control { control, outcome } => {
            let (label, color) = match outcome {
                AgentControlOutcome::Pending => ("Pending".into(), colors.ink_subtle),
                AgentControlOutcome::Accepted => ("Accepted".into(), colors.success),
                AgentControlOutcome::Rejected { message } => {
                    (format!("Rejected — {message}"), colors.failure)
                }
            };
            h_flex()
                .id(element_id)
                .px_3()
                .py_2()
                .justify_between()
                .rounded_md()
                .border_1()
                .border_color(colors.border_variant)
                .bg(colors.surface)
                .child(
                    div()
                        .text_sm()
                        .text_color(colors.ink)
                        .child(control.label()),
                )
                .child(div().text_xs().text_color(color).child(label))
                .into_any_element()
        }
        AgentTranscriptPart::Plan { entries } => v_flex()
            .id(element_id)
            .gap_1()
            .p_3()
            .rounded_md()
            .border_1()
            .border_color(colors.border_variant)
            .bg(colors.surface)
            .child(
                div()
                    .text_xs()
                    .font_weight(FontWeight::SEMIBOLD)
                    .text_color(colors.ink_subtle)
                    .child("PLAN"),
            )
            .children(entries.into_iter().map(|entry| {
                h_flex()
                    .gap_2()
                    .child(
                        div()
                            .text_sm()
                            .text_color(match entry.status {
                                macro_api::AgentPlanStatus::Completed => colors.success,
                                macro_api::AgentPlanStatus::InProgress => colors.accent,
                                macro_api::AgentPlanStatus::Pending => colors.ink_subtle,
                            })
                            .child(entry.status.glyph()),
                    )
                    .child(div().text_sm().text_color(colors.ink).child(entry.content))
            }))
            .into_any_element(),
    }
}

fn render_agent_artifact(
    artifact: AgentArtifact,
    colors: &macro_theme::MacroColors,
    cx: &mut Context<MacroApp>,
) -> AnyElement {
    let label = artifact.label();
    let kind = artifact.kind.label();
    let encoded_len = artifact.encoded_len();
    let image_source = artifact
        .bounded_image_data_url(4 * 1024 * 1024)
        .ok()
        .flatten();
    let open_url = artifact.uri.as_deref().and_then(safe_external_resource_url);
    let uri = artifact.uri.clone();
    let description = artifact.description.clone();
    let text = artifact.text.clone();
    let mime_type = artifact.mime_type.clone();
    let size = artifact.size;
    let unknown_preview = artifact
        .unknown_payload
        .as_ref()
        .and_then(|value| serde_json::to_string_pretty(value).ok())
        .map(|value| truncate_preview_text(&value, 12_000));
    let has_download = artifact.encoded_data.is_some();
    let download_artifact = artifact.clone();
    v_flex()
        .gap_1()
        .p_3()
        .rounded_md()
        .border_1()
        .border_color(colors.border_variant)
        .bg(colors.surface)
        .child(
            h_flex()
                .justify_between()
                .gap_3()
                .child(
                    div()
                        .flex_1()
                        .text_sm()
                        .font_weight(FontWeight::SEMIBOLD)
                        .text_color(colors.ink)
                        .child(label),
                )
                .child(div().text_xs().text_color(colors.accent).child(kind))
                .when_some(open_url, |this, url| {
                    let open_url = url.clone();
                    this.child(
                        macro_button(format!("open-agent-artifact-{url}"), "Open")
                            .style(ButtonStyle::Outlined)
                            .size(ButtonSize::Compact)
                            .on_click(cx.listener(move |_, _, _, cx| cx.open_url(&open_url))),
                    )
                })
                .when(has_download, |this| {
                    this.child(
                        macro_button(
                            format!("save-agent-artifact-{}", download_artifact.label()),
                            "Save…",
                        )
                        .style(ButtonStyle::Outlined)
                        .size(ButtonSize::Compact)
                        .on_click(cx.listener(move |this, _, _, cx| {
                            this.download_agent_artifact(download_artifact.clone(), cx)
                        })),
                    )
                }),
        )
        .when_some(description, |this, description| {
            this.child(
                div()
                    .text_xs()
                    .text_color(colors.ink_muted)
                    .child(description),
            )
        })
        .when_some(image_source, |this, source| {
            this.child(
                div()
                    .w_full()
                    .max_h(px(520.0))
                    .p_2()
                    .rounded_md()
                    .border_1()
                    .border_color(colors.border_variant)
                    .bg(colors.panel)
                    .child(
                        img(source)
                            .w_full()
                            .max_h(px(500.0))
                            .object_fit(ObjectFit::Contain),
                    ),
            )
        })
        .when_some(uri, |this, uri| {
            this.child(
                div()
                    .font_family("monospace")
                    .text_xs()
                    .text_color(colors.ink_muted)
                    .child(truncate_preview_text(&uri, 2_000)),
            )
        })
        .when_some(text, |this, text| {
            this.child(
                div()
                    .p_2()
                    .rounded_sm()
                    .bg(colors.panel)
                    .font_family("monospace")
                    .text_xs()
                    .text_color(colors.ink)
                    .child(truncate_preview_text(&text, 40_000)),
            )
        })
        .when_some(unknown_preview, |this, preview| {
            this.child(
                div()
                    .p_2()
                    .rounded_sm()
                    .bg(colors.panel)
                    .font_family("monospace")
                    .text_xs()
                    .text_color(colors.ink_muted)
                    .child(preview),
            )
        })
        .when(
            mime_type.is_some() || size.is_some() || encoded_len.is_some(),
            |this| {
                let mut metadata = Vec::new();
                if let Some(mime_type) = mime_type {
                    metadata.push(mime_type);
                }
                if let Some(size) = size {
                    metadata.push(format!("{size} bytes"));
                }
                if let Some(size) = encoded_len {
                    metadata.push(format!("{size} encoded bytes"));
                }
                this.child(
                    div()
                        .text_xs()
                        .text_color(colors.ink_subtle)
                        .child(metadata.join(" · ")),
                )
            },
        )
        .into_any_element()
}

fn render_agent_tool_detail(
    detail: AgentToolDetail,
    colors: &macro_theme::MacroColors,
) -> AnyElement {
    match detail {
        AgentToolDetail::Terminal {
            command,
            output,
            exit_code,
        } => {
            let command = command.map(|command| format!("$ {command}"));
            let output = output.map(|output| strip_ansi_sequences(&output));
            v_flex()
                .p_3()
                .gap_2()
                .bg(colors.panel)
                .font_family("monospace")
                .when_some(command, |this, command| {
                    this.child(div().text_sm().text_color(colors.ink).child(command))
                })
                .when_some(output, |this, output| {
                    this.child(
                        div()
                            .text_xs()
                            .text_color(colors.ink_muted)
                            .child(truncate_preview_text(&output, 40_000)),
                    )
                })
                .when_some(exit_code, |this, exit_code| {
                    this.child(
                        div()
                            .text_xs()
                            .text_color(if exit_code == 0 {
                                colors.success
                            } else {
                                colors.failure
                            })
                            .child(format!("Process exited with code {exit_code}")),
                    )
                })
                .into_any_element()
        }
        AgentToolDetail::Edit { diffs } => v_flex()
            .gap_2()
            .p_3()
            .children(diffs.into_iter().map(|diff| {
                let (additions, deletions) = diff.additions_and_deletions();
                v_flex()
                    .gap_1()
                    .child(
                        h_flex()
                            .justify_between()
                            .child(
                                div()
                                    .text_sm()
                                    .font_family("monospace")
                                    .text_color(colors.ink)
                                    .child(diff.path),
                            )
                            .child(
                                h_flex()
                                    .gap_2()
                                    .child(
                                        div()
                                            .text_xs()
                                            .text_color(colors.success)
                                            .child(format!("+{additions}")),
                                    )
                                    .child(
                                        div()
                                            .text_xs()
                                            .text_color(colors.failure)
                                            .child(format!("−{deletions}")),
                                    ),
                            ),
                    )
                    .when_some(diff.old_text, |this, old_text| {
                        this.child(
                            div()
                                .p_2()
                                .rounded_sm()
                                .bg(colors.failure.opacity(0.08))
                                .font_family("monospace")
                                .text_xs()
                                .text_color(colors.ink_muted)
                                .child(truncate_preview_text(&old_text, 20_000)),
                        )
                    })
                    .child(
                        div()
                            .p_2()
                            .rounded_sm()
                            .bg(colors.success.opacity(0.08))
                            .font_family("monospace")
                            .text_xs()
                            .text_color(colors.ink)
                            .child(truncate_preview_text(&diff.new_text, 20_000)),
                    )
            }))
            .into_any_element(),
        AgentToolDetail::Read { paths } => render_agent_paths("Read", paths, None, colors),
        AgentToolDetail::Delete { paths } => render_agent_paths("Deleted", paths, None, colors),
        AgentToolDetail::Move { paths } => render_agent_paths("Moved", paths, None, colors),
        AgentToolDetail::Search { paths, output } => {
            render_agent_paths("Searched", paths, output, colors)
        }
        AgentToolDetail::Fetch { output } => {
            render_agent_paths("Fetched data", Vec::new(), output, colors)
        }
        AgentToolDetail::Think { output } => {
            render_agent_paths("Reasoning", Vec::new(), output, colors)
        }
        AgentToolDetail::Other {
            acp_kind,
            output,
            input,
        } => {
            let raw_input = input.and_then(|input| serde_json::to_string_pretty(&input).ok());
            render_agent_paths(&acp_kind, Vec::new(), output.or(raw_input), colors)
        }
    }
}

fn render_agent_paths(
    label: &str,
    paths: Vec<String>,
    output: Option<String>,
    colors: &macro_theme::MacroColors,
) -> AnyElement {
    v_flex()
        .p_3()
        .gap_2()
        .when(!paths.is_empty(), |this| {
            this.child(
                v_flex()
                    .gap_1()
                    .child(
                        div()
                            .text_xs()
                            .text_color(colors.ink_subtle)
                            .child(label.to_owned()),
                    )
                    .children(paths.into_iter().map(|path| {
                        div()
                            .text_sm()
                            .font_family("monospace")
                            .text_color(colors.ink)
                            .child(path)
                    })),
            )
        })
        .when_some(output, |this, output| {
            this.child(
                div()
                    .p_2()
                    .rounded_sm()
                    .bg(colors.panel)
                    .font_family("monospace")
                    .text_xs()
                    .text_color(colors.ink_muted)
                    .child(truncate_preview_text(&output, 40_000)),
            )
        })
        .into_any_element()
}

fn strip_ansi_sequences(value: &str) -> String {
    let mut output = String::with_capacity(value.len());
    let mut chars = value.chars().peekable();
    while let Some(character) = chars.next() {
        if character != '\u{1b}' {
            output.push(character);
            continue;
        }
        if chars.next_if_eq(&'[').is_some() {
            for next in chars.by_ref() {
                if ('@'..='~').contains(&next) {
                    break;
                }
            }
        }
    }
    output
}

/// Returns a display-safe, non-fetching email body. Macro's service-provided
/// HTML is projected into Zed's native Markdown renderer; no HTML is executed
/// and the renderer is deliberately given no remote-image resolver.
fn email_message_body(message: &serde_json::Value) -> String {
    email_message_body_content(message, false).markdown
}

fn email_message_body_content(
    message: &serde_json::Value,
    prefer_full_html: bool,
) -> EmailBodyContent {
    let body_macro = json_first_text(message, &[&["body_macro"], &["bodyMacro"]])
        .filter(|body| !body.trim().is_empty());
    let body_text = json_first_text(message, &[&["body_text"], &["bodyText"]])
        .filter(|body| !body.trim().is_empty());
    let body_replyless = json_first_text(message, &[&["body_replyless"], &["bodyReplyless"]])
        .filter(|body| !body.trim().is_empty());
    let html = json_first_text(message, &[&["body_html_sanitized"], &["bodyHtmlSanitized"]])
        .filter(|body| !body.trim().is_empty());

    let full = html
        .as_deref()
        .and_then(email_html_to_markdown)
        .or_else(|| body_macro.clone())
        .or_else(|| body_text.clone())
        .or_else(|| {
            body_replyless
                .as_deref()
                .and_then(email_body_fragment_to_markdown)
        });
    let compact = body_macro
        .clone()
        .or_else(|| {
            body_replyless
                .as_deref()
                .and_then(email_body_fragment_to_markdown)
        })
        .or_else(|| body_text.clone())
        .or_else(|| full.clone());
    let full = full.unwrap_or_else(|| {
        json_text(message, &["snippet"]).unwrap_or_else(|| "Message body unavailable".into())
    });
    let compact = compact.unwrap_or_else(|| full.clone());
    let html_has_collapsible_structure = html.as_deref().is_some_and(|html| {
        let html = html.to_ascii_lowercase();
        [
            "macro_quote",
            "gmail_quote",
            "gmail_signature",
            "macro-email-signature",
            "<blockquote",
        ]
        .into_iter()
        .any(|marker| html.contains(marker))
    });
    let has_hidden_reply_structure = html.is_some()
        && (html_has_collapsible_structure
            || normalize_email_body_for_comparison(&compact)
                != normalize_email_body_for_comparison(&full));

    EmailBodyContent {
        markdown: if prefer_full_html { full } else { compact },
        has_hidden_reply_structure,
    }
}

fn email_body_fragment_to_markdown(fragment: &str) -> Option<String> {
    if fragment.contains('<') && fragment.contains('>') {
        email_html_to_markdown(fragment)
    } else {
        Some(fragment.trim().to_owned()).filter(|body| !body.is_empty())
    }
}

fn email_html_to_markdown(html: &str) -> Option<String> {
    html_to_markdown::convert_html_to_markdown(html.as_bytes(), &mut [])
        .ok()
        .map(|markdown| markdown.trim().to_owned())
        .filter(|markdown| !markdown.is_empty())
}

fn normalize_email_body_for_comparison(body: &str) -> String {
    body.chars()
        .filter(|character| !character.is_whitespace())
        .flat_map(char::to_lowercase)
        .collect()
}

fn parse_mailto_url(value: &str) -> Option<MailtoCompose> {
    let url = url::Url::parse(value).ok()?;
    (url.scheme() == "mailto").then_some(())?;
    let to = urlencoding::decode(url.path()).ok()?.into_owned();
    let mut compose = MailtoCompose {
        to,
        ..Default::default()
    };
    for (key, value) in url.query_pairs() {
        let target = match key.to_ascii_lowercase().as_str() {
            "to" => &mut compose.to,
            "cc" => &mut compose.cc,
            "bcc" => &mut compose.bcc,
            "subject" => &mut compose.subject,
            "body" => &mut compose.body,
            _ => continue,
        };
        if target.is_empty() {
            *target = value.into_owned();
        } else if matches!(key.to_ascii_lowercase().as_str(), "to" | "cc" | "bcc") {
            target.push_str(", ");
            target.push_str(&value);
        }
    }
    truncate_mailto_field(&mut compose.to);
    truncate_mailto_field(&mut compose.cc);
    truncate_mailto_field(&mut compose.bcc);
    truncate_mailto_field(&mut compose.subject);
    truncate_mailto_field(&mut compose.body);
    Some(compose)
}

fn truncate_mailto_field(field: &mut String) {
    let mut boundary = field.len().min(20_000);
    while !field.is_char_boundary(boundary) {
        boundary -= 1;
    }
    field.truncate(boundary);
}

/// Extracts only explicit HTTP(S) image sources from service-sanitized HTML.
/// Nothing is fetched until the user opts in for that individual message.
fn email_remote_image_urls(message: &serde_json::Value) -> Vec<String> {
    let Some(html) = json_text(message, &["body_html_sanitized"]) else {
        return Vec::new();
    };
    let lower = html.to_ascii_lowercase();
    let mut offset = 0_usize;
    let mut urls = Vec::new();
    let mut seen = HashSet::new();
    while urls.len() < 20 {
        let Some(relative_start) = lower[offset..].find("<img") else {
            break;
        };
        let start = offset + relative_start;
        let Some(relative_end) = lower[start..].find('>') else {
            break;
        };
        let end = start + relative_end + 1;
        let tag = &html[start..end];
        if let Some(source) = html_attribute(tag, "src") {
            let source = source.replace("&amp;", "&");
            if source.len() <= 2_048
                && let Ok(url) = url::Url::parse(&source)
                && matches!(url.scheme(), "http" | "https")
                && seen.insert(source.clone())
            {
                urls.push(source);
            }
        }
        offset = end;
    }
    urls
}

fn email_message_attachments(message: &serde_json::Value) -> Vec<serde_json::Value> {
    let mut attachments = Vec::new();
    let mut seen = HashSet::new();
    for key in [
        "attachments",
        "attachments_draft",
        "attachmentsDraft",
        "attachments_forwarded",
        "attachmentsForwarded",
    ] {
        for attachment in message
            .get(key)
            .and_then(serde_json::Value::as_array)
            .into_iter()
            .flatten()
        {
            let identity = json_first_text(
                attachment,
                &[
                    &["db_id"],
                    &["id"],
                    &["attachment_id"],
                    &["attachmentId"],
                    &["provider_attachment_id"],
                    &["providerAttachmentId"],
                ],
            )
            .unwrap_or_else(|| attachment.to_string());
            if seen.insert(identity) {
                attachments.push(attachment.clone());
            }
        }
    }
    attachments
}

fn email_attachment_sub_type(filename: &str) -> Option<String> {
    std::path::Path::new(filename)
        .extension()
        .and_then(std::ffi::OsStr::to_str)
        .map(str::to_ascii_lowercase)
}

fn html_attribute(tag: &str, attribute: &str) -> Option<String> {
    let lower = tag.to_ascii_lowercase();
    let bytes = tag.as_bytes();
    let lower_bytes = lower.as_bytes();
    let attribute = attribute.as_bytes();
    let mut offset = 0_usize;
    while offset + attribute.len() <= lower_bytes.len() {
        let relative = lower_bytes[offset..]
            .windows(attribute.len())
            .position(|window| window == attribute)?;
        let start = offset + relative;
        let before_ok = start == 0
            || lower_bytes[start - 1].is_ascii_whitespace()
            || lower_bytes[start - 1] == b'<';
        let mut cursor = start + attribute.len();
        while cursor < lower_bytes.len() && lower_bytes[cursor].is_ascii_whitespace() {
            cursor += 1;
        }
        if !before_ok || lower_bytes.get(cursor) != Some(&b'=') {
            offset = start + attribute.len();
            continue;
        }
        cursor += 1;
        while cursor < lower_bytes.len() && lower_bytes[cursor].is_ascii_whitespace() {
            cursor += 1;
        }
        let quote = lower_bytes.get(cursor).copied();
        if matches!(quote, Some(b'\'' | b'"')) {
            cursor += 1;
            let end = bytes[cursor..]
                .iter()
                .position(|byte| Some(*byte) == quote)
                .map(|end| cursor + end)?;
            return String::from_utf8(bytes[cursor..end].to_vec()).ok();
        }
        let end = lower_bytes[cursor..]
            .iter()
            .position(|byte| byte.is_ascii_whitespace() || *byte == b'>')
            .map(|end| cursor + end)
            .unwrap_or(lower_bytes.len());
        return String::from_utf8(bytes[cursor..end].to_vec()).ok();
    }
    None
}

// Macro's open-source web uploader rejects files above 2 GB and caps the
// aggregate of an email draft's attachments below 18 MB. Enforce those same
// boundaries before allocating a buffer, then read through a capped stream so
// a file that grows after metadata inspection cannot exhaust the process.
const MAX_GENERAL_UPLOAD_BYTES: u64 = 2 * 1_000 * 1_000 * 1_000;
const MAX_EMAIL_ATTACHMENTS_BYTES: u64 = 18_000_000;

fn bounded_file_size(path: &std::path::Path, maximum_bytes: u64) -> anyhow::Result<u64> {
    let metadata =
        std::fs::metadata(path).with_context(|| format!("failed to inspect {}", path.display()))?;
    anyhow::ensure!(
        metadata.is_file(),
        "{} is not a regular file",
        path.display()
    );
    anyhow::ensure!(
        metadata.len() <= maximum_bytes,
        "{} exceeds the {} upload limit",
        path.display(),
        byte_size_label(maximum_bytes)
    );
    Ok(metadata.len())
}

fn read_bounded_file(path: &std::path::Path, maximum_bytes: u64) -> anyhow::Result<Vec<u8>> {
    let expected_size = bounded_file_size(path, maximum_bytes)?;
    let file =
        std::fs::File::open(path).with_context(|| format!("failed to open {}", path.display()))?;
    let initial_capacity = expected_size.min(16 * 1024 * 1024) as usize;
    let mut bytes = Vec::with_capacity(initial_capacity);
    file.take(maximum_bytes.saturating_add(1))
        .read_to_end(&mut bytes)
        .with_context(|| format!("failed to read {}", path.display()))?;
    anyhow::ensure!(
        bytes.len() as u64 <= maximum_bytes,
        "{} grew beyond the {} upload limit while it was being read",
        path.display(),
        byte_size_label(maximum_bytes)
    );
    Ok(bytes)
}

fn safe_download_filename(value: &str, fallback: &str) -> String {
    let leaf = std::path::Path::new(value)
        .file_name()
        .and_then(|name| name.to_str())
        .unwrap_or(fallback);
    let cleaned = leaf
        .chars()
        .filter(|character| !character.is_control() && !matches!(character, '/' | '\\'))
        .take(180)
        .collect::<String>();
    let cleaned = cleaned.trim().trim_matches('.');
    if cleaned.is_empty() {
        fallback.to_owned()
    } else {
        cleaned.to_owned()
    }
}

fn import_run_status_label(status: ImportRunStatus) -> &'static str {
    match status {
        ImportRunStatus::Running => "gathering",
        ImportRunStatus::Ready => "ready",
        ImportRunStatus::Importing => "importing",
        ImportRunStatus::Completed => "completed",
        ImportRunStatus::Failed => "failed",
        ImportRunStatus::Dismissed => "dismissed",
    }
}

fn import_entity_status_label(status: ImportEntityStatus) -> &'static str {
    match status {
        ImportEntityStatus::Staged => "staged",
        ImportEntityStatus::Importing => "importing",
        ImportEntityStatus::Imported => "imported",
        ImportEntityStatus::Discarded => "discarded",
    }
}

fn safe_external_resource_url(value: &str) -> Option<String> {
    let url = url::Url::parse(value).ok()?;
    matches!(url.scheme(), "http" | "https").then(|| url.to_string())
}

fn canvas_static_media_url(base_url: &str, file_id: &str) -> Option<String> {
    safe_external_resource_url(&format!(
        "{}/file/{}",
        base_url.trim_end_matches('/'),
        urlencoding::encode(file_id)
    ))
}

fn agent_artifact_filename(artifact: &AgentArtifact) -> String {
    let fallback = match artifact.kind {
        macro_api::AgentArtifactKind::Image => "agent-image",
        macro_api::AgentArtifactKind::Audio => "agent-audio",
        macro_api::AgentArtifactKind::BlobResource => "agent-artifact",
        macro_api::AgentArtifactKind::TextResource => "agent-resource.txt",
        macro_api::AgentArtifactKind::ResourceLink | macro_api::AgentArtifactKind::Unknown(_) => {
            "agent-artifact"
        }
    };
    let uri_filename = artifact.uri.as_deref().and_then(|uri| {
        url::Url::parse(uri)
            .ok()
            .and_then(|url| url.path_segments()?.next_back().map(ToOwned::to_owned))
            .filter(|value| !value.is_empty())
    });
    let candidate = artifact
        .name
        .as_deref()
        .or(artifact.title.as_deref())
        .map(ToOwned::to_owned)
        .or(uri_filename)
        .unwrap_or_else(|| fallback.into());
    let mut filename = safe_download_filename(&candidate, fallback);
    if std::path::Path::new(&filename).extension().is_none()
        && let Some(extension) = artifact
            .mime_type
            .as_deref()
            .and_then(agent_artifact_extension)
    {
        filename.push('.');
        filename.push_str(extension);
    }
    filename
}

fn agent_artifact_extension(mime_type: &str) -> Option<&'static str> {
    match mime_type.to_ascii_lowercase().as_str() {
        "image/png" => Some("png"),
        "image/jpeg" => Some("jpg"),
        "image/gif" => Some("gif"),
        "image/webp" => Some("webp"),
        "image/svg+xml" => Some("svg"),
        "audio/mpeg" => Some("mp3"),
        "audio/mp4" => Some("m4a"),
        "audio/wav" | "audio/x-wav" => Some("wav"),
        "audio/ogg" => Some("ogg"),
        "application/pdf" => Some("pdf"),
        "application/json" => Some("json"),
        "text/plain" => Some("txt"),
        "text/markdown" => Some("md"),
        _ => None,
    }
}

