fn scheduled_action_run_item(
    action_name: &str,
    record: &ActionExecutionRecord,
) -> Option<Arc<InboxItem>> {
    let chat_id = record.resource_id.as_ref()?.trim();
    if chat_id.is_empty() {
        return None;
    }
    Some(Arc::new(InboxItem {
        id: chat_id.into(),
        tag: "chat".into(),
        sub_type: None,
        entity_type: EntityType::Chat,
        title: format!("{action_name} run"),
        subtitle: if record.id.is_some() {
            if record.is_success {
                "Completed automation output".into()
            } else {
                "Failed automation output".into()
            }
        } else {
            "Automation is running".into()
        },
        timestamp: record.start_time.clone(),
        raw: serde_json::json!({
            "tag": "chat",
            "data": {
                "id": chat_id,
                "chat_id": chat_id,
                "scheduled_action_id": record.action_id,
            }
        }),
    }))
}

fn short_timestamp(timestamp: &str) -> String {
    if timestamp.len() >= 16 {
        timestamp[..16].replace('T', " ")
    } else {
        timestamp.to_owned()
    }
}

fn wall_clock_timestamp_ms() -> i64 {
    SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .unwrap_or_default()
        .as_millis()
        .min(i64::MAX as u128) as i64
}

fn format_history_timestamp(timestamp_ms: i64) -> String {
    chrono::DateTime::<chrono::Utc>::from_timestamp_millis(timestamp_ms)
        .map(|timestamp| timestamp.with_timezone(&chrono::Local))
        .map(|timestamp| timestamp.format("%b %-d, %Y %-I:%M %p").to_string())
        .unwrap_or_else(|| timestamp_ms.to_string())
}

fn awareness_color_index(color: &str) -> u32 {
    color
        .strip_prefix("accent-")
        .and_then(|degrees| degrees.parse::<u32>().ok())
        .map(|degrees| degrees / 30)
        .unwrap_or_else(|| {
            color.bytes().fold(0_u32, |hash, byte| {
                hash.wrapping_mul(31).wrapping_add(byte.into())
            })
        })
}

fn action_id(action: &ListAction) -> &str {
    match action {
        ListAction::Open(id)
        | ListAction::OpenSplit(id)
        | ListAction::Preview(id)
        | ListAction::MarkDone(id) => id,
    }
}

fn selected_or_focused_list_items(
    interaction: Option<&ListInteraction>,
    items: &[Arc<InboxItem>],
) -> Vec<Arc<InboxItem>> {
    let selected = interaction
        .into_iter()
        .flat_map(ListInteraction::selected_ids)
        .collect::<HashSet<_>>();
    if !selected.is_empty() {
        return items
            .iter()
            .filter(|item| selected.contains(item.id.as_str()))
            .cloned()
            .collect();
    }
    interaction
        .and_then(ListInteraction::focused)
        .and_then(|index| items.get(index))
        .cloned()
        .into_iter()
        .collect()
}

fn timestamp_is_after(value: &str, boundary: &str) -> bool {
    match (
        chrono::DateTime::parse_from_rfc3339(value),
        chrono::DateTime::parse_from_rfc3339(boundary),
    ) {
        (Ok(value), Ok(boundary)) => value > boundary,
        _ => value > boundary,
    }
}

fn channel_has_unread(channel: &ChannelSummary, current_user_id: &str) -> bool {
    let Some(viewed_at) = json_first_text(&channel.raw, &[&["viewed_at"], &["viewedAt"]]) else {
        return false;
    };
    let Some(latest) = channel
        .raw
        .get("latest_message")
        .or_else(|| channel.raw.get("latestMessage"))
    else {
        return false;
    };
    let Some(created_at) = json_first_text(latest, &[&["created_at"], &["createdAt"]]) else {
        return false;
    };
    let sender_id = json_first_text(latest, &[&["sender_id"], &["senderId"]]).unwrap_or_default();
    sender_id != current_user_id && timestamp_is_after(&created_at, &viewed_at)
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum ChannelSummaryReconcileOutcome {
    Applied,
    NotLoaded,
    ReloadRequired,
}

fn channel_list_message_id(value: &serde_json::Value) -> Option<&str> {
    value
        .get("message_id")
        .or_else(|| value.get("messageId"))
        .or_else(|| value.get("id"))
        .and_then(serde_json::Value::as_str)
}

fn channel_list_message_from_realtime(
    raw: &serde_json::Value,
    message_id: &str,
    thread_id: Option<&str>,
) -> anyhow::Result<serde_json::Value> {
    let mut message = raw
        .as_object()
        .cloned()
        .context("channel message event data was not an object")?;
    message.insert("message_id".into(), message_id.into());
    message.insert(
        "thread_id".into(),
        thread_id.map_or(serde_json::Value::Null, Into::into),
    );
    Ok(serde_json::Value::Object(message))
}

fn realtime_message_replaces_latest(
    latest: Option<&serde_json::Value>,
    incoming: &serde_json::Value,
    message_id: &str,
) -> bool {
    if latest.and_then(channel_list_message_id) == Some(message_id) {
        return true;
    }
    let Some(incoming_created_at) = json_first_text(incoming, &[&["created_at"], &["createdAt"]])
    else {
        return false;
    };
    latest
        .and_then(|latest| json_first_text(latest, &[&["created_at"], &["createdAt"]]))
        .is_none_or(|latest_created_at| {
            !timestamp_is_after(&latest_created_at, &incoming_created_at)
        })
}

/// Applies the channel-list projection of a comms websocket message even when
/// the corresponding timeline has never been opened. Macro's list contract
/// exposes both the latest message (including replies) and latest top-level
/// message; keeping both projections current makes previews and unread state
/// deterministic without a polling round trip.
fn reconcile_channel_summary_realtime(
    workspace: &mut WorkspaceData,
    event: &CommsRealtimeEvent,
) -> anyhow::Result<ChannelSummaryReconcileOutcome> {
    let CommsRealtimeEvent::Message {
        channel_id,
        message_id,
        thread_id,
        deleted_at,
        raw,
    } = event
    else {
        return Ok(ChannelSummaryReconcileOutcome::Applied);
    };

    if !workspace.channels.is_ready() || workspace.channels.get(channel_id).is_none() {
        return Ok(ChannelSummaryReconcileOutcome::NotLoaded);
    }

    // A deletion can expose an older message that is not present in any local
    // collection, so only the authoritative channel-list endpoint can safely
    // select the replacement preview and unread boundary.
    if deleted_at.is_some() {
        return Ok(ChannelSummaryReconcileOutcome::ReloadRequired);
    }

    let incoming = channel_list_message_from_realtime(raw, message_id, thread_id.as_deref())?;
    let existing = workspace
        .channels
        .get(channel_id)
        .context("loaded channel disappeared during realtime reconciliation")?;
    let mut channel = existing.as_ref().clone();
    let channel_raw = channel
        .raw
        .as_object_mut()
        .context("loaded channel summary data was not an object")?;

    let latest = channel_raw
        .get("latest_message")
        .or_else(|| channel_raw.get("latestMessage"));
    if realtime_message_replaces_latest(latest, &incoming, message_id) {
        let value = latest
            .filter(|latest| channel_list_message_id(latest) == Some(message_id))
            .map_or_else(
                || incoming.clone(),
                |latest| merge_realtime_json(latest, &incoming),
            );
        channel_raw.insert("latest_message".into(), value);
    }

    if thread_id.is_none() {
        let latest_non_thread = channel_raw
            .get("latest_non_thread_message")
            .or_else(|| channel_raw.get("latestNonThreadMessage"));
        if realtime_message_replaces_latest(latest_non_thread, &incoming, message_id) {
            let value = latest_non_thread
                .filter(|latest| channel_list_message_id(latest) == Some(message_id))
                .map_or_else(
                    || incoming.clone(),
                    |latest| merge_realtime_json(latest, &incoming),
                );
            channel_raw.insert("latest_non_thread_message".into(), value);
        }
    }

    if let Some(latest) = channel_raw.get("latest_message") {
        channel.preview = json_first_text(latest, &[&["content"]]).unwrap_or_default();
    }
    if let Some(updated_at) = json_first_text(
        raw,
        &[
            &["updated_at"],
            &["updatedAt"],
            &["created_at"],
            &["createdAt"],
        ],
    ) {
        channel.updated_at = updated_at.clone();
        channel_raw.insert("updated_at".into(), updated_at.into());
    }

    // Posting or editing a message touches comms_channels.updated_at in the
    // Macro backend, whose list endpoint is ordered newest first.
    workspace.channels.remove(channel_id);
    workspace.channels.upsert_front(channel);
    Ok(ChannelSummaryReconcileOutcome::Applied)
}

fn channel_message_is_new(
    message: &ChannelMessage,
    session: &ChannelViewSession,
    current_user_id: &str,
) -> bool {
    if session.new_messages_dismissed || message.sender_id == current_user_id {
        return false;
    }
    let Some(last_viewed_at) = session.last_viewed_at.as_deref() else {
        return false;
    };
    timestamp_is_after(&message.created_at, last_viewed_at)
        && timestamp_is_after(&session.opened_at, &message.created_at)
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum CommsReconcileOutcome {
    Applied,
    NotLoaded,
    TargetMissing,
}

fn merge_realtime_json(
    existing: &serde_json::Value,
    patch: &serde_json::Value,
) -> serde_json::Value {
    let (Some(existing), Some(patch)) = (existing.as_object(), patch.as_object()) else {
        return patch.clone();
    };
    let mut merged = existing.clone();
    for (key, value) in patch {
        merged.insert(key.clone(), value.clone());
    }
    serde_json::Value::Object(merged)
}

fn raw_with_thread_reply_count(raw: &serde_json::Value, count: usize) -> serde_json::Value {
    let mut raw = raw.clone();
    let Some(root) = raw.as_object_mut() else {
        return raw;
    };
    let thread = root
        .entry("thread")
        .or_insert_with(|| serde_json::json!({}));
    if let Some(thread) = thread.as_object_mut() {
        thread.insert("reply_count".into(), serde_json::json!(count));
    }
    raw
}

fn update_parent_thread_reply_count(
    workspace: &mut WorkspaceData,
    channel_id: &str,
    thread_id: &str,
    delta: isize,
) {
    let Some(messages) = workspace.channel_messages.get_mut(channel_id) else {
        return;
    };
    messages.update(thread_id, |message| {
        let mut message = message.clone();
        message.thread_reply_count = if delta.is_negative() {
            message
                .thread_reply_count
                .saturating_sub(delta.unsigned_abs())
        } else {
            message.thread_reply_count.saturating_add(delta as usize)
        };
        message.raw = raw_with_thread_reply_count(&message.raw, message.thread_reply_count);
        message
    });
}

fn patch_loaded_channel_reaction(
    workspace: &mut WorkspaceData,
    channel_id: &str,
    message_id: &str,
    raw: &serde_json::Value,
) -> CommsReconcileOutcome {
    let reactions = parse_channel_reactions(raw);
    let mut has_loaded_collection = false;
    if let Some(messages) = workspace.channel_messages.get_mut(channel_id)
        && messages.is_ready()
    {
        has_loaded_collection = true;
        if messages.update(message_id, |message| {
            let mut message = message.clone();
            message.reactions = reactions.clone();
            message.raw = merge_realtime_json(&message.raw, raw);
            if let Some(object) = message.raw.as_object_mut() {
                object.remove("_gpui_reaction_nonce");
            }
            message
        }) {
            return CommsReconcileOutcome::Applied;
        }
    }

    let prefix = format!("{channel_id}:");
    for (key, replies) in &mut workspace.channel_thread_replies {
        if !key.starts_with(&prefix) || !replies.is_ready() {
            continue;
        }
        has_loaded_collection = true;
        if replies.update(message_id, |reply| {
            let mut reply = reply.clone();
            reply.reactions = reactions.clone();
            reply.raw = merge_realtime_json(&reply.raw, raw);
            if let Some(object) = reply.raw.as_object_mut() {
                object.remove("_gpui_reaction_nonce");
            }
            reply
        }) {
            return CommsReconcileOutcome::Applied;
        }
    }
    if has_loaded_collection {
        CommsReconcileOutcome::TargetMissing
    } else {
        CommsReconcileOutcome::NotLoaded
    }
}

