fn non_empty_string(value: &str) -> Option<String> {
    (!value.trim().is_empty()).then(|| value.trim().to_owned())
}

fn fallback_user_label(value: &str) -> String {
    let identifier = value.rsplit('|').next().unwrap_or(value).trim();
    identifier
        .split('@')
        .next()
        .filter(|name| !name.is_empty())
        .unwrap_or(identifier)
        .to_owned()
}

fn format_usd(value: f64) -> String {
    if !value.is_finite() {
        return "—".into();
    }
    let negative = value.is_sign_negative();
    let absolute = value.abs();
    let formatted = if absolute.fract().abs() < f64::EPSILON {
        format!("{absolute:.0}")
    } else {
        format!("{absolute:.2}")
    };
    let (whole, fraction) = formatted.split_once('.').unwrap_or((&formatted, ""));
    let mut grouped = String::with_capacity(whole.len() + whole.len() / 3);
    for (index, character) in whole.chars().enumerate() {
        if index > 0 && (whole.len() - index) % 3 == 0 {
            grouped.push(',');
        }
        grouped.push(character);
    }
    format!(
        "{}${grouped}{}",
        if negative { "-" } else { "" },
        if fraction.is_empty() {
            String::new()
        } else {
            format!(".{fraction}")
        }
    )
}

fn user_name_label(user: &macro_api::UserName) -> String {
    let display_name = [user.first_name.as_deref(), user.last_name.as_deref()]
        .into_iter()
        .flatten()
        .map(str::trim)
        .filter(|part| !part.is_empty())
        .collect::<Vec<_>>()
        .join(" ");
    if display_name.is_empty() {
        fallback_user_label(&user.id)
    } else {
        display_name
    }
}

fn mention_wire_type_for_entity(entity_type: EntityType) -> Option<&'static str> {
    match entity_type {
        EntityType::Document | EntityType::Skill => Some("document"),
        EntityType::Chat | EntityType::AgentSession => Some("chat"),
        EntityType::Project => Some("project"),
        EntityType::Channel => Some("channel"),
        // Macro's backlink join uses the historical owner discriminator
        // `message` even though the public item type is `channel_message`.
        EntityType::ChannelMessage => Some("message"),
        EntityType::EmailThread | EntityType::EmailMessage => Some("email"),
        EntityType::CalendarEvent => Some("calendar_event"),
        EntityType::Call | EntityType::CallRecord => Some("call"),
        EntityType::CrmCompany => Some("crm_company"),
        EntityType::CrmContact => Some("crm_contact"),
        EntityType::ForeignEntity | EntityType::StaticFile => Some("foreign"),
        EntityType::User => Some("user"),
        EntityType::Team | EntityType::Reminder => None,
    }
}

fn mention_wire_entity_type(value: &str) -> Option<&'static str> {
    match value.trim().to_ascii_lowercase().as_str() {
        "document" | "doc" | "task" | "skill" => Some("document"),
        "chat" | "agent" | "agent_session" => Some("chat"),
        "project" | "folder" => Some("project"),
        "channel" => Some("channel"),
        "message" | "channel_message" | "channel_thread" => Some("channel_message"),
        "email" | "email_thread" | "email_message" => Some("email"),
        "calendar" | "calendar_event" | "event" | "date" => Some("calendar_event"),
        "call" | "call_record" => Some("call"),
        "company" | "crm_company" => Some("crm_company"),
        "contact" | "crm_contact" => Some("crm_contact"),
        "foreign" | "pr" | "pull_request" | "static_file" => Some("foreign"),
        "user" | "person" => Some("user"),
        _ => None,
    }
}

fn entity_mention_request(
    source_entity_type: EntityType,
    source_entity_id: &str,
    target_entity_id: &str,
    target_entity_type: &str,
) -> Result<CreateEntityMentionRequest, &'static str> {
    let source_entity_id = source_entity_id.trim();
    if source_entity_id.is_empty() {
        return Err("Source entity ID is required");
    }
    let target_entity_id = target_entity_id.trim();
    if target_entity_id.is_empty() {
        return Err("Choose an entity to link");
    }
    let source_entity_type = mention_wire_type_for_entity(source_entity_type)
        .ok_or("This source entity cannot own links")?;
    let target_entity_type =
        mention_wire_entity_type(target_entity_type).ok_or("Unsupported target entity type")?;
    Ok(CreateEntityMentionRequest {
        entity_id: target_entity_id.into(),
        entity_type: target_entity_type.into(),
        source_entity_id: source_entity_id.into(),
        source_entity_type: source_entity_type.into(),
    })
}

fn entity_type_from_mention_wire(value: &str) -> EntityType {
    match value.trim().to_ascii_lowercase().as_str() {
        "document" | "task" => EntityType::Document,
        "skill" => EntityType::Skill,
        "chat" | "agent" | "agent_session" => EntityType::Chat,
        "project" | "folder" => EntityType::Project,
        "channel" => EntityType::Channel,
        "channel_message" | "channel_thread" | "message" => EntityType::ChannelMessage,
        "email" | "email_thread" => EntityType::EmailThread,
        "email_message" => EntityType::EmailMessage,
        "calendar" | "calendar_event" | "event" | "date" => EntityType::CalendarEvent,
        "call" => EntityType::Call,
        "call_record" => EntityType::CallRecord,
        "crm_company" | "company" => EntityType::CrmCompany,
        "crm_contact" | "contact" => EntityType::CrmContact,
        "user" | "person" => EntityType::User,
        "static_file" => EntityType::StaticFile,
        _ => EntityType::ForeignEntity,
    }
}

