fn bulk_task_status_notice(
    label: &str,
    requested: usize,
    applied: usize,
    failures: &[(String, String)],
) -> String {
    if failures.is_empty() {
        return format!("Set {applied} task(s) to {label}");
    }
    let failure_preview = failures
        .iter()
        .take(3)
        .map(|(document_id, error)| format!("{document_id}: {error}"))
        .collect::<Vec<_>>()
        .join(" · ");
    let remaining = failures.len().saturating_sub(3);
    format!(
        "Task bulk update partially applied ({applied}/{requested}); {} failed: {failure_preview}{}",
        failures.len(),
        if remaining > 0 {
            format!(" · and {remaining} more")
        } else {
            String::new()
        }
    )
}

fn bulk_task_tag_notice(
    label: &str,
    add: bool,
    requested: usize,
    applied: usize,
    failures: &[(String, String)],
) -> String {
    let action = if add { "Added" } else { "Removed" };
    if failures.is_empty() {
        return format!("{action} tag {label} for {applied} task(s)");
    }
    let failure_preview = failures
        .iter()
        .take(3)
        .map(|(document_id, error)| format!("{document_id}: {error}"))
        .collect::<Vec<_>>()
        .join(" · ");
    let remaining = failures.len().saturating_sub(3);
    format!(
        "Task tag update partially applied ({applied}/{requested}); {} failed: {failure_preview}{}",
        failures.len(),
        if remaining > 0 {
            format!(" · and {remaining} more")
        } else {
            String::new()
        }
    )
}

