fn notification_entity_input(item: &InboxItem) -> Option<NotificationEntityInput> {
    let entity_type = match item.entity_type {
        EntityType::CalendarEvent => "CALENDAR_EVENT",
        EntityType::Channel => "CHANNEL",
        EntityType::ChannelMessage if item.tag == "channelThread" => "CHANNEL_MESSAGE",
        EntityType::Chat => "CHAT",
        EntityType::Document => "DOCUMENT",
        EntityType::EmailThread => "EMAIL_THREAD",
        EntityType::ForeignEntity => "FOREIGN_ENTITY",
        EntityType::Project => "PROJECT",
        EntityType::Reminder => "REMINDER",
        _ => return None,
    };
    Some(NotificationEntityInput {
        entity_id: item.id.clone(),
        entity_type: entity_type.into(),
    })
}

