fn apply_notification_preference(
    preferences: &macro_api::NotificationTypePreferences,
    notification_type: &str,
    enabled: bool,
) -> macro_api::NotificationTypePreferences {
    let mut next = preferences.clone();
    if enabled {
        next.disabled_types
            .retain(|disabled| disabled != notification_type);
    } else if !next
        .disabled_types
        .iter()
        .any(|disabled| disabled == notification_type)
    {
        next.disabled_types.push(notification_type.to_owned());
        next.disabled_types.sort();
    }
    next
}

fn notification_preference_label(notification_type: &str) -> &str {
    NOTIFICATION_PREFERENCES
        .iter()
        .find(|definition| definition.notification_type == notification_type)
        .map(|definition| definition.label)
        .unwrap_or(notification_type)
}

