/// Macro's Recent view is a distinct server query. The backend rejects normal
/// entity filter trees for `touched_by_me`, so this intentionally sends no
/// local type filters and preserves the returned order verbatim.
fn recent_soup_request() -> serde_json::Value {
    serde_json::json!({
        "limit": 100,
        "expand": true,
        "sort_method": "touched_by_me"
    })
}

/// Macro's semicolon menu is backed by a dedicated 500-item Soup query rather
/// than the current Documents page. That distinction is what makes unopened
/// team-shared snippets discoverable.
fn snippet_soup_request() -> serde_json::Value {
    const NIL_UUID: &str = "00000000-0000-0000-0000-000000000000";
    let nil = |field: &str| ast_literal(field, serde_json::json!(NIL_UUID));
    serde_json::json!({
        "limit": 500,
        "expand": true,
        "sort_method": "viewed_updated",
        "sort_direction": "desc",
        "df": ast_literal("dst", serde_json::json!("snippet")),
        "calf": nil("id"),
        "ef": nil("ThreadId"),
        "chanf": nil("ChannelId"),
        "cthf": nil("ThreadId"),
        "cf": nil("cid"),
        "pf": nil("pid"),
        "callf": nil("CallId"),
        "fef": nil("id"),
        "ccf": nil("id")
    })
}

fn snippet_candidates(
    items: Vec<Arc<InboxItem>>,
    query: &str,
    source_document_id: Option<&str>,
) -> Vec<Arc<InboxItem>> {
    let terms = query
        .split_whitespace()
        .map(str::to_ascii_lowercase)
        .collect::<Vec<_>>();
    items
        .into_iter()
        .filter(|item| {
            item.entity_type == EntityType::Document
                && item.sub_type.as_deref() == Some("snippet")
                && source_document_id.is_none_or(|source| item.id != source)
                && {
                    let searchable = format!("{} {}", item.title, item.subtitle).to_lowercase();
                    terms.iter().all(|term| searchable.contains(term))
                }
        })
        .collect()
}

fn inbox_signal_since_now() -> String {
    let local_date = chrono::Local::now().date_naive() - chrono::Duration::days(14);
    local_date
        .and_hms_opt(0, 0, 0)
        .and_then(|midnight| midnight.and_local_timezone(chrono::Local).earliest())
        .map(|midnight| midnight.with_timezone(&chrono::Utc).to_rfc3339())
        .unwrap_or_else(|| (chrono::Utc::now() - chrono::Duration::days(14)).to_rfc3339())
}

fn ast_literal(field: &str, value: serde_json::Value) -> serde_json::Value {
    serde_json::json!({"l": {field: value}})
}

fn ast_unit(field: &str) -> serde_json::Value {
    serde_json::json!({"l": field})
}

fn ast_not(filter: serde_json::Value) -> serde_json::Value {
    serde_json::json!({"!": filter})
}

/// Produces the right-associated conjunction emitted by Macro's TypeScript
/// `compileToAst` implementation. Keeping the wire shape aligned makes these
/// requests directly comparable with the open-source web client and backend
/// contract fixtures.
fn ast_and(mut filters: Vec<serde_json::Value>) -> serde_json::Value {
    let Some(last) = filters.pop() else {
        return serde_json::json!({"l": {}});
    };
    filters
        .into_iter()
        .rev()
        .fold(last, |right, left| serde_json::json!({"&": [left, right]}))
}

fn ast_or(mut filters: Vec<serde_json::Value>) -> serde_json::Value {
    let Some(last) = filters.pop() else {
        return serde_json::json!({"l": {}});
    };
    filters
        .into_iter()
        .rev()
        .fold(last, |right, left| serde_json::json!({"|": [left, right]}))
}

fn list_view_id_for_section(section: NavSection) -> Option<&'static str> {
    match section {
        NavSection::Mail => Some("mail"),
        NavSection::Documents => Some("documents"),
        NavSection::Tasks => Some("tasks"),
        NavSection::Agents => Some("agents"),
        NavSection::Calls => Some("calls"),
        NavSection::Files => Some("files"),
        NavSection::Calendar => Some("calendar"),
        _ => None,
    }
}

fn is_mail_list_view(view_id: &str) -> bool {
    view_id == "mail" || view_id.starts_with("mail-")
}

fn is_calls_list_view(view_id: &str) -> bool {
    view_id == "calls" || view_id.starts_with("calls-")
}

fn soup_filter_for_list_view(view_id: &str) -> Option<SoupFilter> {
    if is_mail_list_view(view_id) {
        return Some(SoupFilter::Exact(EntityType::EmailThread));
    }
    match view_id {
        "documents" => Some(SoupFilter::Documents),
        "tasks" => Some(SoupFilter::Tasks),
        "agents" => Some(SoupFilter::Exact(EntityType::AgentSession)),
        view if is_calls_list_view(view) => Some(SoupFilter::Exact(EntityType::CallRecord)),
        "files" => Some(SoupFilter::Exact(EntityType::StaticFile)),
        "calendar" => Some(SoupFilter::Exact(EntityType::CalendarEvent)),
        _ => None,
    }
}

fn is_taggable_list_view(view_id: &str) -> bool {
    is_mail_list_view(view_id)
        || is_calls_list_view(view_id)
        || matches!(view_id, "documents" | "tasks" | "agents" | "files")
}

fn soup_group_by_field(grouping: ListGrouping) -> Option<SoupGroupByField> {
    match grouping {
        ListGrouping::None => None,
        ListGrouping::Date => Some(SoupGroupByField::Date),
        ListGrouping::EntityType => Some(SoupGroupByField::EntityType),
        ListGrouping::Project => Some(SoupGroupByField::Project),
        ListGrouping::TaskStatus => Some(SoupGroupByField::Property {
            property_definition_id: TASK_STATUS_PROPERTY_ID.into(),
            entity_type: Some(SoupPropertyEntityType::Task),
        }),
        ListGrouping::TaskPriority => Some(SoupGroupByField::Property {
            property_definition_id: TASK_PRIORITY_PROPERTY_ID.into(),
            entity_type: Some(SoupPropertyEntityType::Task),
        }),
        ListGrouping::TaskAssignee => Some(SoupGroupByField::Property {
            property_definition_id: TASK_ASSIGNEES_PROPERTY_ID.into(),
            entity_type: Some(SoupPropertyEntityType::Task),
        }),
    }
}

fn grouped_soup_sort(sort: ListSort) -> GroupedSoupSort {
    match sort {
        ListSort::CreatedAsc | ListSort::CreatedDesc => GroupedSoupSort::CreatedAt,
        ListSort::UpdatedAsc | ListSort::UpdatedDesc => GroupedSoupSort::UpdatedAt,
    }
}

fn filtered_group_loading_key(view_id: &str, group_key: &str) -> String {
    format!("{view_id}\0{group_key}")
}

fn cycle_audio_device_id(
    current: Option<&str>,
    input: bool,
    devices: &[audio::AudioDeviceInfo],
) -> Option<String> {
    let mut ids = devices
        .iter()
        .filter(|device| device.matches_input(input))
        .map(|device| (device.desc.name().to_lowercase(), device.id.to_string()))
        .collect::<Vec<_>>();
    ids.sort();
    let ids = ids.into_iter().map(|(_, id)| id).collect::<Vec<_>>();
    next_audio_device_id(current, &ids)
}

fn next_audio_device_id(current: Option<&str>, ids: &[String]) -> Option<String> {
    match current.and_then(|current| ids.iter().position(|id| id == current)) {
        Some(index) if index + 1 < ids.len() => Some(ids[index + 1].clone()),
        Some(_) => None,
        None if current.is_none() => ids.first().cloned(),
        None => None,
    }
}

fn audio_device_label(
    selected_id: Option<&str>,
    input: bool,
    devices: &[audio::AudioDeviceInfo],
) -> String {
    let Some(selected_id) = selected_id else {
        return "System Default".into();
    };
    devices
        .iter()
        .find(|device| device.matches_input(input) && device.id.to_string() == selected_id)
        .map(|device| device.desc.name().to_owned())
        .unwrap_or_else(|| "Unavailable device".into())
}

fn selected_audio_device_is_missing(
    selected_id: Option<&str>,
    input: bool,
    devices: &[audio::AudioDeviceInfo],
) -> bool {
    selected_id.is_some_and(|selected_id| {
        !devices
            .iter()
            .any(|device| device.matches_input(input) && device.id.to_string() == selected_id)
    })
}

fn audio_device_topology(devices: &[audio::AudioDeviceInfo]) -> Vec<(String, bool, bool)> {
    let mut topology = devices
        .iter()
        .map(|device| {
            (
                device.id.to_string(),
                device.matches_input(true),
                device.matches_input(false),
            )
        })
        .collect::<Vec<_>>();
    topology.sort();
    topology
}

#[cfg(target_os = "macos")]
fn camera_device_label(
    selected_id: Option<&str>,
    devices: &[livekit_client::CameraDevice],
) -> String {
    let Some(selected_id) = selected_id else {
        return "System Default".into();
    };
    devices
        .iter()
        .find(|device| device.id == selected_id)
        .map(|device| device.label.clone())
        .unwrap_or_else(|| "Unavailable camera".into())
}

fn apply_audio_device_settings(
    input_device_id: Option<&str>,
    output_device_id: Option<&str>,
    cx: &mut App,
) {
    let settings = serde_json::json!({
        "audio": {
            "experimental.input_audio_device": input_device_id,
            "experimental.output_audio_device": output_device_id,
        }
    })
    .to_string();
    cx.update_global::<settings::SettingsStore, _>(|store, cx| {
        let _ = store.set_user_settings(&settings, cx);
    });
}

fn merge_grouped_inbox_page(
    existing_items: Vec<InboxItem>,
    groups: &mut [SoupGroupMeta],
    page: GroupedInboxGroupPage,
) -> anyhow::Result<Vec<InboxItem>> {
    let mut records = existing_items
        .into_iter()
        .map(|item| (item.id.clone(), item))
        .collect::<HashMap<_, _>>();
    records.extend(page.items.into_iter().map(|item| (item.id.clone(), item)));

    let group = groups
        .iter_mut()
        .find(|group| group.key == page.group.key)
        .context("grouped list page does not match an existing group")?;
    for item_id in page.group.item_ids {
        if !group.item_ids.contains(&item_id) {
            group.item_ids.push(item_id);
        }
    }
    group.label = page.group.label;
    group.display_order = page.group.display_order;
    group.total_count = page.group.total_count;
    group.next_cursor = page.group.next_cursor;

    let mut inserted = HashSet::new();
    let mut ordered = Vec::new();
    for item_id in groups.iter().flat_map(|group| group.item_ids.iter()) {
        if inserted.insert(item_id.clone()) {
            let item = records
                .get(item_id)
                .with_context(|| format!("group referenced missing item {item_id:?}"))?;
            ordered.push(item.clone());
        }
    }
    Ok(ordered)
}

fn filtered_list_soup_request(view_id: &str, state: &ListQueryState) -> serde_json::Value {
    const NIL_UUID: &str = "00000000-0000-0000-0000-000000000000";
    let nil = |field: &str| ast_literal(field, serde_json::json!(NIL_UUID));
    let not_nil = |field: &str| ast_not(nil(field));
    let (sort_method, sort_direction) = state.sort.api_parts();
    let mut request = serde_json::json!({
        "limit": 100,
        "expand": true,
        "sort_method": sort_method,
        "sort_direction": sort_direction,
        "df": nil("id"),
        "calf": nil("id"),
        "ef": nil("ThreadId"),
        "chanf": nil("ChannelId"),
        "cthf": nil("ThreadId"),
        "cf": nil("cid"),
        "pf": nil("pid"),
        "callf": nil("CallId"),
        "fef": nil("id"),
        "ccf": nil("id")
    });
    let filters = request
        .as_object_mut()
        .expect("filtered list request is always an object");
    match view_id {
        view if is_mail_list_view(view) => {
            let (email_view, mut email_filters) = match view {
                "mail-important" => (
                    "inbox",
                    vec![
                        not_nil("ThreadId"),
                        ast_literal("Importance", serde_json::json!(true)),
                        ast_literal("Shared", serde_json::json!("exclude")),
                    ],
                ),
                "mail-noise" => (
                    "inbox",
                    vec![
                        not_nil("ThreadId"),
                        ast_literal("Importance", serde_json::json!(false)),
                        ast_literal("Shared", serde_json::json!("exclude")),
                    ],
                ),
                "mail-calendar" => (
                    "all",
                    vec![
                        not_nil("ThreadId"),
                        ast_literal("CalendarOnly", serde_json::json!(true)),
                        ast_literal("Shared", serde_json::json!("exclude")),
                    ],
                ),
                "mail-drafts" => ("drafts", vec![not_nil("ThreadId")]),
                "mail-sent" => ("sent", vec![not_nil("ThreadId")]),
                "mail-shared" => (
                    "all",
                    vec![
                        not_nil("ThreadId"),
                        ast_literal("Shared", serde_json::json!("only")),
                    ],
                ),
                "mail" | "mail-all" | _ => ("all", vec![not_nil("ThreadId")]),
            };
            if state.read_filter != ReadFilter::All {
                email_filters.push(ast_literal(
                    "NotificationSeen",
                    serde_json::json!(state.read_filter == ReadFilter::Read),
                ));
            }
            if !state.email_link_ids.is_empty() {
                email_filters.push(ast_or(
                    state
                        .email_link_ids
                        .iter()
                        .map(|link_id| ast_literal("Owner", serde_json::json!(link_id)))
                        .collect(),
                ));
            }
            filters.insert("ef".into(), ast_and(email_filters));
            filters.insert("emailView".into(), serde_json::json!(email_view));
        }
        "documents" | "files" => {
            filters.insert(
                "df".into(),
                ast_and(vec![
                    not_nil("id"),
                    ast_not(ast_literal("dst", serde_json::json!("task"))),
                ]),
            );
        }
        "tasks" => {
            filters.insert("df".into(), ast_literal("dst", serde_json::json!("task")));
        }
        "agents" => {
            filters.insert("cf".into(), not_nil("cid"));
        }
        view if is_calls_list_view(view) => match view {
            "calls-missed" => {
                filters.insert(
                    "callf".into(),
                    ast_literal("Status", serde_json::json!("MISSED")),
                );
            }
            "calls-unattended" => {
                filters.insert(
                    "callf".into(),
                    ast_literal("Status", serde_json::json!("UNATTENDED")),
                );
            }
            _ => {
                // Macro's Calls preset intentionally leaves `callf`
                // unconstrained while NIL-filling every other Soup target.
                filters.remove("callf");
            }
        },
        _ => {}
    }

    if !state.tags.is_empty() {
        let tag_filters = state
            .tags
            .iter()
            .map(|tag| {
                serde_json::json!({
                    "l": {
                        "pd": tag.property_definition_id,
                        "v": {"so": tag.option_id}
                    }
                })
            })
            .collect::<Vec<_>>();
        let property_filter = match state.tag_mode {
            TagFilterMode::Any => ast_or(tag_filters),
            TagFilterMode::All => ast_and(tag_filters),
        };
        filters.insert("propf".into(), property_filter);
    }
    request
}

fn unified_search_request(query: &str, state: &ListQueryState) -> UnifiedSearchRequest {
    const NIL_UUID: &str = "00000000-0000-0000-0000-000000000000";
    let people = state.mentioned_people.clone();
    let mentions = people
        .iter()
        .map(|person| {
            if person.starts_with('@') {
                person.clone()
            } else {
                format!("@{person}")
            }
        })
        .collect::<Vec<_>>();
    let mut filters = serde_json::Map::new();

    if !state.tags.is_empty() && !matches!(state.search_scope, SearchScope::Channels) {
        filters.insert(
            "tag_option_ids".into(),
            serde_json::json!(
                state
                    .tags
                    .iter()
                    .map(|tag| tag.option_id.clone())
                    .collect::<Vec<_>>()
            ),
        );
        if state.tag_mode == TagFilterMode::All {
            filters.insert("tag_filter_mode".into(), serde_json::json!("all"));
        }
    }

    if !people.is_empty() {
        filters.insert(
            "document_filters".into(),
            serde_json::json!({"owners": people}),
        );
        filters.insert(
            "email_filters".into(),
            serde_json::json!({"senders": state.mentioned_people}),
        );
        filters.insert(
            "channel_filters".into(),
            serde_json::json!({
                "sender_ids": state.mentioned_people,
                "mentions": mentions,
            }),
        );
        filters.insert(
            "channel_thread_filters".into(),
            serde_json::json!({
                "root_sender_ids": state.mentioned_people,
                "participant_ids": state.mentioned_people,
            }),
        );
        filters.insert(
            "chat_filters".into(),
            serde_json::json!({"owners": state.mentioned_people}),
        );
        filters.insert(
            "call_filters".into(),
            serde_json::json!({"speaker_ids": state.mentioned_people}),
        );
        filters.insert(
            "project_filters".into(),
            serde_json::json!({"owners": state.mentioned_people}),
        );
    }

    let mut exclude = |target: &str, field: &str| {
        filters.insert(target.into(), serde_json::json!({field: [NIL_UUID]}));
    };
    match state.search_scope {
        SearchScope::All => {}
        SearchScope::Documents | SearchScope::Tasks => {
            exclude("calendar_event_filters", "calendar_event_ids");
            exclude("call_filters", "call_ids");
            exclude("channel_filters", "channel_ids");
            exclude("channel_thread_filters", "thread_ids");
            exclude("chat_filters", "chat_ids");
            exclude("crm_company_filters", "company_ids");
            exclude("email_filters", "email_thread_ids");
            exclude("foreign_entity_filters", "ids");
            exclude("project_filters", "project_ids");
            let mut document = serde_json::Map::new();
            if !people.is_empty() {
                document.insert("owners".into(), serde_json::json!(people));
            }
            if state.search_scope == SearchScope::Tasks {
                document.insert("sub_types".into(), serde_json::json!(["task"]));
            }
            filters.insert("document_filters".into(), document.into());
        }
        SearchScope::Email => {
            exclude_all_search_targets_except(&mut filters, "email_filters");
            let mut email = serde_json::Map::new();
            if !people.is_empty() {
                email.insert("senders".into(), serde_json::json!(people));
            }
            filters.insert("email_filters".into(), email.into());
        }
        SearchScope::Channels => {
            exclude_all_search_targets_except(&mut filters, "channel_filters");
            // Keep both channel names/messages and channel-thread matches.
            filters.remove("channel_thread_filters");
            if !people.is_empty() {
                filters.insert(
                    "channel_filters".into(),
                    serde_json::json!({"sender_ids": people, "mentions": mentions}),
                );
                filters.insert(
                    "channel_thread_filters".into(),
                    serde_json::json!({
                        "root_sender_ids": state.mentioned_people,
                        "participant_ids": state.mentioned_people,
                    }),
                );
            } else {
                filters.remove("channel_filters");
            }
        }
        SearchScope::Calls => {
            exclude_all_search_targets_except(&mut filters, "call_filters");
            let mut calls = serde_json::Map::new();
            if !people.is_empty() {
                calls.insert("speaker_ids".into(), serde_json::json!(people));
            }
            filters.insert("call_filters".into(), calls.into());
        }
        SearchScope::Agents => {
            exclude_all_search_targets_except(&mut filters, "chat_filters");
            let mut chats = serde_json::Map::new();
            if !people.is_empty() {
                chats.insert("owners".into(), serde_json::json!(people));
            }
            filters.insert("chat_filters".into(), chats.into());
        }
        SearchScope::Folders => {
            exclude_all_search_targets_except(&mut filters, "project_filters");
            let mut projects = serde_json::Map::new();
            if !people.is_empty() {
                projects.insert("owners".into(), serde_json::json!(people));
            }
            filters.insert("project_filters".into(), projects.into());
        }
    }

    let mut request = serde_json::json!({
        "query": query,
        "match_type": if query.trim().starts_with('"') && query.trim().ends_with('"') {
            "exact"
        } else {
            "partial"
        },
        "search_on": "name_content",
        "include_crm": true
    });
    if !filters.is_empty() {
        request
            .as_object_mut()
            .expect("search request is an object")
            .insert("filters".into(), filters.into());
    }
    serde_json::from_value(request).expect("native search request matches Macro's generated SDK")
}

fn exclude_all_search_targets_except(
    filters: &mut serde_json::Map<String, serde_json::Value>,
    preserved: &str,
) {
    const NIL_UUID: &str = "00000000-0000-0000-0000-000000000000";
    for (target, field) in [
        ("calendar_event_filters", "calendar_event_ids"),
        ("call_filters", "call_ids"),
        ("channel_filters", "channel_ids"),
        ("channel_thread_filters", "thread_ids"),
        ("chat_filters", "chat_ids"),
        ("crm_company_filters", "company_ids"),
        ("document_filters", "document_ids"),
        ("email_filters", "email_thread_ids"),
        ("foreign_entity_filters", "ids"),
        ("project_filters", "project_ids"),
    ] {
        if target != preserved {
            filters.insert(target.into(), serde_json::json!({field: [NIL_UUID]}));
        }
    }
}

fn search_scope_matches(scope: SearchScope, item: &InboxItem) -> bool {
    match scope {
        SearchScope::All => true,
        SearchScope::Documents => {
            item.entity_type == EntityType::Document && item.sub_type.as_deref() != Some("task")
        }
        SearchScope::Tasks => {
            item.entity_type == EntityType::Document && item.sub_type.as_deref() == Some("task")
        }
        SearchScope::Email => item.entity_type == EntityType::EmailThread,
        SearchScope::Channels => {
            matches!(
                item.entity_type,
                EntityType::Channel | EntityType::ChannelMessage
            )
        }
        SearchScope::Calls => item.entity_type == EntityType::CallRecord,
        SearchScope::Agents => item.entity_type == EntityType::AgentSession,
        SearchScope::Folders => item.entity_type == EntityType::Project,
    }
}

fn inbox_soup_request(
    tab: InboxTab,
    read_filter: ReadFilter,
    signal_since: &str,
) -> serde_json::Value {
    const NIL_UUID: &str = "00000000-0000-0000-0000-000000000000";
    let nil = |field: &str| ast_literal(field, serde_json::json!(NIL_UUID));
    let not_nil = |field: &str| ast_not(nil(field));
    let mut request = serde_json::json!({
        "limit": 100,
        "expand": true,
        "sort_method": "updated_at",
        "sort_direction": "desc"
    });
    let filters = request
        .as_object_mut()
        .expect("inbox request is always an object");

    match tab {
        InboxTab::Signal => {
            filters.insert(
                "df".into(),
                ast_and(vec![
                    ast_literal("nd", serde_json::json!(false)),
                    ast_literal("ua", serde_json::json!({"gte": signal_since})),
                ]),
            );
            filters.insert(
                "ef".into(),
                ast_and(vec![
                    ast_literal("NotificationDone", serde_json::json!(false)),
                    ast_literal("Importance", serde_json::json!(true)),
                    ast_literal("Shared", serde_json::json!("exclude")),
                    ast_literal("ua", serde_json::json!({"gte": signal_since})),
                ]),
            );
            filters.insert(
                "chanf".into(),
                ast_literal("NotificationDone", serde_json::json!(false)),
            );
            filters.insert(
                "cthf".into(),
                ast_literal("NotificationDone", serde_json::json!(false)),
            );
            filters.insert(
                "cf".into(),
                ast_and(vec![
                    ast_literal("nd", serde_json::json!(false)),
                    ast_literal("ua", serde_json::json!({"gte": signal_since})),
                ]),
            );
            filters.insert(
                "pf".into(),
                ast_and(vec![
                    ast_literal("nd", serde_json::json!(false)),
                    ast_literal("ua", serde_json::json!({"gte": signal_since})),
                ]),
            );
            filters.insert(
                "fef".into(),
                ast_and(vec![
                    ast_literal("fes", serde_json::json!("github_pull_request")),
                    ast_literal("nd", serde_json::json!(false)),
                    ast_unit("me"),
                ]),
            );
            filters.insert("calf".into(), ast_literal("nd", serde_json::json!(false)));
            filters.insert("remf".into(), ast_unit("inc"));
            filters.insert("callf".into(), nil("CallId"));
            filters.insert("ccf".into(), nil("id"));
            filters.insert("emailView".into(), serde_json::json!("inbox"));
        }
        InboxTab::Noise => {
            filters.insert("df".into(), ast_literal("nd", serde_json::json!(false)));
            filters.insert(
                "ef".into(),
                ast_and(vec![
                    ast_literal("NotificationDone", serde_json::json!(false)),
                    ast_literal("Importance", serde_json::json!(false)),
                    ast_literal("Shared", serde_json::json!("exclude")),
                ]),
            );
            filters.insert(
                "chanf".into(),
                ast_literal("NotificationDone", serde_json::json!(false)),
            );
            filters.insert(
                "cthf".into(),
                ast_literal("NotificationDone", serde_json::json!(false)),
            );
            filters.insert("cf".into(), ast_literal("nd", serde_json::json!(false)));
            filters.insert("pf".into(), ast_literal("nd", serde_json::json!(false)));
            filters.insert("calf".into(), nil("id"));
            filters.insert("callf".into(), nil("CallId"));
            filters.insert("fef".into(), nil("id"));
            filters.insert("ccf".into(), nil("id"));
            filters.insert("emailView".into(), serde_json::json!("inbox"));
        }
        InboxTab::All => {
            filters.insert("df".into(), not_nil("id"));
            filters.insert("calf".into(), nil("id"));
            filters.insert("ef".into(), not_nil("ThreadId"));
            filters.insert("chanf".into(), not_nil("ChannelId"));
            // Macro deliberately keeps channel-thread replies out of this
            // flat feed; they remain available inside their parent channel.
            filters.insert("cthf".into(), nil("ThreadId"));
            filters.insert("cf".into(), not_nil("cid"));
            filters.insert("pf".into(), not_nil("pid"));
            filters.insert(
                "fef".into(),
                ast_and(vec![
                    not_nil("id"),
                    ast_literal("fes", serde_json::json!("github_pull_request")),
                    ast_unit("me"),
                ]),
            );
            filters.insert("ccf".into(), nil("id"));
            filters.insert("emailView".into(), serde_json::json!("all"));
        }
    }
    apply_inbox_read_filter(&mut request, read_filter);
    request
}

fn apply_inbox_read_filter(request: &mut serde_json::Value, read_filter: ReadFilter) {
    let seen = match read_filter {
        ReadFilter::All => return,
        ReadFilter::Unread => false,
        ReadFilter::Read => true,
    };
    let filters = request
        .as_object_mut()
        .expect("inbox request is always an object");
    for (target, field) in [
        ("df", "ns"),
        ("ef", "NotificationSeen"),
        ("chanf", "NotificationSeen"),
        ("cthf", "NotificationSeen"),
        ("cf", "ns"),
        ("pf", "ns"),
        ("fef", "ns"),
    ] {
        if let Some(existing) = filters.remove(target) {
            filters.insert(
                target.into(),
                ast_and(vec![existing, ast_literal(field, serde_json::json!(seen))]),
            );
        }
    }
}

#[cfg(test)]
mod email_compose_tests {
    use super::{
        EmailDraftAttachmentKind, EmailReplyQuote, EmailReplyQuoteKind, append_email_recipient,
        apply_email_recipient_suggestion, email_address_from_identity,
        email_autosave_draft_from_values, email_draft_attachments_from_message,
        email_draft_from_values, email_draft_from_values_with_policy_and_body,
        email_forward_attachments_from_message, email_recipient_typeahead_query,
        email_reply_all_recipients,
    };
    use base64::{Engine as _, engine::general_purpose::URL_SAFE_NO_PAD};

    fn values(to: &str, subject: &str, body: &str) -> Vec<String> {
        vec![
            to.into(),
            subject.into(),
            body.into(),
            "cc@example.com".into(),
            "bcc@example.com".into(),
            "send".into(),
            String::new(),
            "link-1".into(),
        ]
    }

    #[test]
    fn outgoing_email_contains_macro_markdown_plaintext_and_base64url_html() {
        let draft = email_draft_from_values(
            &values("to@example.com", "Subject", "Hello **Macro**\n\n- one"),
            None,
            None,
        )
        .unwrap();

        assert_eq!(
            draft.body_macro.as_deref(),
            Some("Hello **Macro**\n\n- one")
        );
        assert_eq!(draft.body_text.as_deref(), Some("Hello Macro\none"));
        let html = URL_SAFE_NO_PAD
            .decode(draft.body_html.as_deref().unwrap())
            .unwrap();
        let html = String::from_utf8(html).unwrap();
        assert_eq!(
            html,
            "<body><p>Hello <strong>Macro</strong></p>\n<ul>\n<li>one</li>\n</ul>\n</body>"
        );
        assert_eq!(draft.to[0].email, "to@example.com");
        assert_eq!(draft.cc[0].email, "cc@example.com");
        assert_eq!(draft.bcc[0].email, "bcc@example.com");
    }

    #[test]
    fn outgoing_email_preserves_macro_mentions_and_emits_safe_inert_html() {
        let macro_body = concat!(
            "Hello <m-user-mention>",
            r#"{"userId":"macro|nick@example.com","email":"nick@example.com","displayName":"Nick & Co"}"#,
            "</m-user-mention>!"
        );
        let draft = email_draft_from_values_with_policy_and_body(
            &values("to@example.com", "Subject", "Hello @Nick!"),
            None,
            None,
            true,
            Some(macro_body),
            None,
            true,
        )
        .unwrap();

        assert_eq!(draft.body_macro.as_deref(), Some(macro_body));
        assert_eq!(draft.body_text.as_deref(), Some("Hello Nick & Co!"));
        let html = URL_SAFE_NO_PAD
            .decode(draft.body_html.as_deref().unwrap())
            .unwrap();
        let html = String::from_utf8(html).unwrap();
        assert_eq!(
            html,
            concat!(
                "<body><p>Hello <span data-user-mention=\"true\" ",
                "data-user-id=\"macro|nick@example.com\" data-email=\"nick@example.com\" ",
                "data-display-name=\"Nick &amp; Co\">Nick &amp; Co</span>!</p>\n</body>"
            )
        );

        let invalid = concat!(
            "<m-user-mention>",
            r#"{"userId":"","email":"<script>alert(1)</script>"}"#,
            "</m-user-mention>"
        );
        let invalid = email_draft_from_values_with_policy_and_body(
            &values("to@example.com", "Subject", invalid),
            None,
            None,
            true,
            Some(invalid),
            None,
            true,
        )
        .unwrap();
        let html = URL_SAFE_NO_PAD
            .decode(invalid.body_html.as_deref().unwrap())
            .unwrap();
        let html = String::from_utf8(html).unwrap();
        assert!(!html.contains("<script>"));
        assert!(html.contains("&lt;script&gt;"));
        assert!(!html.contains("data-user-mention"));
    }

    #[test]
    fn composer_signature_only_sends_an_explicit_dismissal() {
        let included = email_draft_from_values_with_policy_and_body(
            &values("to@example.com", "Subject", "Hello"),
            None,
            None,
            true,
            None,
            None,
            true,
        )
        .unwrap();
        assert_eq!(included.include_signature, None);

        let omitted = email_draft_from_values_with_policy_and_body(
            &values("to@example.com", "Subject", "Hello"),
            None,
            None,
            true,
            None,
            None,
            false,
        )
        .unwrap();
        assert_eq!(omitted.include_signature, Some(false));
    }

    #[test]
    fn replies_append_safe_quote_html_without_polluting_macro_body() {
        let quote = EmailReplyQuote {
            kind: EmailReplyQuoteKind::Reply,
            sender: "Maya <maya@example.test>".into(),
            date: "2026-08-31 10:00".into(),
            subject: "Status".into(),
            to: "nick@example.test".into(),
            cc: String::new(),
            body: "Original **message** <script>alert(1)</script>".into(),
        };
        let draft = email_draft_from_values_with_policy_and_body(
            &values("maya@example.test", "Re: Status", "Authored reply"),
            Some("thread-1".into()),
            Some("message-1".into()),
            true,
            None,
            Some(&quote),
            true,
        )
        .unwrap();
        assert_eq!(draft.body_macro.as_deref(), Some("Authored reply"));
        assert!(
            draft
                .body_text
                .as_deref()
                .unwrap()
                .contains("On 2026-08-31 10:00, Maya <maya@example.test> wrote:")
        );
        let html = URL_SAFE_NO_PAD
            .decode(draft.body_html.as_deref().unwrap())
            .unwrap();
        let html = String::from_utf8(html).unwrap();
        assert!(html.contains("class=\"macro_quote gmail_quote\""));
        assert!(html.contains("<strong>message</strong>"));
        assert!(!html.contains("<script>"));
        assert!(html.contains("&lt;script&gt;"));
    }

    #[test]
    fn autosave_accepts_meaningful_recipientless_drafts_and_skips_empty_forms() {
        let mut recipientless = values("", "Unfinished subject", "");
        recipientless[3].clear();
        recipientless[4].clear();
        let draft = email_autosave_draft_from_values(&recipientless, None, None, 0)
            .unwrap()
            .unwrap();
        assert!(draft.to.is_empty());
        assert_eq!(draft.subject, "Unfinished subject");

        let mut empty = values("", "", "");
        empty[3].clear();
        empty[4].clear();
        assert!(
            email_autosave_draft_from_values(&empty, None, None, 0)
                .unwrap()
                .is_none()
        );
        assert!(
            email_autosave_draft_from_values(&empty, None, None, 1)
                .unwrap()
                .is_some()
        );

        let mut untouched_reply = values("maya@example.test", "Re: Existing subject", "");
        untouched_reply[3].clear();
        untouched_reply[4].clear();
        assert!(
            email_autosave_draft_from_values(
                &untouched_reply,
                Some("thread-1".into()),
                Some("message-1".into()),
                0,
            )
            .unwrap()
            .is_none()
        );
        untouched_reply[2] = "A real reply".into();
        assert!(
            email_autosave_draft_from_values(
                &untouched_reply,
                Some("thread-1".into()),
                Some("message-1".into()),
                0,
            )
            .unwrap()
            .is_some()
        );
    }

    #[test]
    fn sends_still_require_a_valid_primary_recipient() {
        let error =
            email_draft_from_values(&values("", "Subject", "Body"), None, None).unwrap_err();
        assert_eq!(error.to_string(), "At least one recipient is required");

        let error = email_draft_from_values(&values("not-an-email", "Subject", "Body"), None, None)
            .unwrap_err();
        assert_eq!(error.to_string(), "Invalid email recipient: not-an-email");
    }

    #[test]
    fn recipient_picker_extracts_macro_identities_and_deduplicates_addresses() {
        assert_eq!(
            email_address_from_identity("macro|Maya@example.test").as_deref(),
            Some("Maya@example.test")
        );
        assert_eq!(email_address_from_identity("auth0|opaque-user"), None);

        let mut recipients = "alex@example.test".to_owned();
        assert!(append_email_recipient(&mut recipients, "maya@example.test"));
        assert_eq!(recipients, "alex@example.test, maya@example.test");
        assert!(!append_email_recipient(
            &mut recipients,
            "MAYA@example.test"
        ));
        assert_eq!(recipients, "alex@example.test, maya@example.test");

        let mut partial = "alex@example.test, ma".to_owned();
        assert_eq!(email_recipient_typeahead_query(&partial), "ma");
        assert!(apply_email_recipient_suggestion(
            &mut partial,
            "maya@example.test"
        ));
        assert_eq!(partial, "alex@example.test, maya@example.test");
        assert_eq!(email_recipient_typeahead_query(&partial), "");
        assert!(!apply_email_recipient_suggestion(
            &mut partial,
            "MAYA@example.test"
        ));
    }

    #[test]
    fn reply_all_keeps_sender_primary_and_excludes_the_active_inbox() {
        let message = serde_json::json!({
            "from": {"email": "maya@example.test"},
            "to": [
                {"email": "alex@example.test"},
                {"email_address": "sam@example.test"}
            ],
            "cc": [
                {"emailAddress": "Jordan@example.test"},
                {"email": "SAM@example.test"}
            ]
        });
        let (to, cc) = email_reply_all_recipients(&message, Some("alex@example.test")).unwrap();
        assert_eq!(to, "maya@example.test");
        assert_eq!(cc, "sam@example.test, Jordan@example.test");

        let sent_message = serde_json::json!({
            "from": {"email": "alex@example.test"},
            "to": [{"email": "maya@example.test"}],
            "cc": []
        });
        assert_eq!(
            email_reply_all_recipients(&sent_message, Some("alex@example.test")),
            Some(("maya@example.test".into(), String::new()))
        );
    }

    #[test]
    fn editable_server_drafts_merge_attachment_shapes_without_duplicates() {
        let attachments = email_draft_attachments_from_message(&serde_json::json!({
            "attachmentsDraft": [{
                "id": "attachment-1",
                "fileName": "brief.pdf",
                "size": 42
            }],
            "attachments": [
                {
                    "id": "attachment-1",
                    "filename": "brief.pdf",
                    "sizeBytes": 42
                },
                {
                    "attachment_id": "attachment-2",
                    "file_name": "notes.txt",
                    "size_bytes": 7
                }
            ],
            "attachmentsForwarded": [{
                "attachmentId": "attachment-3",
                "filename": "forwarded.png",
                "sizeBytes": 99
            }]
        }));
        assert_eq!(attachments.len(), 3);
        assert_eq!(attachments[0].id, "attachment-1");
        assert_eq!(attachments[0].name, "brief.pdf");
        assert_eq!(attachments[0].size, 42);
        assert_eq!(attachments[0].kind, EmailDraftAttachmentKind::Uploaded);
        assert_eq!(attachments[1].id, "attachment-2");
        assert_eq!(attachments[1].name, "notes.txt");
        assert_eq!(attachments[1].size, 7);
        assert_eq!(attachments[1].kind, EmailDraftAttachmentKind::Uploaded);
        assert_eq!(attachments[2].id, "attachment-3");
        assert_eq!(attachments[2].kind, EmailDraftAttachmentKind::Forwarded);

        let source = email_forward_attachments_from_message(&serde_json::json!({
            "attachments": [{
                "id": "original-1",
                "filename": "contract.pdf",
                "sizeBytes": 512
            }]
        }));
        assert_eq!(source.len(), 1);
        assert_eq!(source[0].id, "original-1");
        assert_eq!(source[0].name, "contract.pdf");
        assert_eq!(source[0].kind, EmailDraftAttachmentKind::Forwarded);
    }
}

