fn crm_comment_metadata(value: &str) -> Option<serde_json::Value> {
    let users = comma_separated_values(value);
    (!users.is_empty()).then(|| {
        serde_json::json!({
            "mentions": {
                "mentionId": uuid::Uuid::new_v4().to_string(),
                "users": users,
            }
        })
    })
}

fn document_mention_choice_from_inbox(
    item: &InboxItem,
    current_document_id: &str,
) -> Option<DocumentMentionChoice> {
    match item.entity_type {
        EntityType::Document if item.id != current_document_id => {
            let kind = if item.sub_type.as_deref() == Some("task") {
                "Task"
            } else {
                "Document"
            };
            Some(DocumentMentionChoice {
                id: format!("document:{}", item.id),
                label: item.title.clone(),
                detail: if item.subtitle.trim().is_empty() {
                    kind.into()
                } else {
                    format!("{kind} · {}", item.subtitle)
                },
                entity_type: EntityType::Document,
                mention: MacroInlineMention::Document {
                    document_id: item.id.clone(),
                    document_name: item.title.clone(),
                    block_name: String::new(),
                },
            })
        }
        EntityType::CrmContact | EntityType::CrmCompany => {
            let data = item.raw.get("data").unwrap_or(&item.raw);
            let email_or_domain = ["email", "emailAddress", "domain", "website"]
                .into_iter()
                .find_map(|key| data.get(key).and_then(serde_json::Value::as_str))
                .filter(|value| !value.trim().is_empty())
                .map(ToOwned::to_owned)
                .or_else(|| {
                    item.subtitle
                        .split(" · ")
                        .next()
                        .filter(|value| !value.trim().is_empty())
                        .map(ToOwned::to_owned)
                })?;
            let is_company = item.entity_type == EntityType::CrmCompany;
            let kind = if is_company { "Company" } else { "Contact" };
            let source_detail = item.subtitle.trim();
            let detail = if source_detail.is_empty() {
                format!("{kind} · {email_or_domain}")
            } else {
                format!("{kind} · {source_detail}")
            };
            Some(DocumentMentionChoice {
                id: format!("contact:{}", item.id),
                label: item.title.clone(),
                detail,
                entity_type: item.entity_type,
                mention: MacroInlineMention::Contact {
                    contact_id: item.id.clone(),
                    name: item.title.clone(),
                    email_or_domain,
                    is_company,
                },
            })
        }
        _ => None,
    }
}

fn document_mention_choice_rank(mention: &MacroInlineMention) -> u8 {
    match mention {
        MacroInlineMention::User { .. } => 0,
        MacroInlineMention::Document { .. } => 1,
        MacroInlineMention::Contact { .. } => 2,
        MacroInlineMention::Group { .. } => 3,
        MacroInlineMention::Date { .. } => 4,
        MacroInlineMention::Tag { .. } => 5,
    }
}

fn document_mention_matches_query(choice: &DocumentMentionChoice, query: &str) -> bool {
    let query = query.trim().to_lowercase();
    query.is_empty()
        || choice.label.to_lowercase().contains(&query)
        || choice.detail.to_lowercase().contains(&query)
        || choice
            .mention
            .visible_token()
            .to_lowercase()
            .contains(&query)
}

fn entity_link_choice_from_inbox(
    item: &InboxItem,
    source_entity_type: EntityType,
    source_entity_id: &str,
) -> Option<EntityLinkChoice> {
    if item.entity_type == source_entity_type && item.id == source_entity_id {
        return None;
    }
    let wire_type = mention_wire_type_for_entity(item.entity_type)?;
    let kind = match item.entity_type {
        EntityType::Document if item.sub_type.as_deref() == Some("task") => "Task",
        EntityType::Document => "Document",
        EntityType::EmailThread | EntityType::EmailMessage => "Email",
        EntityType::Channel => "Channel",
        EntityType::ChannelMessage => "Message",
        EntityType::CalendarEvent => "Calendar event",
        EntityType::Call | EntityType::CallRecord => "Call",
        EntityType::Chat | EntityType::AgentSession => "Chat",
        EntityType::Project => "Project",
        EntityType::CrmCompany => "Company",
        EntityType::CrmContact => "Contact",
        EntityType::StaticFile | EntityType::ForeignEntity => "File or external entity",
        EntityType::User => "Person",
        EntityType::Skill => "Skill",
        EntityType::Team | EntityType::Reminder => return None,
    };
    let label = if item.title.trim().is_empty() {
        format!("Untitled {kind}")
    } else {
        item.title.clone()
    };
    Some(EntityLinkChoice {
        id: format!("{wire_type}:{}", item.id),
        entity_id: item.id.clone(),
        wire_type: wire_type.into(),
        entity_type: item.entity_type,
        label,
        detail: if item.subtitle.trim().is_empty() {
            kind.into()
        } else {
            format!("{kind} · {}", item.subtitle)
        },
    })
}

fn entity_link_choice_rank(wire_type: &str) -> u8 {
    match wire_type {
        "user" => 0,
        "document" => 1,
        "project" => 2,
        "channel" | "message" => 3,
        "email" => 4,
        "calendar_event" | "call" => 5,
        "chat" => 6,
        "crm_company" | "crm_contact" => 7,
        "foreign" => 8,
        _ => 9,
    }
}

fn entity_link_matches_query(choice: &EntityLinkChoice, query: &str) -> bool {
    let query = query.trim().to_lowercase();
    query.is_empty()
        || choice.label.to_lowercase().contains(&query)
        || choice.detail.to_lowercase().contains(&query)
        || choice.wire_type.to_lowercase().contains(&query)
}

fn property_reference_for_mention_choice(choice: &DocumentMentionChoice) -> Option<String> {
    match &choice.mention {
        MacroInlineMention::User { user_id, .. } => Some(format!("USER:{user_id}")),
        MacroInlineMention::Document { document_id, .. } => Some(format!(
            "{}:{document_id}",
            if choice.detail.starts_with("Task") {
                "TASK"
            } else {
                "DOCUMENT"
            }
        )),
        MacroInlineMention::Contact {
            contact_id,
            is_company: true,
            ..
        } => Some(format!("COMPANY:{contact_id}")),
        _ => None,
    }
}

fn toggle_property_token_value(current: &str, token: &str, multi: bool) -> String {
    if !multi {
        return token.to_owned();
    }
    let mut values = comma_separated_values(current);
    if let Some(index) = values.iter().position(|value| value == token) {
        values.remove(index);
    } else {
        values.push(token.to_owned());
    }
    values.join(", ")
}

fn crm_comment_mention_users(metadata: Option<&serde_json::Value>) -> Vec<String> {
    metadata
        .and_then(|metadata| metadata.get("mentions"))
        .and_then(|mentions| mentions.get("users"))
        .and_then(serde_json::Value::as_array)
        .into_iter()
        .flatten()
        .filter_map(serde_json::Value::as_str)
        .map(ToOwned::to_owned)
        .collect()
}

fn crm_email_soup_request(
    entity_type: EntityType,
    detail: &serde_json::Value,
    preferences: CrmEmailPreferences,
) -> Option<serde_json::Value> {
    const NIL_UUID: &str = "00000000-0000-0000-0000-000000000000";
    let mut body = serde_json::json!({
        "calf": {"l": {"id": NIL_UUID}},
        "df": {"l": {"id": NIL_UUID}},
        "chanf": {"l": {"ChannelId": NIL_UUID}},
        "cthf": {"l": {"ThreadId": NIL_UUID}},
        "cf": {"l": {"cid": NIL_UUID}},
        "pf": {"l": {"pid": NIL_UUID}},
        "callf": {"l": {"CallId": NIL_UUID}},
        "ccf": {"l": {"id": NIL_UUID}},
        "fef": {"l": {"id": NIL_UUID}},
        "emailView": "all",
        "limit": 100,
        "expand": true,
        "sort_method": "updated_at",
        "sort_direction": "desc"
    });
    let object = body.as_object_mut()?;
    let signal_filter = (preferences.signal == CrmEmailSignal::Signal)
        .then(|| serde_json::json!({"l":{"Importance":true}}));

    let target_filter = match entity_type {
        EntityType::CrmCompany => {
            let domains = detail
                .get("domains")
                .and_then(serde_json::Value::as_array)
                .into_iter()
                .flatten()
                .filter_map(|domain| json_text(domain, &["domain"]))
                .filter(|domain| !domain.trim().is_empty())
                .collect::<Vec<_>>();
            if domains.is_empty() {
                return None;
            }
            if preferences.scope == CrmEmailScope::Team {
                object.insert("ecd".into(), serde_json::json!(domains));
                None
            } else {
                email_filter_for_values(
                    domains
                        .into_iter()
                        .map(|domain| serde_json::json!({"Domain":domain})),
                )
            }
        }
        EntityType::CrmContact => {
            let email = json_text(detail, &["email"])?;
            if email.trim().is_empty() {
                return None;
            }
            if preferences.scope == CrmEmailScope::Team {
                object.insert("eca".into(), serde_json::json!([email]));
                None
            } else {
                email_filter_for_values(std::iter::once(serde_json::json!({"Complete":email})))
            }
        }
        _ => return None,
    };

    if let Some(filter) = and_json_filters(target_filter, signal_filter) {
        object.insert("ef".into(), filter);
    }
    Some(body)
}

fn email_filter_for_values(
    values: impl IntoIterator<Item = serde_json::Value>,
) -> Option<serde_json::Value> {
    values
        .into_iter()
        .map(|value| {
            serde_json::json!({
                "|": [
                    {"|": [
                        {"l": {"Sender": value.clone()}},
                        {"l": {"Cc": value.clone()}}
                    ]},
                    {"|": [
                        {"l": {"Bcc": value.clone()}},
                        {"l": {"Recipient": value}}
                    ]}
                ]
            })
        })
        .reduce(|left, right| serde_json::json!({"|":[left, right]}))
}

fn and_json_filters(
    left: Option<serde_json::Value>,
    right: Option<serde_json::Value>,
) -> Option<serde_json::Value> {
    match (left, right) {
        (Some(left), Some(right)) => Some(serde_json::json!({"&":[left, right]})),
        (Some(filter), None) | (None, Some(filter)) => Some(filter),
        (None, None) => None,
    }
}

fn optional_tag_color(value: &str) -> anyhow::Result<Option<String>> {
    let value = value.trim();
    if value.is_empty() {
        return Ok(None);
    }
    let valid = value.len() == 7
        && value.starts_with('#')
        && value[1..].bytes().all(|byte| byte.is_ascii_hexdigit());
    if !valid {
        anyhow::bail!("Tag color must use #RRGGBB format");
    }
    Ok(Some(value.to_ascii_uppercase()))
}

fn tag_editor_update_request(
    original_label: &str,
    original_color: Option<&str>,
    label: &str,
    displayed_color: &str,
) -> anyhow::Result<UpdatePropertyOptionRequest> {
    let label = label.trim();
    if label.is_empty() {
        anyhow::bail!("Tag name is required");
    }
    let color = optional_tag_color(displayed_color)?;
    let displayed_original_color = original_color.unwrap_or(DEFAULT_TAG_COLOR);
    Ok(UpdatePropertyOptionRequest {
        value: (label != original_label.trim()).then(|| label.to_owned()),
        color: (!displayed_color
            .trim()
            .eq_ignore_ascii_case(displayed_original_color))
        .then_some(color),
        display_order: None,
    })
}

fn tag_swatch_color(value: Option<&str>, colors: &macro_theme::MacroColors) -> Hsla {
    value
        .and_then(|value| value.strip_prefix('#'))
        .and_then(|value| u32::from_str_radix(value, 16).ok())
        .map(|value| rgb(value).into())
        .unwrap_or(colors.accent)
}

fn property_input_value(value: &PropertyValue) -> String {
    match value {
        PropertyValue::Empty => String::new(),
        PropertyValue::Boolean(value) => value.to_string(),
        PropertyValue::Number(value) => value.to_string(),
        PropertyValue::String(value) | PropertyValue::Date(value) => value.clone(),
        PropertyValue::SelectOptions(values) | PropertyValue::Links(values) => values.join(", "),
        PropertyValue::EntityReferences(values) => values
            .iter()
            .map(|value| {
                format!(
                    "{}:{}",
                    property_target_wire_type(value.entity_type).unwrap_or("UNKNOWN"),
                    value.entity_id
                )
            })
            .collect::<Vec<_>>()
            .join(", "),
        PropertyValue::Unknown(value) => value.to_string(),
    }
}

