fn remove_inbox_entity(
    collection: &mut NormalizedCollection<InboxItem>,
    entity_type: EntityType,
    entity_id: &str,
) -> bool {
    let matches = collection
        .get(entity_id)
        .is_some_and(|item| item.entity_type == entity_type);
    if matches {
        collection.remove(entity_id);
    }
    matches
}

fn entity_permission_from_api(
    response: macro_api::GetEntityPermissionResponse,
) -> EntityPermission {
    use macro_api::{ApiEntityPermission, GetEntityPermissionResponse, ShareAccessLevel};

    match response {
        GetEntityPermissionResponse::NoAccess => EntityPermission::NoAccess,
        GetEntityPermissionResponse::Access { permission } => match permission {
            ApiEntityPermission::AccessLevel { access_level } => {
                EntityPermission::AccessLevel(match access_level {
                    ShareAccessLevel::View => macro_entity::AccessLevel::View,
                    ShareAccessLevel::Comment => macro_entity::AccessLevel::Comment,
                    ShareAccessLevel::Edit => macro_entity::AccessLevel::Edit,
                    ShareAccessLevel::Owner => macro_entity::AccessLevel::Owner,
                })
            }
            ApiEntityPermission::ChannelViewOnly => EntityPermission::ChannelViewOnly,
            ApiEntityPermission::ChannelRole { role } => {
                EntityPermission::ChannelRole(role.as_str().into())
            }
            ApiEntityPermission::TeamRole { role } => {
                EntityPermission::TeamRole(role.as_str().into())
            }
        },
    }
}

fn entity_access_gate_from_permission(
    entity_type: EntityType,
    permission: Option<&DataState<EntityPermission>>,
) -> EntityAccessGate {
    if permission_target_wire_type(entity_type).is_none() {
        return EntityAccessGate::Allowed;
    }

    match permission {
        Some(DataState::Loaded(permission)) if permission.can_view() => EntityAccessGate::Allowed,
        Some(DataState::Loaded(_)) => EntityAccessGate::Denied,
        Some(DataState::Loading | DataState::Idle) => EntityAccessGate::Checking,
        Some(DataState::Failed(error)) => EntityAccessGate::Failed(error.clone()),
        // Open-entity navigation installs Loading synchronously before a
        // backend-backed view is rendered. A missing entry is reserved for
        // locally synthesized and deterministic visual-test records.
        None => EntityAccessGate::Allowed,
    }
}

fn entity_permission_label(permission: &EntityPermission) -> String {
    match permission {
        EntityPermission::NoAccess => "No access".into(),
        EntityPermission::AccessLevel(level) => format!("{:?} access", level),
        EntityPermission::ChannelViewOnly => "View-only channel".into(),
        EntityPermission::ChannelRole(role) => format!("Channel {role}"),
        EntityPermission::TeamRole(role) => format!("Team {role}"),
    }
}

fn property_value_label(value: &PropertyValue, options: &[macro_entity::PropertyOption]) -> String {
    match value {
        PropertyValue::SelectOptions(ids) => ids
            .iter()
            .map(|id| {
                options
                    .iter()
                    .find(|option| option.id == *id)
                    .map_or_else(|| id.clone(), |option| option.label.clone())
            })
            .collect::<Vec<_>>()
            .join(", "),
        other => {
            let value = property_input_value(other);
            if value.is_empty() {
                "—".into()
            } else {
                value
            }
        }
    }
}

fn property_request_value(
    data_type: &str,
    is_multi_select: bool,
    input: &str,
) -> anyhow::Result<serde_json::Value> {
    let input = input.trim();
    if input.is_empty() {
        return Ok(serde_json::Value::Null);
    }
    match data_type {
        "BOOLEAN" => Ok(serde_json::json!({
            "type": "boolean",
            "value": input.parse::<bool>().map_err(|_| anyhow::anyhow!("Boolean values must be true or false"))?
        })),
        "NUMBER" => Ok(serde_json::json!({
            "type": "number",
            "value": input.parse::<f64>().map_err(|_| anyhow::anyhow!("Enter a valid number"))?
        })),
        "DATE" => Ok(serde_json::json!({"type": "date", "value": input})),
        "STRING" => Ok(serde_json::json!({"type": "string", "value": input})),
        "SELECT_STRING" | "SELECT_NUMBER" | "TAG" => {
            let option_ids = comma_separated_values(input);
            if is_multi_select || option_ids.len() > 1 {
                Ok(serde_json::json!({
                    "type": "multi_select_option",
                    "option_ids": option_ids
                }))
            } else {
                Ok(serde_json::json!({
                    "type": "select_option",
                    "option_id": option_ids[0]
                }))
            }
        }
        "LINK" => {
            let urls = comma_separated_values(input);
            if is_multi_select || urls.len() > 1 {
                Ok(serde_json::json!({"type": "multi_link", "urls": urls}))
            } else {
                Ok(serde_json::json!({"type": "link", "url": urls[0]}))
            }
        }
        "ENTITY" => {
            let references = parse_typed_entity_references(input)?
                .into_iter()
                .map(|(entity_type, entity_id)| {
                    let entity_type = entity_type.to_ascii_uppercase();
                    if !matches!(
                        entity_type.as_str(),
                        "CALENDAR_EVENT"
                            | "CALL_RECORD"
                            | "CHANNEL"
                            | "CHAT"
                            | "COMPANY"
                            | "DOCUMENT"
                            | "PROJECT"
                            | "TASK"
                            | "THREAD"
                            | "USER"
                    ) {
                        anyhow::bail!("Unsupported property entity type: {entity_type}");
                    }
                    Ok(serde_json::json!({
                        "entity_type": entity_type,
                        "entity_id": entity_id
                    }))
                })
                .collect::<anyhow::Result<Vec<_>>>()?;
            if is_multi_select || references.len() > 1 {
                Ok(serde_json::json!({
                    "type": "multi_entity_reference",
                    "references": references
                }))
            } else {
                Ok(serde_json::json!({
                    "type": "entity_reference",
                    "reference": references[0]
                }))
            }
        }
        other => anyhow::bail!("Unsupported property data type: {other}"),
    }
}

fn normalized_property_definition_type(value: &str) -> String {
    value.trim().to_ascii_lowercase().replace(['_', '-'], " ")
}

fn property_definition_supports_multi(value: &str) -> bool {
    let value = normalized_property_definition_type(value);
    value == "link"
        || value == "select string"
        || value == "select number"
        || value == "entity"
        || value.starts_with("entity:")
}

fn property_definition_has_options(value: &str) -> bool {
    matches!(
        normalized_property_definition_type(value).as_str(),
        "select string" | "select number"
    )
}

fn property_definition_request(
    values: &[String],
) -> anyhow::Result<CreatePropertyDefinitionRequest> {
    if values.len() < 6 {
        anyhow::bail!("Property definition form is incomplete");
    }
    let scope = values[1].trim().to_ascii_lowercase();
    if !matches!(scope.as_str(), "user" | "team") {
        anyhow::bail!("Property scope must be user or team");
    }
    let multi = values[3]
        .trim()
        .parse::<bool>()
        .context("Multi value must be true or false")?;
    let raw_kind = values[2].trim();
    let kind = normalized_property_definition_type(raw_kind);
    let specific_type_from_kind = raw_kind
        .strip_prefix("entity:")
        .or_else(|| raw_kind.strip_prefix("ENTITY:"))
        .map(|value| value.trim().to_ascii_uppercase());
    let data_type = match kind.as_str() {
        "boolean" => CreatePropertyDataType::Boolean,
        "date" => CreatePropertyDataType::Date,
        "number" => CreatePropertyDataType::Number,
        "string" => CreatePropertyDataType::String,
        "select string" | "select" => {
            let options = comma_separated_values(&values[4]);
            if options.is_empty() {
                anyhow::bail!("Select properties require at least one option");
            }
            let unique_options = options.iter().collect::<HashSet<_>>();
            if unique_options.len() != options.len() {
                anyhow::bail!("Property options must be unique");
            }
            CreatePropertyDataType::SelectString {
                multi,
                options: options
                    .into_iter()
                    .enumerate()
                    .map(|(index, value)| SelectStringOption {
                        display_order: index as i64,
                        value,
                    })
                    .collect(),
            }
        }
        "select number" => {
            let raw_options = comma_separated_values(&values[4]);
            let unique_options = raw_options.iter().collect::<HashSet<_>>();
            if unique_options.len() != raw_options.len() {
                anyhow::bail!("Property options must be unique");
            }
            let options = raw_options
                .into_iter()
                .enumerate()
                .map(|(index, value)| {
                    Ok(SelectNumberOption {
                        display_order: index as i64,
                        value: value
                            .parse::<f64>()
                            .with_context(|| format!("Invalid numeric option: {value}"))?,
                    })
                })
                .collect::<anyhow::Result<Vec<_>>>()?;
            if options.is_empty() {
                anyhow::bail!("Select properties require at least one option");
            }
            CreatePropertyDataType::SelectNumber { multi, options }
        }
        value if value == "entity" || value.starts_with("entity:") => {
            let specific_type = specific_type_from_kind.or_else(|| {
                (!values[5].trim().is_empty()).then(|| values[5].trim().to_ascii_uppercase())
            });
            if let Some(entity_type) = specific_type.as_deref()
                && !matches!(
                    entity_type,
                    "CALENDAR_EVENT"
                        | "CALL_RECORD"
                        | "CHANNEL"
                        | "CHAT"
                        | "COMPANY"
                        | "DOCUMENT"
                        | "PROJECT"
                        | "TASK"
                        | "THREAD"
                        | "USER"
                )
            {
                anyhow::bail!("Unsupported property entity type: {entity_type}");
            }
            CreatePropertyDataType::Entity {
                multi,
                specific_type,
            }
        }
        "link" => CreatePropertyDataType::Link { multi },
        _ => anyhow::bail!(
            "Property type must be boolean, date, number, string, select string, select number, entity, or link"
        ),
    };
    let display_name = values[0].trim();
    if display_name.is_empty() {
        anyhow::bail!("Property name is required");
    }
    Ok(CreatePropertyDefinitionRequest {
        data_type,
        display_name: display_name.to_owned(),
        scope,
    })
}

fn parse_channel_composer_fields(
    mentions: &str,
    attachments: &str,
) -> anyhow::Result<(Vec<SimpleMention>, Vec<NewChannelAttachment>)> {
    let mentions = parse_typed_entity_references(mentions)?
        .into_iter()
        .map(|(entity_type, entity_id)| SimpleMention {
            entity_id,
            entity_type,
        })
        .collect();
    let attachments = parse_typed_entity_references(attachments)?
        .into_iter()
        .map(|(entity_type, entity_id)| NewChannelAttachment {
            entity_id,
            entity_type,
            height: None,
            width: None,
        })
        .collect();
    Ok((mentions, attachments))
}

fn merged_channel_mentions(existing: &str, references: Vec<SimpleMention>) -> String {
    let mut merged = parse_typed_entity_references(existing)
        .unwrap_or_default()
        .into_iter()
        .collect::<HashSet<_>>();
    merged.extend(
        references
            .into_iter()
            .map(|reference| (reference.entity_type, reference.entity_id)),
    );
    let mut serialized = merged
        .into_iter()
        .map(|(entity_type, entity_id)| format!("{entity_type}:{entity_id}"))
        .collect::<Vec<_>>();
    serialized.sort();
    serialized.join(", ")
}

fn channel_composer_attachments(
    dialog: &MutationDialog,
) -> anyhow::Result<Vec<NewChannelAttachment>> {
    dialog
        .channel_attachments
        .iter()
        .map(|attachment| {
            anyhow::ensure!(
                matches!(attachment.status, ChannelComposerAttachmentStatus::Ready),
                "Finish, retry, or remove {} before sending",
                attachment.name
            );
            let entity_id = attachment
                .entity_id
                .clone()
                .with_context(|| format!("{} has no uploaded entity ID", attachment.name))?;
            Ok(NewChannelAttachment {
                entity_id,
                entity_type: attachment.kind.entity_type().into(),
                height: attachment.height,
                width: attachment.width,
            })
        })
        .collect()
}

fn channel_edit_payload(
    dialog: &MutationDialog,
) -> anyhow::Result<(Vec<SimpleMention>, Vec<String>, Vec<NewChannelAttachment>)> {
    let mentions = parse_typed_entity_references(
        dialog
            .fields
            .get(1)
            .map_or("", |field| field.value.as_str()),
    )?
    .into_iter()
    .map(|(entity_type, entity_id)| SimpleMention {
        entity_id,
        entity_type,
    })
    .collect::<Vec<_>>();
    let (_, advanced_attachments) = parse_channel_composer_fields(
        "",
        dialog
            .fields
            .get(2)
            .map_or("", |field| field.value.as_str()),
    )?;

    let retained_server_ids = dialog
        .channel_attachments
        .iter()
        .filter_map(|attachment| attachment.server_attachment_id.clone())
        .collect::<HashSet<_>>();
    let retained_entity_ids = dialog
        .channel_attachments
        .iter()
        .filter_map(|attachment| attachment.entity_id.clone())
        .chain(
            advanced_attachments
                .iter()
                .map(|attachment| attachment.entity_id.clone()),
        )
        .collect::<HashSet<_>>();
    let attachment_ids_to_delete = dialog
        .channel_original_attachments
        .iter()
        .filter(|attachment| {
            !retained_server_ids.contains(&attachment.id)
                && !retained_entity_ids.contains(&attachment.entity_id)
        })
        .map(|attachment| attachment.id.clone())
        .collect::<Vec<_>>();
    let original_entity_ids = dialog
        .channel_original_attachments
        .iter()
        .map(|attachment| attachment.entity_id.clone())
        .collect::<HashSet<_>>();
    let mut attachments_to_add = dialog
        .channel_attachments
        .iter()
        .filter(|attachment| attachment.server_attachment_id.is_none())
        .map(|attachment| {
            anyhow::ensure!(
                matches!(attachment.status, ChannelComposerAttachmentStatus::Ready),
                "Finish, retry, or remove {} before saving",
                attachment.name
            );
            let entity_id = attachment
                .entity_id
                .clone()
                .with_context(|| format!("{} has no uploaded entity ID", attachment.name))?;
            Ok(NewChannelAttachment {
                entity_id,
                entity_type: attachment.kind.entity_type().into(),
                height: attachment.height,
                width: attachment.width,
            })
        })
        .collect::<anyhow::Result<Vec<_>>>()?;
    attachments_to_add.extend(advanced_attachments);
    attachments_to_add.retain(|attachment| {
        !original_entity_ids.contains(&attachment.entity_id)
            && retained_entity_ids.contains(&attachment.entity_id)
    });
    attachments_to_add.sort_by(|left, right| {
        (&left.entity_type, &left.entity_id).cmp(&(&right.entity_type, &right.entity_id))
    });
    attachments_to_add.dedup_by(|left, right| {
        left.entity_type == right.entity_type && left.entity_id == right.entity_id
    });

    Ok((mentions, attachment_ids_to_delete, attachments_to_add))
}

fn new_agent_session_request(values: &[String]) -> anyhow::Result<CreateAgentSessionRequest> {
    anyhow::ensure!(values.len() >= 4, "Agent creation fields are incomplete");
    let prompt = values[0].trim();
    let repo_url = values[1].trim();
    let workspace = values[2].trim();
    let bot_id = values[3].trim();

    if workspace.is_empty() {
        anyhow::ensure!(
            !prompt.is_empty(),
            "Managed sessions require an initial prompt"
        );
        anyhow::ensure!(
            bot_id.is_empty(),
            "External bot IDs may only be used with an external workspace"
        );
        return Ok(CreateAgentSessionRequest {
            bot_id: None,
            owner: None,
            prompt: Some(prompt.to_owned()),
            repo_url: (!repo_url.is_empty()).then(|| repo_url.to_owned()),
            thread: None,
            workspace: None,
        });
    }

    anyhow::ensure!(
        prompt.is_empty(),
        "External sessions receive their first prompt from the external runtime"
    );
    anyhow::ensure!(
        workspace.starts_with('/'),
        "External workspaces must be absolute paths"
    );
    anyhow::ensure!(!bot_id.is_empty(), "External sessions require a bot ID");
    Ok(CreateAgentSessionRequest {
        bot_id: Some(bot_id.to_owned()),
        owner: None,
        prompt: None,
        repo_url: (!repo_url.is_empty()).then(|| repo_url.to_owned()),
        thread: None,
        workspace: Some(workspace.to_owned()),
    })
}

fn agent_entity_context_prompt(
    entity_type: EntityType,
    entity_id: &str,
    entity_name: &str,
) -> String {
    format!(
        "Review the Macro {entity_type} \"{entity_name}\" (entity ID {entity_id}). Use the authoritative Macro entity, its linked records, comments, properties, and workspace context to answer my question:\n\n"
    )
}

fn parse_typed_entity_references(value: &str) -> anyhow::Result<Vec<(String, String)>> {
    comma_separated_values(value)
        .into_iter()
        .map(|reference| {
            let Some((entity_type, entity_id)) = reference.split_once(':') else {
                anyhow::bail!("Entity references must use TYPE:ID format: {reference}");
            };
            if entity_type.trim().is_empty() || entity_id.trim().is_empty() {
                anyhow::bail!("Entity references must use TYPE:ID format: {reference}");
            }
            Ok((entity_type.trim().to_owned(), entity_id.trim().to_owned()))
        })
        .collect()
}

fn parse_optional_entity_reference(value: &str) -> anyhow::Result<Option<(String, String)>> {
    let references = parse_typed_entity_references(value)?;
    if references.len() > 1 {
        anyhow::bail!("A reminder can attach to only one entity");
    }
    Ok(references.into_iter().next())
}

fn parse_reminder_schedule(
    schedule_type: &str,
    value: &str,
    timezone: &str,
) -> anyhow::Result<ReminderSchedule> {
    match schedule_type.trim().to_ascii_lowercase().as_str() {
        "once" => Ok(ReminderSchedule::Once {
            remind_at: value.trim().to_owned(),
        }),
        "recurring" => {
            if timezone.trim().is_empty() {
                anyhow::bail!("Recurring reminders require a timezone");
            }
            Ok(ReminderSchedule::Recurring {
                cron: value.trim().to_owned(),
                timezone: timezone.trim().to_owned(),
            })
        }
        _ => anyhow::bail!("Schedule type must be once or recurring"),
    }
}

fn reminder_schedule_label(schedule: &ReminderSchedule) -> String {
    match schedule {
        ReminderSchedule::Once { remind_at } => format!("Once · {}", short_timestamp(remind_at)),
        ReminderSchedule::Recurring { cron, timezone } => {
            format!("Recurring · {cron} · {timezone}")
        }
    }
}

fn entity_type_from_wire(value: &str) -> EntityType {
    match value {
        "chat" => EntityType::Chat,
        "channel" => EntityType::Channel,
        "channel_message" => EntityType::ChannelMessage,
        "document" => EntityType::Document,
        "project" => EntityType::Project,
        "email_thread" => EntityType::EmailThread,
        "calendar_event" => EntityType::CalendarEvent,
        "call" => EntityType::CallRecord,
        "crm_company" => EntityType::CrmCompany,
        "crm_contact" => EntityType::CrmContact,
        "reminder" => EntityType::Reminder,
        "skill" => EntityType::Skill,
        "agent_session" => EntityType::AgentSession,
        "static_file" => EntityType::StaticFile,
        "user" => EntityType::User,
        _ => EntityType::ForeignEntity,
    }
}

fn notification_title(notification: &macro_api::MacroNotification) -> String {
    let metadata = &notification.notification_metadata;
    json_first_text(
        metadata,
        &[
            &["content", "subject"],
            &["content", "summary"],
            &["content", "description"],
            &["content", "channelName"],
            &["content", "documentName"],
            &["subject"],
            &["summary"],
            &["description"],
        ],
    )
    .unwrap_or_else(|| notification.notification_event_type.replace('_', " "))
}

#[derive(Debug, Clone, Copy)]
struct ShortcutSpec {
    id: &'static str,
    label: &'static str,
    default: &'static str,
    alternate: &'static str,
}

fn palette_commands(can_close_tab: bool, can_reopen_tab: bool) -> Vec<PaletteCommand> {
    let mut commands = vec![
        PaletteCommand {
            label: "Toggle sidebar",
            keywords: "show hide navigation layout",
            shortcut: "⌘B",
            kind: PaletteCommandKind::ToggleSidebar,
        },
        PaletteCommand {
            label: "Navigate back",
            keywords: "history previous location",
            shortcut: "⌘[",
            kind: PaletteCommandKind::NavigateBack,
        },
        PaletteCommand {
            label: "Navigate forward",
            keywords: "history next location",
            shortcut: "⌘]",
            kind: PaletteCommandKind::NavigateForward,
        },
        PaletteCommand {
            label: "New document",
            keywords: "create file markdown task",
            shortcut: "⌘N",
            kind: PaletteCommandKind::NewDocument,
        },
    ];
    if can_close_tab {
        commands.extend([
            PaletteCommand {
                label: "Close active entity tab",
                keywords: "close remove pane",
                shortcut: "⌘W",
                kind: PaletteCommandKind::CloseActiveTab,
            },
            PaletteCommand {
                label: "Select next entity tab",
                keywords: "cycle switch tab right",
                shortcut: "⌃Tab",
                kind: PaletteCommandKind::SelectNextTab,
            },
            PaletteCommand {
                label: "Select previous entity tab",
                keywords: "cycle switch tab left",
                shortcut: "⌃⇧Tab",
                kind: PaletteCommandKind::SelectPreviousTab,
            },
            PaletteCommand {
                label: "Toggle detail fullscreen",
                keywords: "zoom split pane preview fullscreen tab",
                shortcut: "⌘⇧Enter",
                kind: PaletteCommandKind::ToggleDetailFullscreen,
            },
            PaletteCommand {
                label: "Copy active task branch name",
                keywords: "github git task branch clipboard",
                shortcut: "⌘⇧B",
                kind: PaletteCommandKind::CopyTaskBranchName,
            },
        ]);
    }
    if can_reopen_tab {
        commands.push(PaletteCommand {
            label: "Reopen closed entity tab",
            keywords: "restore undo close tab",
            shortcut: "⌘⇧T",
            kind: PaletteCommandKind::ReopenClosedTab,
        });
    }
    commands.extend(NavSection::all().iter().copied().map(|section| {
        let keywords = match section {
            NavSection::Home => "home start dashboard",
            NavSection::Inbox => "inbox signal noise notifications",
            NavSection::Search => "search find query",
            NavSection::Mail => "mail email gmail",
            NavSection::Channels => "channels messages chat dm",
            NavSection::Documents => "documents docs markdown",
            NavSection::Tasks => "tasks todo assignments",
            NavSection::Agents => "agents ai sessions",
            NavSection::Calls => "calls meetings recordings",
            NavSection::CRM => "crm customers companies contacts",
            NavSection::Files => "files folders uploads",
            NavSection::Calendar => "calendar events schedule",
            NavSection::Activity => "activity history updates",
            NavSection::Reminders => "reminders alerts",
            NavSection::Integrations => "integrations tools connections",
            NavSection::Settings => "settings preferences account",
        };
        PaletteCommand {
            label: section.label(),
            keywords,
            shortcut: "",
            kind: PaletteCommandKind::Section(section),
        }
    }));
    commands
}

fn filtered_palette_commands(
    query: &str,
    can_close_tab: bool,
    can_reopen_tab: bool,
) -> Vec<PaletteCommand> {
    let query = query.trim().to_lowercase();
    let tokens = query.split_whitespace().collect::<Vec<_>>();
    palette_commands(can_close_tab, can_reopen_tab)
        .into_iter()
        .filter(|command| {
            if tokens.is_empty() {
                return true;
            }
            let haystack = format!(
                "{} {}",
                command.label.to_lowercase(),
                command.keywords.to_lowercase()
            );
            tokens.iter().all(|token| haystack.contains(token))
        })
        .collect()
}

fn cycled_tab_index(
    tab_count: usize,
    active_index: Option<usize>,
    direction: isize,
) -> Option<usize> {
    if tab_count == 0 {
        return None;
    }
    Some(
        match (
            active_index.filter(|index| *index < tab_count),
            direction.is_negative(),
        ) {
            (Some(index), false) => (index + 1) % tab_count,
            (Some(index), true) => (index + tab_count - 1) % tab_count,
            (None, false) => 0,
            (None, true) => tab_count - 1,
        },
    )
}

