fn configured_shortcut<'a>(
    overrides: &'a HashMap<String, String>,
    id: &str,
    default: &'a str,
) -> Option<&'a str> {
    match overrides.get(id) {
        Some(value) if value.is_empty() => None,
        Some(value) if shortcut_is_valid(value) => Some(value.as_str()),
        Some(_) | None => Some(default),
    }
}

fn shortcut_is_valid(value: &str) -> bool {
    !value.is_empty()
        && value
            .split_whitespace()
            .all(|keystroke| gpui::Keystroke::parse(keystroke).is_ok())
}

fn macro_key_bindings(overrides: &HashMap<String, String>) -> Vec<KeyBinding> {
    let mut bindings = Vec::new();
    macro_rules! bind {
        ($id:literal, $default:literal, $action:expr) => {
            if let Some(keys) = configured_shortcut(overrides, $id, $default) {
                bindings.push(KeyBinding::new(keys, $action, None));
            }
        };
    }
    bind!("toggle_sidebar", "cmd-b", ToggleSidebar);
    bind!("navigate_back", "cmd-[", NavigateBack);
    bind!("navigate_forward", "cmd-]", NavigateForward);
    bind!("command_palette", "cmd-k", OpenCommandPalette);
    bind!("close_tab", "cmd-w", CloseActiveTab);
    bind!("reopen_tab", "cmd-shift-t", ReopenClosedTab);
    bind!("next_tab", "ctrl-tab", SelectNextTab);
    bind!("previous_tab", "ctrl-shift-tab", SelectPreviousTab);
    bind!(
        "toggle_detail_fullscreen",
        "cmd-shift-enter",
        ToggleDetailFullscreen
    );
    bind!("inbox", "cmd-1", NavigateToInbox);
    bind!("search", "cmd-shift-f", NavigateToSearch);
    bind!("mail", "cmd-2", NavigateToMail);
    bind!("channels", "cmd-3", NavigateToChannels);
    bind!("documents", "cmd-4", NavigateToDocuments);
    bind!("tasks", "cmd-5", NavigateToTasks);
    bind!("agents", "cmd-6", NavigateToAgents);
    bind!("crm", "cmd-7", NavigateToCRM);
    bind!("new_document", "cmd-n", NewDocument);
    bind!("copy_task_branch_name", "cmd-shift-b", CopyTaskBranchName);
    bindings.extend([
        KeyBinding::new("escape", CloseCommandPalette, None),
        KeyBinding::new("cmd-q", Quit, None),
        KeyBinding::new("tab", FocusNextControl, Some("MacroApp")),
        KeyBinding::new("shift-tab", FocusPreviousControl, Some("MacroApp")),
        KeyBinding::new("enter", RunUnifiedSearch, Some("MacroSearch && Editor")),
        KeyBinding::new(
            "shift-enter",
            OpenSearchResultSplit,
            Some("MacroSearch && Editor"),
        ),
        KeyBinding::new(
            "down",
            SelectNextSearchResult,
            Some("MacroSearch && Editor"),
        ),
        KeyBinding::new(
            "up",
            SelectPreviousSearchResult,
            Some("MacroSearch && Editor"),
        ),
        KeyBinding::new("backspace", editor::actions::Backspace, Some("Editor")),
        KeyBinding::new("delete", editor::actions::Delete, Some("Editor")),
        KeyBinding::new("enter", editor::actions::Newline, Some("Editor")),
        KeyBinding::new("tab", editor::actions::Tab, Some("Editor")),
        KeyBinding::new("shift-tab", editor::actions::Backtab, Some("Editor")),
        KeyBinding::new("left", editor::actions::MoveLeft, Some("Editor")),
        KeyBinding::new("right", editor::actions::MoveRight, Some("Editor")),
        KeyBinding::new("up", zed_actions::editor::MoveUp, Some("Editor")),
        KeyBinding::new("down", zed_actions::editor::MoveDown, Some("Editor")),
        KeyBinding::new("shift-left", editor::actions::SelectLeft, Some("Editor")),
        KeyBinding::new("shift-right", editor::actions::SelectRight, Some("Editor")),
        KeyBinding::new("shift-up", editor::actions::SelectUp, Some("Editor")),
        KeyBinding::new("shift-down", editor::actions::SelectDown, Some("Editor")),
        KeyBinding::new("cmd-a", editor::actions::SelectAll, Some("Editor")),
        KeyBinding::new("cmd-c", editor::actions::Copy, Some("Editor")),
        KeyBinding::new("cmd-x", editor::actions::Cut, Some("Editor")),
        KeyBinding::new("cmd-v", editor::actions::Paste, Some("Editor")),
        KeyBinding::new("cmd-z", editor::actions::Undo, Some("Editor")),
        KeyBinding::new("cmd-shift-z", editor::actions::Redo, Some("Editor")),
    ]);
    bindings
}

fn rebind_macro_keys(overrides: &HashMap<String, String>, cx: &mut App) {
    cx.clear_key_bindings();
    cx.bind_keys(macro_key_bindings(overrides));
}

