    #[test]
    fn channel_edit_payload_diffs_storage_attachment_ids_and_preserves_typed_additions() {
        let original_image = ChannelAttachment {
            id: "attachment-image".into(),
            entity_id: "image-1".into(),
            entity_type: "static/image".into(),
            name: "launch.png".into(),
        };
        let original_document = ChannelAttachment {
            id: "attachment-document".into(),
            entity_id: "document-1".into(),
            entity_type: "document".into(),
            name: "brief.pdf".into(),
        };
        let mut dialog = MutationDialog::new(
            "Edit message",
            "Save changes",
            MutationKind::EditChannelMessage {
                channel_id: "channel-1".into(),
                message_id: "message-1".into(),
            },
            vec![
                super::MacroApp::mutation_field("Message", "Updated", true),
                super::MacroApp::mutation_field("Mentions", "user:user-2", false),
                super::MacroApp::mutation_field("Attachments", "document:document-3", false),
            ],
        );
        dialog.channel_original_attachments =
            vec![original_image.clone(), original_document.clone()];
        dialog.channel_attachments = vec![
            ChannelComposerAttachmentState {
                local_id: "existing-image".into(),
                server_attachment_id: Some(original_image.id),
                entity_id: Some(original_image.entity_id),
                name: original_image.name,
                kind: ChannelComposerAttachmentKind::Image,
                source_path: PathBuf::new(),
                preview_path: None,
                width: None,
                height: None,
                status: ChannelComposerAttachmentStatus::Ready,
            },
            ChannelComposerAttachmentState {
                local_id: "new-video".into(),
                server_attachment_id: None,
                entity_id: Some("video-2".into()),
                name: "demo.mp4".into(),
                kind: ChannelComposerAttachmentKind::Video,
                source_path: PathBuf::from("demo.mp4"),
                preview_path: None,
                width: Some(1920),
                height: Some(1080),
                status: ChannelComposerAttachmentStatus::Ready,
            },
        ];

        let (mentions, deleted, added) = channel_edit_payload(&dialog).unwrap();
        assert_eq!(mentions[0].entity_id, "user-2");
        assert_eq!(deleted, ["attachment-document"]);
        assert_eq!(added.len(), 2);
        assert!(added.iter().any(|attachment| {
            attachment.entity_type == "static/video"
                && attachment.entity_id == "video-2"
                && attachment.width == Some(1920)
                && attachment.height == Some(1080)
        }));
        assert!(added.iter().any(|attachment| {
            attachment.entity_type == "document" && attachment.entity_id == "document-3"
        }));
    }

