    #[test]
    fn entity_access_gate_fails_closed_after_permission_loading_begins() {
        assert_eq!(
            entity_access_gate_from_permission(EntityType::Document, Some(&DataState::Loading)),
            EntityAccessGate::Checking
        );
        assert_eq!(
            entity_access_gate_from_permission(
                EntityType::Document,
                Some(&DataState::Loaded(EntityPermission::NoAccess)),
            ),
            EntityAccessGate::Denied
        );
        assert_eq!(
            entity_access_gate_from_permission(
                EntityType::Document,
                Some(&DataState::Failed("permission service unavailable".into())),
            ),
            EntityAccessGate::Failed("permission service unavailable".into())
        );
        assert_eq!(
            entity_access_gate_from_permission(
                EntityType::Document,
                Some(&DataState::Loaded(EntityPermission::AccessLevel(
                    AccessLevel::View,
                ))),
            ),
            EntityAccessGate::Allowed
        );
        assert_eq!(
            entity_access_gate_from_permission(EntityType::CalendarEvent, None),
            EntityAccessGate::Allowed
        );
    }

    #[test]
    fn channel_deep_link_resolves_an_oversized_thread_target_index() {
        let reply_ids = (0..128)
            .map(|index| format!("reply-{index}"))
            .collect::<Vec<_>>();
        let scroll_handle = UniformListScrollHandle::new();
        let target = ChannelMessageTarget {
            channel_id: "channel-product".into(),
            message_id: "thread-launch".into(),
            reply_id: Some("reply-117".into()),
        };

        assert_eq!(
            channel_target_reply_index(
                Some(&target),
                "channel-product",
                "thread-launch",
                reply_ids.iter().map(String::as_str),
            ),
            Some(117)
        );
        assert_eq!(
            scroll_channel_thread_to_target(
                &scroll_handle,
                Some(&target),
                "channel-product",
                "thread-launch",
                reply_ids.iter().map(String::as_str),
            ),
            Some(117)
        );
        let deferred_scroll = scroll_handle
            .0
            .borrow()
            .deferred_scroll_to_item
            .expect("deep-link target should queue a native list scroll");
        assert_eq!(deferred_scroll.item_index, 117);
        assert_eq!(deferred_scroll.strategy, ScrollStrategy::Center);
        assert!(deferred_scroll.scroll_strict);
    }

    #[test]
    fn channel_deep_link_resolves_the_root_in_rendered_timeline_order() {
        let message_ids = (0..128)
            .map(|index| format!("message-{index}"))
            .collect::<Vec<_>>();
        let target = ChannelMessageTarget {
            channel_id: "channel-product".into(),
            message_id: "message-10".into(),
            reply_id: Some("reply-117".into()),
        };

        assert_eq!(
            channel_target_message_index(
                Some(&target),
                "channel-product",
                message_ids.iter().rev().map(String::as_str),
            ),
            Some(117)
        );
        assert_eq!(
            channel_target_message_index(
                Some(&target),
                "channel-design",
                message_ids.iter().rev().map(String::as_str),
            ),
            None
        );
    }

