    #[test]
    fn canvas_keyboard_contract_matches_macro_primary_shortcuts() {
        let secondary = Modifiers::secondary_key();
        assert_eq!(
            canvas_keyboard_command("a", secondary),
            Some(CanvasKeyboardCommand::SelectAll)
        );
        assert_eq!(
            canvas_keyboard_command("z", secondary),
            Some(CanvasKeyboardCommand::Undo)
        );
        assert_eq!(
            canvas_keyboard_command(
                "z",
                Modifiers {
                    shift: true,
                    ..secondary
                },
            ),
            Some(CanvasKeyboardCommand::Redo)
        );
        assert_eq!(
            canvas_keyboard_command(
                "right",
                Modifiers {
                    shift: true,
                    ..Modifiers::default()
                },
            ),
            Some(CanvasKeyboardCommand::Nudge(CanvasPoint {
                x: 10.0,
                y: 0.0
            }))
        );
        assert_eq!(
            canvas_keyboard_command("h", Modifiers::default()),
            Some(CanvasKeyboardCommand::Tool(CanvasTool::Hand))
        );
        assert_eq!(
            canvas_keyboard_command("x", Modifiers::default()),
            Some(CanvasKeyboardCommand::Tool(CanvasTool::Connector))
        );
        assert_eq!(
            canvas_keyboard_command("t", Modifiers::default()),
            Some(CanvasKeyboardCommand::Tool(CanvasTool::Text))
        );
        assert_eq!(
            canvas_keyboard_command("r", Modifiers::default()),
            Some(CanvasKeyboardCommand::Tool(CanvasTool::Rectangle))
        );
        assert_eq!(
            canvas_keyboard_command("z", Modifiers::default()),
            Some(CanvasKeyboardCommand::Tool(CanvasTool::ZoomIn))
        );
        assert_eq!(
            canvas_keyboard_command(
                "z",
                Modifiers {
                    alt: true,
                    ..Modifiers::default()
                }
            ),
            Some(CanvasKeyboardCommand::Tool(CanvasTool::ZoomOut))
        );
        assert_eq!(
            canvas_keyboard_command(
                "]",
                Modifiers {
                    alt: true,
                    ..Modifiers::default()
                }
            ),
            Some(CanvasKeyboardCommand::ArrangeForward)
        );
        assert_eq!(canvas_keyboard_command("q", Modifiers::default()), None);
    }

