    #[test]
    fn document_mention_picker_builds_typed_choices_and_excludes_self() {
        let item = |id: &str,
                    entity_type: EntityType,
                    sub_type: Option<&str>,
                    title: &str,
                    subtitle: &str| InboxItem {
            id: id.into(),
            tag: entity_type.to_string(),
            sub_type: sub_type.map(str::to_owned),
            entity_type,
            title: title.into(),
            subtitle: subtitle.into(),
            timestamp: "2026-09-01T00:00:00Z".into(),
            raw: serde_json::Value::Null,
        };
        assert!(
            document_mention_choice_from_inbox(
                &item(
                    "document-current",
                    EntityType::Document,
                    None,
                    "Current",
                    ""
                ),
                "document-current"
            )
            .is_none()
        );
        let task = document_mention_choice_from_inbox(
            &item(
                "task-launch",
                EntityType::Document,
                Some("task"),
                "Ship native mentions",
                "In progress",
            ),
            "document-current",
        )
        .unwrap();
        assert_eq!(task.detail, "Task · In progress");
        assert!(matches!(
            &task.mention,
            MacroInlineMention::Document { document_id, .. } if document_id == "task-launch"
        ));

        let company = document_mention_choice_from_inbox(
            &item(
                "company-northwind",
                EntityType::CrmCompany,
                None,
                "Northwind Labs",
                "northwind.example.test · Analytics",
            ),
            "document-current",
        )
        .unwrap();
        assert!(matches!(
            &company.mention,
            MacroInlineMention::Contact {
                email_or_domain,
                is_company: true,
                ..
            } if email_or_domain == "northwind.example.test"
        ));
        assert!(
            document_mention_choice_rank(&MacroInlineMention::User {
                user_id: "user-1".into(),
                email: "user@example.com".into(),
                display_name: "User".into(),
            }) < document_mention_choice_rank(&company.mention)
        );
        assert!(document_mention_matches_query(&task, "native"));
        assert!(document_mention_matches_query(&task, "TASK"));
        assert!(document_mention_matches_query(&company, "analytics"));
        assert!(!document_mention_matches_query(&company, "maya"));
        assert_eq!(
            property_reference_for_mention_choice(&task).as_deref(),
            Some("TASK:task-launch")
        );
        assert_eq!(
            property_reference_for_mention_choice(&company).as_deref(),
            Some("COMPANY:company-northwind")
        );
        assert_eq!(
            toggle_property_token_value("alpha", "beta", true),
            "alpha, beta"
        );
        assert_eq!(
            toggle_property_token_value("alpha, beta", "alpha", true),
            "beta"
        );
        assert_eq!(toggle_property_token_value("alpha", "beta", false), "beta");

        let link_choice = entity_link_choice_from_inbox(
            &item(
                "task-launch",
                EntityType::Document,
                Some("task"),
                "Ship native mentions",
                "In progress",
            ),
            EntityType::Document,
            "document-current",
        )
        .unwrap();
        assert_eq!(link_choice.entity_id, "task-launch");
        assert_eq!(link_choice.wire_type, "document");
        assert!(entity_link_matches_query(&link_choice, "TASK"));
        assert!(
            entity_link_choice_from_inbox(
                &item(
                    "document-current",
                    EntityType::Document,
                    None,
                    "Current",
                    ""
                ),
                EntityType::Document,
                "document-current",
            )
            .is_none()
        );
        assert_eq!(
            entity_mention_request(
                EntityType::Document,
                "document-current",
                &link_choice.entity_id,
                &link_choice.wire_type,
            )
            .unwrap(),
            CreateEntityMentionRequest {
                entity_id: "task-launch".into(),
                entity_type: "document".into(),
                source_entity_id: "document-current".into(),
                source_entity_type: "document".into(),
            }
        );
        assert!(
            entity_mention_request(
                EntityType::Reminder,
                "reminder-current",
                "task-launch",
                "document",
            )
            .is_err()
        );
        assert_eq!(
            canvas_mention_wire_type(link_choice.entity_type),
            Some("document")
        );
        assert!(canvas_mention_wire_type(EntityType::CrmCompany).is_none());
        assert!(matches!(
            canvas_entity_kind(&[
                "document".into(),
                "task-launch".into(),
                "details".into(),
                "ignored search query".into(),
            ])
            .unwrap(),
            CanvasNodeKind::EntityMention {
                entity_type: CanvasMentionType::Document,
                file,
                subpath: Some(subpath),
                ..
            } if file == "task-launch" && subpath == "details"
        ));
    }

    #[test]
    fn tag_editor_uses_macro_palette_and_only_patches_changed_values() {
        assert_eq!(TAG_COLOR_OPTIONS.len(), 12);
        assert_eq!(TAG_COLOR_OPTIONS.last(), Some(&("Gray", DEFAULT_TAG_COLOR)));

        let unchanged =
            tag_editor_update_request("Launch", None, "Launch", DEFAULT_TAG_COLOR).unwrap();
        assert_eq!(unchanged, UpdatePropertyOptionRequest::default());

        let recolored =
            tag_editor_update_request("Launch", Some("#E5484D"), "Launch", "#0091ff").unwrap();
        assert_eq!(recolored.value, None);
        assert_eq!(recolored.color, Some(Some("#0091FF".into())));

        let renamed =
            tag_editor_update_request("Launch", Some("#E5484D"), "Launch plan", "#E5484D").unwrap();
        assert_eq!(renamed.value.as_deref(), Some("Launch plan"));
        assert_eq!(renamed.color, None);
        assert!(tag_editor_update_request("Launch", None, "  ", DEFAULT_TAG_COLOR).is_err());
    }

