    #[test]
    fn command_palette_filters_keywords_and_hides_inapplicable_tab_actions() {
        let commands = filtered_palette_commands("gmail", false, false);
        assert_eq!(commands.len(), 1);
        assert_eq!(
            commands[0].kind,
            PaletteCommandKind::Section(NavSection::Mail)
        );

        let no_tabs = filtered_palette_commands("tab", false, false);
        assert!(no_tabs.is_empty());
        let tabs = filtered_palette_commands("tab", true, true);
        assert!(
            tabs.iter()
                .any(|command| command.kind == PaletteCommandKind::CloseActiveTab)
        );
        assert!(
            tabs.iter()
                .any(|command| command.kind == PaletteCommandKind::ReopenClosedTab)
        );
        assert!(
            tabs.iter()
                .any(|command| command.kind == PaletteCommandKind::SelectNextTab)
        );
        assert!(
            tabs.iter()
                .any(|command| command.kind == PaletteCommandKind::SelectPreviousTab)
        );
        assert!(
            tabs.iter()
                .any(|command| command.kind == PaletteCommandKind::ToggleDetailFullscreen)
        );
        let history = filtered_palette_commands("history", false, false);
        assert!(
            history
                .iter()
                .any(|command| command.kind == PaletteCommandKind::NavigateBack)
        );
        assert!(
            history
                .iter()
                .any(|command| command.kind == PaletteCommandKind::NavigateForward)
        );
        assert_eq!(
            safe_download_filename("../../quarterly/report.pdf", "attachment"),
            "report.pdf"
        );
        assert_eq!(safe_download_filename("...", "attachment"), "attachment");
    }

