    #[test]
    fn crm_list_columns_default_to_macro_fields_and_toggle_independently() {
        let mut columns = CrmListColumns::default();
        let full_width = crm_list_min_width(&columns);
        assert!(
            CrmListColumn::ALL
                .into_iter()
                .all(|column| columns.is_visible(column))
        );

        columns.toggle(CrmListColumn::Owner);
        assert!(columns.stage);
        assert!(!columns.owner);
        assert!(columns.revenue);
        assert!(crm_list_min_width(&columns) < full_width);
        assert_eq!(
            serde_json::to_value(columns).unwrap(),
            serde_json::json!({"stage":true,"owner":false,"revenue":true})
        );
        assert_eq!(CrmGrouping::from_saved_view_id(None), CrmGrouping::None);
        assert_eq!(
            CrmGrouping::from_saved_view_id(CrmGrouping::Stage.saved_view_id().as_deref()),
            CrmGrouping::Stage
        );
        assert_eq!(
            CrmGrouping::from_saved_view_id(CrmGrouping::Owner.saved_view_id().as_deref()),
            CrmGrouping::Owner
        );
        assert_eq!(format_usd(480_000.0), "$480,000");
        assert_eq!(format_usd(-1_250.5), "-$1,250.50");
    }

