    #[test]
    fn shortcut_overrides_support_alternates_disabling_and_safe_fallbacks() {
        let mut overrides = std::collections::HashMap::new();
        assert_eq!(
            configured_shortcut(&overrides, "inbox", "cmd-1"),
            Some("cmd-1")
        );
        overrides.insert("inbox".into(), "ctrl-1".into());
        assert_eq!(
            configured_shortcut(&overrides, "inbox", "cmd-1"),
            Some("ctrl-1")
        );
        overrides.insert("inbox".into(), String::new());
        assert_eq!(configured_shortcut(&overrides, "inbox", "cmd-1"), None);
        overrides.insert("inbox".into(), "cmd-a-b".into());
        assert_eq!(
            configured_shortcut(&overrides, "inbox", "cmd-1"),
            Some("cmd-1")
        );
        assert!(shortcut_is_valid("cmd-shift-p"));
        assert!(!shortcut_is_valid("cmd-a-b"));
    }

    #[test]
    fn unified_search_uses_editor_scoped_navigation_actions() {
        let bindings = macro_key_bindings(&std::collections::HashMap::new());
        let search_bindings = bindings
            .iter()
            .filter(|binding| {
                binding
                    .predicate()
                    .is_some_and(|predicate| predicate.to_string().contains("MacroSearch"))
            })
            .collect::<Vec<_>>();
        assert_eq!(search_bindings.len(), 4);
        assert!(search_bindings.iter().all(|binding| {
            binding
                .predicate()
                .is_some_and(|predicate| predicate.to_string().contains("Editor"))
        }));
        assert!(search_bindings.iter().any(|binding| {
            binding.action().as_any().is::<RunUnifiedSearch>()
                && binding.keystrokes()[0].inner().key == "enter"
        }));
        assert!(search_bindings.iter().any(|binding| {
            binding.action().as_any().is::<OpenSearchResultSplit>()
                && binding.keystrokes()[0].inner().key == "enter"
                && binding.keystrokes()[0].inner().modifiers.shift
        }));
        assert!(
            search_bindings
                .iter()
                .any(|binding| binding.action().as_any().is::<SelectNextSearchResult>())
        );
        assert!(
            search_bindings
                .iter()
                .any(|binding| binding.action().as_any().is::<SelectPreviousSearchResult>())
        );
    }

