    #[test]
    fn agent_retry_reuses_only_the_matching_failed_turn_prompt() {
        let transcript = AgentTranscript {
            bot: AgentSessionBot {
                avatar_url: None,
                id: "bot-1".into(),
                name: "Macro".into(),
            },
            metadata: Default::default(),
            messages: vec![
                AgentTranscriptMessage {
                    turn: 1,
                    author: AgentTranscriptAuthor::User { user_id: None },
                    request_id: Some("prompt-1".into()),
                    parts: vec![AgentTranscriptPart::Text {
                        text: "Earlier prompt".into(),
                    }],
                    stop: None,
                },
                AgentTranscriptMessage {
                    turn: 1,
                    author: AgentTranscriptAuthor::Agent,
                    request_id: None,
                    parts: vec![],
                    stop: Some(AgentStopReason::EndTurn),
                },
                AgentTranscriptMessage {
                    turn: 2,
                    author: AgentTranscriptAuthor::User { user_id: None },
                    request_id: Some("prompt-2".into()),
                    parts: vec![AgentTranscriptPart::Text {
                        text: "Retry this exact request".into(),
                    }],
                    stop: None,
                },
                AgentTranscriptMessage {
                    turn: 2,
                    author: AgentTranscriptAuthor::Agent,
                    request_id: None,
                    parts: vec![],
                    stop: Some(AgentStopReason::Failed {
                        message: "runtime disconnected".into(),
                    }),
                },
            ],
        };

        assert_eq!(
            agent_retryable_prompt(&transcript).as_deref(),
            Some("Retry this exact request")
        );

        let mut successful = transcript;
        successful.messages.last_mut().unwrap().stop = Some(AgentStopReason::EndTurn);
        assert_eq!(agent_retryable_prompt(&successful), None);
    }

