    #[test]
    fn agent_realtime_frames_append_and_refold_without_a_network_reload() {
        let mut detail = serde_json::json!({
            "id":"session-1",
            "_gpuiLog":{
                "bot":{"id":"bot-1","name":"Macro"},
                "entries":[{
                    "createdAt":"2026-08-28T12:00:00Z",
                    "direction":"to_runtime",
                    "content":{
                        "type":"acp","jsonrpc":"2.0","id":"prompt-1","method":"session/prompt",
                        "params":{"prompt":[{"type":"text","text":"Hello"}],"sessionId":"s1"}
                    }
                }]
            }
        });
        let frame = AgentSessionLogEntry {
            created_at: "2026-08-28T12:00:01Z".into(),
            direction: AgentLogDirection::ToServer,
            user_id: None,
            content: serde_json::json!({
                "type":"acp","jsonrpc":"2.0","method":"session/update","params":{
                    "sessionId":"s1","update":{"sessionUpdate":"agent_message_chunk","content":{"type":"text","text":"Hi"}}
                }
            }),
        };
        apply_agent_log_entries_to_detail(&mut detail, "session-1", [frame.clone(), frame])
            .unwrap();
        assert_eq!(detail["_gpuiLog"]["entries"].as_array().unwrap().len(), 2);
        let transcript: AgentTranscript =
            serde_json::from_value(detail["_gpuiTranscript"].clone()).unwrap();
        assert_eq!(transcript.messages.len(), 2);
        assert!(matches!(
            &transcript.messages[1].parts[0],
            AgentTranscriptPart::Text { text } if text == "Hi"
        ));
    }

