    #[test]
    fn task_detail_form_can_create_update_and_clear_planning_properties() {
        let properties = vec![
            EntityProperty {
                entity_property_id: "entity-priority".into(),
                definition_id: TASK_PRIORITY_PROPERTY_ID.into(),
                display_name: "Priority".into(),
                data_type: "SELECT_STRING".into(),
                is_metadata: false,
                is_system: true,
                is_multi_select: false,
                value: PropertyValue::SelectOptions(vec![
                    "00000001-0000-0000-0003-000000000003".into(),
                ]),
                options: vec![PropertyOption {
                    id: "00000001-0000-0000-0003-000000000003".into(),
                    label: "High".into(),
                    color: None,
                }],
            },
            EntityProperty {
                entity_property_id: "entity-due".into(),
                definition_id: TASK_DUE_DATE_PROPERTY_ID.into(),
                display_name: "Due date".into(),
                data_type: "DATE".into(),
                is_metadata: false,
                is_system: true,
                is_multi_select: false,
                value: PropertyValue::Date("2026-09-01".into()),
                options: Vec::new(),
            },
        ];
        let mut values = task_planning_dialog_values(&properties);
        assert_eq!(values[0], "not started");
        assert_eq!(values[1], "High");
        assert_eq!(values[3], "2026-09-01");

        values[2] = "user-1, user-2".into();
        let desired = task_planning_property_values(&values).unwrap();
        assert!(
            desired
                .iter()
                .any(|value| value.property_id == TASK_STATUS_PROPERTY_ID)
        );
        assert!(
            desired
                .iter()
                .any(|value| value.property_id == TASK_PRIORITY_PROPERTY_ID)
        );
        assert!(
            desired
                .iter()
                .any(|value| value.property_id == TASK_DUE_DATE_PROPERTY_ID)
        );

        values[1] = "none".into();
        values[3].clear();
        let cleared = task_planning_property_values(&values).unwrap();
        assert!(
            !cleared
                .iter()
                .any(|value| value.property_id == TASK_PRIORITY_PROPERTY_ID)
        );
        assert!(
            !cleared
                .iter()
                .any(|value| value.property_id == TASK_DUE_DATE_PROPERTY_ID)
        );
    }

    #[test]
    fn bulk_task_status_notice_retains_failed_tasks_for_targeted_retry() {
        assert_eq!(
            bulk_task_status_notice("In review", 2, 2, &[]),
            "Set 2 task(s) to In review"
        );
        let failures = vec![
            ("task-2".into(), "permission denied".into()),
            ("task-3".into(), "conflict".into()),
            ("task-4".into(), "offline".into()),
            ("task-5".into(), "timeout".into()),
        ];
        let notice = bulk_task_status_notice("Completed", 5, 1, &failures);
        assert!(notice.contains("partially applied (1/5)"));
        assert!(notice.contains("4 failed"));
        assert!(notice.contains("task-2: permission denied"));
        assert!(notice.contains("and 1 more"));

        assert_eq!(
            bulk_task_tag_notice("Needs review", true, 3, 3, &[]),
            "Added tag Needs review for 3 task(s)"
        );
        assert!(
            bulk_task_tag_notice(
                "Needs review",
                false,
                3,
                2,
                &[("task-3".into(), "skipped no permission".into())]
            )
            .contains("partially applied (2/3)")
        );
    }

    #[test]
    fn snippet_keyboard_selection_wraps_resets_and_accepts_visible_candidates() {
        let context = DocumentSnippetContext {
            range: 5..8,
            query: "da".into(),
        };
        let mut selection = SnippetTypeaheadSelection {
            context: context.clone(),
            selected_index: 0,
        };
        assert_eq!(
            selection.apply(context.clone(), 3, SnippetTypeaheadCommand::Previous),
            None
        );
        assert_eq!(selection.selected_index, 2);
        selection.apply(context.clone(), 3, SnippetTypeaheadCommand::Next);
        assert_eq!(selection.selected_index, 0);
        selection.apply(context.clone(), 3, SnippetTypeaheadCommand::Next);
        assert_eq!(
            selection.apply(context.clone(), 3, SnippetTypeaheadCommand::Accept),
            Some(1)
        );

        let changed = DocumentSnippetContext {
            range: 5..9,
            query: "dai".into(),
        };
        assert_eq!(
            selection.apply(changed.clone(), 2, SnippetTypeaheadCommand::Accept),
            Some(0)
        );
        assert_eq!(selection.context, changed);
        assert_eq!(
            selection.apply(
                selection.context.clone(),
                0,
                SnippetTypeaheadCommand::Accept
            ),
            None
        );
        assert_eq!(selection.selected_index, 0);
    }

    #[test]
    fn task_pull_request_check_summary_distinguishes_pass_pending_and_failure() {
        let mut pull_request: GithubPullRequest = serde_json::from_value(serde_json::json!({
            "displayName":"macro#42",
            "githubKey":"macro-inc/macro/pull/42",
            "number":42,
            "owner":"macro-inc",
            "repo":"macro",
            "url":"https://github.com/macro-inc/macro/pull/42",
            "checks":[
                {"conclusion":"success","id":1,"name":"test","status":"completed"},
                {"conclusion":"neutral","id":2,"name":"lint","status":"completed"}
            ]
        }))
        .unwrap();
        assert_eq!(
            github_pull_request_check_summary(&pull_request).as_deref(),
            Some("2 checks passed")
        );
        pull_request.checks.as_mut().unwrap()[1].status = "in_progress".into();
        pull_request.checks.as_mut().unwrap()[1].conclusion = None;
        assert_eq!(
            github_pull_request_check_summary(&pull_request).as_deref(),
            Some("1/2 checks pending")
        );
        pull_request.checks.as_mut().unwrap()[1].status = "completed".into();
        pull_request.checks.as_mut().unwrap()[1].conclusion = Some("failure".into());
        assert_eq!(
            github_pull_request_check_summary(&pull_request).as_deref(),
            Some("1/2 checks failed")
        );
    }

    #[test]
    fn only_quota_consuming_mutations_refresh_user_quota() {
        assert!(mutation_affects_user_quota(&MutationKind::NewAgent));
        assert!(mutation_affects_user_quota(&MutationKind::PromptAgent {
            session_id: "agent-1".into()
        }));
        assert!(mutation_affects_user_quota(&MutationKind::NewTask {
            source: None
        }));
        assert!(!mutation_affects_user_quota(&MutationKind::RenameAgent {
            session_id: "agent-1".into()
        }));
        assert!(!mutation_affects_user_quota(&MutationKind::NewProject {
            parent_id: None
        }));
    }

