    #[test]
    fn remote_email_images_require_explicit_safe_http_sources() {
        let message = serde_json::json!({
            "body_html_sanitized": concat!(
                "<p>Hello</p>",
                "<img src='https://images.example.com/a.png?x=1&amp;y=2'>",
                "<img SRC=\"http://images.example.com/b.jpg\">",
                "<img src='https://images.example.com/a.png?x=1&amp;y=2'>",
                "<img data-src='https://images.example.com/lazy.png'>",
                "<img src='data:image/png;base64,abc'>",
                "<img src='javascript:alert(1)'>"
            )
        });
        assert_eq!(
            email_remote_image_urls(&message),
            vec![
                "https://images.example.com/a.png?x=1&y=2",
                "http://images.example.com/b.jpg"
            ]
        );
        assert_eq!(
            html_attribute("<img alt=x src = unquoted.png>", "src"),
            Some("unquoted.png".into())
        );
        assert_eq!(html_attribute("<img data-src='nope'>", "src"), None);
    }

    #[test]
    fn email_bodies_use_native_markdown_and_preserve_trimmed_quote_disclosure() {
        let message = serde_json::json!({
            "body_macro": "Hello **Alex**",
            "body_replyless": "<p>Hello <strong>Alex</strong></p>",
            "body_html_sanitized": concat!(
                "<p>Hello <strong>Alex</strong></p>",
                "<blockquote class='macro_quote'><p>Earlier reply</p></blockquote>"
            )
        });
        let compact = email_message_body_content(&message, false);
        assert_eq!(compact.markdown, "Hello **Alex**");
        assert!(compact.has_hidden_reply_structure);

        let full = email_message_body_content(&message, true);
        assert!(full.markdown.contains("Hello"));
        assert!(full.markdown.contains("Alex"));
        assert!(full.markdown.contains("Earlier reply"));
        assert!(full.has_hidden_reply_structure);

        let plaintext = serde_json::json!({"body_text":"Plain message"});
        assert_eq!(
            email_message_body_content(&plaintext, false),
            EmailBodyContent {
                markdown: "Plain message".into(),
                has_hidden_reply_structure: false,
            }
        );
    }

