    #[test]
    fn agent_authored_email_requires_explicit_review_only_when_sending() {
        let mut dialog = MutationDialog::new(
            "Review agent email draft",
            "Send",
            MutationKind::ComposeEmail,
            vec![
                super::MacroApp::mutation_field("To", "alex@example.test", false),
                super::MacroApp::mutation_field("Subject", "Launch", false),
                super::MacroApp::mutation_field("Message", "Ready", true),
                super::MacroApp::mutation_field("Cc", "", false),
                super::MacroApp::mutation_field("Bcc", "", false),
                super::MacroApp::mutation_field("Action", "send", false),
                super::MacroApp::mutation_field("Schedule", "", false),
                super::MacroApp::mutation_field("From", "link-1", false),
            ],
        );
        dialog.email_agent_authored = true;
        assert!(email_agent_send_confirmation_required(&dialog));
        dialog.email_agent_send_confirmed = true;
        assert!(!email_agent_send_confirmation_required(&dialog));
        dialog.email_agent_send_confirmed = false;
        dialog.fields[5].value = "draft".into();
        assert!(!email_agent_send_confirmation_required(&dialog));
    }

    #[test]
    fn scheduled_email_times_are_future_bounded_and_normalized() {
        let now = chrono::DateTime::parse_from_rfc3339("2026-09-01T12:00:00Z")
            .unwrap()
            .with_timezone(&chrono::Utc);
        assert_eq!(
            validated_email_schedule_time_at("2026-09-02T09:00:00-04:00", now).unwrap(),
            "2026-09-02T13:00:00+00:00"
        );
        assert!(validated_email_schedule_time_at("", now).is_err());
        assert!(validated_email_schedule_time_at("2026-09-01T11:59:59Z", now).is_err());
        assert!(validated_email_schedule_time_at("2027-09-03T12:00:00Z", now).is_err());
        assert!(validated_email_schedule_time_at("tomorrow morning", now).is_err());
    }

    #[test]
    fn canvas_media_and_links_only_open_safe_http_urls() {
        assert_eq!(
            canvas_static_media_url("https://static.example/", "file/id with spaces"),
            Some("https://static.example/file/file%2Fid%20with%20spaces".into())
        );
        assert_eq!(
            canvas_static_media_url("javascript:alert(1)", "file-id"),
            None
        );
        assert_eq!(safe_external_resource_url("file:///tmp/private"), None);
        assert_eq!(safe_external_resource_url("javascript:alert(1)"), None);
        assert_eq!(safe_external_resource_url("data:text/html,unsafe"), None);
        assert_eq!(safe_external_resource_url("macro://auth/callback"), None);
        assert_eq!(safe_external_resource_url("//example.com/ambiguous"), None);
        assert_eq!(safe_external_resource_url("not a url"), None);
        assert_eq!(safe_external_resource_url("ftp://example.com/file"), None);
        assert_eq!(
            safe_external_resource_url("http://example.com/authorize"),
            Some("http://example.com/authorize".into())
        );
        assert_eq!(
            safe_external_resource_url("https://example.com/video.mp4"),
            Some("https://example.com/video.mp4".into())
        );
    }

    #[test]
    fn local_upload_reads_are_bounded_before_and_during_allocation() {
        let directory = tempfile::tempdir().unwrap();
        let small = directory.path().join("small.bin");
        std::fs::write(&small, b"macro").unwrap();
        assert_eq!(bounded_file_size(&small, 5).unwrap(), 5);
        assert_eq!(read_bounded_file(&small, 5).unwrap(), b"macro");
        assert!(bounded_file_size(&small, 4).is_err());
        assert!(read_bounded_file(directory.path(), 5).is_err());

        let oversized = directory.path().join("oversized-email.bin");
        let file = std::fs::File::create(&oversized).unwrap();
        file.set_len(MAX_EMAIL_ATTACHMENTS_BYTES + 1).unwrap();
        assert!(
            bounded_file_size(&oversized, MAX_EMAIL_ATTACHMENTS_BYTES).is_err(),
            "a sparse oversized file must be rejected without allocation"
        );
    }

    #[test]
    fn file_video_preview_recognizes_supported_macro_upload_extensions() {
        for extension in [
            "mp4", "MOV", "m4v", "webm", "avi", "mkv", "mpeg", "mpg", "ogv",
        ] {
            assert!(
                is_video_file_type(extension),
                "{extension} should be previewable"
            );
        }
        for extension in ["pdf", "png", "mp3", "txt", "html"] {
            assert!(!is_video_file_type(extension), "{extension} is not a video");
        }
    }

    #[test]
    fn printable_documents_are_self_contained_safe_and_open_the_print_dialog() {
        let html = printable_document_html(
            "Plan </title><script>alert(1)</script>",
            "# Ship\n\n- [ ] Review `<unsafe>`",
        );
        assert!(html.contains("<title>Plan &lt;/title&gt;&lt;script&gt;"));
        assert!(!html.contains("<script>alert(1)</script>"));
        assert!(html.contains("<h1>Ship</h1>"));
        assert!(html.contains("&lt;unsafe&gt;"));
        assert!(html.contains("setTimeout(()=>print(),100)"));
        assert!(html.contains("@media print"));
    }
